/* 자동 생성 — tools/build_data.py. 직접 고치지 마세요. */
(window.TS_DATA = window.TS_DATA || {}).p7 = [{"id":"p7-001","level":1,"kind":"single","passages":[{"doc_type":"공지","title":"Notice to All Tenants","text":"NOTICE TO ALL TENANTS\n\nThe parking lot behind the Harmon Building will be closed on Saturday, May 10, from 7:00 A.M. to 5:00 P.M. Workers will repaint the lines and repair several lights. During this time, tenants may park at the City Garage on Fifth Street at no charge. Please show your building ID card to the garage attendant. The lot will reopen on Sunday morning. If you have any questions, please contact the building office at 555-0142. We are sorry for any inconvenience."}],"questions":[{"q":"Why will the parking lot be closed?","choices":["For painting and repair work","To add more parking spaces","For a building event","For a street festival"],"answer":0,"type":"세부 사항","explanation":"두 번째 문장 'Workers will repaint the lines and repair several lights.'에서 주차선 도색과 조명 수리 때문에 폐쇄된다고 했다. 주차 공간 추가, 행사, 거리 축제는 언급되지 않았다."},{"q":"What should tenants show at the City Garage?","choices":["A parking receipt","A driver's license","A building ID card","A credit card"],"answer":2,"type":"세부 사항","explanation":"'Please show your building ID card to the garage attendant.'에서 건물 출입증(ID 카드)을 보여 주라고 했다. 주차 영수증, 운전면허증, 신용카드는 언급되지 않았고 주차는 무료(at no charge)이다."}],"translation":"입주자 여러분께 알립니다\n\n하먼 빌딩 뒤편 주차장이 5월 10일 토요일 오전 7시부터 오후 5시까지 폐쇄됩니다. 작업자들이 주차선을 다시 칠하고 조명 몇 개를 수리할 예정입니다. 이 시간 동안 입주자분들은 5번가에 있는 시립 주차장에 무료로 주차하실 수 있습니다. 주차장 관리 직원에게 건물 출입증을 보여 주십시오. 주차장은 일요일 아침에 다시 문을 엽니다. 문의 사항이 있으시면 건물 관리 사무소(555-0142)로 연락해 주십시오. 불편을 드려 죄송합니다.","part":7},{"id":"p7-002","level":1,"kind":"single","passages":[{"doc_type":"문자 메시지","title":"Text-message chain","text":"Kim Dahee (10:02 A.M.): Hi, Paul. Are you still at the printing shop?\nPaul Novak (10:04 A.M.): Yes. The brochures are almost ready.\nKim Dahee (10:05 A.M.): Great. Could you also pick up 200 business cards for Mr. Lee? He ordered them last week.\nPaul Novak (10:06 A.M.): No problem.\nKim Dahee (10:07 A.M.): Thanks. The client meeting starts at 1:00, so please be back by noon. We need time to set up the room.\nPaul Novak (10:08 A.M.): OK. I'll be there by 11:30."}],"questions":[{"q":"At 10:06 A.M., what does Mr. Novak mean when he writes, “No problem”?","choices":["The printing shop is not busy.","He does not need a ride.","The brochures have no errors.","He will pick up the business cards."],"answer":3,"type":"의도 파악","explanation":"바로 앞에서 김다희 씨가 'Could you also pick up 200 business cards for Mr. Lee?'라고 부탁했으므로 'No problem'은 명함을 찾아오겠다는 수락의 뜻이다. 인쇄소가 한가하다거나 브로슈어에 오류가 없다는 뜻이 아니다."},{"q":"By what time will Mr. Novak most likely return?","choices":["10:30 A.M.","11:30 A.M.","1:00 P.M.","2:00 P.M."],"answer":1,"type":"세부 사항","explanation":"마지막 메시지 'I'll be there by 11:30.'에서 11시 30분까지 돌아오겠다고 했다. 1시는 고객 회의 시작 시각이고, 김다희 씨는 정오까지 오라고 요청했다."}],"translation":"김다희 (오전 10:02): 안녕하세요, 폴. 아직 인쇄소에 계세요?\n폴 노박 (오전 10:04): 네. 브로슈어가 거의 다 됐어요.\n김다희 (오전 10:05): 잘됐네요. 이 선생님 명함 200장도 찾아와 주실 수 있어요? 지난주에 주문하셨거든요.\n폴 노박 (오전 10:06): 문제없어요.\n김다희 (오전 10:07): 고마워요. 고객 회의가 1시에 시작하니 정오까지는 돌아와 주세요. 회의실을 준비할 시간이 필요해요.\n폴 노박 (오전 10:08): 알겠어요. 11시 30분까지 갈게요.","part":7},{"id":"p7-003","level":1,"kind":"single","passages":[{"doc_type":"광고","title":"Sunrise Café","text":"Sunrise Café — Now Open on Maple Avenue!\n\nCome and try our fresh bread, sandwiches, and coffee. We are open every day from 6:30 A.M. to 8:00 P.M. For our first month, all customers will receive a free cookie with any drink. We also offer catering for office meetings. Catering orders must be placed at least two days in advance. Call 555-0198 or visit www.sunrisecafe.com to see our full menu. Seating is available both indoors and on our outdoor patio. Free Wi-Fi is available for all guests."}],"questions":[{"q":"What is being advertised?","choices":["A cooking class","A grocery store","A new café","A delivery service"],"answer":2,"type":"주제·목적","explanation":"제목 'Sunrise Café — Now Open on Maple Avenue!'와 빵·샌드위치·커피를 소개하는 내용으로 보아 새로 문을 연 카페 광고이다. 요리 수업이나 식료품점, 배달 서비스 광고가 아니다."},{"q":"What will customers receive during the first month?","choices":["A discount on catering","A free sandwich","A free cup of coffee","A free cookie"],"answer":3,"type":"세부 사항","explanation":"'For our first month, all customers will receive a free cookie with any drink.'에서 첫 달 동안 음료를 사면 쿠키를 무료로 준다고 했다. 커피는 사야 하는 음료이지 무료 품목이 아니다."},{"q":"What is indicated about catering orders?","choices":["They must be made two days ahead.","They are delivered for free.","They are available only on weekends.","They must be paid for online."],"answer":0,"type":"사실 확인(NOT/TRUE)","explanation":"'Catering orders must be placed at least two days in advance.'에서 최소 이틀 전에 주문해야 한다고 했다. 무료 배달, 주말 한정, 온라인 결제는 언급되지 않았다."}],"translation":"선라이즈 카페 — 메이플 가에 새로 문을 열었습니다!\n\n오셔서 갓 구운 빵과 샌드위치, 커피를 맛보세요. 매일 오전 6시 30분부터 오후 8시까지 영업합니다. 개업 첫 달 동안 음료를 주문하시는 모든 손님께 쿠키를 무료로 드립니다. 사무실 회의용 케이터링도 제공합니다. 케이터링 주문은 최소 이틀 전에 해 주셔야 합니다. 전체 메뉴는 555-0198로 전화하시거나 www.sunrisecafe.com을 방문해 확인하세요. 실내와 야외 테라스 모두에 좌석이 마련되어 있습니다. 모든 손님께 무료 와이파이를 제공합니다.","part":7},{"id":"p7-004","level":1,"kind":"single","passages":[{"doc_type":"이메일","title":"From: Laura Chen / To: Marketing Team / Subject: Tomorrow's meeting","text":"Hi everyone,\n\nTomorrow's team meeting will not be in Room 204. That room is being used for job interviews all day. Instead, we will meet in Room 310 on the third floor. The time has not changed. We will start at 9:30 A.M. as usual. Please bring your sales reports from last month so that we can review them together. Coffee and snacks will be provided. If you cannot attend, please let me know by the end of today.\n\nThank you,\nLaura"}],"questions":[{"q":"Why was the e-mail written?","choices":["To cancel a meeting","To invite staff to an interview","To give a new meeting location","To ask for snack suggestions"],"answer":2,"type":"주제·목적","explanation":"'Tomorrow's team meeting will not be in Room 204... we will meet in Room 310'에서 회의 장소 변경을 알리려는 이메일임을 알 수 있다. 회의는 취소되지 않았고 시간도 그대로이다."},{"q":"What are team members asked to bring?","choices":["Sales reports","Coffee","Their ID cards","Job applications"],"answer":0,"type":"세부 사항","explanation":"'Please bring your sales reports from last month'에서 지난달 영업 보고서를 가져오라고 했다. 커피와 간식은 제공된다고 했으므로 가져올 필요가 없다."}],"translation":"보낸 사람: 로라 첸 / 받는 사람: 마케팅팀 / 제목: 내일 회의\n\n여러분 안녕하세요.\n\n내일 팀 회의는 204호에서 하지 않습니다. 그 방은 하루 종일 채용 면접에 사용됩니다. 대신 3층 310호에서 모이겠습니다. 시간은 바뀌지 않았습니다. 평소처럼 오전 9시 30분에 시작합니다. 함께 검토할 수 있도록 지난달 영업 보고서를 가져와 주세요. 커피와 간식이 제공됩니다. 참석하지 못하시면 오늘 중으로 알려 주세요.\n\n감사합니다.\n로라","part":7},{"id":"p7-005","level":1,"kind":"single","passages":[{"doc_type":"일정표","title":"Riverside Community Center — Spring Class Schedule","text":"Riverside Community Center\nSpring Class Schedule\n\nClass | Day | Time | Fee\nBeginner Yoga | Monday | 7:00 P.M. | $40\nWatercolor Painting | Wednesday | 6:30 P.M. | $55\nBasic Spanish | Thursday | 7:30 P.M. | $50\nHome Cooking | Saturday | 10:00 A.M. | $65\n\nAll classes run for six weeks and begin the week of April 7. You can register at the front desk or online. Members of the center receive 10 percent off all fees. The fee for the cooking class includes all ingredients."}],"questions":[{"q":"Which class meets on the weekend?","choices":["Beginner Yoga","Watercolor Painting","Basic Spanish","Home Cooking"],"answer":3,"type":"세부 사항","explanation":"표에서 Home Cooking만 Saturday(토요일)에 열린다. 나머지 수업은 월·수·목요일 저녁에 열린다."},{"q":"How long do the classes last?","choices":["Four weeks","Six weeks","Eight weeks","Ten weeks"],"answer":1,"type":"세부 사항","explanation":"표 아래 'All classes run for six weeks'에서 모든 수업이 6주 동안 진행된다고 했다."},{"q":"What is true about the Home Cooking class?","choices":["It is the least expensive class.","It meets in the evening.","Its fee includes ingredients.","It starts in May."],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"마지막 문장 'The fee for the cooking class includes all ingredients.'에서 재료비가 포함된다고 했다. 요리 수업은 $65로 가장 비싸고, 오전 10시에 열리며, 4월 7일 주에 시작한다."}],"translation":"리버사이드 주민센터\n봄 강좌 일정표\n\n강좌 | 요일 | 시간 | 수강료\n초급 요가 | 월요일 | 오후 7:00 | 40달러\n수채화 | 수요일 | 오후 6:30 | 55달러\n기초 스페인어 | 목요일 | 오후 7:30 | 50달러\n가정 요리 | 토요일 | 오전 10:00 | 65달러\n\n모든 강좌는 6주 동안 진행되며 4월 7일이 있는 주에 시작합니다. 안내 데스크나 온라인으로 등록할 수 있습니다. 센터 회원은 모든 수강료를 10퍼센트 할인받습니다. 요리 강좌 수강료에는 모든 재료비가 포함됩니다.","part":7},{"id":"p7-006","level":1,"kind":"double","passages":[{"doc_type":"구인 광고","title":"Part-Time Office Assistant Wanted","text":"Part-Time Office Assistant Wanted\n\nGreenleaf Travel is looking for a part-time office assistant. The assistant will answer phone calls, file documents, and help customers book tours. Working hours are Monday to Friday, 1:00 P.M. to 5:00 P.M. Applicants must have basic computer skills. Training will be provided for all new staff. Experience in travel is helpful but not required. The successful applicant will begin work on July 1. To apply, send a résumé to Ms. Rita Gomez at rgomez@greenleaftravel.com by June 15."},{"doc_type":"이메일","title":"From: Tom Baker / To: Rita Gomez / Date: June 12 / Subject: Office assistant position","text":"Dear Ms. Gomez,\n\nI am writing to apply for the part-time office assistant position at Greenleaf Travel. I am a university student, and my classes end at noon every weekday, so your working hours are perfect for me. Last summer, I worked at a hotel front desk, where I answered phone calls and helped guests with their plans. I am also good with computers. I would be happy to start on July 1 as stated in your advertisement. My résumé is attached. I hope to hear from you soon.\n\nSincerely,\nTom Baker"}],"questions":[{"q":"What is one duty of the advertised job?","choices":["Leading tours","Driving customers to the airport","Writing travel articles","Answering phone calls"],"answer":3,"type":"세부 사항","explanation":"광고의 'The assistant will answer phone calls, file documents, and help customers book tours.'에서 전화 응대가 업무 중 하나이다. 투어 인솔이 아니라 투어 '예약'을 돕는 일이다."},{"q":"What is stated about travel experience?","choices":["It is required.","It is helpful but not necessary.","It must be at least one year.","It is needed only for full-time work."],"answer":1,"type":"사실 확인(NOT/TRUE)","explanation":"광고의 'Experience in travel is helpful but not required.'에서 여행업 경험은 도움이 되지만 필수는 아니라고 했다."},{"q":"Why did Mr. Baker write the e-mail?","choices":["To apply for a job","To book a tour","To ask about hotel rooms","To change his class schedule"],"answer":0,"type":"주제·목적","explanation":"이메일 첫 문장 'I am writing to apply for the part-time office assistant position'에서 구직 지원이 목적임을 알 수 있다. 호텔은 과거 근무처로만 언급되었다."},{"q":"Why are the working hours good for Mr. Baker?","choices":["He works at a hotel in the morning.","His classes finish before the job starts.","He lives near the office.","He prefers to work on weekends."],"answer":1,"type":"연계 문제","explanation":"광고에서 근무 시간은 오후 1시~5시이고, 이메일에서 베이커 씨는 'my classes end at noon every weekday'라고 했다. 두 지문을 합치면 수업이 끝난 뒤 일을 시작할 수 있어 시간이 맞는다. 호텔 근무는 지난여름 일이다."},{"q":"What did Mr. Baker send with his e-mail?","choices":["His résumé","A reference letter","A photo","His class schedule"],"answer":0,"type":"세부 사항","explanation":"이메일의 'My résumé is attached.'에서 이력서를 첨부했음을 알 수 있다. 광고에서도 지원하려면 이력서를 보내라고 했다."}],"translation":"[구인 광고]\n시간제 사무 보조 구함\n\n그린리프 여행사에서 시간제 사무 보조를 찾습니다. 사무 보조는 전화를 받고, 서류를 정리하고, 고객의 투어 예약을 돕게 됩니다. 근무 시간은 월요일부터 금요일, 오후 1시부터 5시까지입니다. 지원자는 기본적인 컴퓨터 능력이 있어야 합니다. 모든 신입 직원에게 교육이 제공됩니다. 여행업 경험은 도움이 되지만 필수는 아닙니다. 합격자는 7월 1일부터 근무를 시작합니다. 지원하시려면 6월 15일까지 리타 고메즈 씨(rgomez@greenleaftravel.com)에게 이력서를 보내 주십시오.\n\n[이메일]\n보낸 사람: 톰 베이커 / 받는 사람: 리타 고메즈 / 날짜: 6월 12일 / 제목: 사무 보조직\n\n고메즈 님께,\n\n그린리프 여행사의 시간제 사무 보조직에 지원하고자 이 글을 씁니다. 저는 대학생이며 평일에는 매일 정오에 수업이 끝나기 때문에 귀사의 근무 시간이 제게 딱 맞습니다. 지난여름에는 호텔 프런트에서 일하며 전화를 받고 투숙객의 일정을 도왔습니다. 컴퓨터도 잘 다룹니다. 광고에 나온 대로 7월 1일부터 기꺼이 근무를 시작하겠습니다. 이력서를 첨부합니다. 곧 연락 주시기를 바랍니다.\n\n톰 베이커 드림","part":7},{"id":"p7-007","level":2,"kind":"single","passages":[{"doc_type":"회람","title":"To: All Employees / From: Grace Park, Finance Department / Date: March 3 / Subject: New expense reports","text":"MEMO\n\nStarting April 1, all employees must submit travel and meal expenses through our new online system, ExpensePro. Paper forms will no longer be accepted. The new system allows you to upload photos of your receipts directly from your phone, so you will not need to keep the original copies.\n\nTo help everyone get used to the system, the Finance Department will hold two training sessions on March 20 in Conference Room B. The morning session begins at 10:00 A.M., and the afternoon session begins at 3:00 P.M. Each session will last about one hour. Please sign up for one session by March 15 by e-mailing me at gpark@lintonco.com.\n\nIf you have expenses from March, please submit them on paper forms by March 31."}],"questions":[{"q":"What is the purpose of the memo?","choices":["To introduce a new way of reporting expenses","To announce a change in travel destinations","To request receipts for February","To explain a new phone plan"],"answer":0,"type":"주제·목적","explanation":"첫 문단에서 4월 1일부터 새 온라인 시스템 ExpensePro로 경비를 제출해야 한다고 알리고 있으므로 새로운 경비 보고 방식을 소개하는 회람이다. 휴대폰은 영수증 사진을 올리는 도구로만 언급되었다."},{"q":"What are employees asked to do by March 15?","choices":["Submit paper forms","Send original receipts","Register for a training session","Visit Conference Room B"],"answer":2,"type":"세부 사항","explanation":"두 번째 문단 'Please sign up for one session by March 15'에서 3월 15일까지 교육 한 회차에 신청하라고 했다. 종이 양식 제출 기한은 3월 31일이고, 회의실 B 방문은 교육 당일(3월 20일)의 일이다."},{"q":"The word “hold” in paragraph 2, line 1, is closest in meaning to","choices":["grab","support","carry","conduct"],"answer":3,"type":"동의어","explanation":"'will hold two training sessions'는 교육을 '열다, 실시하다'라는 뜻이므로 conduct가 가장 가깝다. grab(붙잡다), support(지탱하다), carry(나르다)는 물건을 잡거나 드는 의미의 hold에 해당한다."}],"translation":"회람\n받는 사람: 전 직원 / 보낸 사람: 재무부 그레이스 박 / 날짜: 3월 3일 / 제목: 새 경비 보고서\n\n4월 1일부터 모든 직원은 출장비와 식비를 새 온라인 시스템인 ExpensePro로 제출해야 합니다. 종이 양식은 더 이상 받지 않습니다. 새 시스템에서는 휴대폰으로 영수증 사진을 바로 올릴 수 있으므로 원본을 보관하지 않아도 됩니다.\n\n모두가 시스템에 익숙해질 수 있도록 재무부에서 3월 20일 회의실 B에서 교육을 두 차례 실시합니다. 오전 교육은 오전 10시, 오후 교육은 오후 3시에 시작합니다. 각 교육은 약 한 시간 동안 진행됩니다. 3월 15일까지 gpark@lintonco.com으로 제게 이메일을 보내 한 회차에 신청해 주십시오.\n\n3월에 발생한 경비는 3월 31일까지 종이 양식으로 제출해 주십시오.","part":7},{"id":"p7-008","level":2,"kind":"single","passages":[{"doc_type":"온라인 채팅","title":"Online chat discussion","text":"Maria Lopez [2:14 P.M.]: Hi, Ken. The projector in Meeting Room A isn't turning on. My client presentation starts at 3:00.\nKen Ito [2:15 P.M.]: Did you check that it's plugged in?\nMaria Lopez [2:16 P.M.]: Yes, twice. The power light doesn't come on at all.\nKen Ito [2:17 P.M.]: Then the lamp might be broken. We ordered new ones, but they haven't arrived yet.\nMaria Lopez [2:18 P.M.]: What should I do?\nKen Ito [2:19 P.M.]: Room C has a large-screen TV. I can connect your laptop to it.\nMaria Lopez [2:20 P.M.]: That would work. Is Room C free at 3:00?\nKen Ito [2:21 P.M.]: I'll check the booking system and get back to you in five minutes.\nMaria Lopez [2:22 P.M.]: Thanks. I'll start gathering my materials."}],"questions":[{"q":"What problem does Ms. Lopez have?","choices":["A projector is not working.","Her laptop battery is low.","Her client is late.","A meeting room is locked."],"answer":0,"type":"세부 사항","explanation":"첫 메시지 'The projector in Meeting Room A isn't turning on.'에서 프로젝터가 켜지지 않는 문제가 있음을 알 수 있다. 노트북 배터리나 고객 지각, 잠긴 회의실은 언급되지 않았다."},{"q":"At 2:20 P.M., what does Ms. Lopez mean when she writes, “That would work”?","choices":["She thinks the projector will be fixed soon.","She will work in Room C all afternoon.","She wants to order a new lamp.","She accepts Mr. Ito's suggestion."],"answer":3,"type":"의도 파악","explanation":"바로 앞에서 이토 씨가 C실의 대형 TV에 노트북을 연결해 주겠다고 제안했고, 로페즈 씨는 'That would work'라며 그 방법이면 되겠다고 받아들였다. 곧바로 C실이 3시에 비어 있는지 묻는 것도 제안을 수락했다는 근거이다."},{"q":"What will Mr. Ito most likely do next?","choices":["Replace the lamp","Call Ms. Lopez's client","Check whether a room is available","Bring a new laptop"],"answer":2,"type":"추론","explanation":"2시 21분에 이토 씨가 'I'll check the booking system and get back to you'라고 했으므로 C실 예약 가능 여부를 확인할 것이다. 새 램프는 아직 도착하지 않아 교체할 수 없다."}],"translation":"마리아 로페즈 [오후 2:14]: 안녕하세요, 켄. A 회의실 프로젝터가 켜지지 않아요. 고객 발표가 3시에 시작하는데요.\n켄 이토 [오후 2:15]: 전원이 꽂혀 있는지 확인해 보셨어요?\n마리아 로페즈 [오후 2:16]: 네, 두 번이나요. 전원 표시등이 아예 안 들어와요.\n켄 이토 [오후 2:17]: 그럼 램프가 고장 났을 수도 있어요. 새 램프를 주문했는데 아직 안 왔어요.\n마리아 로페즈 [오후 2:18]: 어떻게 하면 될까요?\n켄 이토 [오후 2:19]: C실에 대형 TV가 있어요. 거기에 노트북을 연결해 드릴 수 있어요.\n마리아 로페즈 [오후 2:20]: 그거면 되겠네요. C실이 3시에 비어 있나요?\n켄 이토 [오후 2:21]: 예약 시스템을 확인하고 5분 안에 다시 알려 드릴게요.\n마리아 로페즈 [오후 2:22]: 고마워요. 자료를 챙기기 시작할게요.","part":7},{"id":"p7-009","level":2,"kind":"single","passages":[{"doc_type":"기사","title":"Bright Market Expands to Westfield","text":"WESTFIELD (May 4) — Bright Market, a grocery chain known for its locally grown produce, will open its fifth store in Westfield next month. [1] The new store will be located on Carver Road, in the building that once housed Delmont Furniture.\n\nThe Westfield location will be larger than the chain's other stores. [2] In addition to fresh fruit and vegetables, it will include a bakery and a small café where shoppers can enjoy coffee and sandwiches. [3]\n\nBright Market plans to hire about 60 workers for the new store. Job fairs will be held on May 18 and 19 at the Westfield Public Library. [4] A grand opening celebration with free samples and live music is scheduled for June 14."}],"questions":[{"q":"What is the article mainly about?","choices":["The closing of a furniture store","The opening of a new grocery store","A job fair at a university","A local music festival"],"answer":1,"type":"주제·목적","explanation":"첫 문장에서 식료품 체인 Bright Market이 웨스트필드에 다섯 번째 매장을 연다고 했고 기사 전체가 새 매장 이야기이다. 가구점은 건물의 예전 입주자로만 언급되었다."},{"q":"What is indicated about the Westfield store?","choices":["It will be the chain's first store.","It will open on May 18.","It will be bigger than the chain's other stores.","It will sell furniture."],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"두 번째 문단 'The Westfield location will be larger than the chain's other stores.'와 일치한다. 이 매장은 다섯 번째 매장이고, 5월 18일은 채용 박람회 날짜이며, 개점 행사는 6월 14일이다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? “Interested applicants should bring a copy of their résumé.”","choices":["[1]","[2]","[3]","[4]"],"answer":3,"type":"문장 삽입","explanation":"주어진 문장은 지원자(applicants)에게 이력서를 가져오라는 내용이므로 채용 박람회를 소개한 'Job fairs will be held on May 18 and 19...' 바로 뒤인 [4]가 알맞다. 다른 위치는 채용과 관련 없는 매장 소개 부분이다."}],"translation":"브라이트 마켓, 웨스트필드로 확장\n\n웨스트필드 (5월 4일) — 지역에서 재배한 농산물로 알려진 식료품 체인 브라이트 마켓이 다음 달 웨스트필드에 다섯 번째 매장을 연다. [1] 새 매장은 카버 로드에 있는, 예전에 델몬트 가구가 입주해 있던 건물에 들어선다.\n\n웨스트필드 매장은 체인의 다른 매장보다 더 크다. [2] 신선한 과일과 채소 외에도 빵집과, 쇼핑객이 커피와 샌드위치를 즐길 수 있는 작은 카페가 들어선다. [3]\n\n브라이트 마켓은 새 매장을 위해 약 60명을 채용할 계획이다. 채용 박람회는 5월 18일과 19일 웨스트필드 공공도서관에서 열린다. [4] 무료 시식과 라이브 음악이 함께하는 개점 기념 행사는 6월 14일로 예정되어 있다.","part":7},{"id":"p7-010","level":2,"kind":"single","passages":[{"doc_type":"후기","title":"Customer Review — Harbor View Hotel ★★★★☆ / Posted by: J. Morales","text":"I stayed at the Harbor View Hotel for three nights last week while attending a conference downtown. The location was excellent. The convention center was only a ten-minute walk away, and there were many restaurants nearby.\n\nMy room was clean and quiet, and the bed was very comfortable. The staff at the front desk were friendly and helped me print documents for my presentation. The breakfast buffet had a good variety of hot and cold dishes.\n\nMy only complaint is about the Internet. The Wi-Fi in my room was quite slow, so I often had to work in the lobby, where the connection was better. I mentioned this to the manager, and she said the hotel is planning to upgrade its network soon. I would definitely stay here again on my next business trip."}],"questions":[{"q":"Why did the reviewer visit the city?","choices":["To attend a conference","To take a vacation","To visit family members","To look for an apartment"],"answer":0,"type":"세부 사항","explanation":"첫 문장 'while attending a conference downtown'에서 시내 콘퍼런스 참석차 머물렀음을 알 수 있다. 마지막 문장의 'business trip'도 업무 목적임을 뒷받침한다."},{"q":"What did the front desk staff do for the reviewer?","choices":["They printed some documents.","They recommended a restaurant.","They changed his room.","They called a taxi."],"answer":0,"type":"세부 사항","explanation":"두 번째 문단 'helped me print documents for my presentation'에서 발표 자료 인쇄를 도와주었다고 했다. 식당은 근처에 많다고만 했을 뿐 추천받았다는 말은 없다."},{"q":"What is NOT mentioned as a positive feature of the hotel?","choices":["Its location","Its breakfast","Its Internet service","Its beds"],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"위치(The location was excellent), 조식(good variety), 침대(very comfortable)는 모두 칭찬했지만, 인터넷은 'My only complaint is about the Internet'이라며 유일한 불만으로 꼽았다."}],"translation":"고객 후기 — 하버 뷰 호텔 ★★★★☆ / 작성자: J. 모랄레스\n\n지난주 시내에서 열린 콘퍼런스에 참석하느라 하버 뷰 호텔에서 3박을 했습니다. 위치가 아주 좋았습니다. 컨벤션 센터까지 걸어서 10분밖에 안 걸렸고 근처에 식당도 많았습니다.\n\n객실은 깨끗하고 조용했으며 침대가 매우 편안했습니다. 프런트 직원들은 친절했고 제 발표 자료 인쇄를 도와주었습니다. 조식 뷔페에는 따뜻한 요리와 찬 요리가 다양하게 있었습니다.\n\n유일한 불만은 인터넷입니다. 객실 와이파이가 꽤 느려서 연결이 더 잘되는 로비에서 자주 일해야 했습니다. 지배인에게 이 점을 이야기했더니 호텔이 곧 네트워크를 개선할 계획이라고 했습니다. 다음 출장 때도 꼭 이곳에 묵을 것입니다.","part":7},{"id":"p7-011","level":2,"kind":"double","passages":[{"doc_type":"공지","title":"Annual Staff Picnic","text":"Annual Staff Picnic\n\nDate: Saturday, August 23\nTime: 11:00 A.M. – 4:00 P.M.\nPlace: Lakeside Park, Area 3\n\nAll employees and their families are invited to this year's staff picnic. Lunch will be served at noon, and games for children will begin at 1:30 P.M. The company will provide food and drinks, but employees are welcome to bring a dessert to share. A bus will leave from the main office parking lot at 10:15 A.M. If you plan to take the bus, please tell Sandra Cole in Human Resources by August 15. In case of rain, the picnic will be moved to Saturday, August 30."},{"doc_type":"이메일","title":"From: Brian Walsh / To: Sandra Cole / Date: August 12 / Subject: Staff picnic","text":"Hi Sandra,\n\nMy wife and I will be attending the picnic with our two children. We would like to take the company bus, so please save four seats for us. My wife is planning to bake a chocolate cake for everyone.\n\nAlso, I have a question. My daughter has a soccer game on the morning of August 30. If the picnic is postponed, we will probably arrive late. Would it still be possible for us to join in the afternoon?\n\nThanks,\nBrian Walsh\nAccounting Department"}],"questions":[{"q":"What is the notice mainly about?","choices":["A new bus route","A park renovation","A company event","A sports competition"],"answer":2,"type":"주제·목적","explanation":"공지는 직원과 가족을 초대하는 연례 직원 야유회(Annual Staff Picnic)의 날짜·장소·버스 안내를 담고 있으므로 회사 행사에 관한 것이다. 버스는 행사 교통편으로만 언급되었다."},{"q":"What are employees encouraged to bring?","choices":["Games for children","A dessert","Drinks","Folding chairs"],"answer":1,"type":"세부 사항","explanation":"공지의 'employees are welcome to bring a dessert to share'에서 나눠 먹을 디저트를 가져와도 좋다고 했다. 음식과 음료는 회사가 제공한다."},{"q":"What is one purpose of Mr. Walsh's e-mail?","choices":["To volunteer to organize games","To ask about the lunch menu","To announce a department change","To reserve bus seats"],"answer":3,"type":"주제·목적","explanation":"이메일의 'We would like to take the company bus, so please save four seats for us.'에서 버스 좌석 네 개를 예약하려는 목적이 드러난다. 또 다른 목적은 연기될 경우 늦게 합류해도 되는지 묻는 것이다."},{"q":"Under what condition might Mr. Walsh's family arrive late?","choices":["If the bus leaves early","If it rains on August 23","If lunch is served at noon","If his daughter's game is canceled"],"answer":1,"type":"연계 문제","explanation":"공지에 따르면 비가 오면 야유회가 8월 30일로 옮겨지고, 이메일에서 월시 씨는 딸의 축구 경기가 8월 30일 오전에 있어 연기되면 늦을 것이라고 했다. 따라서 8월 23일에 비가 오는 경우 늦게 도착할 수 있다."},{"q":"At what time should Mr. Walsh's family be at the main office parking lot on August 23?","choices":["By 10:15 A.M.","By 11:00 A.M.","By 12:00 P.M.","By 1:30 P.M."],"answer":0,"type":"연계 문제","explanation":"이메일에서 월시 씨 가족은 회사 버스를 타겠다고 했고, 공지에 버스가 본사 주차장에서 오전 10시 15분에 출발한다고 나와 있다. 11시는 야유회 시작, 정오는 점심, 1시 30분은 어린이 게임 시작 시각이다."}],"translation":"[공지]\n연례 직원 야유회\n\n날짜: 8월 23일 토요일\n시간: 오전 11:00 – 오후 4:00\n장소: 레이크사이드 공원 3구역\n\n모든 직원과 가족을 올해 직원 야유회에 초대합니다. 점심은 정오에 제공되고, 어린이 게임은 오후 1시 30분에 시작합니다. 음식과 음료는 회사가 제공하지만, 함께 나눠 먹을 디저트를 가져오셔도 좋습니다. 버스가 오전 10시 15분에 본사 주차장에서 출발합니다. 버스를 이용하실 분은 8월 15일까지 인사부 샌드라 콜 씨에게 알려 주십시오. 비가 오면 야유회는 8월 30일 토요일로 옮겨집니다.\n\n[이메일]\n보낸 사람: 브라이언 월시 / 받는 사람: 샌드라 콜 / 날짜: 8월 12일 / 제목: 직원 야유회\n\n안녕하세요, 샌드라.\n\n아내와 저는 두 아이와 함께 야유회에 참석합니다. 회사 버스를 타고 싶으니 네 자리를 맡아 주세요. 아내가 모두를 위해 초콜릿 케이크를 구울 계획입니다.\n\n그리고 질문이 하나 있습니다. 딸아이가 8월 30일 오전에 축구 경기가 있어요. 야유회가 연기되면 저희는 아마 늦게 도착할 겁니다. 그래도 오후에 합류할 수 있을까요?\n\n감사합니다.\n브라이언 월시\n회계부","part":7},{"id":"p7-012","level":2,"kind":"triple","passages":[{"doc_type":"웹페이지","title":"www.officeplus.com/chairs","text":"Office Plus — Ergonomic Chairs\n\nModel | Features | Price\nBasic C100 | Adjustable height | $120\nComfort C200 | Adjustable height, armrests | $180\nPro C300 | Adjustable height, armrests, back support | $250\nExecutive C400 | All Pro features, leather seat | $340\n\nFree delivery on all orders over $500. All chairs come with a two-year warranty. Business customers ordering ten or more chairs at once receive a 15 percent discount. Most orders are delivered within one week. For large orders, please contact our sales team."},{"doc_type":"주문 확인서","title":"Order Confirmation — Order number 58213","text":"Order Confirmation\nOrder number: 58213\nCustomer: Hanley Design Studio\nOrder date: October 2\n\nItem | Quantity | Unit Price\nPro C300 | 4 | $250\n\nSubtotal: $1,000\nDelivery: Free\nExpected delivery date: October 9\n\nNotes: Assembly instructions are included in each box. Please inspect all items upon arrival and report any damage or defects to customerservice@officeplus.com. Items covered by the warranty will be replaced free of charge, and we will arrange pickup of the defective item. Thank you for shopping with Office Plus."},{"doc_type":"이메일","title":"From: Olivia Hanley / To: customerservice@officeplus.com / Date: October 10 / Subject: Order 58213","text":"Hello,\n\nWe received our chairs yesterday as promised, and my designers are very pleased with them. However, one of the chairs has a problem. The back support does not stay in position and slowly moves down during the day. Since the chairs are still under warranty, I would like a replacement. Please let me know when someone can pick up the broken chair.\n\nI am also thinking of ordering six more of the same model for our new employees next month.\n\nOlivia Hanley"}],"questions":[{"q":"What is indicated about Office Plus?","choices":["It charges for all deliveries.","It offers discounts to some business customers.","It sells only leather chairs.","It gives a five-year warranty."],"answer":1,"type":"사실 확인(NOT/TRUE)","explanation":"웹페이지의 'Business customers ordering ten or more chairs at once receive a 15 percent discount.'와 일치한다. 500달러 초과 주문은 무료 배송이고, 보증 기간은 2년이다."},{"q":"What feature does the chair Ms. Hanley ordered have that the Comfort C200 does not?","choices":["Adjustable height","Armrests","Back support","A leather seat"],"answer":2,"type":"연계 문제","explanation":"주문 확인서에서 핸리 씨는 Pro C300을 주문했고, 웹페이지 표에서 Pro C300은 Comfort C200의 기능(높이 조절, 팔걸이)에 등받이 지지(back support)가 더해진 모델이다. 가죽 시트는 Executive C400에만 있다."},{"q":"Why was delivery free for Ms. Hanley's order?","choices":["She ordered ten or more chairs.","She is a new customer.","She used a coupon.","Her order was over $500."],"answer":3,"type":"연계 문제","explanation":"웹페이지에 500달러 초과 주문은 무료 배송이라고 했고, 주문 확인서의 합계가 1,000달러이다. 의자는 4개만 주문했으므로 10개 이상 조건과는 관계없다."},{"q":"What does Ms. Hanley request in her e-mail?","choices":["A refund","A product catalog","A replacement chair","A discount on her next order"],"answer":2,"type":"세부 사항","explanation":"이메일의 'Since the chairs are still under warranty, I would like a replacement.'에서 보증 기간이므로 교체를 원한다고 했다. 환불이나 할인은 요청하지 않았다."},{"q":"What will Ms. Hanley most likely receive if she places the order mentioned in her e-mail?","choices":["A 15 percent discount","Free delivery","A free leather seat","A longer warranty"],"answer":1,"type":"연계 문제","explanation":"이메일에서 같은 모델(Pro C300, 250달러) 6개를 더 주문할 생각이라고 했으므로 합계는 1,500달러로 500달러를 넘어 무료 배송 대상이다. 10개 미만이라 15퍼센트 할인은 받을 수 없다."}],"translation":"[웹페이지]\n오피스 플러스 — 인체공학 의자\n\n모델 | 기능 | 가격\n베이직 C100 | 높이 조절 | 120달러\n컴포트 C200 | 높이 조절, 팔걸이 | 180달러\n프로 C300 | 높이 조절, 팔걸이, 등받이 지지 | 250달러\n이그제큐티브 C400 | 프로의 모든 기능, 가죽 시트 | 340달러\n\n500달러를 넘는 모든 주문은 무료 배송입니다. 모든 의자는 2년 보증이 제공됩니다. 한 번에 10개 이상 주문하는 기업 고객은 15퍼센트 할인을 받습니다. 대부분의 주문은 일주일 안에 배송됩니다. 대량 주문은 영업팀에 문의해 주십시오.\n\n[주문 확인서]\n주문 확인서\n주문 번호: 58213\n고객: 핸리 디자인 스튜디오\n주문일: 10월 2일\n\n품목 | 수량 | 단가\n프로 C300 | 4 | 250달러\n\n소계: 1,000달러\n배송: 무료\n배송 예정일: 10월 9일\n\n참고: 조립 설명서는 상자마다 들어 있습니다. 도착 즉시 모든 제품을 확인하시고 파손이나 결함이 있으면 customerservice@officeplus.com으로 알려 주십시오. 보증 대상 제품은 무료로 교체해 드리며, 결함 제품의 회수도 저희가 준비합니다. 오피스 플러스를 이용해 주셔서 감사합니다.\n\n[이메일]\n보낸 사람: 올리비아 핸리 / 받는 사람: customerservice@officeplus.com / 날짜: 10월 10일 / 제목: 주문 58213\n\n안녕하세요.\n\n약속대로 어제 의자를 받았고, 저희 디자이너들이 매우 만족하고 있습니다. 그런데 의자 하나에 문제가 있습니다. 등받이 지지대가 제자리에 고정되지 않고 하루 동안 조금씩 내려갑니다. 아직 보증 기간이므로 교체를 원합니다. 고장 난 의자를 언제 가지러 오실 수 있는지 알려 주세요.\n\n또한 다음 달 신입 직원들을 위해 같은 모델을 6개 더 주문할까 생각하고 있습니다.\n\n올리비아 핸리","part":7},{"id":"p7-013","level":3,"kind":"single","passages":[{"doc_type":"편지","title":"Travel Horizons Magazine / 88 Bristol Lane, Portland, OR 97205 / To: Mr. Daniel Reeves","text":"Dear Mr. Reeves,\n\nThank you for being a loyal reader of Travel Horizons for the past three years. Our records show that your current subscription will end with the November issue. [1]\n\nIf you renew before October 31, you will pay only $36 for twelve issues, a savings of 40 percent off the newsstand price. [2] Renewing subscribers will also receive a free copy of our new guidebook, Hidden Villages of Europe, which will not be sold in stores until next spring.\n\nStarting in January, every issue will include a special section on budget travel, featuring tips from readers around the world. [3] You can also access all past issues on our Web site at no extra cost.\n\nTo renew, simply complete the enclosed card and return it in the postage-paid envelope. [4] We look forward to sharing many more journeys with you.\n\nSincerely,\nAmanda Brooks\nCirculation Manager"}],"questions":[{"q":"Why was the letter sent?","choices":["To announce a price increase","To request payment for an overdue bill","To encourage a reader to renew a subscription","To advertise a travel agency"],"answer":2,"type":"주제·목적","explanation":"첫 문단에서 구독이 11월호로 끝난다고 알린 뒤 갱신 시 할인 가격과 무료 가이드북을 제시하고 갱신 방법을 안내하므로 구독 갱신을 권유하는 편지이다. 오히려 40퍼센트 할인을 제시하므로 가격 인상 안내가 아니다."},{"q":"What is indicated about Hidden Villages of Europe?","choices":["It was written by Ms. Brooks.","It will be available in stores next spring.","It is currently sold at newsstands.","It focuses on budget travel."],"answer":1,"type":"사실 확인(NOT/TRUE)","explanation":"두 번째 문단 'which will not be sold in stores until next spring'은 내년 봄이 되어야 서점에서 판매된다는 뜻이다. 현재는 판매되지 않으며, 저가 여행 특집은 1월부터 잡지에 실리는 별도 코너이다."},{"q":"What will change in January?","choices":["The magazine will cost less.","Past issues will be removed online.","The magazine will be published twice a month.","Each issue will include a new section."],"answer":3,"type":"세부 사항","explanation":"세 번째 문단 'Starting in January, every issue will include a special section on budget travel'에서 1월부터 매호에 저가 여행 특집 코너가 추가된다고 했다. 지난 호는 웹사이트에서 계속 무료로 볼 수 있다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? “This offer is available only to current subscribers.”","choices":["[1]","[2]","[3]","[4]"],"answer":1,"type":"문장 삽입","explanation":"'This offer'가 가리키는 대상이 필요하므로 12개월호 36달러, 40퍼센트 할인이라는 제안 바로 뒤인 [2]가 알맞다. 기존 구독자만 받을 수 있다는 조건도 갱신 할인과 자연스럽게 이어진다."}],"translation":"트래블 호라이즌스 매거진 / 오리건주 포틀랜드 브리스톨 레인 88 / 받는 사람: 대니얼 리브스 님\n\n리브스 님께,\n\n지난 3년 동안 트래블 호라이즌스를 꾸준히 읽어 주셔서 감사합니다. 저희 기록에 따르면 현재 구독은 11월호로 종료됩니다. [1]\n\n10월 31일 전에 갱신하시면 12개 호를 단 36달러에 받으실 수 있으며, 이는 가판대 가격보다 40퍼센트 저렴합니다. [2] 갱신하시는 구독자께는 저희의 새 가이드북 '유럽의 숨은 마을들'도 무료로 드리는데, 이 책은 내년 봄에야 서점에서 판매됩니다.\n\n1월부터는 매호에 전 세계 독자들의 팁을 담은 저가 여행 특집 코너가 실립니다. [3] 또한 웹사이트에서 지난 호 전체를 추가 비용 없이 보실 수 있습니다.\n\n갱신하시려면 동봉된 카드를 작성하여 우편 요금이 선납된 봉투에 넣어 보내 주시기만 하면 됩니다. [4] 앞으로도 더 많은 여행을 함께하기를 기대합니다.\n\n어맨다 브룩스 드림\n구독 관리 책임자","part":7},{"id":"p7-014","level":3,"kind":"single","passages":[{"doc_type":"문자 메시지","title":"Text-message chain","text":"Ryan Cho (8:47 A.M.): Hi, Nadia. I'm stuck in traffic on Route 9. There's been an accident near the bridge.\nNadia Farouk (8:48 A.M.): Oh no. The Delgado Foods representatives are arriving at 9:30.\nRyan Cho (8:50 A.M.): I know. My GPS says I won't get there until 9:45 at the earliest.\nNadia Farouk (8:51 A.M.): I can start the tour of the production line without you. It usually takes about 30 minutes anyway.\nRyan Cho (8:52 A.M.): That would be a big help. The sample packages are on my desk, in the blue box.\nNadia Farouk (8:53 A.M.): Got it. Should I also give them the new price list?\nRyan Cho (8:55 A.M.): Let's hold off on that. I'd like to discuss pricing with them myself after the tour.\nNadia Farouk (8:56 A.M.): Understood. Drive safely."}],"questions":[{"q":"Why is Mr. Cho late?","choices":["He is caught in heavy traffic.","His car broke down.","He missed a train.","He had to pick up samples."],"answer":0,"type":"세부 사항","explanation":"첫 메시지 'I'm stuck in traffic on Route 9. There's been an accident near the bridge.'에서 사고로 인한 교통 체증 때문에 늦는다는 것을 알 수 있다. 샘플은 이미 그의 책상 위에 있다."},{"q":"What will Ms. Farouk most likely do at 9:30?","choices":["Lead a tour for visitors","Meet Mr. Cho at the bridge","Print a price list","Call Delgado Foods"],"answer":0,"type":"추론","explanation":"델가도 푸드 담당자들이 9시 30분에 도착하고, 파루크 씨가 8시 51분에 'I can start the tour of the production line without you.'라고 제안했으며 조 씨가 수락했다. 따라서 9시 30분에는 방문객에게 생산 라인 견학을 안내할 것이다."},{"q":"At 8:55 A.M., what does Mr. Cho mean when he writes, “Let's hold off on that”?","choices":["He wants the tour to be shortened.","He wants to postpone the meeting until tomorrow.","He does not want the price list shared yet.","He wants the samples kept on his desk."],"answer":2,"type":"의도 파악","explanation":"파루크 씨가 새 가격표도 전달할지 묻자 조 씨는 'Let's hold off on that'이라고 한 뒤 견학 후 직접 가격을 논의하겠다고 했다. 즉 가격표 전달을 미루자는 뜻이다."}],"translation":"라이언 조 (오전 8:47): 안녕하세요, 나디아. 9번 도로에서 차가 막혀 꼼짝 못 하고 있어요. 다리 근처에서 사고가 났대요.\n나디아 파루크 (오전 8:48): 이런. 델가도 푸드 담당자들이 9시 30분에 도착하는데요.\n라이언 조 (오전 8:50): 알아요. 내비게이션으로는 빨라도 9시 45분에나 도착한대요.\n나디아 파루크 (오전 8:51): 제가 먼저 생산 라인 견학을 시작할 수 있어요. 어차피 보통 30분쯤 걸리니까요.\n라이언 조 (오전 8:52): 그러면 정말 큰 도움이 되겠어요. 샘플 패키지는 제 책상 위 파란 상자에 있어요.\n나디아 파루크 (오전 8:53): 알겠어요. 새 가격표도 드릴까요?\n라이언 조 (오전 8:55): 그건 좀 미뤄 두죠. 견학이 끝난 뒤 가격은 제가 직접 이야기하고 싶어요.\n나디아 파루크 (오전 8:56): 알겠어요. 조심히 운전하세요.","part":7},{"id":"p7-015","level":3,"kind":"single","passages":[{"doc_type":"웹페이지","title":"www.norvellbank.com/community","text":"Norvell Bank Community Partners Program\n\nAt Norvell Bank, we believe that strong communities make strong businesses. Through our Community Partners Program, employees can spend up to sixteen paid hours per year volunteering with approved local organizations.\n\nEligible activities include tutoring students, helping at food banks, and assisting with park clean-ups. Employees who wish to volunteer must submit a request form to their supervisor at least two weeks before the activity date. Requests are generally approved as long as the absence will not affect customer service at the employee's branch.\n\nIn addition, the bank will donate $10 to the organization for every hour an employee volunteers there. Last year, our staff contributed more than 4,200 hours to over 90 organizations across the region.\n\nOrganizations interested in becoming approved partners may apply by completing the online form on this page. Applications are reviewed by our Community Relations team each quarter."}],"questions":[{"q":"What is the purpose of the Web page?","choices":["To describe a volunteer program","To advertise a new savings account","To announce a branch opening","To recruit new bank tellers"],"answer":0,"type":"주제·목적","explanation":"웹페이지는 직원들이 유급으로 지역 단체에서 봉사할 수 있는 Community Partners Program의 내용, 신청 절차, 기부 방식을 설명한다. 금융 상품이나 채용 안내가 아니다."},{"q":"The word “affect” in paragraph 2, line 4, is closest in meaning to","choices":["pretend","receive","prefer","influence"],"answer":3,"type":"동의어","explanation":"'as long as the absence will not affect customer service'는 결근이 고객 서비스에 '영향을 주지' 않는 한이라는 뜻이므로 influence가 가장 가깝다."},{"q":"What is NOT mentioned as an eligible activity?","choices":["Tutoring students","Cleaning parks","Building houses","Working at food banks"],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"두 번째 문단에서 학생 개인 지도(tutoring students), 푸드뱅크 봉사(helping at food banks), 공원 청소(park clean-ups)는 언급되었지만 집 짓기는 나오지 않는다."},{"q":"What can be inferred about Norvell Bank?","choices":["It requires all employees to volunteer.","It gave over $40,000 to organizations last year.","It reviews partner applications every month.","It works only with national charities."],"answer":1,"type":"추론","explanation":"봉사 1시간당 10달러를 기부하고 작년 직원 봉사 시간이 4,200시간을 넘었으므로 기부액은 4만 2천 달러 이상이다. 봉사는 희망자만 신청하고, 신청서 검토는 분기마다(each quarter) 하며, 지역 단체와 협력한다."}],"translation":"www.norvellbank.com/community\n노벨 은행 지역사회 파트너 프로그램\n\n노벨 은행은 튼튼한 지역사회가 튼튼한 기업을 만든다고 믿습니다. 지역사회 파트너 프로그램을 통해 직원들은 1년에 최대 16시간까지 유급으로 승인된 지역 단체에서 봉사할 수 있습니다.\n\n참여 가능한 활동에는 학생 개인 지도, 푸드뱅크 봉사, 공원 청소 지원 등이 있습니다. 봉사를 원하는 직원은 활동일 최소 2주 전에 상사에게 신청서를 제출해야 합니다. 신청은 해당 직원의 부재가 소속 지점의 고객 서비스에 영향을 주지 않는 한 대체로 승인됩니다.\n\n또한 은행은 직원이 봉사한 시간 1시간마다 해당 단체에 10달러를 기부합니다. 작년에 저희 직원들은 지역 내 90개가 넘는 단체에서 4,200시간 이상 봉사했습니다.\n\n승인된 파트너가 되고자 하는 단체는 이 페이지의 온라인 양식을 작성하여 신청하실 수 있습니다. 신청서는 지역사회 관계팀이 분기마다 검토합니다.","part":7},{"id":"p7-016","level":3,"kind":"single","passages":[{"doc_type":"이메일","title":"From: Henry Lau, Crestline Paper Supply / To: Joanna Whitfield / Date: February 6 / Subject: Order #4471","text":"Dear Ms. Whitfield,\n\nI am writing about your order of 300 boxes of recycled printer paper, which was scheduled to arrive at your office on February 10. [1] Unfortunately, our paper mill has experienced equipment problems, and production has been delayed by about a week. [2]\n\nWe expect to ship your order on February 15, so it should reach you by February 17. If this new date is not acceptable, we can offer two alternatives. First, we could send 100 boxes from our current stock immediately and the remaining 200 once production resumes. [3] Second, we could substitute standard white paper of the same weight, which is in stock, at no extra charge.\n\nPlease let me know which option you prefer by February 8. [4] I apologize for the inconvenience and appreciate your patience.\n\nSincerely,\nHenry Lau\nCustomer Accounts Manager"}],"questions":[{"q":"Why did Mr. Lau write the e-mail?","choices":["To report a delay in an order","To confirm a price change","To request an overdue payment","To introduce a new product"],"answer":0,"type":"주제·목적","explanation":"첫 문단에서 2월 10일 도착 예정이던 주문이 제지 공장 설비 문제로 약 일주일 지연된다고 알리고 있다. 가격 변경이나 결제 요청은 언급되지 않았다."},{"q":"What is one option Mr. Lau offers?","choices":["A full refund","A discount on a future order","Faster delivery by air","A different type of paper"],"answer":3,"type":"세부 사항","explanation":"두 번째 대안 'we could substitute standard white paper of the same weight'에서 재고가 있는 일반 백색 용지로 대체해 주겠다고 했다. 환불, 할인, 항공 배송은 제안하지 않았다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? “There would be no additional delivery fee for the second shipment.”","choices":["[1]","[2]","[3]","[4]"],"answer":2,"type":"문장 삽입","explanation":"'the second shipment(두 번째 배송분)'가 성립하려면 앞에 배송을 두 번으로 나누는 내용이 있어야 한다. 100상자를 먼저 보내고 나머지 200상자는 생산 재개 후 보낸다는 첫 번째 대안 바로 뒤인 [3]이 알맞다."}],"translation":"보낸 사람: 크레스트라인 제지 공급 헨리 라우 / 받는 사람: 조애나 휘트필드 / 날짜: 2월 6일 / 제목: 주문 번호 4471\n\n휘트필드 님께,\n\n2월 10일 귀하의 사무실에 도착할 예정이었던 재생 프린터 용지 300상자 주문과 관련하여 연락드립니다. [1] 안타깝게도 저희 제지 공장에 설비 문제가 생겨 생산이 약 일주일 지연되었습니다. [2]\n\n주문품은 2월 15일에 발송될 예정이며 2월 17일까지는 도착할 것입니다. 이 새 날짜가 곤란하시면 두 가지 대안을 드릴 수 있습니다. 첫째, 현재 재고에서 100상자를 즉시 보내 드리고 나머지 200상자는 생산이 재개되는 대로 보내 드릴 수 있습니다. [3] 둘째, 재고가 있는 같은 무게의 일반 백색 용지로 추가 비용 없이 대체해 드릴 수 있습니다.\n\n어느 방법을 원하시는지 2월 8일까지 알려 주십시오. [4] 불편을 드려 죄송하며 양해해 주셔서 감사합니다.\n\n헨리 라우 드림\n고객 계정 관리자","part":7},{"id":"p7-017","level":3,"kind":"double","passages":[{"doc_type":"광고","title":"Kenwood Business Writing Workshops","text":"Kenwood Business Writing Workshops\n\nImprove the way you communicate at work! Our one-day workshops are led by experienced corporate trainers, and each is limited to 15 participants.\n\n• Writing Clear E-mails — Tuesday, March 8\n• Reports and Proposals — Tuesday, March 15\n• Persuasive Presentations — Tuesday, March 22\n• Editing Your Own Work — Tuesday, March 29\n\nAll workshops run from 9:00 A.M. to 4:00 P.M. at the Kenwood Center, 210 Grant Street. The fee is $180 per workshop, which includes lunch and course materials. Companies registering five or more employees for the same workshop receive a group rate of $150 per person. Register at www.kenwoodworkshops.com."},{"doc_type":"이메일","title":"From: Lisa Tran / To: info@kenwoodworkshops.com / Date: March 1 / Subject: Registration question","text":"Hello,\n\nI manage the sales team at Pellman Industries. Six of my team members would like to attend your workshop on preparing reports and proposals. However, two of them will be at a trade show in Chicago that week and will not return until March 17. Would it be possible for those two employees to attend the same workshop at a later date? If so, could the group rate still apply to all six people even if they attend on different days?\n\nI would also like to know whether parking is available at the Kenwood Center.\n\nBest regards,\nLisa Tran"}],"questions":[{"q":"What is stated about the workshops?","choices":["They take place over several days.","They have a limited number of participants.","They are held online.","They are free for groups."],"answer":1,"type":"사실 확인(NOT/TRUE)","explanation":"광고의 'each is limited to 15 participants'에서 인원이 15명으로 제한된다고 했다. 워크숍은 하루 과정(one-day)이고 켄우드 센터에서 열리며, 단체는 무료가 아니라 1인당 150달러이다."},{"q":"In the advertisement, the word “run” in paragraph 3, line 1, is closest in meaning to","choices":["hurry","manage","last","compete"],"answer":2,"type":"동의어","explanation":"'All workshops run from 9:00 A.M. to 4:00 P.M.'은 워크숍이 오전 9시부터 오후 4시까지 '진행된다, 계속된다'는 뜻이므로 last가 가장 가깝다. hurry(서두르다), manage(운영하다), compete(경쟁하다)는 문맥에 맞지 않는다."},{"q":"On what date do Ms. Tran's team members want to attend a workshop?","choices":["March 8","March 15","March 22","March 29"],"answer":1,"type":"연계 문제","explanation":"이메일에서 트랜 씨 팀원들은 보고서·제안서 작성(preparing reports and proposals) 워크숍을 원한다고 했고, 광고에서 Reports and Proposals 워크숍은 3월 15일에 열린다."},{"q":"Why might two of Ms. Tran's employees be unable to attend?","choices":["They have already taken the workshop.","They have to meet clients.","They will be attending a trade show.","They will be on vacation."],"answer":2,"type":"세부 사항","explanation":"이메일의 'two of them will be at a trade show in Chicago that week'에서 두 명이 그 주에 시카고 무역 박람회에 가 있다고 했다."},{"q":"Why might Ms. Tran's request be difficult to fulfill?","choices":["The workshops are already fully booked.","The group rate requires ten participants.","The Kenwood Center does not have parking.","The workshop she wants is scheduled only once in March."],"answer":3,"type":"연계 문제","explanation":"트랜 씨는 두 명이 3월 17일 이후 같은 워크숍을 듣게 해 달라고 요청했지만, 광고 일정상 Reports and Proposals 워크숍은 3월 15일 한 번뿐이다. 단체 요금은 5명 이상이면 되고, 주차 여부는 광고에 나와 있지 않다."}],"translation":"[광고]\n켄우드 비즈니스 글쓰기 워크숍\n\n직장에서의 소통 방식을 개선하세요! 저희 1일 워크숍은 경험 많은 기업 강사가 진행하며, 회차마다 참가 인원은 15명으로 제한됩니다.\n\n• 명확한 이메일 쓰기 — 3월 8일 화요일\n• 보고서와 제안서 — 3월 15일 화요일\n• 설득력 있는 프레젠테이션 — 3월 22일 화요일\n• 자기 글 편집하기 — 3월 29일 화요일\n\n모든 워크숍은 그랜트 가 210번지 켄우드 센터에서 오전 9시부터 오후 4시까지 진행됩니다. 수강료는 워크숍당 180달러이며 점심과 교재가 포함됩니다. 같은 워크숍에 직원 5명 이상을 등록하는 회사는 1인당 150달러의 단체 요금을 적용받습니다. www.kenwoodworkshops.com에서 등록하세요.\n\n[이메일]\n보낸 사람: 리사 트랜 / 받는 사람: info@kenwoodworkshops.com / 날짜: 3월 1일 / 제목: 등록 문의\n\n안녕하세요.\n\n저는 펠먼 인더스트리의 영업팀을 관리하고 있습니다. 저희 팀원 6명이 보고서·제안서 작성 워크숍에 참석하고 싶어 합니다. 그런데 그중 2명은 그 주에 시카고의 무역 박람회에 가 있어서 3월 17일에야 돌아옵니다. 이 두 직원이 나중에 같은 워크숍을 들을 수 있을까요? 가능하다면 서로 다른 날 참석하더라도 6명 모두에게 단체 요금을 적용받을 수 있을까요?\n\n켄우드 센터에 주차가 가능한지도 알고 싶습니다.\n\n리사 트랜 드림","part":7},{"id":"p7-018","level":3,"kind":"triple","passages":[{"doc_type":"회람","title":"To: All Staff / From: Facilities Management / Date: June 2 / Subject: Move to the Oakridge Tower","text":"MEMO\n\nAs announced, our company will relocate to the Oakridge Tower over the next four weeks. Each department will move according to the schedule below. Please pack your personal items and files in the boxes provided by 5:00 P.M. on the Thursday before your move. Movers will transport all boxes and furniture on Friday evening, and your new workspace will be ready the following Monday.\n\nDepartment | Moving date (Friday)\nAccounting | June 13\nMarketing | June 20\nHuman Resources | June 20\nCustomer Support | June 27"},{"doc_type":"이메일","title":"From: Carlos Mendes / To: Facilities Management / Date: June 10 / Subject: Moving schedule","text":"Hello,\n\nI'm writing on behalf of the Marketing Department. We are hosting a major product launch event on June 21, and several team members will need access to their files and computers until late on June 20. Our team has been preparing for this launch for several months, and moving the day before would make it very difficult to complete our final preparations. Would it be possible for our department to move with Customer Support instead? We would be happy to pack everything well in advance of that date.\n\nThank you,\nCarlos Mendes\nMarketing Manager"},{"doc_type":"이메일","title":"From: Irene Walsh / To: Carlos Mendes / Date: June 11 / Subject: RE: Moving schedule","text":"Dear Mr. Mendes,\n\nThank you for letting us know about your event. We have arranged for your department to move on the same date as Customer Support, as you requested. Please note that the movers will arrive at 6:00 P.M., so all of your boxes must be labeled with your new floor number, 14, before then. Human Resources will still move on its original date.\n\nIf you need additional boxes, please contact my assistant, Paul Diaz, at extension 3310.\n\nBest regards,\nIrene Walsh\nFacilities Management"}],"questions":[{"q":"What is the purpose of the memo?","choices":["To announce a new office manager","To explain a relocation schedule","To request volunteers for an event","To describe new office furniture"],"answer":1,"type":"주제·목적","explanation":"회람은 회사가 오크리지 타워로 이전한다는 사실과 부서별 이사 날짜, 짐 싸기 기한을 안내한다. 따라서 이전 일정 안내가 목적이다."},{"q":"According to the memo, when will employees be able to use their new workspace?","choices":["On the Thursday before their move","On the Friday evening of their move","On the Monday after their move","Four weeks after the memo"],"answer":2,"type":"세부 사항","explanation":"회람의 'your new workspace will be ready the following Monday'에서 이사한 금요일 다음 월요일에 새 업무 공간을 쓸 수 있다고 했다. 목요일은 짐 싸기 기한, 금요일 저녁은 운반 시간이다."},{"q":"Why does Mr. Mendes make his request?","choices":["His department needs more boxes.","He will be on vacation on June 20.","His team is moving to a different floor.","His team is preparing for an event."],"answer":3,"type":"세부 사항","explanation":"멘데스 씨는 6월 21일 대규모 제품 출시 행사가 있어 팀원들이 6월 20일 늦게까지 파일과 컴퓨터를 써야 한다고 했다. 즉 행사 준비 때문에 이사 날짜 변경을 요청했다."},{"q":"On what date will the Marketing Department move?","choices":["June 27","June 13","June 20","June 21"],"answer":0,"type":"연계 문제","explanation":"답장 이메일에서 마케팅부는 고객지원부와 같은 날 이사하게 되었다고 했고, 회람 일정표에서 고객지원부의 이사 날짜는 6월 27일이다. 6월 20일은 원래 날짜이며 인사부는 그대로 이 날 이사한다."},{"q":"By when must the Marketing Department finish packing?","choices":["5:00 P.M. on June 19","5:00 P.M. on June 26","6:00 P.M. on June 27","9:00 A.M. on June 30"],"answer":1,"type":"연계 문제","explanation":"회람에 따르면 이사 전 목요일 오후 5시까지 짐을 싸야 하고, 답장에서 마케팅부는 6월 27일(금)에 이사하게 되었다. 따라서 기한은 6월 26일(목) 오후 5시이다. 오후 6시는 이사 업체가 도착하는 시각이다."}],"translation":"[회람]\n받는 사람: 전 직원 / 보낸 사람: 시설관리부 / 날짜: 6월 2일 / 제목: 오크리지 타워로 이전\n\n공지한 대로 우리 회사는 앞으로 4주에 걸쳐 오크리지 타워로 이전합니다. 각 부서는 아래 일정에 따라 이사합니다. 이사 전 목요일 오후 5시까지 제공된 상자에 개인 물품과 파일을 싸 주십시오. 이사 업체가 금요일 저녁에 모든 상자와 가구를 옮기며, 새 업무 공간은 그다음 월요일에 준비됩니다.\n\n부서 | 이사 날짜(금요일)\n회계부 | 6월 13일\n마케팅부 | 6월 20일\n인사부 | 6월 20일\n고객지원부 | 6월 27일\n\n[이메일 1]\n보낸 사람: 카를로스 멘데스 / 받는 사람: 시설관리부 / 날짜: 6월 10일 / 제목: 이사 일정\n\n안녕하세요.\n\n마케팅부를 대표해 연락드립니다. 저희는 6월 21일에 대규모 제품 출시 행사를 여는데, 팀원 몇 명이 6월 20일 늦게까지 파일과 컴퓨터를 써야 합니다. 저희 팀은 몇 달 동안 이 출시를 준비해 왔는데, 행사 전날 이사하면 마지막 준비를 마치기가 매우 어려워집니다. 저희 부서가 대신 고객지원부와 함께 이사할 수 있을까요? 그 날짜보다 훨씬 전에 모든 짐을 싸 두겠습니다.\n\n감사합니다.\n카를로스 멘데스\n마케팅부장\n\n[이메일 2]\n보낸 사람: 아이린 월시 / 받는 사람: 카를로스 멘데스 / 날짜: 6월 11일 / 제목: 회신: 이사 일정\n\n멘데스 님께,\n\n행사에 대해 알려 주셔서 감사합니다. 요청하신 대로 귀 부서가 고객지원부와 같은 날 이사하도록 조정했습니다. 이사 업체가 오후 6시에 도착하므로, 그 전에 모든 상자에 새 층 번호인 14를 표시해 두셔야 합니다. 인사부는 원래 날짜에 그대로 이사합니다.\n\n상자가 더 필요하시면 제 비서 폴 디아즈(내선 3310)에게 연락해 주십시오.\n\n아이린 월시 드림\n시설관리부","part":7},{"id":"p7-019","level":4,"kind":"single","passages":[{"doc_type":"기사","title":"Halvorsen Logistics to Acquire Coastal Freight","text":"OSLO (September 9) — Halvorsen Logistics announced on Monday that it has reached an agreement to acquire Coastal Freight, a regional shipping company based in Bergen, for an undisclosed sum. The deal is expected to be finalized by the end of the year, pending approval from government regulators. [1]\n\nFounded in 1987, Coastal Freight operates a fleet of 40 cargo vessels serving ports along Norway's western coast. [2] Halvorsen, which has traditionally focused on trucking and warehouse services, has been seeking to expand into sea transport for several years. “Combining our road network with Coastal Freight's shipping routes will allow us to offer customers a truly complete service,” said Halvorsen CEO Ingrid Solberg.\n\nCoastal Freight's 650 employees will keep their positions, according to the announcement, and the company will continue to operate under its own name for at least two years. [3] Its current director, Magnus Eide, will join Halvorsen's board.\n\nIndustry analysts reacted positively to the news. [4] “Halvorsen has long been strong on land but vulnerable at sea,” noted Tove Lindqvist of Nordic Market Watch. “This purchase fills that gap.”"}],"questions":[{"q":"What is the article mainly about?","choices":["The opening of a new port","A business acquisition","A government decision on shipping rules","The retirement of a company director"],"answer":1,"type":"주제·목적","explanation":"첫 문장에서 할보르센 로지스틱스가 코스탈 프레이트를 인수하기로 합의했다고 밝히고, 기사 전체가 이 인수 건을 다룬다. 정부 규제 당국은 승인 절차로만 언급되었고, 에이데 대표는 은퇴가 아니라 이사회에 합류한다."},{"q":"The word “finalized” in paragraph 1, line 3, is closest in meaning to","choices":["reported","delayed","completed","opposed"],"answer":2,"type":"동의어","explanation":"'The deal is expected to be finalized by the end of the year'는 거래가 연말까지 '마무리될' 것으로 예상된다는 뜻이므로 completed가 가장 가깝다."},{"q":"What is indicated about Coastal Freight?","choices":["Its employees will keep their jobs.","It will immediately change its name.","It was founded by Ms. Solberg.","It mainly provides trucking services."],"answer":0,"type":"사실 확인(NOT/TRUE)","explanation":"세 번째 문단 'Coastal Freight's 650 employees will keep their positions'와 일치한다. 최소 2년간 자체 이름을 유지하며, 트럭·창고 사업은 할보르센 쪽의 전통적 주력이고, 솔베르그는 할보르센 CEO이다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? “Shares of Halvorsen rose nearly 6 percent following the announcement.”","choices":["[1]","[2]","[3]","[4]"],"answer":3,"type":"문장 삽입","explanation":"주가 상승은 시장의 긍정적 반응을 보여 주는 내용이므로 'Industry analysts reacted positively to the news.' 바로 뒤인 [4]가 가장 자연스럽다. 이어지는 분석가의 호의적 발언과도 흐름이 맞는다."}],"translation":"할보르센 로지스틱스, 코스탈 프레이트 인수\n\n오슬로 (9월 9일) — 할보르센 로지스틱스는 월요일, 베르겐에 본사를 둔 지역 해운사 코스탈 프레이트를 비공개 금액에 인수하기로 합의했다고 발표했다. 이 거래는 정부 규제 당국의 승인을 거쳐 연말까지 마무리될 것으로 예상된다. [1]\n\n1987년에 설립된 코스탈 프레이트는 화물선 40척을 운영하며 노르웨이 서해안의 항구들을 운항한다. [2] 전통적으로 트럭 운송과 창고 서비스에 주력해 온 할보르센은 수년간 해상 운송 진출을 모색해 왔다. 할보르센의 잉그리드 솔베르그 CEO는 \"우리의 도로망과 코스탈 프레이트의 해운 노선을 결합하면 고객에게 진정으로 완전한 서비스를 제공할 수 있다\"고 말했다.\n\n발표에 따르면 코스탈 프레이트의 직원 650명은 자리를 유지하며, 회사는 최소 2년 동안 기존 이름으로 운영을 계속한다. [3] 현 대표 망누스 에이데는 할보르센 이사회에 합류한다.\n\n업계 분석가들은 이 소식에 긍정적으로 반응했다. [4] 노르딕 마켓 워치의 토베 린드크비스트는 \"할보르센은 오랫동안 육상에서는 강했지만 해상에서는 취약했다\"며 \"이번 인수로 그 공백이 메워진다\"고 말했다.","part":7},{"id":"p7-020","level":4,"kind":"single","passages":[{"doc_type":"온라인 채팅","title":"Online chat discussion","text":"Grace Kim [11:02 A.M.]: Has anyone heard back from the caterer about the retirement dinner for Mr. Hughes?\nOmar Patel [11:03 A.M.]: They called this morning. They can't do the salmon anymore—their supplier ran short.\nGrace Kim [11:04 A.M.]: That was his favorite dish. Did they suggest an alternative?\nOmar Patel [11:05 A.M.]: Grilled chicken or a vegetable pasta, same price per plate.\nLeah Novak [11:06 A.M.]: What about Bella Marina? They cater too, and seafood is their specialty.\nGrace Kim [11:07 A.M.]: We've already paid a deposit to the current caterer, though.\nLeah Novak [11:08 A.M.]: Good point. How much was it?\nGrace Kim [11:08 A.M.]: Thirty percent of the total. And it's non-refundable.\nOmar Patel [11:10 A.M.]: Then let's go with the chicken. I'll let them know today and ask whether they can add a seafood appetizer instead.\nLeah Novak [11:11 A.M.]: I'll update the menu cards once we hear back."}],"questions":[{"q":"What are the writers mainly discussing?","choices":["Changes to an event menu","The location of a dinner","A new supplier for their office","A replacement for Mr. Hughes"],"answer":0,"type":"주제·목적","explanation":"케이터링 업체가 연어 요리를 제공할 수 없게 되어 은퇴 기념 만찬 메뉴를 어떻게 바꿀지 논의하고 있다. 장소나 휴즈 씨의 후임은 언급되지 않았다."},{"q":"What problem does Mr. Patel report?","choices":["The price per plate has increased.","A restaurant is fully booked.","A deposit was not received.","A caterer cannot provide a dish."],"answer":3,"type":"세부 사항","explanation":"11시 3분에 파텔 씨가 'They can't do the salmon anymore—their supplier ran short.'라고 했다. 대체 메뉴는 같은 가격이라고 했으므로 가격 인상은 사실이 아니다."},{"q":"At 11:08 A.M., what does Ms. Novak most likely mean when she writes, “Good point”?","choices":["She thinks Bella Marina is too expensive.","She realizes that switching caterers could waste money.","She wants to request a refund.","She believes salmon is the best option."],"answer":1,"type":"의도 파악","explanation":"노박 씨가 다른 업체(벨라 마리나)를 제안하자 김 씨가 이미 현재 업체에 계약금을 냈다고 지적했고, 노박 씨는 'Good point'라며 수긍했다. 즉 업체를 바꾸면 계약금을 날릴 수 있다는 점을 인정한 것이며, 뒤이어 금액을 묻는 것도 그 근거이다."},{"q":"What will Mr. Patel most likely do next?","choices":["Print the menu cards","Visit Bella Marina","Contact the current caterer","Speak with Mr. Hughes"],"answer":2,"type":"추론","explanation":"11시 10분에 파텔 씨가 'I'll let them know today'라며 현재 업체에 닭고기 요리로 정했다고 알리고 해산물 전채 추가도 문의하겠다고 했다. 메뉴 카드 수정은 노박 씨가 맡았다."}],"translation":"그레이스 김 [오전 11:02]: 휴즈 씨 은퇴 기념 만찬 건으로 케이터링 업체에서 연락 온 분 있어요?\n오마르 파텔 [오전 11:03]: 오늘 아침에 전화 왔어요. 공급업체 물량이 부족해서 이제 연어 요리는 못 한대요.\n그레이스 김 [오전 11:04]: 그게 그분이 제일 좋아하는 요리였는데. 대안을 제시했어요?\n오마르 파텔 [오전 11:05]: 닭고기 구이나 채소 파스타요. 1인분 가격은 같고요.\n레아 노박 [오전 11:06]: 벨라 마리나는 어때요? 거기도 케이터링을 하고 해산물이 전문이에요.\n그레이스 김 [오전 11:07]: 그런데 지금 업체에 이미 계약금을 냈어요.\n레아 노박 [오전 11:08]: 맞는 말이네요. 얼마였어요?\n그레이스 김 [오전 11:08]: 전체의 30퍼센트요. 그리고 환불이 안 돼요.\n오마르 파텔 [오전 11:10]: 그럼 닭고기로 하죠. 오늘 업체에 알리고 대신 해산물 전채를 추가할 수 있는지 물어볼게요.\n레아 노박 [오전 11:11]: 답을 받으면 제가 메뉴 카드를 수정할게요.","part":7},{"id":"p7-021","level":4,"kind":"single","passages":[{"doc_type":"청구서","title":"Invoice — Brightway Cleaning Services","text":"INVOICE\nBrightway Cleaning Services\n412 Elm Street, Denver, CO 80203\n\nBill to: Parkside Dental Clinic, 77 Cole Avenue\nInvoice number: BC-2291\nInvoice date: April 30\nPayment due: May 30\n\nDate | Service | Amount\nApril 5 | Standard office cleaning | $220\nApril 12 | Standard office cleaning | $220\nApril 19 | Standard office cleaning + carpet shampoo (waiting room) | $360\nApril 26 | Standard office cleaning | $220\n\nSubtotal: $1,020\nLoyalty discount (5%): –$51\nTotal due: $969\n\nNotes: Payments received after the due date are subject to a $25 late fee. Starting in June, our standard cleaning rate will increase to $235 per visit because of higher supply costs. Clients who sign a twelve-month contract before May 31 will keep their current rate for the full contract period. Please contact our office manager, Dana Ruiz, at 303-555-0167 with any questions."}],"questions":[{"q":"What additional service did the clinic receive in April?","choices":["Carpet cleaning","Window washing","Floor waxing","Furniture repair"],"answer":0,"type":"세부 사항","explanation":"4월 19일 항목 'Standard office cleaning + carpet shampoo (waiting room)'에서 대기실 카펫 세척이 추가되었음을 알 수 있다."},{"q":"What can be inferred about Parkside Dental Clinic?","choices":["It has paid a late fee before.","It receives cleaning twice a week.","It is likely a long-term customer.","It has signed a twelve-month contract."],"answer":2,"type":"추론","explanation":"청구서에 'Loyalty discount (5%)'가 적용되어 있어 꾸준히 이용해 온 단골 고객임을 추론할 수 있다. 청소는 매주 한 번(5, 12, 19, 26일)이고, 연체료나 12개월 계약 체결 사실은 나오지 않는다."},{"q":"According to the invoice, how can the clinic avoid the price increase?","choices":["By paying the invoice early","By requesting fewer visits","By calling Ms. Ruiz before June","By signing a year-long contract by May 31"],"answer":3,"type":"세부 사항","explanation":"Notes의 'Clients who sign a twelve-month contract before May 31 will keep their current rate'에서 5월 31일 전에 12개월 계약을 맺으면 현재 요금이 유지된다고 했다. 루이즈 씨에게 전화하는 것은 문의 방법일 뿐이다."}],"translation":"청구서\n브라이트웨이 청소 서비스\n콜로라도주 덴버 엘름 가 412번지 (우편번호 80203)\n\n청구 대상: 파크사이드 치과, 콜 애비뉴 77번지\n청구서 번호: BC-2291\n발행일: 4월 30일\n납부 기한: 5월 30일\n\n날짜 | 서비스 | 금액\n4월 5일 | 기본 사무실 청소 | 220달러\n4월 12일 | 기본 사무실 청소 | 220달러\n4월 19일 | 기본 사무실 청소 + 카펫 세척(대기실) | 360달러\n4월 26일 | 기본 사무실 청소 | 220달러\n\n소계: 1,020달러\n단골 할인(5%): -51달러\n납부 총액: 969달러\n\n참고: 납부 기한 이후 받은 금액에는 25달러의 연체료가 부과됩니다. 6월부터 소모품 비용 상승으로 기본 청소 요금이 방문당 235달러로 인상됩니다. 5월 31일 전에 12개월 계약을 체결하는 고객은 계약 기간 내내 현재 요금을 유지합니다. 문의 사항은 사무장 다나 루이즈(303-555-0167)에게 연락해 주십시오.","part":7},{"id":"p7-022","level":4,"kind":"single","passages":[{"doc_type":"이메일","title":"From: Victor Almeida / To: All Warehouse Supervisors / Date: January 14 / Subject: Revised shift arrangements","text":"Dear Supervisors,\n\nAs you know, order volume at our Riverside warehouse has grown steadily over the past year, and our current two-shift system is no longer sufficient. [1] Beginning March 3, we will introduce a third shift running from 10:00 P.M. to 6:00 A.M., Monday through Friday.\n\nTo staff the new shift, we will first invite current employees to transfer voluntarily. [2] Those who move to the overnight shift will receive an additional $3 per hour on top of their regular wage. Any remaining positions will be filled through external hiring, which Human Resources expects to begin in early February.\n\nI am asking each of you to discuss this change with your teams before the end of the month and to submit the names of interested employees to me by January 31. [3] Please also let me know if you yourself would consider supervising the new shift, as we will need two supervisors to cover it.\n\nA detailed schedule and revised safety procedures for overnight work will be distributed next week. [4]\n\nRegards,\nVictor Almeida\nDirector of Operations"}],"questions":[{"q":"What is the main purpose of the e-mail?","choices":["To report a decline in orders","To introduce a new supervisor","To announce the addition of a work shift","To explain changes to safety rules"],"answer":2,"type":"주제·목적","explanation":"첫 문단에서 주문량 증가로 3월 3일부터 세 번째 근무조(야간조)를 도입한다고 알리고, 이후 인력 배치 방법을 설명한다. 주문은 감소가 아니라 증가했고, 안전 절차는 다음 주에 배포될 자료로만 언급되었다."},{"q":"The word “sufficient” in paragraph 1, line 2, is closest in meaning to","choices":["adequate","efficient","popular","flexible"],"answer":0,"type":"동의어","explanation":"'our current two-shift system is no longer sufficient'는 현재 2교대 체제로는 더 이상 '충분하지' 않다는 뜻이므로 adequate가 가장 가깝다. efficient(효율적인)는 형태가 비슷해 헷갈리기 쉬운 오답이다."},{"q":"What is NOT mentioned as a task for the supervisors?","choices":["Talking to their teams about the change","Submitting the names of interested staff","Interviewing outside candidates","Indicating their own interest in a role"],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"세 번째 문단에서 감독자에게 팀과 논의하기, 1월 31일까지 희망자 명단 제출하기, 본인의 야간조 감독 의향 알리기를 요청했다. 외부 채용은 인사부가 진행한다고 했을 뿐 감독자의 면접 업무는 언급되지 않았다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? “Priority will be given to those with at least one year of service.”","choices":["[1]","[2]","[3]","[4]"],"answer":1,"type":"문장 삽입","explanation":"근속 1년 이상인 사람에게 우선권을 준다는 문장은 기존 직원에게 자발적 전환 기회를 먼저 준다는 'we will first invite current employees to transfer voluntarily' 바로 뒤인 [2]에 들어가야 자연스럽다."}],"translation":"보낸 사람: 빅터 알메이다 / 받는 사람: 전 창고 감독자 / 날짜: 1월 14일 / 제목: 근무조 편성 변경\n\n감독자 여러분께,\n\n아시다시피 리버사이드 창고의 주문량이 지난 1년간 꾸준히 늘어 현재의 2교대 체제로는 더 이상 충분하지 않습니다. [1] 3월 3일부터 월요일부터 금요일까지 오후 10시부터 오전 6시까지 운영되는 세 번째 근무조를 도입합니다.\n\n새 근무조의 인력을 채우기 위해 먼저 기존 직원들에게 자발적 전환 신청을 받겠습니다. [2] 야간조로 옮기는 직원은 기본 시급에 더해 시간당 3달러를 추가로 받습니다. 남은 자리는 외부 채용으로 채우며, 인사부는 2월 초에 채용을 시작할 예정입니다.\n\n각 감독자께서는 이달 말 전에 팀원들과 이 변경 사항을 논의하고 1월 31일까지 희망 직원 명단을 제게 제출해 주시기 바랍니다. [3] 새 근무조에는 감독자 두 명이 필요하므로, 본인이 직접 야간조 감독을 맡을 의향이 있는지도 알려 주십시오.\n\n자세한 근무표와 야간 작업을 위한 개정 안전 절차는 다음 주에 배포됩니다. [4]\n\n빅터 알메이다\n운영 이사","part":7},{"id":"p7-023","level":4,"kind":"double","passages":[{"doc_type":"기사","title":"Greenfield Library Launches 'Tech Help' Sessions","text":"GREENFIELD (October 3) — Beginning this month, the Greenfield Public Library will offer free one-on-one technology help sessions for residents. Trained volunteers will assist participants with tasks such as setting up e-mail accounts, using smartphones, and filling out online job applications.\n\nSessions last 45 minutes and are held on Tuesdays and Thursdays from 2:00 to 6:00 P.M. at the main branch and on Saturday mornings at the Eastside branch. Advance booking is required and can be made by phone or at any circulation desk. Participants are encouraged to bring their own devices, although a limited number of library laptops are available.\n\nThe program is funded by a grant from the Harmon Foundation. Library director Paul Okafor said the library hopes to expand the service to its Northgate branch next year if demand is high. The library is also seeking additional volunteers, particularly those who speak Spanish or Vietnamese."},{"doc_type":"이메일","title":"From: Mei Tran / To: Paul Okafor / Date: October 12 / Subject: Volunteering","text":"Dear Mr. Okafor,\n\nI read about the new Tech Help sessions in the Greenfield Gazette and would like to offer my assistance. I recently retired after 25 years as a network technician, and I am comfortable with both computers and mobile devices. I also grew up speaking Vietnamese at home, so I could help residents who are more at ease in that language.\n\nI live close to the Eastside branch, so I would prefer to volunteer there. Unfortunately, I am taking a painting class on Saturday mornings until the end of November, so I would not be able to start until December.\n\nPlease let me know what the next steps would be.\n\nSincerely,\nMei Tran"}],"questions":[{"q":"What is the article mainly about?","choices":["The opening of a new branch","A new free service at a library","A fundraising campaign","A community computer sale"],"answer":1,"type":"주제·목적","explanation":"기사 첫 문장에서 그린필드 공공도서관이 주민을 위한 무료 일대일 기술 도움 세션을 시작한다고 했다. 노스게이트 지점은 확대 가능성으로만 언급되었고, 새 지점 개관 기사가 아니다."},{"q":"According to the article, what is required to participate in a session?","choices":["A personal laptop","A library membership fee","Proof of residence","An advance booking"],"answer":3,"type":"세부 사항","explanation":"기사의 'Advance booking is required'에서 사전 예약이 필수라고 했다. 개인 기기는 가져오도록 권장(encouraged)될 뿐이며 도서관 노트북도 일부 있다."},{"q":"What is suggested about Ms. Tran?","choices":["She is currently working as a network technician.","She works at the Eastside branch.","She teaches a painting class.","She speaks a language the library is looking for."],"answer":3,"type":"연계 문제","explanation":"기사에서 도서관은 특히 스페인어나 베트남어를 하는 자원봉사자를 찾는다고 했고, 이메일에서 트랜 씨는 집에서 베트남어를 쓰며 자랐다고 했다. 그녀는 이미 은퇴했고, 그림 수업은 가르치는 것이 아니라 듣는 것이다."},{"q":"When would Ms. Tran most likely be able to volunteer?","choices":["On Saturday mornings from December","On Tuesday afternoons in November","On Thursday afternoons in October","At the Northgate branch next year"],"answer":0,"type":"연계 문제","explanation":"기사에 따르면 이스트사이드 지점 세션은 토요일 오전에 열린다. 트랜 씨는 이스트사이드 지점을 원하지만 11월 말까지 토요일 오전에 그림 수업이 있어 12월부터 가능하다고 했다."},{"q":"In the e-mail, the word “comfortable” in paragraph 1, line 2, is closest in meaning to","choices":["wealthy","cozy","familiar","quiet"],"answer":2,"type":"동의어","explanation":"'I am comfortable with both computers and mobile devices'는 컴퓨터와 모바일 기기를 '잘 다룬다, 익숙하다'는 뜻이므로 familiar가 가장 가깝다. wealthy(부유한), cozy(아늑한)는 다른 의미의 comfortable이다."}],"translation":"[기사]\n그린필드 도서관, '기술 도움' 세션 시작\n\n그린필드 (10월 3일) — 이달부터 그린필드 공공도서관이 주민을 위한 무료 일대일 기술 도움 세션을 제공한다. 교육받은 자원봉사자들이 이메일 계정 만들기, 스마트폰 사용, 온라인 구직 지원서 작성 같은 일을 도와준다.\n\n세션은 45분간 진행되며, 본관에서는 화요일과 목요일 오후 2시부터 6시까지, 이스트사이드 지점에서는 토요일 오전에 열린다. 사전 예약이 필수이며 전화나 대출 데스크에서 예약할 수 있다. 참가자는 자신의 기기를 가져오도록 권장되지만, 도서관 노트북도 소수 마련되어 있다.\n\n이 프로그램은 하먼 재단의 보조금으로 운영된다. 폴 오카포 도서관장은 수요가 많으면 내년에 노스게이트 지점까지 서비스를 확대하고 싶다고 말했다. 도서관은 특히 스페인어나 베트남어를 할 줄 아는 자원봉사자를 추가로 모집하고 있다.\n\n[이메일]\n보낸 사람: 메이 트랜 / 받는 사람: 폴 오카포 / 날짜: 10월 12일 / 제목: 자원봉사\n\n오카포 님께,\n\n그린필드 가제트에서 새 기술 도움 세션에 관한 기사를 읽고 도움을 드리고 싶어 연락드립니다. 저는 25년간 네트워크 기술자로 일하다 최근 은퇴했으며, 컴퓨터와 모바일 기기를 모두 잘 다룹니다. 또 집에서 베트남어를 쓰며 자라서 베트남어가 더 편한 주민들을 도울 수 있습니다.\n\n이스트사이드 지점 근처에 살고 있어 그곳에서 봉사하고 싶습니다. 다만 11월 말까지 토요일 오전마다 그림 수업을 듣고 있어서 12월이 되어야 시작할 수 있습니다.\n\n다음 절차를 알려 주시기 바랍니다.\n\n메이 트랜 드림","part":7},{"id":"p7-024","level":4,"kind":"triple","passages":[{"doc_type":"웹페이지","title":"www.lakeshorehotel.com/meetings","text":"Lakeshore Conference Hotel — Meeting Packages\n\nPackage | Room capacity | Includes | Price per person\nEssential | Up to 30 | Meeting room, projector, coffee break | $45\nStandard | Up to 60 | Essential items + buffet lunch | $70\nPremium | Up to 120 | Standard items + second coffee break, video recording | $95\n\nAll packages include free Wi-Fi and parking for attendees. Groups booking 20 or more guest rooms for overnight stays receive a complimentary dinner reception. Bookings must be confirmed at least 21 days before the event."},{"doc_type":"이메일","title":"From: Daniel Frost / To: events@lakeshorehotel.com / Date: April 2 / Subject: Training seminar booking","text":"Hello,\n\nI would like to book a meeting package for a training seminar on May 14. We expect 55 participants, and lunch will need to be provided. We do not need the session recorded. In addition, 25 of our attendees will be traveling from our regional offices and will need rooms for the night of May 13.\n\nCould you also confirm that there is a vegetarian option at lunch? Several attendees have asked.\n\nBest regards,\nDaniel Frost\nTraining Coordinator, Fairmont Pharmaceuticals"},{"doc_type":"고객 의견서","title":"Client Feedback Form — Lakeshore Conference Hotel","text":"Name: Daniel Frost\nEvent date: May 14\nOverall rating: 4/5\n\nComments: The meeting room was spacious, and the technical staff quickly solved a problem with our microphone. The buffet lunch received many compliments, including from our vegetarian attendees. The dinner reception the night before was a wonderful way for our regional staff to get to know each other. My only suggestion is to provide clearer directions to the conference wing, as several participants got lost after parking in the east lot. We plan to hold our autumn seminar here as well."}],"questions":[{"q":"What is indicated about all of the meeting packages?","choices":["They include lunch.","They accommodate up to 120 people.","They include free parking.","They can be booked one week in advance."],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"웹페이지의 'All packages include free Wi-Fi and parking for attendees.'와 일치한다. 점심은 Standard 이상, 120명은 Premium만 해당하며, 예약은 최소 21일 전에 확정해야 한다."},{"q":"Which package did Mr. Frost most likely book?","choices":["Essential","Standard","Premium","Deluxe"],"answer":1,"type":"연계 문제","explanation":"이메일에서 참가자는 55명이고 점심이 필요하며 녹화는 필요 없다고 했다. 웹페이지 표에서 60명까지 수용하고 뷔페 점심이 포함되며 녹화는 없는 패키지는 Standard이다."},{"q":"By what date did Mr. Frost's booking need to be confirmed?","choices":["April 2","May 7","April 23","May 13"],"answer":2,"type":"연계 문제","explanation":"웹페이지에 행사 최소 21일 전까지 예약을 확정해야 한다고 했고, 이메일의 행사일은 5월 14일이다. 5월 14일에서 21일을 빼면 4월 23일이다."},{"q":"Why did Mr. Frost's group most likely receive a dinner reception?","choices":["They booked the Premium package.","They were first-time customers.","They plan to return in the autumn.","They reserved more than 20 guest rooms."],"answer":3,"type":"연계 문제","explanation":"웹페이지에 객실을 20개 이상 예약하는 단체는 무료 저녁 리셉션을 받는다고 했고, 이메일에서 25명이 5월 13일 숙박이 필요하다고 했다. 의견서에서도 전날 밤 저녁 리셉션을 언급했다."},{"q":"According to the feedback form, what problem did some participants have?","choices":["They could not easily find the conference area.","Their lunch had no vegetarian food.","The microphone was never repaired.","The parking lot was full."],"answer":0,"type":"세부 사항","explanation":"의견서의 'several participants got lost after parking in the east lot'에서 일부 참가자가 회의동을 찾지 못해 헤맸음을 알 수 있다. 마이크 문제는 기술 직원이 빠르게 해결했고, 채식 참석자도 점심을 칭찬했다."}],"translation":"[웹페이지]\n레이크쇼어 콘퍼런스 호텔 — 회의 패키지\n\n패키지 | 수용 인원 | 포함 사항 | 1인당 가격\n에센셜 | 최대 30명 | 회의실, 프로젝터, 커피 브레이크 | 45달러\n스탠더드 | 최대 60명 | 에센셜 항목 + 뷔페 점심 | 70달러\n프리미엄 | 최대 120명 | 스탠더드 항목 + 두 번째 커피 브레이크, 영상 녹화 | 95달러\n\n모든 패키지에는 참석자용 무료 와이파이와 주차가 포함됩니다. 숙박용 객실을 20개 이상 예약하는 단체에는 저녁 리셉션을 무료로 제공합니다. 예약은 행사 최소 21일 전까지 확정해야 합니다.\n\n[이메일]\n보낸 사람: 대니얼 프로스트 / 받는 사람: events@lakeshorehotel.com / 날짜: 4월 2일 / 제목: 교육 세미나 예약\n\n안녕하세요.\n\n5월 14일 교육 세미나를 위한 회의 패키지를 예약하고 싶습니다. 참가자는 55명으로 예상하며 점심이 제공되어야 합니다. 세션 녹화는 필요 없습니다. 또한 참석자 중 25명은 지역 사무소에서 오기 때문에 5월 13일 밤 숙박할 객실이 필요합니다.\n\n점심에 채식 메뉴가 있는지도 확인해 주시겠어요? 여러 참석자가 물어봤습니다.\n\n대니얼 프로스트 드림\n페어몬트 제약 교육 담당\n\n[고객 의견서]\n이름: 대니얼 프로스트\n행사일: 5월 14일\n종합 평점: 4/5\n\n의견: 회의실이 넓었고, 기술 직원들이 마이크 문제를 빠르게 해결해 주었습니다. 뷔페 점심은 채식 참석자들을 포함해 많은 칭찬을 받았습니다. 전날 밤 저녁 리셉션은 지역 사무소 직원들이 서로 알아 가는 데 아주 좋은 자리였습니다. 한 가지 제안하자면, 여러 참가자가 동쪽 주차장에 주차한 뒤 길을 잃었으니 회의동으로 가는 안내를 더 명확하게 해 주시면 좋겠습니다. 가을 세미나도 이곳에서 열 계획입니다.","part":7},{"id":"p7-025","level":5,"kind":"single","passages":[{"doc_type":"기사","title":"Regional Airlines Rethink the Hub Model / By Marcus Heller","text":"For decades, regional carriers have relied on the so-called hub-and-spoke model, funneling passengers from smaller cities through a handful of major airports before sending them on to their final destinations. [1] The approach allowed airlines to fill larger aircraft and concentrate maintenance operations, but it also meant long layovers and frequent missed connections.\n\nThat model is now being quietly revisited. Several mid-sized carriers, including Tern Air and Coastline Jet, have begun adding direct routes between secondary cities that previously had no nonstop service. The shift has been made possible largely by a new generation of fuel-efficient narrow-body aircraft, which can operate profitably with as few as 90 passengers per flight. [2]\n\nNot everyone is convinced the trend will last. [3] Aviation consultant Rhea Castellano points out that point-to-point routes are highly sensitive to fuel prices and seasonal demand. “When jet fuel costs rise, the first routes to be cut are the ones that depend on thin margins,” she said. “Hubs are not glamorous, but they are resilient.”\n\nFor now, travelers appear to be responding favorably. Tern Air reports that its new Midland–Porterville route operated at 87 percent capacity in its first quarter, well above the airline's network average. [4] Whether such results can be sustained through an economic downturn, however, remains an open question."}],"questions":[{"q":"What is the article mainly about?","choices":["The merger of two regional airlines","Rising ticket prices at major airports","New safety rules for narrow-body aircraft","A shift in some airlines' route strategies"],"answer":3,"type":"주제·목적","explanation":"기사는 허브 앤 스포크 모델이 재검토되고 일부 항공사가 중소 도시 간 직항 노선을 늘리는 흐름과 그 지속 가능성을 다룬다. 턴 에어와 코스트라인 젯은 합병한 것이 아니라 각각 노선을 추가한 사례로 언급되었다."},{"q":"The word “sustained” in paragraph 4, line 3, is closest in meaning to","choices":["supported","suffered","maintained","confirmed"],"answer":2,"type":"동의어","explanation":"'Whether such results can be sustained through an economic downturn'은 그런 실적이 경기 침체 동안에도 '유지될' 수 있을지라는 뜻이므로 maintained가 가장 가깝다. supported(떠받치다)는 sustain의 다른 뜻이지만 결과(results)와 어울리지 않는다."},{"q":"What does Ms. Castellano suggest about the hub-and-spoke system?","choices":["It is better able to withstand difficult conditions.","It is becoming more popular with travelers.","It depends on newer, smaller aircraft.","It reduces layover times for passengers."],"answer":0,"type":"추론","explanation":"카스텔라노는 연료비가 오르면 수익이 적은 직항 노선이 먼저 없어진다고 하며 'Hubs are not glamorous, but they are resilient.'라고 했다. 즉 허브 방식이 어려운 여건을 더 잘 견딘다는 뜻이다. 긴 대기 시간은 오히려 허브 방식의 단점으로 소개되었다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? “Earlier aircraft of similar size, by contrast, typically required at least 130 passengers to break even.”","choices":["[1]","[2]","[3]","[4]"],"answer":1,"type":"문장 삽입","explanation":"'by contrast(그에 비해)'로 이전 세대 항공기와 비교하므로, 새 항공기가 승객 90명만으로도 수익을 낸다는 문장 바로 뒤인 [2]가 알맞다. 90명과 130명의 대비가 자연스럽게 이어진다."}],"translation":"지역 항공사들, 허브 모델을 재고하다 / 마커스 헬러\n\n수십 년 동안 지역 항공사들은 이른바 허브 앤 스포크 모델에 의존해 왔다. 작은 도시의 승객들을 소수의 대형 공항으로 모은 뒤 최종 목적지로 보내는 방식이다. [1] 이 방식 덕분에 항공사들은 더 큰 항공기를 채우고 정비 업무를 한곳에 모을 수 있었지만, 긴 환승 대기와 잦은 연결편 놓침도 뒤따랐다.\n\n그 모델이 지금 조용히 재검토되고 있다. 턴 에어와 코스트라인 젯을 비롯한 여러 중견 항공사가 그동안 직항편이 없던 중소 도시들 사이에 직항 노선을 추가하기 시작했다. 이러한 변화는 주로 승객이 90명만 되어도 수익을 내며 운항할 수 있는 신세대 고연비 협동체 항공기 덕분에 가능해졌다. [2]\n\n모두가 이 흐름이 지속될 것이라고 확신하는 것은 아니다. [3] 항공 컨설턴트 레아 카스텔라노는 도시 간 직항 노선이 연료 가격과 계절 수요에 매우 민감하다고 지적한다. 그녀는 \"항공유 가격이 오르면 가장 먼저 없어지는 노선이 박한 이윤에 의존하는 노선\"이라며 \"허브는 화려하지 않지만 회복력이 있다\"고 말했다.\n\n현재로서는 여행객들이 호의적으로 반응하는 것으로 보인다. 턴 에어는 새 미들랜드–포터빌 노선이 첫 분기에 좌석 점유율 87퍼센트를 기록해 자사 노선망 평균을 크게 웃돌았다고 밝혔다. [4] 그러나 이런 실적이 경기 침체기에도 유지될 수 있을지는 여전히 미지수이다.","part":7},{"id":"p7-026","level":5,"kind":"single","passages":[{"doc_type":"이메일","title":"From: Sofia Brandt, Velmont Hospital Group / To: Arjun Mehta, Clearwave Medical Supplies / Date: 17 November / Subject: Proposal for supply agreement","text":"Dear Mr. Mehta,\n\nThank you for your revised proposal of 10 November. Our purchasing committee reviewed it at length on Friday, and while we appreciate the reduced unit prices for surgical gloves and gowns, several concerns remain.\n\nFirst, the proposal commits us to a minimum annual order of 400,000 units across all product lines. Given that two of our five facilities are scheduled to merge next autumn, our combined demand is likely to fall short of that figure. We would ask that the minimum be lowered by roughly a quarter or that it be calculated on a per-facility basis.\n\nSecond, the delivery terms remain unchanged from our current agreement. As you know, three shipments last quarter arrived more than 48 hours late, forcing our Eastbrook facility to purchase emergency stock from another supplier at considerably higher cost. The committee would like to see a penalty clause covering late deliveries.\n\nFinally, we noted that the proposal no longer mentions the quarterly usage reports your team has provided in the past. These have been invaluable to our planning, and their omission, whether intentional or not, should be addressed.\n\nProvided these points can be resolved, we would be prepared to sign a three-year agreement rather than the two-year term originally discussed. I look forward to your response.\n\nKind regards,\nSofia Brandt\nProcurement Director"}],"questions":[{"q":"Why did Ms. Brandt write the e-mail?","choices":["To cancel an existing supply agreement","To request changes to a proposed agreement","To complain about the quality of some products","To announce the merger of two hospital groups"],"answer":1,"type":"주제·목적","explanation":"브랜트 씨는 수정 제안서를 검토한 뒤 최소 주문량, 배송 지연 위약 조항, 사용량 보고서 누락 등 세 가지 우려 사항을 제시하며 수정을 요청하고 있다. 합병은 자사 시설 두 곳의 통합이지 두 병원 그룹의 합병이 아니다."},{"q":"What minimum annual order would Ms. Brandt most likely find acceptable?","choices":["About 100,000 units","About 400,000 units","About 500,000 units","About 300,000 units"],"answer":3,"type":"추론","explanation":"두 번째 문단에서 최소 주문량 40만 개를 'roughly a quarter(약 4분의 1)' 낮춰 달라고 했으므로 약 30만 개를 원한다고 추론할 수 있다. 10만 개는 4분의 1만큼 '줄인 양'이지 조정 후 수량이 아니다."},{"q":"What is indicated about the Eastbrook facility?","choices":["It will close next autumn.","It received damaged goods.","It had to buy costly supplies elsewhere.","It prepares the quarterly usage reports."],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"세 번째 문단 'forcing our Eastbrook facility to purchase emergency stock from another supplier at considerably higher cost'와 일치한다. 내년 가을에는 폐쇄가 아니라 시설 두 곳이 통합되며, 사용량 보고서는 공급업체 측이 제공해 왔다."},{"q":"What does Ms. Brandt offer if her concerns are addressed?","choices":["A longer contract period","A larger minimum order","Earlier payment of invoices","Acceptance of higher unit prices"],"answer":0,"type":"세부 사항","explanation":"마지막 문단 'we would be prepared to sign a three-year agreement rather than the two-year term originally discussed'에서 문제가 해결되면 2년이 아닌 3년 계약을 맺겠다고 했다. 최소 주문량은 오히려 낮춰 달라고 요청했다."}],"translation":"보낸 사람: 벨몬트 병원 그룹 소피아 브란트 / 받는 사람: 클리어웨이브 의료용품 아르준 메타 / 날짜: 11월 17일 / 제목: 공급 계약 제안서\n\n메타 님께,\n\n11월 10일자 수정 제안서를 보내 주셔서 감사합니다. 저희 구매위원회가 금요일에 이를 오랫동안 검토했으며, 수술용 장갑과 가운의 단가 인하는 감사하게 생각하지만 몇 가지 우려 사항이 남아 있습니다.\n\n첫째, 제안서는 저희가 모든 제품군을 합쳐 연간 최소 40만 개를 주문하도록 규정하고 있습니다. 저희 시설 다섯 곳 중 두 곳이 내년 가을 통합될 예정이어서 전체 수요가 그 수치에 못 미칠 가능성이 높습니다. 최소 주문량을 약 4분의 1 낮추거나 시설별로 산정해 주시기를 요청합니다.\n\n둘째, 배송 조건이 현재 계약과 달라진 것이 없습니다. 아시다시피 지난 분기에 세 차례 배송이 48시간 넘게 늦게 도착해, 저희 이스트브룩 시설이 다른 공급업체로부터 훨씬 비싼 가격에 긴급 재고를 구입해야 했습니다. 위원회는 배송 지연에 대한 위약 조항이 포함되기를 바랍니다.\n\n마지막으로, 제안서에 귀사 팀이 그동안 제공해 온 분기별 사용량 보고서에 대한 언급이 더 이상 없다는 점을 확인했습니다. 이 보고서는 저희 계획 수립에 매우 귀중했으며, 의도한 것이든 아니든 이 누락은 해결되어야 합니다.\n\n이러한 사항들이 해결된다면, 저희는 원래 논의했던 2년이 아닌 3년 계약을 체결할 준비가 되어 있습니다. 답변을 기다리겠습니다.\n\n소피아 브란트 드림\n구매 이사","part":7},{"id":"p7-027","level":5,"kind":"single","passages":[{"doc_type":"웹페이지","title":"www.aldencityutilities.gov/notices","text":"Water Main Replacement Project: Phase 2\n\nAlden City Utilities will begin the second phase of its water main replacement project on July 7. This phase covers the Hillcrest and Old Mill neighborhoods, where many pipes date back more than 80 years. [1]\n\nWork will proceed one block at a time, and each block is expected to take approximately ten working days. Residents will receive a door hanger at least 72 hours before work begins on their street. During that period, water service may be interrupted for up to six hours on any given day, typically between 9:00 A.M. and 3:00 P.M. [2]\n\nOn-street parking will be restricted on affected blocks from 7:00 A.M. to 5:00 P.M. Residents who lack off-street parking may obtain a temporary permit for the Hillcrest Community Center lot by calling our project office. [3] Garbage and recycling collection will continue on the usual schedule, although bins may need to be placed at the end of the block rather than at the curb.\n\nUpon completion of each block, crews will restore road surfaces and sidewalks to their prior condition. [4] Phase 2 is expected to conclude in late November, weather permitting. For updates, subscribe to our text alert service or visit this page, which is refreshed every Monday."}],"questions":[{"q":"What is the main purpose of the notice?","choices":["To announce new water rates","To inform residents about upcoming construction","To introduce a recycling program","To recruit construction workers"],"answer":1,"type":"주제·목적","explanation":"공지는 7월 7일 시작하는 상수도 본관 교체 공사 2단계의 대상 지역, 단수, 주차 제한, 복구 계획 등을 주민에게 안내한다. 쓰레기 수거는 공사 중에도 평소처럼 진행된다는 부수적 안내일 뿐이다."},{"q":"The word “restore” in paragraph 4, line 1, is closest in meaning to","choices":["save","store","repeat","return"],"answer":3,"type":"동의어","explanation":"'crews will restore road surfaces and sidewalks to their prior condition'은 도로와 보도를 이전 상태로 '되돌린다, 복구한다'는 뜻이므로 return이 가장 가깝다. store(보관하다)는 철자가 비슷한 오답이다."},{"q":"What is NOT mentioned as something residents may experience?","choices":["A change in garbage collection days","Brief interruptions in water service","Limits on street parking","Moving bins to a different spot"],"answer":0,"type":"사실 확인(NOT/TRUE)","explanation":"단수(최대 6시간), 도로변 주차 제한, 쓰레기통을 블록 끝에 내놓아야 할 수 있다는 점은 모두 언급되었다. 그러나 수거는 'will continue on the usual schedule'이라고 했으므로 수거 요일 변경은 해당하지 않는다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? “Permits are limited, so early requests are recommended.”","choices":["[1]","[2]","[3]","[4]"],"answer":2,"type":"문장 삽입","explanation":"'Permits'는 커뮤니티 센터 주차장 임시 허가증을 가리키므로, 프로젝트 사무소에 전화해 허가증을 받을 수 있다는 문장 바로 뒤인 [3]이 알맞다. 다른 위치 앞에는 허가증에 관한 언급이 없다."}],"translation":"www.aldencityutilities.gov/notices\n상수도 본관 교체 공사: 2단계\n\n올던시 공공사업국은 7월 7일 상수도 본관 교체 공사 2단계를 시작합니다. 이번 단계는 힐크레스트와 올드밀 지역으로, 이곳의 상당수 수도관은 80년 이상 된 것입니다. [1]\n\n공사는 한 번에 한 블록씩 진행되며, 블록마다 약 10일(근무일 기준)이 걸릴 것으로 예상됩니다. 주민들은 자신이 사는 거리에서 공사가 시작되기 최소 72시간 전에 문고리 안내문을 받게 됩니다. 공사 기간에는 하루 최대 6시간, 주로 오전 9시에서 오후 3시 사이에 단수될 수 있습니다. [2]\n\n공사 구간 블록에서는 오전 7시부터 오후 5시까지 도로변 주차가 제한됩니다. 도로 밖 주차 공간이 없는 주민은 프로젝트 사무소에 전화하여 힐크레스트 커뮤니티 센터 주차장 임시 허가증을 받을 수 있습니다. [3] 쓰레기와 재활용품 수거는 평소 일정대로 계속되지만, 수거함을 도로변이 아닌 블록 끝에 내놓아야 할 수도 있습니다.\n\n각 블록 공사가 끝나면 작업반이 도로 표면과 보도를 이전 상태로 복구합니다. [4] 2단계는 날씨가 허락하면 11월 말에 끝날 예정입니다. 최신 소식은 문자 알림 서비스를 신청하시거나 매주 월요일에 갱신되는 이 페이지에서 확인하십시오.","part":7},{"id":"p7-028","level":5,"kind":"single","passages":[{"doc_type":"온라인 채팅","title":"Online chat discussion","text":"Yuna Seo [3:12 P.M.]: Quick update on the Dresner account. Their legal team sent back the contract with edits to the liability section.\nTheo Martins [3:13 P.M.]: Substantial edits?\nYuna Seo [3:14 P.M.]: They want to cap our liability at the value of a single month's service instead of the full annual fee.\nTheo Martins [3:15 P.M.]: That's a big shift. Carla, can finance live with that?\nCarla Jimenez [3:17 P.M.]: Honestly, it's not unusual for clients their size. What concerns me more is the new payment term. Did you see they've changed it from 30 to 60 days?\nYuna Seo [3:18 P.M.]: I missed that. It was buried in an appendix.\nTheo Martins [3:19 P.M.]: We agreed to 60 days with Harlow Group last year, and our cash flow suffered for months.\nCarla Jimenez [3:20 P.M.]: Exactly. I'd push back on that one and let the liability change go.\nYuna Seo [3:21 P.M.]: So accept one, reject the other. I'll draft a response tonight and send it to both of you before it goes out.\nTheo Martins [3:22 P.M.]: Copy Anton as well. He signed off on the original terms."}],"questions":[{"q":"What is the discussion mainly about?","choices":["A late payment from Harlow Group","Hiring new legal staff","A client's proposed changes to a contract","Preparing a sales presentation"],"answer":2,"type":"주제·목적","explanation":"서 씨가 드레스너 측 법무팀이 계약서의 책임 조항을 수정해 보냈다고 알리며 시작하고, 이후 책임 한도와 결제 기한 변경을 받아들일지 논의한다. 할로 그룹은 과거 사례로만 언급되었다."},{"q":"At 3:17 P.M., what does Ms. Jimenez imply when she writes, “Honestly, it's not unusual for clients their size”?","choices":["She thinks Dresner is a small company.","She finds the liability request acceptable.","She wants the contract to be canceled.","She plans to call Dresner's lawyers."],"answer":1,"type":"의도 파악","explanation":"책임 한도 변경을 재무팀이 감수할 수 있느냐는 질문에 그 규모의 고객에게는 흔한 일이라고 답하고, 3시 20분에는 'let the liability change go'라고 했다. 따라서 책임 조항 변경은 받아들일 만하다는 뜻이다. 오히려 결제 기한 변경을 더 걱정했다."},{"q":"What is suggested about Harlow Group?","choices":["It is no longer a client.","It referred Dresner to the company.","It recently replaced its legal team.","It was given a 60-day payment period."],"answer":3,"type":"추론","explanation":"마틴스 씨가 'We agreed to 60 days with Harlow Group last year, and our cash flow suffered'라고 했으므로 할로 그룹에 60일 결제 기한을 허용했던 적이 있음을 알 수 있다. 현재 거래 여부나 소개 관계는 알 수 없다."},{"q":"What will Ms. Seo do before sending her response to Dresner?","choices":["Share her draft with colleagues","Sign the original contract","Meet Dresner's legal team","Rewrite the appendix herself"],"answer":0,"type":"세부 사항","explanation":"3시 21분에 서 씨가 'I'll draft a response tonight and send it to both of you before it goes out'이라고 했으므로 발송 전에 초안을 동료들에게 공유할 것이다. 마틴스 씨는 안톤도 참조로 넣으라고 덧붙였다."}],"translation":"서유나 [오후 3:12]: 드레스너 건 간단히 공유할게요. 그쪽 법무팀이 책임 조항을 수정한 계약서를 보내왔어요.\n테오 마틴스 [오후 3:13]: 수정이 많아요?\n서유나 [오후 3:14]: 우리 책임 한도를 연간 전체 요금이 아니라 한 달 서비스 금액으로 제한하길 원해요.\n테오 마틴스 [오후 3:15]: 큰 변화네요. 카를라, 재무팀에서 감수할 수 있어요?\n카를라 히메네스 [오후 3:17]: 솔직히 그 정도 규모 고객이면 드문 일은 아니에요. 제가 더 걱정되는 건 새 결제 조건이에요. 30일에서 60일로 바꾼 거 보셨어요?\n서유나 [오후 3:18]: 그걸 놓쳤네요. 부록에 묻혀 있었어요.\n테오 마틴스 [오후 3:19]: 작년에 할로 그룹과 60일로 합의했다가 몇 달 동안 현금 흐름이 어려웠잖아요.\n카를라 히메네스 [오후 3:20]: 맞아요. 그건 반대하고 책임 조항 변경은 받아들이는 게 좋겠어요.\n서유나 [오후 3:21]: 그럼 하나는 수용하고 하나는 거절하는 거네요. 오늘 밤 답변 초안을 쓰고 발송 전에 두 분께 보낼게요.\n테오 마틴스 [오후 3:22]: 안톤도 참조로 넣어 주세요. 원래 조건을 승인한 사람이 안톤이에요.","part":7},{"id":"p7-029","level":5,"kind":"double","passages":[{"doc_type":"회람","title":"To: All Employees / From: Deborah Lange, Chief Financial Officer / Date: February 20 / Subject: Revised travel reimbursement policy","text":"MEMO\n\nEffective March 1, the following changes to our travel policy will apply to all business trips.\n\nAirfare: Economy class is required for flights under six hours. For longer flights, employees may book premium economy with the prior approval of their department head.\n\nLodging: The nightly limit is $180 in most cities and $260 in designated high-cost cities (currently New York, London, Tokyo, and Zurich).\n\nMeals: Employees will receive a flat daily allowance of $65 instead of submitting individual meal receipts. The allowance is reduced by half on days when meals are provided at a conference or client event.\n\nGround transportation: Ride-share and taxi costs are reimbursable with receipts. Rental cars require advance approval unless no reasonable alternative exists.\n\nClaims must be submitted within 30 days of the trip's end date."},{"doc_type":"이메일","title":"From: Kevin O'Brien / To: Deborah Lange / Date: April 18 / Subject: Question about Tokyo trip claim","text":"Dear Ms. Lange,\n\nI returned on April 9 from a four-day trip to Tokyo, where I attended the Asia Retail Forum. My flight from Chicago was about thirteen hours, and my department head, Ms. Adeyemi, approved a premium economy seat before I booked it. My hotel cost $240 per night.\n\nThe forum provided lunch and dinner on two of the four days, so I understand my meal allowance will be adjusted for those days. However, one point is unclear to me. On my final day, a train strike made it impossible to reach the airport by public transportation, so I rented a car without advance approval. I have the rental receipt. Will this expense be covered?\n\nI plan to submit my full claim next week.\n\nBest regards,\nKevin O'Brien"}],"questions":[{"q":"What is the purpose of the memo?","choices":["To announce updated rules for travel expenses","To list approved hotels","To introduce a new travel agency","To reduce the number of business trips"],"answer":0,"type":"주제·목적","explanation":"회람은 3월 1일부터 적용되는 항공, 숙박, 식비, 지상 교통, 청구 기한 등 출장비 환급 규정의 변경 사항을 안내한다. 특정 호텔 목록이 아니라 숙박비 한도를 제시했다."},{"q":"What is suggested about Mr. O'Brien's hotel expense?","choices":["It exceeds the limit by $60.","It required approval from Ms. Adeyemi.","It is within the permitted amount.","It will not be reimbursed."],"answer":2,"type":"연계 문제","explanation":"회람에서 도쿄는 고비용 도시로 지정되어 1박 한도가 260달러이고, 이메일에서 오브라이언 씨의 호텔비는 1박 240달러이다. 따라서 한도 안에 든다. 일반 도시 한도 180달러를 적용하면 60달러 초과처럼 보이는 함정이다."},{"q":"What total meal allowance should Mr. O'Brien expect for the trip?","choices":["$130","$195","$260","$325"],"answer":1,"type":"연계 문제","explanation":"회람에 따르면 식비는 하루 65달러이고 행사에서 식사가 제공된 날은 절반(32.5달러)이다. 이메일에서 4일 중 2일은 포럼이 식사를 제공했으므로 65×2 + 32.5×2 = 195달러이다."},{"q":"Why will Mr. O'Brien's rental car expense most likely be reimbursed?","choices":["His department head approved it in advance.","He used the car for less than one day.","Rental cars are always reimbursable.","He had no reasonable alternative."],"answer":3,"type":"연계 문제","explanation":"회람에 렌터카는 사전 승인이 필요하지만 'unless no reasonable alternative exists(합리적인 대안이 없는 경우 제외)'라고 했다. 이메일에서 철도 파업으로 대중교통으로 공항에 갈 수 없었다고 했으므로 예외에 해당한다. 사전 승인은 받지 않았다."},{"q":"What is indicated about Mr. O'Brien's flight?","choices":["It was booked in economy class.","It qualified for a premium economy seat.","It was paid for by the forum organizers.","It departed from New York."],"answer":1,"type":"연계 문제","explanation":"회람에서 6시간 이상 비행은 부서장의 사전 승인이 있으면 프리미엄 이코노미를 예약할 수 있다고 했다. 이메일에서 비행은 약 13시간이었고 부서장 아데예미 씨가 예약 전에 승인했으므로 조건을 충족한다. 출발지는 시카고이다."}],"translation":"[회람]\n받는 사람: 전 직원 / 보낸 사람: 최고재무책임자 데버라 랭 / 날짜: 2월 20일 / 제목: 출장비 환급 규정 개정\n\n3월 1일부터 모든 출장에 다음과 같은 출장 규정 변경 사항이 적용됩니다.\n\n항공: 6시간 미만 비행은 이코노미석을 이용해야 합니다. 그보다 긴 비행은 부서장의 사전 승인을 받아 프리미엄 이코노미석을 예약할 수 있습니다.\n\n숙박: 1박 한도는 대부분의 도시에서 180달러, 지정된 고비용 도시(현재 뉴욕, 런던, 도쿄, 취리히)에서 260달러입니다.\n\n식비: 개별 식사 영수증을 제출하는 대신 하루 65달러의 정액 수당을 받습니다. 콘퍼런스나 고객 행사에서 식사가 제공된 날에는 수당이 절반으로 줄어듭니다.\n\n지상 교통: 차량 공유 서비스와 택시 비용은 영수증이 있으면 환급됩니다. 렌터카는 합리적인 대안이 없는 경우를 제외하고 사전 승인이 필요합니다.\n\n청구는 출장 종료일로부터 30일 이내에 제출해야 합니다.\n\n[이메일]\n보낸 사람: 케빈 오브라이언 / 받는 사람: 데버라 랭 / 날짜: 4월 18일 / 제목: 도쿄 출장비 청구 문의\n\n랭 님께,\n\n저는 아시아 리테일 포럼 참석차 4일간 도쿄에 다녀와 4월 9일에 돌아왔습니다. 시카고에서 출발한 비행은 약 13시간이었고, 부서장이신 아데예미 님이 예약 전에 프리미엄 이코노미석을 승인해 주셨습니다. 호텔 비용은 1박에 240달러였습니다.\n\n포럼에서 4일 중 이틀은 점심과 저녁을 제공했으므로, 그날들의 식비 수당이 조정된다는 점은 이해하고 있습니다. 다만 한 가지가 분명하지 않습니다. 마지막 날 철도 파업으로 대중교통으로는 공항에 갈 수 없어서 사전 승인 없이 차를 빌렸습니다. 렌터카 영수증은 가지고 있습니다. 이 비용도 환급되나요?\n\n다음 주에 전체 청구서를 제출할 계획입니다.\n\n케빈 오브라이언 드림","part":7},{"id":"p7-030","level":5,"kind":"triple","passages":[{"doc_type":"공고","title":"Harbor City Public Space Design Competition","text":"Harbor City Public Space Design Competition\n\nThe Harbor City Planning Office invites proposals for the redesign of Lantern Square, a 1.2-hectare plaza in the heart of the Old Port district. Entries should address three priorities: increased shade and greenery, flexible space for markets and performances, and improved access for people with limited mobility.\n\nThe competition is open to licensed landscape architects and to teams that include at least one licensed member. Students may participate only as part of such a team. Submissions, consisting of no more than six presentation boards and a written statement of up to 1,500 words, are due by 5:00 P.M. on August 29. No other materials will be accepted.\n\nA jury of five, chaired by city architect Lena Vogt, will select three finalists in October. Finalists will each receive $15,000 to develop their proposals further, and the winning team will be announced in January. The city reserves the right to combine elements of multiple proposals in the final design."},{"doc_type":"이메일","title":"From: Samuel Ortiz / To: competition@harborcity.gov / Date: August 22 / Subject: Eligibility question","text":"Hello,\n\nI am a final-year landscape architecture student at Merriton University, and two classmates and I have been developing a proposal for Lantern Square. Our faculty advisor, Professor Hana Ueda, is a licensed landscape architect and has agreed to join our team formally.\n\nOur written statement is currently about 1,800 words, and we have eight boards. Before we begin cutting, I want to confirm one thing: may we include a short video in addition to the boards? Much of our concept depends on showing how the square changes between daytime and evening use.\n\nThank you,\nSamuel Ortiz"},{"doc_type":"기사","title":"Finalists Named for Lantern Square Redesign","text":"HARBOR CITY (October 16) — Three teams have been selected as finalists in the Lantern Square design competition, which drew 64 entries from across the country. The finalists are Brennan & Holt Associates of Glenport; Studio Verde, a local firm; and a team from Merriton University led by Professor Hana Ueda.\n\nJury chair Lena Vogt praised the Merriton proposal in particular for its movable canopy system, which allows the square to shift from a shaded market in the daytime to an open performance space at night. “It is rare for a student-led team to reach this stage,” she noted. Studio Verde's entry was singled out for its extensive tree planting, while Brennan & Holt focused on step-free access throughout the square.\n\nFinal designs are due in December."}],"questions":[{"q":"What is NOT stated as a priority for the Lantern Square redesign?","choices":["Additional parking spaces","More shade and plants","Flexible space for events","Easier access for people with limited mobility"],"answer":0,"type":"사실 확인(NOT/TRUE)","explanation":"공고에서 제시한 세 가지 우선순위는 그늘과 녹지 확대, 시장·공연을 위한 유연한 공간, 이동이 불편한 사람의 접근성 개선이다. 주차 공간 확충은 언급되지 않았다."},{"q":"What is suggested about Mr. Ortiz's team?","choices":["It needed special permission to enter.","It entered without a licensed member.","It met the eligibility rules by including Professor Ueda.","It was announced as the winner in October."],"answer":2,"type":"연계 문제","explanation":"공고에 따르면 학생은 면허를 가진 구성원이 한 명 이상 있는 팀의 일원으로만 참가할 수 있다. 이메일에서 면허를 가진 우에다 교수가 팀에 정식 합류했다고 했으므로 참가 자격을 충족한다. 10월에는 우승팀이 아니라 결선 진출팀이 발표되었다."},{"q":"What changes did Mr. Ortiz's team most likely have to make before submitting?","choices":["Add more licensed members","Cut its statement to 1,500 words and use no more than six boards","Replace its boards with a video","Request a later deadline"],"answer":1,"type":"연계 문제","explanation":"이메일에서 설명문은 약 1,800단어, 보드는 8장이라고 했지만 공고의 제한은 보드 6장 이하, 설명문 1,500단어 이하이다. 또 공고에 'No other materials will be accepted'라고 했으므로 영상은 제출할 수 없다."},{"q":"What is suggested about the Merriton team's proposal?","choices":["It focused mainly on tree planting.","It was submitted after the deadline.","It was merged with Studio Verde's design.","It developed the day-to-evening idea Mr. Ortiz described."],"answer":3,"type":"연계 문제","explanation":"오르티스 씨는 이메일에서 광장이 낮과 저녁에 어떻게 달라지는지가 콘셉트의 핵심이라고 했고, 기사에서 메리턴 팀의 이동식 캐노피는 낮에는 그늘진 시장, 밤에는 공연 공간으로 광장을 바꾼다고 소개되었다. 나무 심기는 스튜디오 베르데의 특징이다."},{"q":"In the article, the phrase “singled out” in paragraph 2, line 5, is closest in meaning to","choices":["noted specifically","separated physically","rejected","counted"],"answer":0,"type":"동의어","explanation":"'Studio Verde's entry was singled out for its extensive tree planting'은 스튜디오 베르데의 출품작이 대규모 나무 심기로 '특별히 주목받았다'는 뜻이므로 noted specifically가 가장 가깝다. 탈락(rejected)이나 물리적 분리의 의미가 아니다."}],"translation":"[공고]\n하버시티 공공 공간 설계 공모전\n\n하버시티 도시계획국은 올드포트 지구 중심부에 있는 1.2헥타르 규모의 광장, 랜턴 스퀘어의 재설계안을 공모합니다. 출품작은 세 가지 우선순위를 다루어야 합니다. 그늘과 녹지 확대, 시장과 공연을 위한 유연한 공간, 이동이 불편한 사람들의 접근성 개선입니다.\n\n공모전에는 면허를 가진 조경 건축가, 그리고 면허 소지자가 한 명 이상 포함된 팀이 참가할 수 있습니다. 학생은 그러한 팀의 일원으로만 참가할 수 있습니다. 제출물은 발표 보드 6장 이하와 1,500단어 이하의 설명문으로 구성되며 8월 29일 오후 5시까지 제출해야 합니다. 그 밖의 자료는 받지 않습니다.\n\n시 건축가 레나 포크트가 위원장을 맡은 5인 심사위원단이 10월에 결선 진출팀 세 팀을 선정합니다. 결선 진출팀은 각각 설계안을 발전시키기 위한 1만 5천 달러를 받으며, 우승팀은 1월에 발표됩니다. 시는 최종 설계에 여러 제안의 요소를 결합할 권리를 가집니다.\n\n[이메일]\n보낸 사람: 새뮤얼 오르티스 / 받는 사람: competition@harborcity.gov / 날짜: 8월 22일 / 제목: 참가 자격 문의\n\n안녕하세요.\n\n저는 메리턴 대학교 조경학과 4학년 학생이며, 동기 두 명과 함께 랜턴 스퀘어 설계안을 준비하고 있습니다. 저희 지도 교수이신 하나 우에다 교수님은 면허를 가진 조경 건축가이시며 저희 팀에 정식으로 합류하기로 하셨습니다.\n\n현재 설명문은 약 1,800단어이고 보드는 8장입니다. 분량을 줄이기 시작하기 전에 한 가지 확인하고 싶습니다. 보드 외에 짧은 영상을 포함해도 될까요? 저희 콘셉트의 상당 부분은 광장이 낮과 저녁 시간대에 어떻게 달라지는지를 보여 주는 데 달려 있습니다.\n\n감사합니다.\n새뮤얼 오르티스\n\n[기사]\n랜턴 스퀘어 재설계 결선 진출팀 발표\n\n하버시티 (10월 16일) — 전국에서 64개 작품이 출품된 랜턴 스퀘어 설계 공모전의 결선 진출팀 세 팀이 선정되었다. 결선 진출팀은 글렌포트의 브레넌 앤드 홀트 어소시에이츠, 지역 업체인 스튜디오 베르데, 그리고 하나 우에다 교수가 이끄는 메리턴 대학교 팀이다.\n\n레나 포크트 심사위원장은 특히 메리턴 팀의 이동식 캐노피 시스템을 높이 평가했다. 이 시스템은 광장을 낮에는 그늘진 시장으로, 밤에는 탁 트인 공연 공간으로 바꿀 수 있게 해 준다. 그녀는 \"학생이 주도한 팀이 이 단계까지 오는 것은 드문 일\"이라고 말했다. 스튜디오 베르데의 출품작은 대규모 나무 심기로 특별히 주목받았고, 브레넌 앤드 홀트는 광장 전체의 계단 없는 접근성에 초점을 맞추었다.\n\n최종 설계안은 12월까지 제출해야 한다.","part":7},{"id":"p7-031","level":1,"kind":"single","passages":[{"doc_type":"메뉴","title":"Casa Lucia Trattoria — Lunch Menu","text":"CASA LUCIA TRATTORIA\nLunch Menu (served Monday–Friday, 11:30 A.M.–2:30 P.M.)\n\nSoups and Salads\nTomato Basil Soup ............ $5.50\nGarden Salad ............ $6.00\nChicken Caesar Salad ............ $9.50\n\nPasta\nSpaghetti with Meatballs ............ $12.00\nMushroom Ravioli ............ $11.50\nSeafood Linguine ............ $15.00\n\nDrinks\nLemonade ............ $3.00\nIced Tea ............ $2.50\n\nLunch Set: Choose any soup or salad and any pasta, and get a free drink!\nAll pasta dishes come with fresh bread. Please tell your server about any food allergies. Take-out orders are also welcome."}],"questions":[{"q":"When is the lunch menu available?","choices":["Only on Fridays","On weekdays","Every evening","On weekends"],"answer":1,"type":"세부 사항","explanation":"메뉴 맨 위 'served Monday–Friday, 11:30 A.M.–2:30 P.M.'에서 월~금요일, 즉 평일에 제공됨을 알 수 있다. 주말이나 저녁 제공은 언급되지 않았고, 금요일에만 제공되는 것도 아니다."},{"q":"What comes with every pasta dish?","choices":["A salad","A drink","Soup","Bread"],"answer":3,"type":"세부 사항","explanation":"마지막 부분 'All pasta dishes come with fresh bread.'에서 모든 파스타에 빵이 함께 나온다고 했다. 음료는 런치 세트를 주문할 때만 무료로 제공되고, 수프·샐러드는 따로 골라야 한다."},{"q":"What is indicated about the Lunch Set?","choices":["It must be ordered in advance.","It costs $15.00.","It includes a free drink.","It is available only on Fridays."],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"'Lunch Set: Choose any soup or salad and any pasta, and get a free drink!'에서 세트에 무료 음료가 포함된다고 했다. $15.00은 해산물 링귀니 가격이고, 금요일 한정이나 사전 주문 조건은 없다."}],"translation":"카사 루치아 트라토리아\n점심 메뉴 (월~금요일, 오전 11시 30분~오후 2시 30분 제공)\n\n수프와 샐러드\n토마토 바질 수프 ...... 5.50달러\n가든 샐러드 ...... 6.00달러\n치킨 시저 샐러드 ...... 9.50달러\n\n파스타\n미트볼 스파게티 ...... 12.00달러\n버섯 라비올리 ...... 11.50달러\n해산물 링귀니 ...... 15.00달러\n\n음료\n레모네이드 ...... 3.00달러\n아이스티 ...... 2.50달러\n\n런치 세트: 수프나 샐러드 중 하나와 파스타 하나를 고르시면 음료를 무료로 드립니다!\n모든 파스타 요리에는 갓 구운 빵이 함께 나옵니다. 음식 알레르기가 있으시면 담당 직원에게 말씀해 주세요. 포장 주문도 환영합니다.","part":7},{"id":"p7-032","level":1,"kind":"single","passages":[{"doc_type":"문자 메시지","title":"Text-message chain","text":"Nadia Okoro (9:05 A.M.): Hi, Sam. Are you at the office yet?\nSam Whitley (9:06 A.M.): Almost. I'm on the bus. Why?\nNadia Okoro (9:07 A.M.): A delivery for our team is at the front desk. It's the new printer paper.\nSam Whitley (9:08 A.M.): Can't you get it?\nNadia Okoro (9:09 A.M.): I'm working from home today. The receptionist wants it picked up before noon.\nSam Whitley (9:10 A.M.): No problem. I'll be there in ten minutes.\nNadia Okoro (9:11 A.M.): Thanks! The boxes are heavy, so use the cart by the elevator."}],"questions":[{"q":"Why does Ms. Okoro contact Mr. Whitley?","choices":["To ask him to collect a delivery","To change a meeting time","To ask about a bus schedule","To order some printer paper"],"answer":0,"type":"주제·목적","explanation":"9시 7분과 9시 9분 메시지에서 팀 앞으로 온 배송물이 안내 데스크에 있고 정오 전에 가져가야 한다고 했으므로, 배송물을 찾아 달라고 부탁하려는 것이다. 종이는 이미 도착했으며 회의나 버스 시간은 목적이 아니다."},{"q":"At 9:10 A.M., what does Mr. Whitley mean when he writes, “No problem”?","choices":["The printer is working again.","He has already found the cart.","He is willing to pick up the boxes.","He does not need a ride."],"answer":2,"type":"의도 파악","explanation":"오코로 씨가 재택근무 중이라 직접 못 가져간다고 하자 휘틀리 씨가 'No problem'이라 하고 곧바로 '10분 뒤에 도착한다'고 했으므로 상자를 가져가겠다는 뜻이다. 카트 이야기는 그 뒤에 나오고, 프린터 수리나 차편은 관련이 없다."},{"q":"What does Ms. Okoro suggest?","choices":["Using a cart","Taking the stairs","Opening the boxes","Calling the receptionist"],"answer":0,"type":"세부 사항","explanation":"마지막 메시지 'use the cart by the elevator'에서 상자가 무거우니 엘리베이터 옆 카트를 쓰라고 제안했다. 계단, 접수 담당자에게 전화, 상자 개봉은 언급되지 않았다."}],"translation":"나디아 오코로 (오전 9:05): 안녕하세요, 샘. 벌써 사무실에 계세요?\n샘 휘틀리 (오전 9:06): 거의 다 왔어요. 버스 안이에요. 왜요?\n나디아 오코로 (오전 9:07): 우리 팀 앞으로 온 배송물이 안내 데스크에 있어요. 새 프린터 용지예요.\n샘 휘틀리 (오전 9:08): 직접 가져가실 수 없어요?\n나디아 오코로 (오전 9:09): 오늘 재택근무 중이에요. 접수 담당자가 정오 전에 가져가 달래요.\n샘 휘틀리 (오전 9:10): 문제없어요. 10분 뒤에 도착해요.\n나디아 오코로 (오전 9:11): 고마워요! 상자가 무거우니까 엘리베이터 옆 카트를 쓰세요.","part":7},{"id":"p7-033","level":1,"kind":"single","passages":[{"doc_type":"시간표","title":"Coastline Rail — Weekday Timetable","text":"COASTLINE RAIL\nWeekday Timetable: Brighton Bay → Port Selby\n\nTrain | Brighton Bay | Milford | Port Selby\n101 | 6:40 A.M. | 7:05 A.M. | 7:35 A.M.\n103 | 7:50 A.M. | 8:15 A.M. | 8:45 A.M.\n105 | 9:30 A.M. | — | 10:10 A.M.\n107 | 12:15 P.M. | 12:40 P.M. | 1:10 P.M.\n\n* Train 105 is an express train and does not stop at Milford.\n* Tickets can be bought at the station or on our mobile app.\n* Bicycles are allowed on all trains except Train 103."}],"questions":[{"q":"Which train is an express train?","choices":["Train 101","Train 105","Train 103","Train 107"],"answer":1,"type":"세부 사항","explanation":"표 아래 첫 번째 안내 'Train 105 is an express train and does not stop at Milford.'에서 105번이 급행임을 알 수 있다. 표에서도 105번만 밀퍼드 칸이 '—'로 비어 있다."},{"q":"A passenger with a bicycle must arrive in Port Selby before 9:00 A.M. Which train should the passenger take?","choices":["Train 103","Train 107","Train 105","Train 101"],"answer":3,"type":"추론","explanation":"9시 전에 포트 셀비에 도착하는 열차는 101번(7:35)과 103번(8:45)인데, 마지막 안내에서 103번은 자전거를 실을 수 없다고 했다. 따라서 101번을 타야 한다. 105번과 107번은 9시 이후에 도착한다."},{"q":"How can passengers buy tickets?","choices":["By telephone","Only on the train","At a travel agency","By using a mobile app"],"answer":3,"type":"세부 사항","explanation":"두 번째 안내 'Tickets can be bought at the station or on our mobile app.'에서 역이나 모바일 앱으로 표를 살 수 있다고 했다. 열차 안, 전화, 여행사는 언급되지 않았다."}],"translation":"코스트라인 철도\n평일 시간표: 브라이턴 베이 → 포트 셀비\n\n열차 | 브라이턴 베이 | 밀퍼드 | 포트 셀비\n101 | 오전 6:40 | 오전 7:05 | 오전 7:35\n103 | 오전 7:50 | 오전 8:15 | 오전 8:45\n105 | 오전 9:30 | — | 오전 10:10\n107 | 오후 12:15 | 오후 12:40 | 오후 1:10\n\n* 105번 열차는 급행으로 밀퍼드에 정차하지 않습니다.\n* 승차권은 역이나 모바일 앱에서 구입할 수 있습니다.\n* 자전거는 103번 열차를 제외한 모든 열차에 실을 수 있습니다.","part":7},{"id":"p7-034","level":1,"kind":"single","passages":[{"doc_type":"쿠폰","title":"Greenleaf Garden Center — Spring Savings Coupon","text":"GREENLEAF GARDEN CENTER\nSPRING SAVINGS COUPON\n\n20% OFF\nany one plant, pot, or bag of soil\n\nValid April 1 – April 30\nGreenleaf Garden Center, 48 Maple Road, Dunmore\n\n- Limit one coupon per customer per visit.\n- Cannot be combined with other offers.\n- Not valid on gardening tools or gift cards.\n- Show this coupon at the checkout counter.\n\nJoin our Garden Club for free and receive coupons like this one every month! Garden Club members also get early access to our seasonal plant sales."}],"questions":[{"q":"What can the coupon be used for?","choices":["A gardening tool","A bag of soil","A gift card","A club membership fee"],"answer":1,"type":"세부 사항","explanation":"'20% OFF any one plant, pot, or bag of soil'에서 식물, 화분, 흙 한 포대에 쓸 수 있다고 했다. 원예 도구와 상품권은 'Not valid on gardening tools or gift cards'로 제외되며, 클럽 가입은 무료이다."},{"q":"What is NOT stated about the coupon?","choices":["It can be used online.","It expires at the end of April.","It must be shown at checkout.","Only one can be used per visit."],"answer":0,"type":"사실 확인(NOT/TRUE)","explanation":"유효 기간(4월 1일~30일), 방문당 1장 제한, 계산대에서 제시해야 한다는 점은 모두 쿠폰에 적혀 있다. 온라인 사용 가능 여부는 언급되지 않았으므로 이것이 정답이다."},{"q":"According to the coupon, how can customers get more coupons?","choices":["By writing a review","By visiting on weekends","By joining a free club","By spending over $50"],"answer":2,"type":"세부 사항","explanation":"마지막 문장 'Join our Garden Club for free and receive coupons like this one every month!'에서 무료 가든 클럽에 가입하면 매달 쿠폰을 받는다고 했다. 구매 금액, 주말 방문, 후기 작성 조건은 없다."}],"translation":"그린리프 가든 센터\n봄맞이 할인 쿠폰\n\n20% 할인\n식물, 화분, 흙 한 포대 중 1개\n\n유효 기간: 4월 1일~4월 30일\n그린리프 가든 센터, 던모어 메이플 로 48번지\n\n- 고객 1인당 방문 1회에 쿠폰 1장만 사용할 수 있습니다.\n- 다른 할인 행사와 중복 사용할 수 없습니다.\n- 원예 도구와 상품권에는 사용할 수 없습니다.\n- 계산대에서 이 쿠폰을 제시해 주세요.\n\n가든 클럽에 무료로 가입하시고 매달 이런 쿠폰을 받으세요! 가든 클럽 회원은 계절별 식물 할인 판매에도 먼저 참여하실 수 있습니다.","part":7},{"id":"p7-035","level":1,"kind":"single","passages":[{"doc_type":"배송 알림","title":"Shipping Notification — Tekko Electronics","text":"Hello Ms. Fernandes,\n\nGood news! Your order has shipped.\n\nOrder number: TK-40387\nItem: Tekko Wireless Keyboard (black) x 1\nShipped: Tuesday, June 3\nCarrier: SwiftPost\nEstimated delivery: Friday, June 6\n\nYou can track your package at www.swiftpost.com with tracking number SP-778120. A signature is not required. If no one is home, the driver will leave the package at your front door. Please check the package when it arrives. If any item is damaged, contact us within 7 days at support@tekko.com.\n\nThank you for shopping with Tekko Electronics!"}],"questions":[{"q":"Why was the notice sent?","choices":["To tell a customer that an item is on its way","To report a problem with a payment","To ask a customer for a signature","To advertise a new keyboard"],"answer":0,"type":"주제·목적","explanation":"첫머리 'Good news! Your order has shipped.'에서 주문한 물건이 발송되었음을 알리는 통지임을 알 수 있다. 결제 문제나 광고 내용은 없고, 서명은 필요하지 않다고 했다."},{"q":"When will the package most likely arrive?","choices":["On Wednesday","On Monday","On Tuesday","On Friday"],"answer":3,"type":"세부 사항","explanation":"'Estimated delivery: Friday, June 6'에서 금요일에 도착할 예정임을 알 수 있다. 화요일(6월 3일)은 발송일이다."},{"q":"What is indicated about the delivery?","choices":["A signature will be required.","The package may be left at the door.","It will cost extra.","It will be made by Tekko staff."],"answer":1,"type":"사실 확인(NOT/TRUE)","explanation":"'If no one is home, the driver will leave the package at your front door.'에서 집에 아무도 없으면 현관 앞에 두고 간다고 했다. 서명은 필요 없고(A signature is not required), 배송은 스위프트포스트가 맡으며 추가 요금은 언급되지 않았다."}],"translation":"페르난데스 님, 안녕하세요.\n\n좋은 소식입니다! 주문하신 상품이 발송되었습니다.\n\n주문 번호: TK-40387\n상품: 테코 무선 키보드(검정) 1개\n발송일: 6월 3일 화요일\n택배사: 스위프트포스트\n도착 예정일: 6월 6일 금요일\n\n운송장 번호 SP-778120으로 www.swiftpost.com에서 배송 상황을 확인하실 수 있습니다. 서명은 필요하지 않습니다. 집에 아무도 없으면 기사가 현관 앞에 물건을 두고 갑니다. 물건이 도착하면 확인해 주세요. 파손된 상품이 있으면 7일 이내에 support@tekko.com으로 연락해 주십시오.\n\n테코 일렉트로닉스를 이용해 주셔서 감사합니다!","part":7},{"id":"p7-036","level":1,"kind":"single","passages":[{"doc_type":"웹페이지","title":"www.peakfitclub.com/faq","text":"PeakFit Club — Frequently Asked Questions\n\nQ: What are your opening hours?\nA: We are open from 5:00 A.M. to 11:00 P.M. on weekdays and from 7:00 A.M. to 8:00 P.M. on weekends. [1]\n\nQ: Can I bring a friend?\nA: Yes. Members may bring one guest per month for free. [2] Guests must sign a form at the front desk.\n\nQ: Do you offer group classes?\nA: Yes. We offer yoga, cycling, and dance classes every day. [3] Classes are free for members, but space is limited.\n\nQ: How do I cancel my membership?\nA: Please visit the front desk or send an e-mail to help@peakfitclub.com. [4] Cancellations take effect at the end of the month."}],"questions":[{"q":"What is true about PeakFit Club?","choices":["It allows members to bring guests every day for free.","It offers classes only on weekends.","It closes later on weekdays than on weekends.","It charges members for group classes."],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"첫 답변에서 평일은 밤 11시, 주말은 저녁 8시에 문을 닫는다고 했으므로 평일에 더 늦게 닫는다. 강좌는 회원에게 무료이고 매일 열리며, 무료 동반 손님은 한 달에 한 명뿐이다."},{"q":"How can members cancel their membership?","choices":["By filling out an online form","By mailing a letter","By calling a manager","By sending an e-mail"],"answer":3,"type":"세부 사항","explanation":"마지막 답변 'Please visit the front desk or send an e-mail to help@peakfitclub.com.'에서 안내 데스크 방문이나 이메일로 해지할 수 있다고 했다. 전화, 온라인 양식, 우편은 언급되지 않았다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? “You can check the class times on our mobile app.”","choices":["[1]","[2]","[3]","[4]"],"answer":2,"type":"문장 삽입","explanation":"주어진 문장은 강좌 시간표(class times)를 확인하는 방법이므로 요가·사이클·댄스 강좌를 매일 연다는 문장 뒤인 [3]이 알맞다. [1]은 운영 시간, [2]는 동반 손님, [4]는 회원 해지에 관한 내용이라 어울리지 않는다."}],"translation":"피크핏 클럽 — 자주 묻는 질문\n\n질문: 운영 시간은 어떻게 되나요?\n답변: 평일은 오전 5시부터 밤 11시까지, 주말은 오전 7시부터 저녁 8시까지 운영합니다.\n\n질문: 친구를 데려가도 되나요?\n답변: 네. 회원은 한 달에 한 명까지 손님을 무료로 동반할 수 있습니다. 손님은 안내 데스크에서 양식에 서명해야 합니다.\n\n질문: 단체 강좌가 있나요?\n답변: 네. 요가, 사이클, 댄스 강좌를 매일 운영합니다. (모바일 앱에서 강좌 시간을 확인하실 수 있습니다.) 강좌는 회원에게 무료이지만 정원이 제한되어 있습니다.\n\n질문: 회원 해지는 어떻게 하나요?\n답변: 안내 데스크를 방문하시거나 help@peakfitclub.com으로 이메일을 보내 주세요. 해지는 그달 말일에 적용됩니다.","part":7},{"id":"p7-037","level":1,"kind":"double","passages":[{"doc_type":"예약 확인서","title":"Hotel Mirabel — Booking Confirmation","text":"HOTEL MIRABEL — BOOKING CONFIRMATION\n\nGuest name: Kenji Watanabe\nConfirmation number: HM-55120\nCheck-in: Thursday, September 11 (after 3:00 P.M.)\nCheck-out: Saturday, September 13 (before 11:00 A.M.)\nRoom type: Standard Double, city view\nRate: $140 per night (breakfast included)\nNumber of nights: 2\nTotal: $280\n\nFree cancellation until 48 hours before check-in. Airport shuttle service is available for $15 each way. Please book the shuttle at least one day in advance. Parking is available in the hotel garage for $20 per day."},{"doc_type":"이메일","title":"From: Kenji Watanabe / To: reservations@hotelmirabel.com / Date: September 8 / Subject: Booking HM-55120","text":"Hello,\n\nI have a reservation for September 11 to 13. My meeting on Friday has been moved to Saturday afternoon, so I would like to stay one more night and check out on Sunday instead. Could you please keep the same room type for the extra night?\n\nAlso, my flight lands at 2:00 P.M. on Thursday. I would like to use your airport shuttle to get to the hotel. Please also let me know if the rate for the extra night will be the same.\n\nThank you,\nKenji Watanabe"}],"questions":[{"q":"What is included in the room rate?","choices":["Breakfast","Dinner","Parking","An airport shuttle"],"answer":0,"type":"세부 사항","explanation":"예약 확인서의 'Rate: $140 per night (breakfast included)'에서 조식이 포함되어 있음을 알 수 있다. 공항 셔틀은 편도 15달러의 별도 요금이 있고, 주차나 저녁 식사는 언급되지 않았다."},{"q":"Why did Mr. Watanabe write the e-mail?","choices":["To cancel his booking","To extend his stay","To change his flight","To ask about meeting rooms"],"answer":1,"type":"주제·목적","explanation":"이메일 첫 단락 'I would like to stay one more night and check out on Sunday instead.'에서 숙박을 하루 연장하려는 것이 목적임을 알 수 있다. 예약 취소나 항공편 변경은 요청하지 않았다."},{"q":"If Mr. Watanabe's request is accepted, how much will he most likely pay for his room?","choices":["$295","$420","$280","$435"],"answer":1,"type":"연계 문제","explanation":"확인서에서 1박 요금은 140달러이고, 이메일에서 1박을 더 묵겠다고 했으므로 총 3박이다. 140×3=420달러이다. 280달러는 기존 2박 요금이고, 435달러는 셔틀 요금 15달러를 더한 금액이라 객실 요금이 아니다."},{"q":"What is true about Mr. Watanabe's shuttle request?","choices":["It was made at least one day in advance.","It is free of charge.","It is for a trip to the airport.","It was made by telephone."],"answer":0,"type":"연계 문제","explanation":"확인서는 셔틀을 최소 하루 전에 예약하라고 했는데, 와타나베 씨는 9월 8일 이메일로 9월 11일 셔틀을 요청했으므로 조건을 충족한다. 셔틀은 편도 15달러이고, 요청은 공항에서 호텔로 가는 것이며 이메일로 했다."},{"q":"When does Mr. Watanabe now want to check out?","choices":["On Friday","On Saturday","On Thursday","On Sunday"],"answer":3,"type":"세부 사항","explanation":"이메일 'check out on Sunday instead'에서 일요일에 체크아웃하고 싶다고 했다. 토요일은 원래 체크아웃 날짜이자 옮겨진 회의 날짜이다."}],"translation":"[예약 확인서]\n호텔 미라벨 — 예약 확인서\n\n투숙객 이름: 겐지 와타나베\n확인 번호: HM-55120\n체크인: 9월 11일 목요일 (오후 3시 이후)\n체크아웃: 9월 13일 토요일 (오전 11시 이전)\n객실 유형: 스탠더드 더블, 시내 전망\n요금: 1박 140달러 (조식 포함)\n숙박 일수: 2박\n합계: 280달러\n\n체크인 48시간 전까지 무료 취소가 가능합니다. 공항 셔틀은 편도 15달러에 이용할 수 있습니다. 셔틀은 최소 하루 전에 예약해 주세요. 호텔 주차장은 하루 20달러에 이용할 수 있습니다.\n\n[이메일]\n발신: 겐지 와타나베 / 수신: reservations@hotelmirabel.com / 날짜: 9월 8일 / 제목: 예약 HM-55120\n\n안녕하세요.\n\n9월 11일부터 13일까지 예약했습니다. 금요일 회의가 토요일 오후로 옮겨져서, 하룻밤 더 묵고 일요일에 체크아웃하고 싶습니다. 추가 1박도 같은 객실 유형으로 해 주실 수 있을까요?\n\n그리고 제 항공편이 목요일 오후 2시에 도착합니다. 호텔까지 공항 셔틀을 이용하고 싶습니다. 추가 1박 요금도 같은지 알려 주세요.\n\n감사합니다.\n겐지 와타나베","part":7},{"id":"p7-038","level":1,"kind":"double","passages":[{"doc_type":"주문서","title":"Rosewood Bakery — Catering Order Form","text":"ROSEWOOD BAKERY — CATERING ORDER FORM\n\nCustomer: Aisha Rahman, Norland Insurance\nPhone: 555-0187\nPickup or Delivery: Delivery\nDate needed: Wednesday, May 21, by 9:30 A.M.\nAddress: Norland Insurance, 210 Hill Street, 4th floor\n\nItem | Quantity | Price\nButter croissants | 20 | $2.00 each\nBlueberry muffins | 15 | $2.50 each\nFresh fruit tray (large) | 1 | $30.00\n\nDelivery fee: $10.00 (free for orders over $100)\nSpecial requests: Please include napkins and paper plates.\nPayment: Invoice to Norland Insurance (due in 30 days)"},{"doc_type":"이메일","title":"From: Aisha Rahman / To: orders@rosewoodbakery.com / Date: May 19 / Subject: Change to my order","text":"Hello,\n\nI placed a catering order for Wednesday morning. Unfortunately, fewer people can come to our training session than we expected. Please reduce the number of blueberry muffins from 15 to 5. Everything else can stay the same. The session will still be held in our 4th-floor meeting room, so the delivery address does not change.\n\nI understand this may change the total cost. Please send me the new total before Tuesday at 5:00 P.M.\n\nBest regards,\nAisha Rahman"}],"questions":[{"q":"Why did Ms. Rahman send the e-mail?","choices":["To cancel an order","To change a delivery address","To make an order smaller","To complain about a late delivery"],"answer":2,"type":"주제·목적","explanation":"이메일에서 'Please reduce the number of blueberry muffins from 15 to 5.'라고 했으므로 주문 수량을 줄이려는 것이다. 나머지는 그대로 두라고 했으므로 취소나 주소 변경이 아니다."},{"q":"What did Ms. Rahman ask the bakery to include with the order?","choices":["Name tags","Coffee","A cake","Paper plates"],"answer":3,"type":"세부 사항","explanation":"주문서의 'Special requests: Please include napkins and paper plates.'에서 냅킨과 종이 접시를 요청했음을 알 수 있다. 커피, 이름표, 케이크는 없다."},{"q":"How much will the muffins cost after the change?","choices":["$10.00","$12.50","$37.50","$25.00"],"answer":1,"type":"연계 문제","explanation":"주문서에서 블루베리 머핀은 개당 2.50달러이고, 이메일에서 5개로 줄였으므로 2.50×5=12.50달러이다. 37.50달러는 원래 15개의 가격이다."},{"q":"What will most likely happen as a result of the change?","choices":["The delivery time will change.","Ms. Rahman will pick up the order herself.","A delivery fee will be charged.","The fruit tray will be removed."],"answer":2,"type":"연계 문제","explanation":"원래 주문은 40+37.50+30=107.50달러로 100달러가 넘어 배달비가 무료였지만, 머핀을 줄이면 40+12.50+30=82.50달러가 되어 주문서의 조건(100달러 초과 시 무료)에 못 미친다. 따라서 배달비 10달러가 붙게 된다. 배달 시간과 과일 쟁반은 그대로 두라고 했다."},{"q":"By when does Ms. Rahman want to receive the new total?","choices":["Tuesday at 5:00 P.M.","Tuesday morning","Monday at noon","Wednesday at 9:30 A.M."],"answer":0,"type":"세부 사항","explanation":"이메일 마지막 'Please send me the new total before Tuesday at 5:00 P.M.'에서 화요일 오후 5시 전까지 새 합계를 보내 달라고 했다. 수요일 오전 9시 30분은 배달 시각이다."}],"translation":"[주문서]\n로즈우드 베이커리 — 케이터링 주문서\n\n고객: 아이샤 라만, 놀랜드 보험\n전화: 555-0187\n방문 수령 또는 배달: 배달\n필요 날짜: 5월 21일 수요일 오전 9시 30분까지\n주소: 놀랜드 보험, 힐 가 210번지 4층\n\n품목 | 수량 | 가격\n버터 크루아상 | 20 | 개당 2.00달러\n블루베리 머핀 | 15 | 개당 2.50달러\n신선한 과일 쟁반(대) | 1 | 30.00달러\n\n배달비: 10.00달러 (100달러 초과 주문 시 무료)\n특별 요청 사항: 냅킨과 종이 접시를 함께 넣어 주세요.\n결제: 놀랜드 보험으로 청구 (30일 이내 지급)\n\n[이메일]\n발신: 아이샤 라만 / 수신: orders@rosewoodbakery.com / 날짜: 5월 19일 / 제목: 주문 변경\n\n안녕하세요.\n\n수요일 오전 케이터링을 주문했습니다. 아쉽게도 교육에 참석할 수 있는 인원이 예상보다 적습니다. 블루베리 머핀 수량을 15개에서 5개로 줄여 주세요. 나머지는 그대로 두시면 됩니다. 교육은 그대로 4층 회의실에서 열리므로 배달 주소는 바뀌지 않습니다.\n\n이 때문에 총액이 달라질 수 있다는 것을 알고 있습니다. 화요일 오후 5시 전까지 새 합계를 보내 주세요.\n\n감사합니다.\n아이샤 라만","part":7},{"id":"p7-039","level":2,"kind":"single","passages":[{"doc_type":"영수증","title":"Receipt — Baxter Home & Hardware","text":"BAXTER HOME & HARDWARE\n1520 Orchard Avenue, Lakemont\nTel. 555-0133\n\nDate: 07/14   Time: 4:52 P.M.\nCashier: Leo\n\nPaint roller set ............ $12.99\nInterior paint (1 gallon, ivory) x 2 ............ $59.98\nPainter's tape ............ $4.50\nDrop cloth ............ $8.25\n\nSubtotal ............ $85.72\nMember discount (10%) ............ -$8.57\nTotal ............ $77.15\nPaid by: Credit card\n\nReturns accepted within 30 days with receipt. Opened paint cannot be returned.\nThis week only: free paint mixing on all orders!\nThank you for shopping at Baxter! Ask about our free delivery on orders over $150."}],"questions":[{"q":"What did the customer most likely plan to do?","choices":["Repair a car","Plant a garden","Build a fence","Paint a room"],"answer":3,"type":"추론","explanation":"구입 품목이 페인트 롤러, 실내용 페인트(Interior paint), 마스킹 테이프, 바닥 보호 천이므로 실내를 칠하려는 것으로 추론할 수 있다. 정원, 자동차, 울타리와 관련된 물건은 없다."},{"q":"What is indicated about the customer?","choices":["The customer is a store member.","The customer returned an item.","The customer paid in cash.","The customer bought outdoor paint."],"answer":0,"type":"사실 확인(NOT/TRUE)","explanation":"'Member discount (10%)'가 적용되었으므로 회원임을 알 수 있다. 결제는 신용카드(Paid by: Credit card)였고, 페인트는 실내용이며, 반품 기록은 없다."},{"q":"According to the receipt, what cannot be returned?","choices":["Items bought at a discount","Paint that has been opened","Tools without a box","Items paid for by credit card"],"answer":1,"type":"세부 사항","explanation":"영수증 아래 'Opened paint cannot be returned.'에서 개봉한 페인트는 반품이 안 된다고 했다. 결제 수단, 할인 여부, 상자 유무에 따른 반품 제한은 언급되지 않았다."}],"translation":"백스터 홈 앤드 하드웨어\n레이크몬트 오처드 가 1520번지\n전화 555-0133\n\n날짜: 7/14   시각: 오후 4:52\n계산원: 레오\n\n페인트 롤러 세트 ...... 12.99달러\n실내용 페인트 (1갤런, 아이보리) 2개 ...... 59.98달러\n마스킹 테이프 ...... 4.50달러\n바닥 보호 천 ...... 8.25달러\n\n소계 ...... 85.72달러\n회원 할인 (10%) ...... -8.57달러\n합계 ...... 77.15달러\n결제 수단: 신용카드\n\n영수증이 있으면 30일 이내 반품 가능합니다. 개봉한 페인트는 반품할 수 없습니다.\n이번 주 한정: 모든 주문에 페인트 조색 무료!\n백스터를 이용해 주셔서 감사합니다! 150달러 초과 주문 무료 배달에 대해 문의해 주세요.","part":7},{"id":"p7-040","level":2,"kind":"single","passages":[{"doc_type":"온라인 채팅","title":"Live Chat — Nimbus Internet Customer Support","text":"Nimbus Support (Priya) [10:02 A.M.]: Welcome to Nimbus Internet. How can I help you today?\nDiego Alvarez [10:03 A.M.]: My internet has been very slow since yesterday. I work from home, so this is a big problem.\nNimbus Support (Priya) [10:04 A.M.]: I'm sorry to hear that. Have you tried restarting your modem?\nDiego Alvarez [10:04 A.M.]: Three times already.\nNimbus Support (Priya) [10:06 A.M.]: Thank you. I've checked your line, and there is some maintenance work in your area. It should be finished by 3:00 P.M. today.\nDiego Alvarez [10:07 A.M.]: I have a video call with a client at 1:00.\nNimbus Support (Priya) [10:08 A.M.]: I understand. I can add 20 GB of free mobile data to your phone plan today so you can use your phone as a hotspot.\nDiego Alvarez [10:09 A.M.]: That would help a lot.\nNimbus Support (Priya) [10:10 A.M.]: Done. You'll get a text message confirming it in a few minutes."}],"questions":[{"q":"What is Mr. Alvarez's problem?","choices":["His modem was not delivered.","He missed a video call.","His internet connection is slow.","His phone bill is too high."],"answer":2,"type":"세부 사항","explanation":"10시 3분 'My internet has been very slow since yesterday.'에서 인터넷이 느린 것이 문제임을 알 수 있다. 화상 통화는 1시에 예정되어 있을 뿐 놓친 것이 아니다."},{"q":"At 10:04 A.M., what does Mr. Alvarez mean when he writes, “Three times already”?","choices":["He has already tried the suggested solution.","He would like three new modems.","He has contacted customer support before.","His internet has stopped working three times."],"answer":0,"type":"의도 파악","explanation":"상담원이 모뎀을 재시작해 봤는지 묻자 '벌써 세 번이나요'라고 답했으므로, 제안된 방법을 이미 해 봤다는 뜻이다. 고객 센터에 여러 번 연락했다거나 모뎀이 필요하다는 뜻이 아니다."},{"q":"Why does Mr. Alvarez mention a video call?","choices":["To ask for a lower monthly rate","To request a technician visit at 1:00","To show that he needs a connection before the repair is finished","To explain why he is contacting support late"],"answer":2,"type":"추론","explanation":"상담원이 작업이 오후 3시에 끝난다고 하자 1시에 고객과 화상 통화가 있다고 했다. 즉 수리가 끝나기 전에 인터넷이 필요하다는 점을 알리려는 것이며, 그래서 상담원이 모바일 데이터를 제안했다."},{"q":"What will Mr. Alvarez most likely receive soon?","choices":["An e-mail invoice","A text message","A visit from a technician","A new modem"],"answer":1,"type":"세부 사항","explanation":"마지막 메시지 'You'll get a text message confirming it in a few minutes.'에서 몇 분 안에 확인 문자를 받게 된다고 했다. 새 모뎀, 청구서, 기사 방문은 언급되지 않았다."}],"translation":"님버스 고객 지원 (프리야) [오전 10:02]: 님버스 인터넷입니다. 무엇을 도와드릴까요?\n디에고 알바레스 [오전 10:03]: 어제부터 인터넷이 너무 느려요. 재택근무를 해서 큰 문제예요.\n님버스 고객 지원 (프리야) [오전 10:04]: 불편을 드려 죄송합니다. 모뎀을 다시 켜 보셨나요?\n디에고 알바레스 [오전 10:04]: 벌써 세 번이나요.\n님버스 고객 지원 (프리야) [오전 10:06]: 감사합니다. 회선을 확인해 보니 고객님 지역에 유지 보수 작업이 있습니다. 오늘 오후 3시까지는 끝날 예정입니다.\n디에고 알바레스 [오전 10:07]: 1시에 고객과 화상 통화가 있어요.\n님버스 고객 지원 (프리야) [오전 10:08]: 알겠습니다. 오늘 고객님 휴대전화 요금제에 무료 모바일 데이터 20GB를 추가해 드릴 수 있어요. 휴대전화를 핫스폿으로 쓰실 수 있도록요.\n디에고 알바레스 [오전 10:09]: 그러면 정말 도움이 되겠어요.\n님버스 고객 지원 (프리야) [오전 10:10]: 처리했습니다. 몇 분 안에 확인 문자를 받으실 거예요.","part":7},{"id":"p7-041","level":2,"kind":"single","passages":[{"doc_type":"보증서","title":"Brevio Limited Warranty — Espresso Machine, Model E-200","text":"BREVIO LIMITED WARRANTY\nProduct: Brevio Espresso Machine, Model E-200\n\nBrevio guarantees this product against defects in materials and workmanship for two years from the date of purchase. During this period, we will repair or replace the machine free of charge.\n\nThis warranty does not cover:\n- damage caused by dropping the machine or by improper use\n- normal wear of parts such as the water filter and rubber seals\n- machines used in restaurants, cafés, or other businesses\n\nTo make a claim, register your product at www.brevio.com/warranty within 30 days of purchase and keep your original receipt. Machines must be sent to an authorized service center. Brevio will pay return shipping after the repair is completed.\n\nCustomer Service: 1-800-555-0166 (Mon–Fri, 8 A.M.–6 P.M.)"}],"questions":[{"q":"How long does the warranty last?","choices":["One year","Five years","30 days","Two years"],"answer":3,"type":"세부 사항","explanation":"첫 단락 'for two years from the date of purchase'에서 구입일로부터 2년간 보증한다고 했다. 30일은 제품 등록 기한이다."},{"q":"What is NOT covered by the warranty?","choices":["A problem caused by poor workmanship","A worn-out water filter","A faulty part found after one year of home use","A defect in the machine's materials"],"answer":1,"type":"사실 확인(NOT/TRUE)","explanation":"보증 제외 항목에 'normal wear of parts such as the water filter'가 있으므로 닳은 정수 필터는 보증 대상이 아니다. 재료·제작상의 결함은 2년간 보증되므로 1년 뒤 가정에서 발견된 불량 부품도 보증된다."},{"q":"The word “authorized” in paragraph 3 is closest in meaning to","choices":["approved","written","famous","local"],"answer":0,"type":"동의어","explanation":"'an authorized service center'는 회사가 인정한(공인된) 서비스 센터를 뜻하므로 'approved(승인된)'와 뜻이 가장 가깝다. written(글로 쓴), famous(유명한), local(지역의)은 문맥에 맞지 않는다."},{"q":"What must customers do to make a claim?","choices":["Call customer service within 30 days","Visit a Brevio store","Keep the original receipt","Pay for return shipping"],"answer":2,"type":"세부 사항","explanation":"셋째 단락에서 30일 이내 웹사이트에서 제품을 등록하고 'keep your original receipt'라고 했다. 반송 배송비는 브레비오가 부담하며, 30일 이내에 해야 하는 것은 전화가 아니라 온라인 등록이다."}],"translation":"브레비오 제한 보증\n제품: 브레비오 에스프레소 머신, 모델 E-200\n\n브레비오는 이 제품의 재료 및 제작상 결함에 대해 구입일로부터 2년간 보증합니다. 이 기간 동안 기계를 무상으로 수리하거나 교체해 드립니다.\n\n다음은 이 보증에 포함되지 않습니다.\n- 기계를 떨어뜨리거나 잘못 사용하여 생긴 손상\n- 정수 필터, 고무 패킹 등 부품의 일반적인 마모\n- 식당, 카페 또는 기타 사업장에서 사용한 기계\n\n보증을 청구하려면 구입 후 30일 이내에 www.brevio.com/warranty에서 제품을 등록하고 영수증 원본을 보관하십시오. 기계는 공인 서비스 센터로 보내야 합니다. 수리가 끝난 뒤 반송 배송비는 브레비오가 부담합니다.\n\n고객 서비스: 1-800-555-0166 (월~금, 오전 8시~오후 6시)","part":7},{"id":"p7-042","level":2,"kind":"single","passages":[{"doc_type":"사내 소식지","title":"Halden Foods Monthly — Employee Spotlight","text":"EMPLOYEE SPOTLIGHT: FATIMA OSEI\n\nThis month, we are happy to introduce Fatima Osei, a quality control specialist at our Riverside packaging plant. [1] Ms. Osei joined Halden Foods six years ago as a machine operator. After completing our in-house training program, she moved to the quality control team in 2023.\n\nLast spring, Ms. Osei noticed that some juice bottles were not being sealed tightly. [2] She worked with the maintenance team to adjust the sealing machines, and the number of returned products dropped by 40 percent. [3]\n\nOutside of work, Ms. Osei coaches a youth soccer team on weekends. [4] Next month, she will lead a workshop for new employees on food safety. Congratulations, Fatima!"}],"questions":[{"q":"What is the purpose of the article?","choices":["To report a product recall","To announce the opening of a new plant","To advertise a training program","To recognize an employee's achievements"],"answer":3,"type":"주제·목적","explanation":"제목 'EMPLOYEE SPOTLIGHT'와 오세이 씨가 반품을 40퍼센트 줄인 일, 마지막의 'Congratulations, Fatima!'로 보아 직원의 성과를 소개·칭찬하는 글이다. 새 공장이나 제품 회수 발표가 아니다."},{"q":"What is indicated about Ms. Osei?","choices":["She designed new juice bottles.","She manages the maintenance team.","She has worked at Halden Foods for ten years.","She began at the company in a different position."],"answer":3,"type":"사실 확인(NOT/TRUE)","explanation":"첫 단락에서 6년 전 기계 운전원(machine operator)으로 입사해 2023년에 품질 관리팀으로 옮겼다고 했으므로 처음에는 다른 직무였다. 근무 기간은 10년이 아니라 6년이고, 정비팀과는 함께 일했을 뿐 관리하지 않는다."},{"q":"What will Ms. Osei do next month?","choices":["Teach new staff about food safety","Replace the sealing machines","Transfer to another plant","Coach in a soccer tournament"],"answer":0,"type":"세부 사항","explanation":"마지막 단락 'Next month, she will lead a workshop for new employees on food safety.'에서 다음 달 신입 직원 대상 식품 안전 워크숍을 진행한다고 했다. 축구 코치는 평소 주말에 하는 일이다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? “Her quick action saved the company thousands of dollars.”","choices":["[1]","[2]","[3]","[4]"],"answer":2,"type":"문장 삽입","explanation":"'Her quick action(그녀의 신속한 조치)'은 밀봉 기계를 조정해 반품이 40퍼센트 줄었다는 내용을 가리키므로 그 바로 뒤인 [3]이 알맞다. [2]는 문제를 발견한 직후라 아직 조치가 나오기 전이다."}],"translation":"이달의 직원: 파티마 오세이\n\n이번 달에는 리버사이드 포장 공장의 품질 관리 전문가 파티마 오세이 씨를 소개합니다. 오세이 씨는 6년 전 기계 운전원으로 할든 푸드에 입사했습니다. 사내 교육 과정을 마친 뒤 2023년에 품질 관리팀으로 옮겼습니다.\n\n지난봄 오세이 씨는 일부 주스 병이 단단히 밀봉되지 않는다는 것을 알아차렸습니다. 그녀는 정비팀과 함께 밀봉 기계를 조정했고, 반품된 제품 수가 40퍼센트 줄었습니다. (그녀의 신속한 조치로 회사는 수천 달러를 아꼈습니다.)\n\n업무 외에 오세이 씨는 주말마다 청소년 축구팀을 지도합니다. 다음 달에는 신입 직원을 대상으로 식품 안전 워크숍을 진행할 예정입니다. 축하합니다, 파티마!","part":7},{"id":"p7-043","level":2,"kind":"single","passages":[{"doc_type":"행사 일정표","title":"Harborfront Food & Music Festival — Saturday Program","text":"HARBORFRONT FOOD & MUSIC FESTIVAL\nSaturday, August 23 — Pier 9 Park\n\n10:00 A.M. Gates open / Farmers' market (North Lawn)\n11:00 A.M. Cooking demonstration: Korean street food with Chef Min-ji Kang (Tent A)\n12:30 P.M. Children's pizza-making class (Tent B) — ages 6-12, sign-up required\n2:00 P.M. Live music: The Blue Tides (Main Stage)\n3:30 P.M. Cooking demonstration: Brazilian barbecue with Chef Rafael Lima (Tent A)\n5:00 P.M. Dessert contest — results announced (Main Stage)\n7:00 P.M. Fireworks over the harbor\n\nAdmission is free. Food tickets are sold at the information booth ($1 per ticket). In case of rain, cooking demonstrations will move to the Community Hall on Dock Street."}],"questions":[{"q":"Where will Chef Lima's demonstration take place if it rains?","choices":["In Tent B","At the Community Hall","At the information booth","On the Main Stage"],"answer":1,"type":"세부 사항","explanation":"마지막 문장 'In case of rain, cooking demonstrations will move to the Community Hall on Dock Street.'에서 비가 오면 요리 시연이 커뮤니티 홀로 옮겨진다고 했다. 리마 셰프의 행사는 요리 시연이므로 커뮤니티 홀에서 열린다."},{"q":"What is required for the children's class?","choices":["Bringing an adult ticket","Buying a food ticket","Signing up","Wearing an apron"],"answer":2,"type":"세부 사항","explanation":"12시 30분 항목 'ages 6-12, sign-up required'에서 신청이 필요하다고 했다. 식권, 성인 입장권, 앞치마는 언급되지 않았다."},{"q":"What is true about the festival?","choices":["Visitors do not pay to enter.","Food tickets are sold online.","Live music begins in the morning.","It lasts for two days."],"answer":0,"type":"사실 확인(NOT/TRUE)","explanation":"'Admission is free.'에서 입장료가 없음을 알 수 있다. 일정은 토요일 하루이고, 라이브 음악은 오후 2시에 시작하며, 식권은 안내 부스에서 판다."},{"q":"What will most likely happen at 5:00 P.M.?","choices":["The farmers' market will open.","Contest winners will be revealed.","A band will begin performing.","A chef will teach children."],"answer":1,"type":"추론","explanation":"5시 항목 'Dessert contest — results announced'에서 디저트 대회 결과가 발표된다고 했으므로 우승자가 공개될 것이다. 밴드 공연은 2시, 농산물 시장은 10시, 어린이 수업은 12시 30분이다."}],"translation":"하버프런트 음식·음악 축제\n8월 23일 토요일 — 9번 부두 공원\n\n오전 10:00 개장 / 농산물 시장 (북쪽 잔디밭)\n오전 11:00 요리 시연: 강민지 셰프의 한국 길거리 음식 (A 천막)\n오후 12:30 어린이 피자 만들기 교실 (B 천막) — 6~12세, 사전 신청 필수\n오후 2:00 라이브 음악: 더 블루 타이즈 (메인 무대)\n오후 3:30 요리 시연: 라파엘 리마 셰프의 브라질식 바비큐 (A 천막)\n오후 5:00 디저트 경연 대회 — 결과 발표 (메인 무대)\n오후 7:00 항구 불꽃놀이\n\n입장은 무료입니다. 식권은 안내 부스에서 판매합니다(1장 1달러). 비가 오면 요리 시연은 도크 가의 커뮤니티 홀로 옮겨 진행합니다.","part":7},{"id":"p7-044","level":2,"kind":"double","passages":[{"doc_type":"구인 광고","title":"Spokes & Gears Bicycle Shop — Now Hiring","text":"SPOKES & GEARS BICYCLE SHOP — NOW HIRING\n\nWe are looking for a full-time bicycle mechanic to join our busy shop on Carver Avenue in Millbrook.\n\nResponsibilities:\n- Repair and tune bicycles, including electric bikes\n- Help customers choose parts and accessories\n- Keep the workshop clean and organized\n\nRequirements:\n- At least two years of repair experience\n- Weekend availability\n- A certificate in electric bike repair is a plus\n\nWe offer competitive pay, a 30 percent staff discount, and free training courses. To apply, send your résumé to Marco Bianchi at jobs@spokesgears.com by March 15."},{"doc_type":"이메일","title":"From: Yusuf Demir / To: jobs@spokesgears.com / Date: March 10 / Subject: Bicycle mechanic position","text":"Dear Mr. Bianchi,\n\nI am writing to apply for the bicycle mechanic position advertised on your Web site. For the past three years, I have worked at Ridewell Cycles, where I repair about 15 bicycles each week. Last year, I also earned a certificate in electric bike repair.\n\nI am currently studying part-time on weekday evenings, but I am free all day on Saturdays and Sundays. I have been a customer of your shop for years and would love to be part of your team.\n\nMy résumé is attached. Thank you for your consideration.\n\nSincerely,\nYusuf Demir"}],"questions":[{"q":"What is NOT listed as a responsibility of the job?","choices":["Fixing electric bicycles","Advising customers on parts","Cleaning the workshop","Delivering bicycles to customers"],"answer":3,"type":"사실 확인(NOT/TRUE)","explanation":"광고의 업무 목록에는 전기 자전거를 포함한 수리, 부품 선택 안내, 작업장 정리가 있다. 고객에게 자전거를 배달하는 일은 없으므로 이것이 정답이다."},{"q":"What benefit does the shop offer?","choices":["A discount on store products","A free bicycle","A company car","Paid travel abroad"],"answer":0,"type":"세부 사항","explanation":"광고 마지막 단락 'a 30 percent staff discount'에서 직원 할인을 제공한다고 했다. 이 밖에 경쟁력 있는 급여와 무료 교육이 있을 뿐, 자전거·해외여행·회사 차량은 없다."},{"q":"What is suggested about Mr. Demir?","choices":["He does not have enough repair experience.","He has worked at Spokes & Gears before.","He has a qualification that the shop prefers.","He cannot work on weekends."],"answer":2,"type":"연계 문제","explanation":"광고는 전기 자전거 수리 자격증을 우대 사항(a plus)으로 들었고, 데미르 씨는 이메일에서 작년에 그 자격증을 땄다고 했다. 경력은 3년으로 조건(2년 이상)을 넘고, 주말에는 하루 종일 가능하며, 이 가게에서는 손님이었을 뿐 일한 적은 없다."},{"q":"How does Mr. Demir know about Spokes & Gears?","choices":["He took a training course there.","A friend works there.","He read about it in a newspaper.","He has shopped there."],"answer":3,"type":"세부 사항","explanation":"이메일 둘째 단락 'I have been a customer of your shop for years'에서 오랫동안 그 가게의 손님이었다고 했다. 광고는 신문이 아니라 웹사이트에서 보았다."},{"q":"What is true about Mr. Demir's application?","choices":["It did not include a résumé.","It was sent before the deadline.","It was sent by mail.","It was sent to the wrong person."],"answer":1,"type":"연계 문제","explanation":"광고의 지원 마감은 3월 15일이고 이메일은 3월 10일에 보냈으므로 마감 전에 지원했다. 광고에서 지정한 마르코 비앙키 씨에게 이메일로 보냈고, 이력서도 첨부했다(My résumé is attached)."}],"translation":"[구인 광고]\n스포크스 앤드 기어스 자전거 가게 — 직원 모집\n\n밀브룩 카버 가에 있는 저희 바쁜 가게에서 함께 일할 정규직 자전거 정비사를 찾습니다.\n\n업무:\n- 전기 자전거를 포함한 자전거 수리 및 정비\n- 고객의 부품·액세서리 선택 도움\n- 작업장을 깨끗하고 정돈된 상태로 유지\n\n자격 요건:\n- 수리 경력 2년 이상\n- 주말 근무 가능\n- 전기 자전거 수리 자격증 소지자 우대\n\n경쟁력 있는 급여, 30퍼센트 직원 할인, 무료 교육 과정을 제공합니다. 지원하려면 3월 15일까지 이력서를 마르코 비앙키(jobs@spokesgears.com)에게 보내 주세요.\n\n[이메일]\n발신: 유수프 데미르 / 수신: jobs@spokesgears.com / 날짜: 3월 10일 / 제목: 자전거 정비사 직책\n\n비앙키 씨께,\n\n귀사 웹사이트에 게시된 자전거 정비사 직책에 지원하고자 이 글을 씁니다. 저는 지난 3년 동안 라이드웰 사이클스에서 일하며 매주 약 15대의 자전거를 수리해 왔습니다. 작년에는 전기 자전거 수리 자격증도 취득했습니다.\n\n현재 평일 저녁에 시간제로 공부하고 있지만, 토요일과 일요일에는 하루 종일 시간이 됩니다. 저는 수년간 귀사의 손님이었고, 귀사 팀의 일원이 되고 싶습니다.\n\n이력서를 첨부합니다. 검토해 주셔서 감사합니다.\n\n유수프 데미르 드림","part":7},{"id":"p7-045","level":2,"kind":"double","passages":[{"doc_type":"강좌 안내","title":"Westbury Community College — Evening Courses, Fall Term","text":"WESTBURY COMMUNITY COLLEGE\nEvening Courses — Fall Term (Starts September 8)\n\nCourse | Day | Time | Weeks | Fee\nBeginner Spanish (L101) | Monday | 6:30–8:00 P.M. | 10 | $180\nDigital Photography (P210) | Tuesday | 7:00–9:00 P.M. | 8 | $220\nSmall Business Accounting (B150) | Wednesday | 6:00–8:30 P.M. | 12 | $260\nPublic Speaking (C120) | Thursday | 6:30–8:30 P.M. | 6 | $150\n\n- Students who register for two or more courses receive $30 off the total fee.\n- P210 students must bring their own camera.\n- Register online at www.westbury.edu/evening or at the Student Services Office."},{"doc_type":"이메일","title":"From: Hana Novak / To: Student Services, Westbury Community College / Date: August 28 / Subject: Registration question","text":"Hello,\n\nI would like to sign up for the course on Tuesday evenings. I recently opened a small bakery, so I am also interested in the accounting course. However, I work late on Wednesdays, so I can't attend it this term. Instead, I will take the Thursday course, since I often have to present my products to customers.\n\nCould you tell me whether I can pay the fees in two parts? Also, is there parking near Building C?\n\nThank you,\nHana Novak"}],"questions":[{"q":"What must students in the Digital Photography course provide?","choices":["Printed photographs","A textbook","Their own camera","A laptop computer"],"answer":2,"type":"세부 사항","explanation":"강좌 안내의 'P210 students must bring their own camera.'에서 디지털 사진(P210) 수강생은 자기 카메라를 가져와야 한다고 했다. 노트북, 사진 인화물, 교재는 언급되지 않았다."},{"q":"Why can't Ms. Novak take the accounting course?","choices":["She has taken it before.","She works late on the day it meets.","It is too expensive for her.","It is already full."],"answer":1,"type":"세부 사항","explanation":"이메일 'I work late on Wednesdays, so I can't attend it this term.'에서 수요일에 늦게까지 일해 들을 수 없다고 했다. 강좌 안내에 따르면 회계 강좌(B150)는 수요일 수업이다."},{"q":"Which course will Ms. Novak take to help her present her products?","choices":["C120","P210","B150","L101"],"answer":0,"type":"연계 문제","explanation":"이메일에서 제품을 고객에게 소개할 일이 많아 목요일 강좌를 듣겠다고 했고, 강좌 안내에서 목요일 강좌는 대중 연설(Public Speaking, C120)이다. B150은 수요일 회계, P210은 화요일 사진 강좌이다."},{"q":"How much will Ms. Novak most likely pay in total?","choices":["$310","$370","$400","$340"],"answer":3,"type":"연계 문제","explanation":"노박 씨는 화요일 P210(220달러)과 목요일 C120(150달러)을 들으므로 합계 370달러이고, 두 과목 이상 등록하면 30달러 할인되므로 340달러를 낸다. 370달러는 할인 전 금액이다."},{"q":"What does Ms. Novak ask about?","choices":["A payment option","Class sizes","A course textbook","A refund policy"],"answer":0,"type":"세부 사항","explanation":"이메일 마지막 단락에서 수강료를 두 번에 나눠 낼 수 있는지(pay the fees in two parts)와 주차 가능 여부를 물었다. 교재, 환불 규정, 수강 인원은 묻지 않았다."}],"translation":"[강좌 안내]\n웨스트버리 커뮤니티 칼리지\n야간 강좌 — 가을 학기 (9월 8일 개강)\n\n강좌 | 요일 | 시간 | 주 수 | 수강료\n초급 스페인어 (L101) | 월요일 | 오후 6:30~8:00 | 10 | 180달러\n디지털 사진 (P210) | 화요일 | 오후 7:00~9:00 | 8 | 220달러\n소상공인 회계 (B150) | 수요일 | 오후 6:00~8:30 | 12 | 260달러\n대중 연설 (C120) | 목요일 | 오후 6:30~8:30 | 6 | 150달러\n\n- 두 과목 이상 등록하면 총 수강료에서 30달러를 할인해 드립니다.\n- P210 수강생은 개인 카메라를 가져와야 합니다.\n- 등록은 www.westbury.edu/evening 또는 학생 지원실에서 할 수 있습니다.\n\n[이메일]\n발신: 하나 노박 / 수신: 웨스트버리 커뮤니티 칼리지 학생 지원실 / 날짜: 8월 28일 / 제목: 등록 문의\n\n안녕하세요.\n\n화요일 저녁 강좌에 등록하고 싶습니다. 최근에 작은 빵집을 열어서 회계 강좌에도 관심이 있습니다. 하지만 수요일에는 늦게까지 일해서 이번 학기에는 들을 수 없습니다. 대신 고객에게 제품을 소개할 일이 많아서 목요일 강좌를 듣겠습니다.\n\n수강료를 두 번에 나눠 낼 수 있는지 알려 주시겠어요? 그리고 C동 근처에 주차장이 있나요?\n\n감사합니다.\n하나 노박","part":7},{"id":"p7-046","level":2,"kind":"triple","passages":[{"doc_type":"웹페이지","title":"www.trailcraftgear.com/backpacks","text":"TRAILCRAFT GEAR — Hiking Backpacks\n\nDayLite 20 — $59\n20 liters. Light and simple, perfect for short walks. Colors: gray, blue.\n\nSummit 35 — $89\n35 liters. Waterproof cover included. Colors: green, black.\n\nExpedition 50 — $129\n50 liters. Waterproof cover included. Padded laptop pocket. Colors: black, red.\n\nFree shipping on orders over $75. All backpacks can be returned within 60 days if unused. Not sure which size is right for you? Use our online size guide or chat with our staff, available every day from 8 A.M. to 8 P.M."},{"doc_type":"후기","title":"Customer Review ★★☆☆☆ — Posted by Chloé Martin, October 4","text":"I bought this backpack for a three-day hiking trip last month. The size was perfect for my clothes and food, and the waterproof cover kept everything dry during a storm. However, after only two days, one of the shoulder straps started to tear. I expected better quality at this price, especially since I paid $89. I also had to pay for shipping, even though the Web site says shipping is free for orders like mine. I have contacted customer service and am waiting for a reply."},{"doc_type":"이메일","title":"From: Tom Eriksen, TrailCraft Gear / To: Chloé Martin / Date: October 6 / Subject: Your review and order #7781","text":"Dear Ms. Martin,\n\nThank you for your honest review, and I am sorry about the torn strap. I have checked your order, and you are correct: a system error added a shipping charge to several orders in September. We have refunded the $8 fee to your credit card.\n\nBecause your backpack has been used, it cannot be returned for a refund. However, we will send you a replacement free of charge. It will be the same color as your original one unless you tell me you would prefer the other color we offer for that model.\n\nBest regards,\nTom Eriksen\nCustomer Care, TrailCraft Gear"}],"questions":[{"q":"Which backpack did Ms. Martin most likely buy?","choices":["The Expedition 50","A model that is not listed","The Summit 35","The DayLite 20"],"answer":2,"type":"연계 문제","explanation":"후기에서 89달러를 냈고 방수 커버가 있었다고 했는데, 웹페이지에서 89달러이고 방수 커버가 포함된 제품은 서밋 35이다. 데이라이트 20은 59달러, 익스페디션 50은 129달러이다."},{"q":"What does Ms. Martin praise about the backpack?","choices":["It is extremely light.","It kept her belongings dry.","It has a laptop pocket.","Its straps are very strong."],"answer":1,"type":"세부 사항","explanation":"후기에서 'the waterproof cover kept everything dry during a storm'이라며 폭풍 속에서도 물건이 젖지 않았다고 칭찬했다. 어깨끈은 오히려 찢어졌고, 노트북 수납은 익스페디션 50의 기능이다."},{"q":"What is suggested about the shipping fee that Ms. Martin paid?","choices":["It will be deducted from her replacement.","It was higher than the price of the backpack.","It was added because she ordered in October.","It should not have been charged because of her order total."],"answer":3,"type":"연계 문제","explanation":"웹페이지는 75달러를 넘는 주문에 무료 배송이라고 했는데, 마틴 씨는 89달러를 냈으므로 배송비가 부과되지 말았어야 했다. 이메일도 시스템 오류로 9월 주문에 배송비가 붙었다며 8달러를 환불했다."},{"q":"What will Ms. Martin receive?","choices":["A discount coupon","A full refund of $89","A new backpack at no cost","A repair kit for the strap"],"answer":2,"type":"세부 사항","explanation":"이메일 둘째 단락 'we will send you a replacement free of charge'에서 새 가방을 무료로 보내 준다고 했다. 사용한 가방이라 환불은 안 되며, 쿠폰이나 수리 키트는 언급되지 않았다."},{"q":"If Ms. Martin wants a different color, which color could she choose?","choices":["Gray","Blue","Red","Green or black, whichever she did not have"],"answer":3,"type":"추론","explanation":"이메일은 그 모델의 '다른 색상'을 고를 수 있다고 했고, 웹페이지에서 서밋 35의 색상은 초록과 검정 두 가지뿐이다. 따라서 원래 색이 아닌 초록이나 검정 중 하나를 고를 수 있다. 회색·파랑은 데이라이트 20, 빨강은 익스페디션 50의 색상이다."}],"translation":"[웹페이지]\n트레일크래프트 기어 — 등산 배낭\n\n데이라이트 20 — 59달러\n20리터. 가볍고 단순해 짧은 산책에 딱 맞습니다. 색상: 회색, 파란색.\n\n서밋 35 — 89달러\n35리터. 방수 커버 포함. 색상: 초록색, 검은색.\n\n익스페디션 50 — 129달러\n50리터. 방수 커버 포함. 완충 노트북 수납칸. 색상: 검은색, 빨간색.\n\n75달러 초과 주문은 무료 배송. 모든 배낭은 사용하지 않은 경우 60일 이내 반품할 수 있습니다. 어떤 크기가 맞을지 모르겠다면 온라인 크기 안내를 이용하시거나 매일 오전 8시부터 오후 8시까지 직원과 채팅으로 상담하세요.\n\n[후기]\n고객 후기 ★★☆☆☆ — 작성자: 클로에 마르탱, 10월 4일\n\n지난달 3일짜리 등산 여행을 위해 이 배낭을 샀습니다. 옷과 음식을 넣기에 크기가 딱 맞았고, 폭풍우 속에서도 방수 커버 덕분에 모든 게 젖지 않았어요. 그런데 겨우 이틀 만에 어깨끈 하나가 찢어지기 시작했습니다. 이 가격이면 품질이 더 좋을 줄 알았어요. 특히 89달러나 냈으니까요. 게다가 웹사이트에는 제 주문 같은 경우 배송이 무료라고 되어 있는데도 배송비를 내야 했습니다. 고객 서비스에 연락했고 답변을 기다리고 있습니다.\n\n[이메일]\n발신: 톰 에릭센, 트레일크래프트 기어 / 수신: 클로에 마르탱 / 날짜: 10월 6일 / 제목: 고객님의 후기와 주문 #7781\n\n마르탱 님께,\n\n솔직한 후기에 감사드리며, 어깨끈이 찢어진 점 사과드립니다. 주문을 확인해 보니 말씀하신 대로 9월에 시스템 오류로 여러 주문에 배송비가 추가되었습니다. 배송비 8달러는 고객님의 신용카드로 환불해 드렸습니다.\n\n배낭을 사용하셨기 때문에 반품 환불은 해 드릴 수 없습니다. 하지만 교체품을 무료로 보내 드리겠습니다. 해당 모델에서 판매하는 다른 색상을 원한다고 알려 주시지 않으면 원래 제품과 같은 색상으로 보내 드립니다.\n\n톰 에릭센\n트레일크래프트 기어 고객 관리팀","part":7},{"id":"p7-047","level":3,"kind":"single","passages":[{"doc_type":"회의 안건","title":"Solvay Kitchenware — Product Planning Meeting Agenda","text":"SOLVAY KITCHENWARE\nProduct Planning Meeting — Agenda\nDate: Tuesday, November 4\nTime: 9:30 A.M.–12:00 P.M.\nLocation: Conference Room 3B (remote participants: use the video link in the calendar invitation)\n\n9:30 Welcome and review of last meeting's action items — Ingrid Solberg, Director\n9:45 Third-quarter sales results for the Everyday cookware line — Tariq Aziz\n10:15 Customer feedback on the new nonstick frying pans — Lena Fischer\n10:45 Break\n11:00 Proposal: expanding into the café equipment market — Rahul Menon\n11:40 Open discussion and next steps\n\nNotes: Please read the attached customer survey summary before the meeting. Mr. Menon's proposal is still a draft and should not be shared outside the planning team. Lunch will be provided in the staff lounge after the meeting."}],"questions":[{"q":"What will Ms. Fischer talk about?","choices":["A plan to enter a new market","Customers' opinions of a product","Tasks from the previous meeting","Sales figures for the third quarter"],"answer":1,"type":"세부 사항","explanation":"10시 15분 항목 'Customer feedback on the new nonstick frying pans — Lena Fischer'에서 새 코팅 프라이팬에 대한 고객 의견을 발표함을 알 수 있다. 3분기 매출은 아지즈 씨, 신시장 진출은 메논 씨, 지난 회의 과제 검토는 솔베르그 씨 담당이다."},{"q":"What are participants asked to do before the meeting?","choices":["Read a document","Submit a proposal","Order lunch","Test some frying pans"],"answer":0,"type":"세부 사항","explanation":"Notes의 첫 문장 'Please read the attached customer survey summary before the meeting.'에서 첨부된 고객 설문 요약을 미리 읽으라고 했다. 점심은 회사에서 제공한다."},{"q":"What is suggested about Mr. Menon's proposal?","choices":["It was presented at the last meeting.","It has already been approved.","It concerns nonstick frying pans.","It is confidential for now."],"answer":3,"type":"추론","explanation":"Notes에서 메논 씨의 제안은 아직 초안이며 기획팀 밖으로 공유하면 안 된다고 했으므로 현재는 대외비임을 알 수 있다. 초안이므로 승인된 것이 아니며, 주제는 카페 장비 시장 진출이다."},{"q":"In the agenda, the word “line” in the item at 9:45 is closest in meaning to","choices":["border","row","range","queue"],"answer":2,"type":"동의어","explanation":"'the Everyday cookware line'은 '에브리데이'라는 이름으로 묶인 조리 기구 제품군을 뜻하므로 'range(제품군)'와 뜻이 가장 가깝다. queue(대기 줄), row(열), border(경계)는 문맥에 맞지 않는다."}],"translation":"솔베이 키친웨어\n제품 기획 회의 — 안건\n날짜: 11월 4일 화요일\n시간: 오전 9시 30분~오후 12시\n장소: 3B 회의실 (원격 참석자는 일정 초대장의 화상 회의 링크 사용)\n\n9:30 개회 및 지난 회의 실행 과제 검토 — 잉그리드 솔베르그 이사\n9:45 에브리데이 조리 기구 제품군 3분기 매출 실적 — 타리크 아지즈\n10:15 신제품 코팅 프라이팬에 대한 고객 의견 — 레나 피셔\n10:45 휴식\n11:00 제안: 카페 장비 시장 진출 — 라훌 메논\n11:40 자유 토론 및 향후 계획\n\n참고: 회의 전에 첨부된 고객 설문 요약을 읽어 주십시오. 메논 씨의 제안은 아직 초안이므로 기획팀 외부에 공유하면 안 됩니다. 회의 후 직원 휴게실에서 점심이 제공됩니다.","part":7},{"id":"p7-048","level":3,"kind":"single","passages":[{"doc_type":"문자 메시지","title":"Text-message chain","text":"Grace Liu (1:12 P.M.): Our booth at the Home Expo opens at 9 tomorrow. Has anyone confirmed the display furniture?\nOmar Haddad (1:14 P.M.): The rental company says the delivery truck will arrive at 7:30 A.M.\nGrace Liu (1:15 P.M.): Good. What about the brochures?\nOmar Haddad (1:16 P.M.): Bella was handling those.\nBella Rossi (1:20 P.M.): Sorry, I was on a call. The printer just told me they found a mistake in our phone number, so they're reprinting all 500.\nGrace Liu (1:21 P.M.): Will they be ready in time?\nBella Rossi (1:22 P.M.): Not before tomorrow afternoon, unfortunately.\nGrace Liu (1:24 P.M.): Then let's print 100 copies at the office tonight to use in the morning.\nOmar Haddad (1:25 P.M.): The office printer is out of color ink.\nBella Rossi (1:27 P.M.): I'll pick some up on my way back from lunch.\nGrace Liu (1:28 P.M.): Perfect. Omar, can you meet the truck at the convention center tomorrow?\nOmar Haddad (1:29 P.M.): I'll be there at 7:15."}],"questions":[{"q":"What event are the writers preparing for?","choices":["An exhibition","A job fair","A training workshop","A company picnic"],"answer":0,"type":"세부 사항","explanation":"첫 메시지 'Our booth at the Home Expo opens at 9 tomorrow.'에서 홈 엑스포(박람회)의 부스를 준비하고 있음을 알 수 있다. 교육, 야유회, 채용 박람회는 언급되지 않았다."},{"q":"What problem does Ms. Rossi report?","choices":["A delivery truck has broken down.","Some printed materials contained an error.","Some furniture was damaged.","The booth location has changed."],"answer":1,"type":"세부 사항","explanation":"1시 20분 메시지에서 인쇄소가 전화번호 오류를 발견해 500부를 모두 다시 인쇄한다고 했으므로, 인쇄물에 오류가 있었다는 것이 문제이다. 트럭은 7시 30분에 올 예정이다."},{"q":"At 1:25 P.M., why does Mr. Haddad write, “The office printer is out of color ink”?","choices":["To suggest printing the brochures in black and white","To ask Ms. Rossi to call the print shop","To point out a problem with Ms. Liu's plan","To explain how the mistake in the brochures happened"],"answer":2,"type":"의도 파악","explanation":"바로 앞에서 리우 씨가 오늘 밤 사무실에서 100부를 인쇄하자고 하자 해다드 씨가 사무실 프린터에 컬러 잉크가 없다고 했다. 즉 그 계획의 문제점을 지적한 것이며, 이어서 로시 씨가 잉크를 사 오겠다고 한 것도 이를 뒷받침한다."},{"q":"What will Mr. Haddad most likely do tomorrow morning?","choices":["Wait for a furniture delivery","Buy printer ink","Pick up brochures from the printer","Design a new brochure"],"answer":0,"type":"추론","explanation":"리우 씨가 내일 컨벤션 센터에서 트럭을 맞아 달라고 하자 해다드 씨가 7시 15분에 가겠다고 했다. 이 트럭은 1시 14분에 언급된 진열 가구 배송 트럭이므로 가구 배송을 기다릴 것이다. 잉크는 로시 씨가 사 온다."}],"translation":"그레이스 리우 (오후 1:12): 홈 엑스포 우리 부스가 내일 9시에 열어요. 진열 가구는 누가 확인했나요?\n오마르 해다드 (오후 1:14): 대여 업체 말로는 배송 트럭이 오전 7시 30분에 도착한대요.\n그레이스 리우 (오후 1:15): 좋아요. 안내 책자는요?\n오마르 해다드 (오후 1:16): 그건 벨라가 맡고 있었어요.\n벨라 로시 (오후 1:20): 미안해요, 통화 중이었어요. 인쇄소에서 방금 우리 전화번호에 오류가 있는 걸 발견해서 500부를 전부 다시 인쇄한대요.\n그레이스 리우 (오후 1:21): 시간 안에 준비될까요?\n벨라 로시 (오후 1:22): 아쉽게도 내일 오후 전에는 안 된대요.\n그레이스 리우 (오후 1:24): 그럼 오늘 밤 사무실에서 100부를 인쇄해서 오전에 쓰죠.\n오마르 해다드 (오후 1:25): 사무실 프린터에 컬러 잉크가 떨어졌어요.\n벨라 로시 (오후 1:27): 점심 먹고 돌아오는 길에 사 올게요.\n그레이스 리우 (오후 1:28): 좋아요. 오마르, 내일 컨벤션 센터에서 트럭 좀 맞아 줄 수 있어요?\n오마르 해다드 (오후 1:29): 7시 15분에 가 있을게요.","part":7},{"id":"p7-049","level":3,"kind":"single","passages":[{"doc_type":"임대 계약서","title":"Commercial Lease Agreement — Excerpt","text":"COMMERCIAL LEASE AGREEMENT (EXCERPT)\n\nThis agreement is made between Crestview Properties (\"Landlord\") and Amara Nwosu, owner of Petal & Stem Florist (\"Tenant\"), for the ground-floor unit at 77 Linden Street.\n\nSection 3. Term. The lease begins on March 1 and runs for three years. The Tenant may renew the lease for an additional two years by giving written notice at least 90 days before the end of the term.\n\nSection 4. Rent. Monthly rent is $2,400, due on the first day of each month. A late fee of $75 will be charged if rent is received after the fifth day of the month.\n\nSection 7. Alterations. The Tenant may not make structural changes to the unit without the Landlord's written approval. Signs placed on the front window must comply with city regulations.\n\nSection 9. Maintenance. The Landlord is responsible for repairs to the roof, heating system, and plumbing. The Tenant is responsible for cleaning and for any damage caused by the Tenant's customers or employees."}],"questions":[{"q":"What kind of business will occupy the unit?","choices":["A clothing store","A law office","A bakery","A flower shop"],"answer":3,"type":"세부 사항","explanation":"첫 단락에서 임차인이 'Petal & Stem Florist'의 주인이라고 했으므로 꽃집이 들어선다. 다른 업종은 언급되지 않았다."},{"q":"What must Ms. Nwosu do to extend the lease?","choices":["Obtain approval from the city","Notify the landlord in writing in advance","Pay an additional deposit","Sign a new agreement on March 1"],"answer":1,"type":"세부 사항","explanation":"3조에서 임대 기간 종료 최소 90일 전에 서면 통지(written notice)를 하면 2년 더 연장할 수 있다고 했다. 추가 보증금이나 시의 승인은 연장 조건이 아니다."},{"q":"What is NOT the tenant's responsibility under the agreement?","choices":["Repairing the plumbing","Fixing damage caused by employees","Cleaning the unit","Paying rent by the fifth of the month to avoid a fee"],"answer":0,"type":"사실 확인(NOT/TRUE)","explanation":"9조에서 지붕, 난방, 배관 수리는 임대인(Landlord) 책임이라고 했다. 청소와 직원·고객이 낸 손상은 임차인 책임이고, 4조에 따라 5일이 지나 납부하면 연체료가 붙는다."},{"q":"The word “comply” in Section 7 is closest in meaning to","choices":["compete","complete","conform","compare"],"answer":2,"type":"동의어","explanation":"'must comply with city regulations'는 시의 규정을 따라야 한다는 뜻이므로 'conform(따르다, 부합하다)'과 가장 가깝다. 나머지는 철자가 비슷할 뿐 뜻이 다르다."}],"translation":"상가 임대차 계약서 (발췌)\n\n이 계약은 크레스트뷰 프로퍼티스(\"임대인\")와 페털 앤드 스템 꽃집의 주인 아마라 은워수(\"임차인\") 사이에 린든 가 77번지 1층 점포에 대해 체결한다.\n\n제3조 기간. 임대 기간은 3월 1일에 시작하여 3년간 지속된다. 임차인은 기간 종료 최소 90일 전에 서면으로 통지하면 2년 더 임대를 연장할 수 있다.\n\n제4조 임대료. 월 임대료는 2,400달러이며 매월 1일에 납부한다. 그달 5일이 지나 임대료가 입금되면 연체료 75달러가 부과된다.\n\n제7조 개조. 임차인은 임대인의 서면 승인 없이 점포의 구조를 변경할 수 없다. 앞 유리창에 붙이는 간판은 시의 규정을 따라야 한다.\n\n제9조 유지 보수. 임대인은 지붕, 난방 시설, 배관 수리를 책임진다. 임차인은 청소와 임차인의 고객이나 직원이 초래한 모든 손상을 책임진다.","part":7},{"id":"p7-050","level":3,"kind":"single","passages":[{"doc_type":"보도 자료","title":"FOR IMMEDIATE RELEASE — Andes SolarWorks","text":"FOR IMMEDIATE RELEASE\nContact: Valentina Ortiz, Communications Manager, press@andessolar.com\n\nANDES SOLARWORKS TO OPEN NEW FACTORY IN ANTOFAGASTA\n\nSANTIAGO, May 12 — Andes SolarWorks, a manufacturer of solar panels for homes and small businesses, announced today that it will open a new factory in the northern city of Antofagasta next spring. [1] The facility will produce up to 400,000 panels per year, doubling the company's current output.\n\nThe new plant is expected to create about 350 jobs. [2] Andes SolarWorks will work with local technical schools to train workers, and hiring will begin in October. \"Antofagasta has excellent sunlight and a strong engineering community,\" said CEO Joaquín Reyes. \"It was the natural choice for us.\"\n\n[3] The company's panels are currently sold in Chile, Peru, and Argentina. With the added production, Andes SolarWorks plans to begin exporting to Brazil the following year. [4]\n\nMore information about job openings will be posted at www.andessolar.com/careers."}],"questions":[{"q":"What is the purpose of the press release?","choices":["To advertise a new line of home appliances","To announce a company's expansion","To report a decline in sales","To introduce a new chief executive"],"answer":1,"type":"주제·목적","explanation":"첫 단락에서 안데스 솔라웍스가 안토파가스타에 새 공장을 열어 생산량을 두 배로 늘린다고 발표했으므로 회사의 확장을 알리는 글이다. 레예스 CEO는 새로 소개되는 인물이 아니며 매출 감소는 언급되지 않았다."},{"q":"What is indicated about the new factory?","choices":["It will produce panels only for Brazil.","It will open in October.","It will be located in Santiago.","It will increase the company's production capacity."],"answer":3,"type":"사실 확인(NOT/TRUE)","explanation":"'doubling the company's current output'에서 현재 생산량을 두 배로 늘린다고 했다. 공장은 내년 봄에 열고 10월은 채용 시작 시점이며, 위치는 산티아고가 아니라 안토파가스타이다."},{"q":"According to the press release, what will happen in October?","choices":["The factory will begin operating.","The company will start hiring.","Exports to Brazil will begin.","A new CEO will be appointed."],"answer":1,"type":"세부 사항","explanation":"둘째 단락 'hiring will begin in October'에서 10월에 채용이 시작된다고 했다. 공장 가동은 내년 봄, 브라질 수출은 그다음 해이다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? “Most of these positions will be in production and quality testing.”","choices":["[1]","[2]","[3]","[4]"],"answer":1,"type":"문장 삽입","explanation":"'these positions(이 일자리들)'는 약 350개의 일자리를 가리키므로 'The new plant is expected to create about 350 jobs.' 바로 뒤인 [2]가 알맞다. 다른 위치 앞에는 일자리를 언급한 문장이 없다."}],"translation":"즉시 배포용 보도 자료\n문의: 발렌티나 오르티스, 홍보 담당 매니저, press@andessolar.com\n\n안데스 솔라웍스, 안토파가스타에 새 공장 개설\n\n산티아고, 5월 12일 — 가정 및 소규모 사업장용 태양광 패널 제조사인 안데스 솔라웍스는 내년 봄 북부 도시 안토파가스타에 새 공장을 연다고 오늘 발표했다. 이 시설은 연간 최대 40만 개의 패널을 생산하여 회사의 현재 생산량을 두 배로 늘리게 된다.\n\n새 공장은 약 350개의 일자리를 만들 것으로 예상된다. (이 일자리의 대부분은 생산 및 품질 검사 분야가 될 것이다.) 안데스 솔라웍스는 지역 기술 학교와 협력해 인력을 교육할 예정이며, 채용은 10월에 시작된다. 호아킨 레예스 CEO는 \"안토파가스타는 일조량이 뛰어나고 탄탄한 엔지니어 인력층이 있다\"며 \"우리에게는 자연스러운 선택이었다\"고 말했다.\n\n현재 이 회사의 패널은 칠레, 페루, 아르헨티나에서 판매되고 있다. 늘어난 생산량을 바탕으로 안데스 솔라웍스는 그다음 해에 브라질 수출을 시작할 계획이다.\n\n채용 정보는 www.andessolar.com/careers에 게시될 예정이다.","part":7},{"id":"p7-051","level":3,"kind":"single","passages":[{"doc_type":"설문 결과","title":"To: All Staff, Kestrel Engineering / From: Sustainability Committee / Subject: Commuting survey results","text":"Thank you to the 240 employees who completed last month's commuting survey. Here is a summary of how staff usually travel to work:\n\nMethod | Share of respondents\nDrive alone | 46%\nPublic transportation | 28%\nBicycle | 12%\nCarpool | 9%\nWalk | 5%\n\nMany respondents who drive said they would consider taking the bus if the company offered discounted transit passes. Several cyclists also asked for a safer place to lock their bicycles.\n\nBased on these results, the committee will propose two changes to management: a 50 percent discount on monthly transit passes and a covered bicycle shelter in the east parking lot. We will share management's decision at the staff meeting on July 10."}],"questions":[{"q":"About how many respondents usually ride a bicycle to work?","choices":["About 67","About 12","About 22","About 29"],"answer":3,"type":"세부 사항","explanation":"응답자는 240명이고 표에서 자전거 비율은 12퍼센트이므로 240×0.12=28.8, 약 29명이다. 약 67명은 대중교통(28퍼센트)에 해당하는 수이다."},{"q":"What did some cyclists request?","choices":["Free bicycle repairs","Showers at the office","Secure bicycle parking","A new bicycle lane"],"answer":2,"type":"세부 사항","explanation":"'Several cyclists also asked for a safer place to lock their bicycles.'에서 자전거를 더 안전하게 묶어 둘 곳을 요청했다고 했다. 샤워 시설, 수리, 자전거 도로는 언급되지 않았다."},{"q":"What is true about the committee's proposals?","choices":["They have not yet been approved.","They were suggested by management.","They include a new carpool program.","They will be paid for by employees."],"answer":0,"type":"사실 확인(NOT/TRUE)","explanation":"마지막 단락에서 위원회가 경영진에 두 가지 변화를 '제안할 것'이며 경영진의 결정은 7월 10일에 알리겠다고 했으므로 아직 승인되지 않았다. 제안은 경영진이 아니라 위원회가 하며, 카풀 프로그램은 포함되지 않는다."},{"q":"What will most likely happen on July 10?","choices":["Employees will learn whether the changes will be made.","A new commuting survey will be conducted.","A bicycle shelter will open.","Discounted transit passes will go on sale."],"answer":0,"type":"추론","explanation":"'We will share management's decision at the staff meeting on July 10.'에서 7월 10일 직원 회의에서 경영진의 결정을 공유한다고 했으므로, 직원들은 변화가 시행될지 알게 된다. 보관소 개장이나 할인 판매는 아직 결정되지 않았다."}],"translation":"수신: 케스트럴 엔지니어링 전 직원 / 발신: 지속 가능성 위원회 / 제목: 출퇴근 설문 결과\n\n지난달 출퇴근 설문에 응해 주신 직원 240명께 감사드립니다. 직원들이 평소 출근하는 방법을 요약하면 다음과 같습니다.\n\n방법 | 응답자 비율\n혼자 운전 | 46%\n대중교통 | 28%\n자전거 | 12%\n카풀 | 9%\n도보 | 5%\n\n운전하는 응답자 중 다수가 회사에서 할인된 교통 정기권을 제공하면 버스를 타는 것을 고려하겠다고 답했습니다. 자전거 이용자 몇 명은 자전거를 더 안전하게 묶어 둘 곳을 요청했습니다.\n\n이 결과를 바탕으로 위원회는 경영진에 두 가지 변화를 제안할 예정입니다. 월간 교통 정기권 50퍼센트 할인과 동쪽 주차장의 지붕 있는 자전거 보관소입니다. 경영진의 결정은 7월 10일 직원 회의에서 알려 드리겠습니다.","part":7},{"id":"p7-052","level":3,"kind":"double","passages":[{"doc_type":"회람","title":"To: All Sales Staff / From: Accounting Department, Brightwater Pharmaceuticals / Date: February 3 / Subject: Updated travel expense policy","text":"Starting February 15, the following rules apply to all business trips:\n\n- Hotel costs will be reimbursed up to $180 per night. Any amount above this limit must be approved by your department head before the trip.\n- Meals will be reimbursed up to $60 per day. Alcoholic drinks are not covered.\n- Employees should take a taxi only when public transportation is not available. Economy-class train tickets are preferred for trips under 400 kilometers.\n- Expense forms must be submitted within 14 days after returning, with original receipts attached.\n\nForms submitted late will be processed with the following month's payroll."},{"doc_type":"양식","title":"Brightwater Pharmaceuticals — Travel Expense Form","text":"Employee: Lucas Moreau, Sales (Eastern Region)\nTrip: Client visits in Lyon, February 18–20 (2 nights)\nDate submitted: March 12\n\nExpense | Amount\nHotel (2 nights @ $210) | $420\nMeals (3 days) | $165\nTrain tickets (economy, round trip) | $96\nTaxi (station to hotel) | $28\nTotal | $709\n\nNote: Department head Sofia Russo approved the hotel rate on February 10 because a trade fair was being held in Lyon that week and few rooms were available.\nOriginal receipts: attached (6 items)"}],"questions":[{"q":"What is the purpose of the memo?","choices":["To request receipts for a past trip","To announce a sales trip to Lyon","To introduce a new department head","To explain new rules for travel costs"],"answer":3,"type":"주제·목적","explanation":"회람 제목이 'Updated travel expense policy'이고 2월 15일부터 적용되는 숙박·식비·교통비·제출 규정을 나열했으므로 새 출장비 규정을 설명하는 글이다."},{"q":"What does the memo say about meals?","choices":["Meals must be approved by a department head.","Receipts are not needed for meals.","Alcoholic beverages will not be paid for.","Meals are limited to $180 per day."],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"회람 둘째 항목에서 식비는 하루 60달러까지이며 'Alcoholic drinks are not covered.'라고 했다. 180달러는 호텔 1박 한도이고, 모든 경비 양식에는 영수증 원본을 첨부해야 한다."},{"q":"Why was Mr. Moreau's hotel rate higher than usual?","choices":["A large event was being held in the city.","He stayed in a suite by mistake.","He traveled with a client.","His train arrived late at night."],"answer":0,"type":"세부 사항","explanation":"양식의 Note에서 그 주에 리옹에서 무역 박람회가 열려 빈방이 적었기 때문에 요금이 승인되었다고 했다. 스위트룸, 고객 동행, 열차 지연은 언급되지 않았다."},{"q":"What is suggested about Mr. Moreau's hotel expense?","choices":["It includes his meals.","It follows the policy because it was approved before the trip.","It will not be reimbursed because it is over the limit.","It was approved after he returned."],"answer":1,"type":"연계 문제","explanation":"회람은 1박 180달러를 넘는 금액은 출장 전에 부서장의 승인을 받아야 한다고 했다. 양식에서 1박 210달러는 한도를 넘지만, 출장(2월 18일) 전인 2월 10일에 부서장이 승인했으므로 규정에 맞다. 식비는 별도 항목이다."},{"q":"What will most likely happen to Mr. Moreau's reimbursement?","choices":["It will be rejected completely.","It will be reduced by the taxi fare.","It will be paid in February.","It will be paid later than usual."],"answer":3,"type":"연계 문제","explanation":"회람에 따르면 경비 양식은 돌아온 뒤 14일 이내에 내야 하고 늦으면 다음 달 급여 때 처리된다. 모로 씨는 2월 20일에 돌아와 3월 6일까지 내야 했지만 3월 12일에 제출했으므로 평소보다 늦게 지급될 것이다. 전액 거절한다는 규정은 없다."}],"translation":"[회람]\n수신: 영업부 전 직원 / 발신: 브라이트워터 제약 회계부 / 날짜: 2월 3일 / 제목: 출장비 규정 개정\n\n2월 15일부터 모든 출장에 다음 규정이 적용됩니다.\n\n- 호텔 비용은 1박에 180달러까지 환급됩니다. 이 한도를 넘는 금액은 출장 전에 부서장의 승인을 받아야 합니다.\n- 식비는 하루 60달러까지 환급됩니다. 주류는 포함되지 않습니다.\n- 택시는 대중교통을 이용할 수 없을 때만 타야 합니다. 400킬로미터 미만의 출장에는 일반석 기차표를 권장합니다.\n- 경비 양식은 돌아온 뒤 14일 이내에 영수증 원본을 첨부하여 제출해야 합니다.\n\n늦게 제출된 양식은 다음 달 급여와 함께 처리됩니다.\n\n[양식]\n브라이트워터 제약 — 출장 경비 양식\n\n직원: 뤼카 모로, 영업부 (동부 지역)\n출장: 리옹 고객 방문, 2월 18~20일 (2박)\n제출일: 3월 12일\n\n경비 | 금액\n호텔 (2박, 1박 210달러) | 420달러\n식비 (3일) | 165달러\n기차표 (일반석, 왕복) | 96달러\n택시 (역에서 호텔까지) | 28달러\n합계 | 709달러\n\n참고: 그 주에 리옹에서 무역 박람회가 열려 빈방이 적었기 때문에 소피아 루소 부서장이 2월 10일에 호텔 요금을 승인했음.\n영수증 원본: 첨부 (6건)","part":7},{"id":"p7-053","level":3,"kind":"double","passages":[{"doc_type":"달력","title":"Ashford Museum of Science — Group Tour Calendar, April 7–11","text":"ASHFORD MUSEUM OF SCIENCE\nGroup Tour Calendar — April 7–11\n\nMon, April 7 | 10:00 A.M. Space Gallery tour (booked: Linwood Elementary) | 2:00 P.M. OPEN\nTue, April 8 | 10:00 A.M. OPEN | 2:00 P.M. Robotics Lab tour (booked: Carver Tech Club)\nWed, April 9 | Museum closed for staff training\nThu, April 10 | 10:00 A.M. Ocean Life tour (booked: Pine Hill Seniors Center) | 2:00 P.M. OPEN\nFri, April 11 | 10:00 A.M. OPEN | 2:00 P.M. OPEN\n\nGroups of 10–30 people. Tours last 90 minutes. Groups of 20 or more receive a free planetarium show."},{"doc_type":"이메일","title":"From: Mariana Costa, Hillcrest Middle School / To: tours@ashfordscience.org / Date: March 20 / Subject: Tour request","text":"Hello,\n\nI teach eighth-grade science at Hillcrest Middle School, and I would like to bring 24 students on a tour during the week of April 7. Our students are studying robots this term, so the Robotics Lab would be ideal. We can only visit in the morning because our bus must return to school by 1:00 P.M. Also, Wednesday is not possible for us because of school exams.\n\nPlease let me know which dates are available.\n\nBest regards,\nMariana Costa"}],"questions":[{"q":"What is indicated about the museum?","choices":["It accepts groups of up to 50 people.","It offers tours only in the morning.","It will be closed on one weekday.","Its tours last two hours."],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"달력에서 4월 9일 수요일은 'Museum closed for staff training'으로 직원 교육 때문에 휴관한다. 투어는 90분이고, 단체는 10~30명이며, 오후 2시 투어도 있다."},{"q":"Why does Ms. Costa want to visit the Robotics Lab?","choices":["It offers a free planetarium show.","It is the only lab open in the morning.","It is related to what her students are studying.","Her students have visited it before."],"answer":2,"type":"세부 사항","explanation":"이메일에서 'Our students are studying robots this term, so the Robotics Lab would be ideal.'이라고 했으므로 학생들이 배우는 내용과 관련이 있기 때문이다."},{"q":"Which time slot could Ms. Costa's group most likely book?","choices":["Tuesday at 2:00 P.M.","Thursday at 10:00 A.M.","Monday at 2:00 P.M.","Friday at 10:00 A.M."],"answer":3,"type":"연계 문제","explanation":"코스타 씨는 오전에만, 수요일이 아닌 날에 방문할 수 있다. 달력에서 비어 있는 오전 시간은 화요일 10시와 금요일 10시뿐이므로 선택지 중에서는 금요일 오전 10시이다. 목요일 10시는 이미 예약되어 있고, 오후 2시 시간대는 오전이 아니다."},{"q":"What will Ms. Costa's group most likely receive?","choices":["A free planetarium show","Robot-building kits","A guided tour lasting two hours","A discount on admission"],"answer":0,"type":"연계 문제","explanation":"달력 아래에 20명 이상 단체는 무료 천체 투영관 관람을 제공한다고 했고, 이메일에서 학생 24명을 데려온다고 했으므로 무료 관람을 받게 된다. 투어는 90분이다."},{"q":"What is mentioned about Hillcrest Middle School?","choices":["Its bus is available only in the afternoon.","Its students will be taking exams on Wednesday.","It has booked a tour for April 8.","It has a robotics club."],"answer":1,"type":"세부 사항","explanation":"이메일 'Wednesday is not possible for us because of school exams'에서 수요일에 시험이 있음을 알 수 있다. 버스는 오후 1시까지 학교로 돌아가야 하므로 오전에만 가능하며, 아직 예약하지 않았다."}],"translation":"[달력]\n애시퍼드 과학관\n단체 관람 일정 — 4월 7일~11일\n\n4월 7일 월 | 오전 10:00 우주관 관람 (예약: 린우드 초등학교) | 오후 2:00 예약 가능\n4월 8일 화 | 오전 10:00 예약 가능 | 오후 2:00 로봇 연구실 관람 (예약: 카버 테크 클럽)\n4월 9일 수 | 직원 교육으로 휴관\n4월 10일 목 | 오전 10:00 해양 생물 관람 (예약: 파인힐 노인 복지관) | 오후 2:00 예약 가능\n4월 11일 금 | 오전 10:00 예약 가능 | 오후 2:00 예약 가능\n\n단체 인원 10~30명. 관람 시간 90분. 20명 이상 단체에는 천체 투영관 관람을 무료로 제공합니다.\n\n[이메일]\n발신: 마리아나 코스타, 힐크레스트 중학교 / 수신: tours@ashfordscience.org / 날짜: 3월 20일 / 제목: 관람 요청\n\n안녕하세요.\n\n저는 힐크레스트 중학교에서 8학년 과학을 가르치고 있으며, 4월 7일이 있는 주에 학생 24명을 데리고 관람하고 싶습니다. 학생들이 이번 학기에 로봇을 배우고 있어서 로봇 연구실이면 가장 좋겠습니다. 버스가 오후 1시까지 학교로 돌아가야 해서 오전에만 방문할 수 있습니다. 또한 수요일은 학교 시험 때문에 불가능합니다.\n\n가능한 날짜를 알려 주세요.\n\n마리아나 코스타 드림","part":7},{"id":"p7-054","level":3,"kind":"triple","passages":[{"doc_type":"웹페이지","title":"www.lingualinktranslations.com/rates","text":"LinguaLink Translations — Rates\n\nStandard service (delivered in 5 business days): $0.12 per word\nExpress service (delivered in 2 business days): $0.18 per word\nCertified translation of legal documents: add $25 per document\n\nLanguages: English, Spanish, French, German, Japanese, Korean, and Arabic.\nNew clients receive 10 percent off their first order. Minimum charge: $40.\n\nAll translations are checked by a second professional translator before delivery. Volume discounts are available for documents over 20,000 words. Payment can be made by bank transfer or credit card."},{"doc_type":"이메일","title":"From: Henrik Lund, Nordvik Furniture / To: orders@lingualinktranslations.com / Date: June 2 / Subject: Translation request","text":"Hello,\n\nWe are launching our furniture line in Japan next month and need our 3,000-word product catalog translated from English into Japanese. We will need the translation by June 5, as the catalog goes to print on June 6. This is the first time we have used your company, so please confirm that the discount will apply. Please also let me know the final cost before you begin.\n\nWe may also need a German translation of our assembly instructions later this summer.\n\nRegards,\nHenrik Lund\nMarketing Manager"},{"doc_type":"청구서","title":"Invoice #LL-2291 — LinguaLink Translations","text":"INVOICE #LL-2291\nBill to: Nordvik Furniture, Attn: Henrik Lund\nDate: June 4\n\nDescription | Amount\nJapanese translation — product catalog, 3,000 words | $540.00\nNew client discount (10%) | -$54.00\nTotal due | $486.00\n\nLanguage pair: English to Japanese\n\nPayment is due within 30 days by bank transfer or by credit card at www.lingualinktranslations.com/pay. Please include the invoice number with your payment. For questions about this invoice, contact billing@lingualinktranslations.com. Thank you for choosing LinguaLink!"}],"questions":[{"q":"Why did Mr. Lund write the e-mail?","choices":["To request a service","To complain about a translation","To confirm a payment","To apply for a job"],"answer":0,"type":"주제·목적","explanation":"이메일에서 3,000단어 제품 카탈로그를 일본어로 번역해 달라고 요청했으므로 서비스를 의뢰하려는 목적이다. 불만이나 결제 확인은 없다."},{"q":"What is suggested about Nordvik Furniture?","choices":["It has an office in Germany.","It prints its own catalogs.","It has used LinguaLink many times.","It is entering a new market."],"answer":3,"type":"추론","explanation":"이메일 첫 문장 'We are launching our furniture line in Japan next month'에서 일본 시장에 새로 진출함을 알 수 있다. 링구아링크 이용은 처음이라고 했고, 독일 사무소는 언급되지 않았다."},{"q":"Which service did Nordvik Furniture most likely receive?","choices":["German translation","Certified legal translation","Express service","Standard service"],"answer":2,"type":"연계 문제","explanation":"청구서의 번역비는 3,000단어에 540달러, 즉 단어당 0.18달러로 웹페이지의 급행 서비스 요금과 같다. 6월 2일 요청해 6월 5일까지 받아야 했으므로 5영업일이 걸리는 일반 서비스로는 기한을 맞출 수 없다는 점도 일치한다."},{"q":"What is true about the invoice?","choices":["It was sent before the request was made.","It includes the discount Mr. Lund asked about.","It charges a fee for a legal document.","It must be paid by June 6."],"answer":1,"type":"연계 문제","explanation":"런드 씨는 이메일에서 첫 거래 할인이 적용되는지 확인해 달라고 했고, 청구서에 'New client discount (10%) -$54.00'이 반영되어 있다. 법률 문서 수수료는 없고, 결제 기한은 30일 이내이다."},{"q":"What might Nordvik Furniture request later?","choices":["A certified legal translation","A Korean version of its catalog","A translation of assembly instructions","A refund of its first payment"],"answer":2,"type":"세부 사항","explanation":"이메일 마지막 단락에서 올여름 후반에 조립 설명서의 독일어 번역이 필요할 수 있다고 했다. 한국어 카탈로그나 법률 번역은 언급되지 않았다."}],"translation":"[웹페이지]\n링구아링크 번역 — 요금\n\n일반 서비스 (5영업일 내 납품): 단어당 0.12달러\n급행 서비스 (2영업일 내 납품): 단어당 0.18달러\n법률 문서 공증 번역: 문서당 25달러 추가\n\n언어: 영어, 스페인어, 프랑스어, 독일어, 일본어, 한국어, 아랍어.\n신규 고객은 첫 주문 시 10퍼센트 할인. 최소 요금: 40달러.\n\n모든 번역은 납품 전에 다른 전문 번역가가 한 번 더 검토합니다. 2만 단어가 넘는 문서는 분량 할인을 받을 수 있습니다. 결제는 계좌 이체나 신용카드로 할 수 있습니다.\n\n[이메일]\n발신: 헨리크 룬드, 노르드비크 가구 / 수신: orders@lingualinktranslations.com / 날짜: 6월 2일 / 제목: 번역 요청\n\n안녕하세요.\n\n저희는 다음 달 일본에서 가구 제품군을 출시하며, 3,000단어 분량의 제품 카탈로그를 영어에서 일본어로 번역해야 합니다. 카탈로그가 6월 6일에 인쇄에 들어가므로 6월 5일까지 번역이 필요합니다. 귀사를 처음 이용하는 것이니 할인이 적용되는지 확인해 주세요. 작업을 시작하기 전에 최종 비용도 알려 주세요.\n\n올여름 후반에 조립 설명서의 독일어 번역도 필요할 수 있습니다.\n\n헨리크 룬드\n마케팅 매니저\n\n[청구서]\n청구서 #LL-2291\n청구 대상: 노르드비크 가구, 헨리크 룬드 앞\n날짜: 6월 4일\n\n내역 | 금액\n일본어 번역 — 제품 카탈로그, 3,000단어 | 540.00달러\n신규 고객 할인 (10%) | -54.00달러\n청구 합계 | 486.00달러\n\n언어: 영어 → 일본어\n\n30일 이내에 계좌 이체나 www.lingualinktranslations.com/pay에서 신용카드로 결제해 주십시오. 결제 시 청구서 번호를 함께 기재해 주십시오. 이 청구서에 관한 문의는 billing@lingualinktranslations.com으로 해 주십시오. 링구아링크를 선택해 주셔서 감사합니다!","part":7},{"id":"p7-055","level":4,"kind":"single","passages":[{"doc_type":"잡지 기사","title":"Buzz on the Rooftop: Hotels Turn to Beekeeping / By Ingrid Havel","text":"When guests at the Stellan Grand Hotel in Copenhagen order breakfast, the honey on their table comes from just a few floors above them. Since 2022, the hotel has kept six beehives on its roof, producing roughly 150 kilograms of honey each year. [1]\n\nThe Stellan Grand is part of a growing trend. According to the Urban Hospitality Council, more than 80 hotels across Europe now keep bees, up from fewer than 20 a decade ago. [2] Managers say the hives are inexpensive to maintain and give guests a story they remember. Several hotels have even begun offering rooftop tours led by professional beekeepers.\n\nThe practice is not without challenges, however. Hives must be inspected regularly, and staff need training to handle them safely. [3] In cities with few parks or gardens, bees may struggle to find enough flowers, which is why some hotels now plant herbs and wildflowers on nearby balconies.\n\nFor Mikkel Dahl, the Stellan Grand's head chef, the benefits extend beyond the breakfast table. \"Our pastry team uses the honey in desserts, and the flavor changes with the seasons,\" he said. \"Guests often ask to take a jar home.\" [4] The hotel now sells its honey in the lobby gift shop, with proceeds supporting a local environmental charity."}],"questions":[{"q":"What is the article mainly about?","choices":["Hotels that keep bees on their property","A charity that protects city parks","A new breakfast menu at a Copenhagen hotel","Training programs for professional beekeepers"],"answer":0,"type":"주제·목적","explanation":"기사는 스텔란 그랜드 호텔을 예로 들어 유럽 호텔들이 옥상에서 벌을 키우는 추세와 그 장단점을 다룬다. 아침 식사, 양봉가 교육, 자선 단체는 이 주제를 설명하는 세부 요소일 뿐이다."},{"q":"What is NOT mentioned as a challenge of keeping bees?","choices":["The need for regular inspections","Complaints from hotel guests","A shortage of flowers in cities","Training staff to handle the hives"],"answer":1,"type":"사실 확인(NOT/TRUE)","explanation":"셋째 단락에서 정기 점검, 직원 교육, 공원·정원이 적은 도시의 꽃 부족을 어려움으로 들었다. 투숙객의 불만은 언급되지 않았고, 오히려 투숙객이 꿀을 사 가고 싶어 한다고 했다."},{"q":"The word “extend” in paragraph 4 is closest in meaning to","choices":["delay","offer","lengthen","reach"],"answer":3,"type":"동의어","explanation":"'the benefits extend beyond the breakfast table'은 이점이 아침 식탁을 넘어서까지 '미친다'는 뜻이므로 'reach(이르다, 미치다)'가 가장 가깝다. lengthen은 길이·기간을 늘린다는 뜻이라 이 문맥에 맞지 않는다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? “The council expects that number to keep rising.”","choices":["[1]","[2]","[3]","[4]"],"answer":1,"type":"문장 삽입","explanation":"'The council'과 'that number'는 도시 숙박업 협의회와 벌을 키우는 호텔 수(80곳 이상)를 가리키므로 그 통계 바로 뒤인 [2]가 알맞다. [1] 앞의 숫자 150킬로그램은 협의회와 관계가 없다."}],"translation":"옥상 위의 윙윙 소리: 양봉에 나선 호텔들 / 잉그리드 하벨 기자\n\n코펜하겐의 스텔란 그랜드 호텔 투숙객이 아침 식사를 주문하면, 식탁 위의 꿀은 겨우 몇 층 위에서 온 것이다. 2022년부터 이 호텔은 옥상에서 벌통 여섯 개를 관리하며 매년 약 150킬로그램의 꿀을 생산하고 있다.\n\n스텔란 그랜드는 커지고 있는 추세의 일부이다. 도시 숙박업 협의회에 따르면 현재 유럽 전역에서 80곳이 넘는 호텔이 벌을 키우고 있으며, 이는 10년 전 20곳 미만에서 늘어난 것이다. (협의회는 그 수가 계속 늘어날 것으로 예상한다.) 관리자들은 벌통이 유지비가 적게 들고 투숙객에게 기억에 남는 이야깃거리를 준다고 말한다. 몇몇 호텔은 전문 양봉가가 안내하는 옥상 투어까지 시작했다.\n\n하지만 어려움이 없는 것은 아니다. 벌통은 정기적으로 점검해야 하고, 직원은 안전하게 다루는 법을 교육받아야 한다. 공원이나 정원이 적은 도시에서는 벌이 충분한 꽃을 찾기 어려울 수 있어서, 일부 호텔은 이제 근처 발코니에 허브와 야생화를 심는다.\n\n스텔란 그랜드의 총주방장 미켈 달에게 그 이점은 아침 식탁을 넘어선다. 그는 \"제과팀이 디저트에 이 꿀을 쓰는데, 계절에 따라 맛이 달라진다\"며 \"투숙객들이 한 병 가져가고 싶다고 자주 요청한다\"고 말했다. 호텔은 현재 로비 기념품점에서 꿀을 판매하며, 수익금은 지역 환경 자선 단체를 후원하는 데 쓰인다.","part":7},{"id":"p7-056","level":4,"kind":"single","passages":[{"doc_type":"온라인 채팅","title":"Online chat discussion","text":"Sven Larsen [3:02 P.M.]: Quick update: the app store review for our Budgetly 2.0 update is taking longer than expected. We may miss the Monday launch.\nKavya Iyer [3:03 P.M.]: How much longer?\nSven Larsen [3:04 P.M.]: They usually respond within 48 hours, but it's been four days.\nKavya Iyer [3:05 P.M.]: The press release is scheduled to go out Monday at 8 A.M. I can hold it, but the tech bloggers already have their advance copies.\nTomás Rivera [3:07 P.M.]: I've been through this before. If we submit an expedited review request and explain the launch date, they often approve it within a day.\nSven Larsen [3:08 P.M.]: Worth a try. Can you draft the request, Tomás? You know what to say.\nTomás Rivera [3:09 P.M.]: Consider it done.\nKavya Iyer [3:11 P.M.]: I'll e-mail the bloggers anyway to let them know Monday could slip by a day. Better they hear it from us.\nAnnette Brooks [3:14 P.M.]: Just catching up. Kavya, go ahead, but don't mention the review. Just say the date is being confirmed.\nKavya Iyer [3:15 P.M.]: Understood."}],"questions":[{"q":"What problem are the writers discussing?","choices":["Some bloggers published information too early.","An app has stopped working for users.","An approval process is taking too long.","A press release contains errors."],"answer":2,"type":"주제·목적","explanation":"3시 2분에 라르센 씨가 앱 스토어의 업데이트 심사가 예상보다 오래 걸려 월요일 출시를 놓칠 수 있다고 했고, 이후 대화는 이 문제의 대응에 관한 것이다. 보도 자료 오류나 블로거의 조기 공개는 언급되지 않았다."},{"q":"At 3:08 P.M., what does Mr. Larsen mean when he writes, “Worth a try”?","choices":["He agrees with Mr. Rivera's suggestion.","He thinks the press release should be rewritten.","He doubts that the bloggers will reply.","He wants to test the app again."],"answer":0,"type":"의도 파악","explanation":"리베라 씨가 긴급 심사를 요청하면 대개 하루 안에 승인된다고 제안하자 라르센 씨가 'Worth a try(해 볼 만하다)'라고 한 뒤 요청서 작성을 부탁했다. 따라서 그 제안에 동의한다는 뜻이다."},{"q":"At 3:09 P.M., what does Mr. Rivera most likely mean when he writes, “Consider it done”?","choices":["He thinks the discussion should end.","He has already completed the app update.","He is sure that the launch will go as planned.","He will take care of the request right away."],"answer":3,"type":"의도 파악","explanation":"라르센 씨가 긴급 심사 요청서를 써 달라고 하자 'Consider it done(맡겨 달라, 바로 처리하겠다)'이라고 답했으므로 요청서를 즉시 처리하겠다는 뜻이다. 앱 업데이트를 끝냈다거나 출시를 확신한다는 뜻이 아니다."},{"q":"What does Ms. Brooks instruct Ms. Iyer to do?","choices":["Postpone the press release by a week","Send the bloggers new advance copies","Contact the app store directly","Avoid giving the reason for a possible delay"],"answer":3,"type":"세부 사항","explanation":"3시 14분 브룩스 씨가 블로거에게 연락하되 'don't mention the review. Just say the date is being confirmed.'라고 했으므로 지연 가능성의 이유(심사)를 밝히지 말라는 지시이다."}],"translation":"스벤 라르센 [오후 3:02]: 간단히 알려 드려요. 버짓리 2.0 업데이트의 앱 스토어 심사가 예상보다 오래 걸리고 있어요. 월요일 출시를 놓칠 수도 있어요.\n카비야 아이어 [오후 3:03]: 얼마나 더 걸린대요?\n스벤 라르센 [오후 3:04]: 보통 48시간 안에 답을 주는데 벌써 나흘째예요.\n카비야 아이어 [오후 3:05]: 보도 자료는 월요일 오전 8시에 나갈 예정이에요. 보류할 수는 있지만, 테크 블로거들은 이미 사전 자료를 받았어요.\n토마스 리베라 [오후 3:07]: 저 이런 일 겪어 봤어요. 긴급 심사 요청을 넣고 출시일을 설명하면 대개 하루 안에 승인해 줘요.\n스벤 라르센 [오후 3:08]: 해 볼 만하네요. 토마스, 요청서 초안 좀 써 줄래요? 뭐라고 쓸지 잘 아시잖아요.\n토마스 리베라 [오후 3:09]: 맡겨 주세요.\n카비야 아이어 [오후 3:11]: 어쨌든 블로거들에게는 월요일이 하루 밀릴 수 있다고 이메일을 보낼게요. 우리한테서 듣는 게 나으니까요.\n아네트 브룩스 [오후 3:14]: 이제야 읽었어요. 카비야, 그렇게 하되 심사 얘기는 하지 마세요. 날짜를 확정하는 중이라고만 하세요.\n카비야 아이어 [오후 3:15]: 알겠습니다.","part":7},{"id":"p7-057","level":4,"kind":"single","passages":[{"doc_type":"신청서","title":"Oakridge Farmers' Market — 2027 Vendor Application","text":"OAKRIDGE FARMERS' MARKET — 2027 VENDOR APPLICATION\n\nBusiness name: Two Rivers Creamery\nContact person: Chiara Bellini\nPhone: 555-0119   E-mail: chiara@tworiverscreamery.com\n\nProducts to be sold (check all that apply):\n[ ] Fresh fruit and vegetables  [x] Dairy products  [ ] Baked goods  [x] Prepared foods  [ ] Crafts\n\nStall size requested: [ ] Small (3m x 3m, $35/week)  [x] Large (3m x 6m, $55/week)\nMarket days: [x] Saturday  [ ] Sunday\nElectricity needed? [x] Yes (additional $10/week)  [ ] No\n\nDo you produce all items yourself? Yes. We make cheese and yogurt from the milk of cows raised on our own farm in Harlow Valley. Our prepared foods include cheese sandwiches and salads.\n\nFor office use only — Health permit received: [x]  Insurance certificate received: [ ]\n\nNote to applicants: Vendors selling prepared foods must attend a food handling session on April 5. Applications are incomplete until all required documents are received."}],"questions":[{"q":"What kind of business most likely is Two Rivers Creamery?","choices":["A dairy farm","A bakery","A restaurant chain","A craft studio"],"answer":0,"type":"추론","explanation":"자기 농장에서 키운 소의 우유로 치즈와 요구르트를 만든다고 했고 판매 품목에 유제품이 표시되어 있으므로 낙농장으로 볼 수 있다. 제과(Baked goods)와 공예품(Crafts)은 표시되지 않았다."},{"q":"How much will Ms. Bellini most likely pay each week?","choices":["$35","$45","$65","$55"],"answer":2,"type":"세부 사항","explanation":"큰 매대(Large, 주당 55달러)를 신청했고 전기 사용(주당 10달러 추가)에 표시했으므로 55+10=65달러이다. 55달러는 전기 요금을 뺀 금액이고, 45달러는 작은 매대에 전기를 더한 금액이다."},{"q":"What is suggested about the application?","choices":["It does not need a health permit.","It is missing a required document.","It is for a Sunday stall.","It has already been approved."],"answer":1,"type":"추론","explanation":"사무실 기재란에 보건 허가증은 접수 표시가 있지만 보험 증명서(Insurance certificate)는 비어 있고, 필요한 서류가 모두 접수되어야 신청이 완료된다고 했으므로 서류가 하나 빠져 있다. 시장 요일은 토요일에만 표시되어 있다."},{"q":"What will Ms. Bellini have to do on April 5?","choices":["Attend a food handling session","Set up her stall","Pay her first week's fee","Submit her insurance certificate"],"answer":0,"type":"세부 사항","explanation":"신청서에서 즉석 식품(Prepared foods)에 표시했고, 안내문에 즉석 식품 판매자는 4월 5일 식품 취급 교육에 참석해야 한다고 했다. 보험 증명서 제출일이나 매대 설치일은 나와 있지 않다."}],"translation":"오크리지 농산물 시장 — 2027년 판매자 신청서\n\n업체명: 투 리버스 크리머리\n담당자: 키아라 벨리니\n전화: 555-0119   이메일: chiara@tworiverscreamery.com\n\n판매 품목 (해당 항목 모두 표시):\n[ ] 신선 과일·채소  [x] 유제품  [ ] 제과  [x] 즉석 식품  [ ] 공예품\n\n신청 매대 크기: [ ] 소형 (3m x 3m, 주당 35달러)  [x] 대형 (3m x 6m, 주당 55달러)\n시장 요일: [x] 토요일  [ ] 일요일\n전기 필요 여부: [x] 예 (주당 10달러 추가)  [ ] 아니요\n\n모든 품목을 직접 생산하십니까? 예. 할로 밸리에 있는 저희 농장에서 키운 소의 우유로 치즈와 요구르트를 만듭니다. 즉석 식품으로는 치즈 샌드위치와 샐러드가 있습니다.\n\n사무실 기재란 — 보건 허가증 접수: [x]  보험 증명서 접수: [ ]\n\n신청자 참고 사항: 즉석 식품 판매자는 4월 5일 식품 취급 교육에 참석해야 합니다. 필요한 서류가 모두 접수되기 전까지 신청은 완료되지 않은 것으로 봅니다.","part":7},{"id":"p7-058","level":4,"kind":"single","passages":[{"doc_type":"이메일","title":"From: Ruth Adeyemi, Kalahari Leather Goods / To: Wholesale Customers / Date: August 18 / Subject: 2027 price adjustments","text":"Dear Valued Partner,\n\nThank you for your continued business with Kalahari Leather Goods. I am writing to inform you of changes to our wholesale prices that will take effect on January 1.\n\nOver the past year, the cost of high-quality leather has risen by nearly 18 percent, largely because of reduced supply from our tanneries in Botswana and Namibia. [1] Shipping costs have also increased. As a result, prices for our handbags and wallets will rise by 6 percent. [2] Prices for belts and small accessories will remain unchanged.\n\nWe understand that this news may be difficult. [3] To ease the transition, orders placed before December 15 will be invoiced at current prices, even if they are delivered in January. In addition, partners who commit to a minimum annual order of $20,000 will receive a fixed rate for all of 2027.\n\nIf you would like to discuss your account, please contact your regional representative directly. [4] We appreciate your understanding and look forward to another successful year together.\n\nSincerely,\nRuth Adeyemi\nDirector of Sales"}],"questions":[{"q":"Why was the e-mail sent?","choices":["To introduce a new regional representative","To announce a new line of belts","To notify customers of a price change","To apologize for a shipping delay"],"answer":2,"type":"주제·목적","explanation":"첫 단락 'I am writing to inform you of changes to our wholesale prices that will take effect on January 1.'에서 도매가 변경을 알리려는 목적임을 알 수 있다. 벨트 가격은 그대로라고 했을 뿐 신제품 발표는 없다."},{"q":"What is mentioned as a reason for the change?","choices":["A drop in customer demand","The opening of a new factory","A rise in local taxes","A decrease in the supply of materials"],"answer":3,"type":"세부 사항","explanation":"둘째 단락에서 보츠와나와 나미비아 가죽 공장의 공급 감소(reduced supply)로 가죽 가격이 약 18퍼센트 올랐고 운송비도 올랐다고 했다. 세금, 새 공장, 수요 감소는 언급되지 않았다."},{"q":"The word “ease” in paragraph 3 is closest in meaning to","choices":["comfort","smooth","relax","lower"],"answer":1,"type":"동의어","explanation":"'To ease the transition'은 가격이 바뀌는 과정을 수월하게 한다는 뜻이므로 'smooth(순조롭게 하다)'가 가장 가깝다. relax와 comfort는 사람의 긴장·마음을 풀어 준다는 뜻이고, lower는 양을 줄인다는 뜻이라 'transition'과 어울리지 않는다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? “This is the first increase we have made in four years.”","choices":["[1]","[2]","[3]","[4]"],"answer":1,"type":"문장 삽입","explanation":"'This is the first increase we have made'는 회사가 가격을 올리는 것을 가리키므로 핸드백과 지갑 가격을 6퍼센트 올린다는 문장 바로 뒤인 [2]가 알맞다. [1]은 아직 회사의 가격 인상이 언급되기 전이다."}],"translation":"발신: 루스 아데예미, 칼라하리 가죽 제품 / 수신: 도매 고객 / 날짜: 8월 18일 / 제목: 2027년 가격 조정\n\n소중한 협력사께,\n\n칼라하리 가죽 제품과 계속 거래해 주셔서 감사합니다. 1월 1일부터 적용되는 도매가 변경 사항을 알려 드리고자 합니다.\n\n지난 1년간 고급 가죽 가격이 18퍼센트 가까이 올랐는데, 이는 주로 보츠와나와 나미비아의 거래 무두질 공장에서 공급이 줄었기 때문입니다. 운송비도 올랐습니다. 이에 따라 핸드백과 지갑 가격을 6퍼센트 인상합니다. (이는 4년 만의 첫 인상입니다.) 벨트와 소형 액세서리 가격은 변동이 없습니다.\n\n이 소식이 부담스러우실 수 있다는 것을 알고 있습니다. 전환을 순조롭게 하기 위해 12월 15일 이전에 들어온 주문은 1월에 배송되더라도 현재 가격으로 청구합니다. 또한 연간 최소 2만 달러 주문을 약정하시는 협력사에는 2027년 한 해 동안 고정 가격을 적용해 드립니다.\n\n거래 계정에 대해 상의하고 싶으시면 담당 지역 영업 담당자에게 직접 연락해 주십시오. 양해해 주셔서 감사드리며, 함께 또 한 번 성공적인 한 해를 보내기를 기대합니다.\n\n루스 아데예미\n영업 이사","part":7},{"id":"p7-059","level":4,"kind":"single","passages":[{"doc_type":"사내 소식지","title":"Veridian Health Systems — Staff Newsletter, Spring Issue","text":"MENTORING PROGRAM ENTERS ITS SECOND YEAR\n\nWhen Veridian Health Systems launched its mentoring program last April, organizers hoped to attract 40 pairs of participants. By the end of the year, 112 employees had signed up, forming 56 mentor-mentee pairs across our hospitals in Leeds, Manchester, and York. [1]\n\nThe program matches newer staff with experienced colleagues from a different department. \"Being paired with someone outside nursing gave me a much broader view of how the hospital operates,\" said Aaliyah Brown, a nurse who joined Veridian in 2025. Her mentor, finance manager Daniel Keane, added that the experience had been equally valuable for him. [2]\n\nThis year, the program will introduce two changes. First, pairs will meet at least twice a month instead of once, following feedback that monthly meetings were too infrequent to build momentum. [3] Second, mentors will attend a half-day workshop on coaching skills before being matched. [4]\n\nApplications for this year's program close on March 31. Because the number of mentors is limited, the committee will give preference to mentee applicants who have been with Veridian for less than two years."}],"questions":[{"q":"What is true about the program's first year?","choices":["More people took part than organizers had expected.","It paired employees from the same department.","It had a total of 40 participants.","It was offered only at the hospital in Leeds."],"answer":0,"type":"사실 확인(NOT/TRUE)","explanation":"첫 단락에서 목표는 40쌍이었는데 실제로는 56쌍(112명)이 참여했다고 했으므로 예상보다 많았다. 리즈, 맨체스터, 요크 세 병원에서 운영했고, 다른 부서 직원끼리 짝을 지었다."},{"q":"What is suggested about Mr. Keane?","choices":["He joined Veridian in 2025.","He organized the mentoring program.","He does not work in nursing.","He will lead a coaching workshop."],"answer":2,"type":"추론","explanation":"브라운 씨는 간호 부서 밖의 사람과 짝이 되었다고 했고, 그 멘토인 킨 씨는 재무 관리자(finance manager)이므로 간호 분야에서 일하지 않는다. 2025년에 입사한 사람은 브라운 씨이다."},{"q":"The word “momentum” in paragraph 3 is closest in meaning to","choices":["importance","weight","speed","progress"],"answer":3,"type":"동의어","explanation":"'too infrequent to build momentum'은 만남이 너무 드물어 관계나 성과가 앞으로 나아가는 '추진력'을 쌓기 어렵다는 뜻이므로 'progress(진전)'가 가장 가깝다. speed는 물리적 속도를 뜻해 문맥에 맞지 않는다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? “The session will be led by an outside consultant who specializes in workplace coaching.”","choices":["[1]","[2]","[3]","[4]"],"answer":3,"type":"문장 삽입","explanation":"'The session'은 멘토들이 매칭 전에 듣는 코칭 기술 반일 워크숍을 가리키므로 그 문장 바로 뒤인 [4]가 알맞다. 다른 위치 앞에는 세션이나 교육이 언급되지 않았다."}],"translation":"멘토링 프로그램, 2년 차에 들어서다\n\n베리디언 헬스 시스템즈가 지난 4월 멘토링 프로그램을 시작했을 때, 기획자들은 40쌍의 참가자를 모으기를 바랐습니다. 연말까지 112명의 직원이 신청해 리즈, 맨체스터, 요크의 병원에서 멘토-멘티 56쌍이 만들어졌습니다.\n\n이 프로그램은 비교적 새로 들어온 직원을 다른 부서의 경험 많은 동료와 연결합니다. 2025년에 베리디언에 입사한 간호사 알리야 브라운 씨는 \"간호 부서 밖의 사람과 짝이 되면서 병원이 어떻게 운영되는지 훨씬 넓게 볼 수 있었다\"고 말했습니다. 그녀의 멘토인 재무 관리자 대니얼 킨 씨는 이 경험이 자신에게도 똑같이 값졌다고 덧붙였습니다.\n\n올해 프로그램에는 두 가지 변화가 있습니다. 첫째, 한 달에 한 번이던 만남을 최소 두 번으로 늘립니다. 한 달에 한 번은 너무 드물어 진전을 이루기 어렵다는 의견을 반영한 것입니다. 둘째, 멘토는 매칭 전에 코칭 기술에 관한 반일 워크숍에 참석합니다. (이 세션은 직장 코칭을 전문으로 하는 외부 컨설턴트가 진행합니다.)\n\n올해 프로그램 신청은 3월 31일에 마감됩니다. 멘토 수가 한정되어 있어, 위원회는 베리디언 근무 기간이 2년 미만인 멘티 신청자를 우선 선발할 예정입니다.","part":7},{"id":"p7-060","level":4,"kind":"double","passages":[{"doc_type":"설문 결과","title":"Carrow Museum of History — Visitor Survey, \"Silk Roads\" Exhibition (June 1–30)","text":"CARROW MUSEUM OF HISTORY\nVisitor Survey — \"Silk Roads\" Exhibition (June 1–30)\nResponses received: 1,250\n\nQuestion | Satisfied | Neutral | Dissatisfied\nQuality of objects on display | 91% | 7% | 2%\nClarity of wall texts and labels | 64% | 21% | 15%\nAudio guide | 58% | 22% | 20%\nWaiting time at entrance | 49% | 18% | 33%\nGift shop | 72% | 20% | 8%\n\nMost common comments:\n- \"Labels were hard to read in the dim lighting.\"\n- \"The audio guide skipped several rooms.\"\n- \"The line on weekends was far too long.\""},{"doc_type":"회람","title":"To: Exhibition Staff / From: Dr. Elif Şahin, Head of Visitor Experience / Date: July 8 / Subject: Improvements for July and August","text":"Thank you all for your hard work in June. The survey results show that visitors love the collection itself, so our priority now is the experience around it.\n\nBeginning July 15, we will introduce timed-entry tickets on Saturdays and Sundays, which should reduce the problem that received the highest dissatisfaction rating. Visitors will be able to reserve a 30-minute entry window online.\n\nIn addition, the design team will reprint the labels in larger type, and technicians will add small spotlights above each display case. Work on the audio guide will have to wait until September, when the vendor can update the recordings.\n\nPlease encourage visitors to fill out the survey again so that we can measure the effect of these changes."}],"questions":[{"q":"Which aspect of the exhibition received the highest satisfaction rating?","choices":["The audio guide","The wall texts and labels","The objects on display","The gift shop"],"answer":2,"type":"세부 사항","explanation":"설문 표에서 전시품의 질(Quality of objects on display)의 만족 비율이 91퍼센트로 가장 높다. 기념품점은 72퍼센트, 안내문은 64퍼센트, 오디오 가이드는 58퍼센트이다."},{"q":"What problem are the timed-entry tickets meant to solve?","choices":["Long waits at the entrance","Labels that are hard to read","Gaps in the audio guide","High prices in the gift shop"],"answer":0,"type":"연계 문제","explanation":"회람은 시간 지정 입장권이 '불만족 비율이 가장 높은 문제'를 줄일 것이라고 했다. 설문 표에서 불만족 비율이 가장 높은 항목은 입구 대기 시간(33퍼센트)이며, 주말 줄이 너무 길다는 의견과도 일치한다."},{"q":"Which visitor comment will the new spotlights most likely address?","choices":["“The line on weekends was far too long.”","“Labels were hard to read in the dim lighting.”","“The gift shop was too crowded.”","“The audio guide skipped several rooms.”"],"answer":1,"type":"연계 문제","explanation":"회람에서 각 진열장 위에 작은 조명을 설치한다고 했는데, 이는 설문 의견 중 '어두운 조명 때문에 안내문을 읽기 어려웠다'는 불만에 대응하는 조치이다. 기념품점 관련 의견은 설문에 없다."},{"q":"What is indicated about the audio guide?","choices":["It will be replaced by a mobile app.","It is being updated by the museum's technicians.","It will not be updated until September.","It received the lowest satisfaction rating."],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"회람 셋째 단락에서 오디오 가이드 작업은 업체가 녹음을 수정할 수 있는 9월까지 기다려야 한다고 했다. 만족 비율이 가장 낮은 항목은 입구 대기 시간(49퍼센트)이고, 수정은 박물관 기술자가 아니라 업체가 한다."},{"q":"In the memo, the word “measure” in paragraph 4 is closest in meaning to","choices":["extend","assess","mark","divide"],"answer":1,"type":"동의어","explanation":"'measure the effect of these changes'는 변화의 효과를 '평가하다, 가늠하다'라는 뜻이므로 'assess'가 가장 가깝다. divide(나누다), extend(늘리다), mark(표시하다)는 문맥에 맞지 않는다."}],"translation":"[설문 결과]\n캐로 역사박물관\n관람객 설문 — \"실크로드\" 전시 (6월 1일~30일)\n응답 수: 1,250\n\n항목 | 만족 | 보통 | 불만족\n전시품의 질 | 91% | 7% | 2%\n벽면 설명과 안내문의 명확성 | 64% | 21% | 15%\n오디오 가이드 | 58% | 22% | 20%\n입구 대기 시간 | 49% | 18% | 33%\n기념품점 | 72% | 20% | 8%\n\n가장 많았던 의견:\n- \"어두운 조명 때문에 안내문을 읽기 어려웠다.\"\n- \"오디오 가이드가 몇몇 전시실을 건너뛰었다.\"\n- \"주말 줄이 너무 길었다.\"\n\n[회람]\n수신: 전시 담당 직원 / 발신: 엘리프 샤힌 박사, 관람 경험 책임자 / 날짜: 7월 8일 / 제목: 7~8월 개선 사항\n\n6월 한 달간 수고해 주신 모든 분께 감사드립니다. 설문 결과를 보면 관람객들은 소장품 자체를 매우 좋아하므로, 이제 우리가 우선할 일은 그 주변의 관람 경험입니다.\n\n7월 15일부터 토요일과 일요일에 시간 지정 입장권을 도입합니다. 이는 불만족 비율이 가장 높았던 문제를 줄여 줄 것입니다. 관람객은 온라인으로 30분 단위 입장 시간을 예약할 수 있습니다.\n\n또한 디자인팀은 안내문을 더 큰 글씨로 다시 인쇄하고, 기술자들은 각 진열장 위에 작은 조명을 설치할 것입니다. 오디오 가이드 작업은 업체가 녹음을 수정할 수 있는 9월까지 기다려야 합니다.\n\n이러한 변화의 효과를 평가할 수 있도록 관람객들에게 설문에 다시 참여하도록 권해 주십시오.","part":7},{"id":"p7-061","level":4,"kind":"double","passages":[{"doc_type":"웹페이지","title":"www.voltaride.com/service","text":"VOLTARIDE ELECTRIC SCOOTERS — REPAIR SERVICE\n\nWarranty repairs\nAll VoltaRide scooters include a one-year warranty on the motor and frame and a six-month warranty on the battery. Warranty repairs are free, and we cover shipping both ways.\n\nOut-of-warranty repairs\nDiagnosis fee: $40 (deducted from the repair cost if you proceed with the repair)\nBattery replacement: $180\nBrake adjustment: $25\nTire replacement: $35 per tire\n\nTurnaround time is usually 7–10 business days. Customers in Denver, Austin, and Portland may bring their scooters to one of our service hubs for same-day brake and tire repairs.\n\nTo request service, complete the online form and include your serial number and proof of purchase."},{"doc_type":"이메일","title":"From: Rafael Gutiérrez / To: service@voltaride.com / Date: November 20 / Subject: Battery problem — serial VR-88302","text":"Hello,\n\nI bought my VoltaRide X2 scooter on March 3 of this year. Over the past month, the battery has been losing power quickly; it now lasts about 20 minutes instead of 90. I use the scooter every day to commute to my office, so I'd like this fixed as soon as possible.\n\nI live in Austin, so I could bring the scooter in myself if that would be faster. I've attached a copy of my receipt. Please let me know the cost and how long the repair will take.\n\nBest,\nRafael Gutiérrez"}],"questions":[{"q":"Why did Mr. Gutiérrez write the e-mail?","choices":["To complain about a late delivery","To order a second scooter","To cancel a service appointment","To ask about repairing his scooter"],"answer":3,"type":"주제·목적","explanation":"이메일에서 배터리가 빨리 닳는 문제를 설명하고 비용과 수리 기간을 알려 달라고 했으므로 스쿠터 수리를 문의하려는 것이다."},{"q":"What is suggested about Mr. Gutiérrez's battery?","choices":["It is no longer covered by the warranty.","It was damaged during shipping.","It is still under the one-year warranty.","It was replaced once before."],"answer":0,"type":"연계 문제","explanation":"웹페이지에 따르면 배터리 보증 기간은 6개월이다. 구티에레스 씨는 3월 3일에 구입했으므로 보증은 9월 초에 끝났고, 이메일은 11월 20일에 보냈다. 1년 보증은 모터와 차체에만 해당한다."},{"q":"If Mr. Gutiérrez goes ahead with the repair, how much will he most likely pay in total?","choices":["$40","Nothing","$220","$180"],"answer":3,"type":"연계 문제","explanation":"보증이 끝났으므로 배터리 교체비 180달러를 내야 한다. 진단비 40달러는 수리를 진행하면 수리비에서 차감되므로 총액은 180달러이다. 220달러는 진단비를 따로 더한 잘못된 계산이다."},{"q":"Why will Mr. Gutiérrez probably not get a same-day repair in Austin?","choices":["Same-day service covers only brakes and tires.","He did not include his serial number.","The Austin service hub has closed.","Same-day service is only for warranty repairs."],"answer":0,"type":"연계 문제","explanation":"이메일에서 오스틴에 살아 직접 가져갈 수 있다고 했지만, 웹페이지는 서비스 허브의 당일 수리가 브레이크와 타이어에만 해당한다고 했다. 그의 문제는 배터리이므로 당일 수리 대상이 아니다. 일련번호는 제목에 적혀 있다."},{"q":"What did Mr. Gutiérrez include with his e-mail?","choices":["A diagnosis report","A photograph of the battery","Proof of purchase","A completed online form"],"answer":2,"type":"세부 사항","explanation":"이메일 'I've attached a copy of my receipt.'에서 영수증 사본, 즉 구매 증빙을 첨부했다. 사진이나 진단서는 없으며, 온라인 양식을 작성했다는 말도 없다."}],"translation":"[웹페이지]\n볼타라이드 전동 킥보드 — 수리 서비스\n\n보증 수리\n모든 볼타라이드 킥보드는 모터와 차체에 1년, 배터리에 6개월 보증이 적용됩니다. 보증 수리는 무료이며 왕복 배송비도 저희가 부담합니다.\n\n보증 기간 외 수리\n진단비: 40달러 (수리를 진행하면 수리비에서 차감)\n배터리 교체: 180달러\n브레이크 조정: 25달러\n타이어 교체: 타이어 1개당 35달러\n\n수리 기간은 보통 7~10영업일입니다. 덴버, 오스틴, 포틀랜드의 고객은 서비스 허브에 킥보드를 직접 가져오시면 브레이크와 타이어를 당일 수리받을 수 있습니다.\n\n수리를 요청하려면 온라인 양식을 작성하고 일련번호와 구매 증빙을 첨부해 주세요.\n\n[이메일]\n발신: 라파엘 구티에레스 / 수신: service@voltaride.com / 날짜: 11월 20일 / 제목: 배터리 문제 — 일련번호 VR-88302\n\n안녕하세요.\n\n올해 3월 3일에 볼타라이드 X2 킥보드를 샀습니다. 지난 한 달 동안 배터리가 빠르게 닳아서, 이제는 90분이 아니라 20분 정도밖에 가지 않습니다. 매일 출퇴근에 쓰고 있어서 가능한 한 빨리 고치고 싶습니다.\n\n오스틴에 살고 있으니 그게 더 빠르다면 직접 가져갈 수도 있습니다. 영수증 사본을 첨부했습니다. 비용과 수리 기간을 알려 주세요.\n\n라파엘 구티에레스 드림","part":7},{"id":"p7-062","level":4,"kind":"triple","passages":[{"doc_type":"행사 일정표","title":"Nordic Sustainable Architecture Forum — Day 2 Program (Friday, October 17), Bergen Congress Hall","text":"9:00–9:45 Keynote: \"Building with Timber in Cold Climates\" — Prof. Astrid Nygaard (Main Hall)\n10:00–11:00 Panel: Retrofitting Historic Buildings — moderated by Jonas Berg (Room 2)\n11:15–12:15 Workshop: Energy Modeling Software for Beginners — Leila Farahani (Room 4; limited to 25 participants; bring a laptop)\n12:15–1:30 Lunch (Harbor Terrace)\n1:30–2:30 Case Study: The Tromsø Library Project — Hiroshi Tanaka (Main Hall)\n2:45–3:45 Panel: Financing Green Construction — moderated by Clara Weiss (Room 2)\n4:00 Closing remarks (Main Hall)\n\nAll sessions will be recorded and made available to registered attendees after the forum."},{"doc_type":"이메일","title":"From: Hiroshi Tanaka / To: Nils Østby, Program Coordinator / Date: October 14 / Subject: Friday schedule","text":"Dear Mr. Østby,\n\nI'm afraid my flight from Osaka has been rebooked, and I will now land in Bergen at 12:40 P.M. on Friday instead of in the morning. Since the airport is about 30 minutes from the Congress Hall, I would prefer not to risk starting my talk late.\n\nWould it be possible to exchange time slots with another afternoon session? I would be happy to present at 2:45 if the moderator of that session agrees. Otherwise, I could shorten my presentation to 40 minutes.\n\nMy apologies for the trouble.\n\nBest regards,\nHiroshi Tanaka"},{"doc_type":"문자 메시지","title":"Text-message chain","text":"Nils Østby (3:10 P.M.): Clara, Mr. Tanaka's flight has changed. Would you be willing to move your panel to 1:30 on Friday so he can take 2:45?\nClara Weiss (3:14 P.M.): That should be fine. I'll need to check with my panelists, though. One of them is also attending the workshop in Room 4 that morning.\nNils Østby (3:15 P.M.): That ends at 12:15, so there's no conflict.\nClara Weiss (3:32 P.M.): All three panelists agreed. Go ahead and update the program.\nNils Østby (3:33 P.M.): Great. I'll send a notice to all attendees tonight."}],"questions":[{"q":"What is Prof. Nygaard's talk about?","choices":["Restoring old buildings","Using wood in construction","Designing public libraries","Financing environmentally friendly buildings"],"answer":1,"type":"세부 사항","explanation":"일정표의 기조연설 제목 'Building with Timber in Cold Climates'에서 추운 기후에서 목재로 짓는 건축에 관한 강연임을 알 수 있다. 친환경 건축 자금은 바이스 씨, 역사적 건물 개보수는 베르그 씨의 패널, 도서관은 다나카 씨의 사례 발표 주제이다."},{"q":"Why did Mr. Tanaka write the e-mail?","choices":["To book a flight to Bergen","To request a change to the schedule","To cancel his presentation","To ask for a larger room"],"answer":1,"type":"주제·목적","explanation":"이메일에서 비행기 도착이 늦어졌다며 다른 오후 세션과 시간대를 바꿀 수 있는지(exchange time slots) 물었으므로 일정 변경을 요청하려는 것이다. 발표를 취소하지는 않았다."},{"q":"Which session does one of Ms. Weiss's panelists plan to attend?","choices":["A keynote speech on timber buildings","A panel on historic buildings","A workshop on energy modeling software","A case study of a library project"],"answer":2,"type":"연계 문제","explanation":"문자 메시지에서 바이스 씨는 패널 한 명이 그날 오전 4번 룸 워크숍에 참석한다고 했다. 일정표에서 4번 룸 행사는 초보자를 위한 에너지 모델링 소프트웨어 워크숍이다."},{"q":"At 3:15 P.M., why does Mr. Østby write, “That ends at 12:15, so there's no conflict”?","choices":["To assure Ms. Weiss that the new time will work for her panelist","To explain why Mr. Tanaka's flight was changed","To remind Ms. Weiss that lunch starts at 12:15","To suggest that the workshop be shortened"],"answer":0,"type":"의도 파악","explanation":"바이스 씨가 패널 한 명이 오전 워크숍에 간다고 걱정하자, 외스트뷔 씨는 워크숍이 12시 15분에 끝나므로 1시 30분 패널과 겹치지 않는다고 답했다. 즉 새 시간이 그 패널에게도 문제없다고 안심시키려는 것이다."},{"q":"When will the panel on financing green construction most likely begin?","choices":["At 12:40 P.M.","At 2:45 P.M.","At 4:00 P.M.","At 1:30 P.M."],"answer":3,"type":"연계 문제","explanation":"일정표에서 친환경 건축 자금 패널은 원래 2시 45분에 바이스 씨가 진행하기로 되어 있었다. 문자 메시지에서 외스트뷔 씨가 이 패널을 1시 30분으로 옮기자고 했고 패널 전원이 동의했으므로 1시 30분에 시작할 것이다."}],"translation":"[행사 일정표]\n북유럽 지속 가능 건축 포럼 — 2일 차 프로그램 (10월 17일 금요일), 베르겐 콩그레스 홀\n\n9:00~9:45 기조연설: \"추운 기후에서 목재로 짓기\" — 아스트리드 뉘고르 교수 (메인 홀)\n10:00~11:00 패널 토론: 역사적 건물의 개보수 — 사회: 요나스 베르그 (2번 룸)\n11:15~12:15 워크숍: 초보자를 위한 에너지 모델링 소프트웨어 — 레일라 파라하니 (4번 룸, 정원 25명, 노트북 지참)\n12:15~1:30 점심 (하버 테라스)\n1:30~2:30 사례 연구: 트롬쇠 도서관 프로젝트 — 히로시 다나카 (메인 홀)\n2:45~3:45 패널 토론: 친환경 건축 자금 조달 — 사회: 클라라 바이스 (2번 룸)\n4:00 폐회사 (메인 홀)\n\n모든 세션은 녹화되어 포럼이 끝난 뒤 등록 참석자에게 제공됩니다.\n\n[이메일]\n발신: 히로시 다나카 / 수신: 닐스 외스트뷔, 프로그램 코디네이터 / 날짜: 10월 14일 / 제목: 금요일 일정\n\n외스트뷔 씨께,\n\n죄송하지만 오사카발 항공편이 다시 예약되어 금요일 오전이 아니라 오후 12시 40분에 베르겐에 도착하게 되었습니다. 공항에서 콩그레스 홀까지 약 30분이 걸리므로, 발표를 늦게 시작하는 위험은 피하고 싶습니다.\n\n다른 오후 세션과 시간대를 바꿀 수 있을까요? 그 세션 사회자가 동의한다면 2시 45분에 발표하고 싶습니다. 그렇지 않다면 발표를 40분으로 줄일 수도 있습니다.\n\n번거롭게 해 드려 죄송합니다.\n\n히로시 다나카 드림\n\n[문자 메시지]\n닐스 외스트뷔 (오후 3:10): 클라라, 다나카 씨 항공편이 바뀌었어요. 다나카 씨가 2시 45분을 쓸 수 있게 금요일 패널을 1시 30분으로 옮겨 주실 수 있을까요?\n클라라 바이스 (오후 3:14): 괜찮을 것 같아요. 그래도 패널들에게 확인해야 해요. 그중 한 명이 그날 오전 4번 룸 워크숍에도 참석하거든요.\n닐스 외스트뷔 (오후 3:15): 그건 12시 15분에 끝나니까 겹치지 않아요.\n클라라 바이스 (오후 3:32): 패널 세 명 모두 동의했어요. 프로그램을 수정하셔도 돼요.\n닐스 외스트뷔 (오후 3:33): 좋아요. 오늘 밤 모든 참석자에게 공지를 보낼게요.","part":7},{"id":"p7-063","level":5,"kind":"single","passages":[{"doc_type":"잡지 기사","title":"The Quiet Rise of Shared Commercial Kitchens / By Priyanka Sethi","text":"For decades, opening a restaurant meant signing a long lease, installing costly ventilation, and hoping enough diners would walk through the door. A new model is rewriting those assumptions. Shared commercial kitchens, which rent fully equipped cooking stations by the hour or by the month, now operate in more than 60 cities across North America, according to the consultancy Forkline Analytics.\n\nThe appeal is largely financial. A cook launching a delivery-only brand in a shared kitchen in Toronto might spend around $4,000 a month, compared with an estimated $250,000 in upfront costs to build out a conventional space. [1] Operators, meanwhile, earn steady income by keeping their facilities busy around the clock, often assigning early-morning slots to bakers and late-night slots to caterers.\n\nYet the model has its skeptics. Because tenants rely heavily on third-party delivery apps, which can charge commissions of up to 30 percent per order, profit margins remain thin. [2] Some neighborhood groups have also objected to the steady stream of delivery drivers idling outside facilities.\n\nOperators are responding. Several have begun offering shared storefront counters where customers can pick up orders directly, bypassing app fees altogether. [3] Others have negotiated group rates with delivery platforms on behalf of their tenants.\n\nWhether shared kitchens will reshape the industry or remain a niche is an open question. [4] What is clear is that they have lowered the barrier to entry for a generation of cooks who, a decade ago, could never have afforded to open their doors."}],"questions":[{"q":"What is NOT mentioned as a drawback of shared kitchens?","choices":["Commissions charged by delivery apps","Small profit margins for tenants","The high cost of installing ventilation","Objections from local residents"],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"셋째 단락에서 배달 앱 수수료, 얇은 이윤, 배달 기사들의 공회전에 대한 주민 단체의 반대를 문제점으로 들었다. 값비싼 환기 설비는 첫 단락에서 전통적인 식당을 열 때의 부담으로 언급되었을 뿐 공유 주방의 단점이 아니다."},{"q":"What can be inferred about the operators of shared kitchens?","choices":["They benefit when tenants work at different times of day.","They were first established in Toronto.","They charge higher rents than conventional landlords.","They prefer tenants who do not use delivery apps."],"answer":0,"type":"추론","explanation":"둘째 단락에서 운영자는 시설을 24시간 가동해 꾸준한 수입을 얻으며, 이른 아침은 제빵사에게, 늦은 밤은 케이터링 업체에 배정한다고 했다. 따라서 입주자들의 작업 시간대가 서로 다를수록 운영자에게 유리하다고 추론할 수 있다. 토론토는 예시로 든 도시일 뿐이다."},{"q":"The word “thin” in paragraph 3 is closest in meaning to","choices":["delicate","small","clear","diluted"],"answer":1,"type":"동의어","explanation":"'profit margins remain thin'은 이윤 폭이 '작다, 적다'는 뜻이므로 'small'이 가장 가깝다. clear(투명한), delicate(섬세한), diluted(희석된)는 물건의 두께나 액체의 농도를 말할 때의 thin이라 이 문맥에 맞지 않는다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? “Tamar Levi, who runs a Georgian dumpling business out of one such facility in Chicago, says her pickup counter now accounts for a quarter of her sales.”","choices":["[1]","[2]","[3]","[4]"],"answer":2,"type":"문장 삽입","explanation":"주어진 문장은 '픽업 카운터'가 매출의 4분의 1을 차지한다는 사례이므로, 고객이 직접 주문을 찾아가는 공용 매장 카운터를 도입했다는 문장 뒤인 [3]이 알맞다. 다른 위치 앞에는 픽업 카운터가 언급되지 않았다."}],"translation":"공유 상업 주방의 조용한 부상 / 프리양카 세티 기자\n\n수십 년 동안 식당을 연다는 것은 장기 임대 계약을 맺고, 비싼 환기 설비를 설치하고, 충분한 손님이 문을 열고 들어오기를 바라는 일이었다. 새로운 모델이 이런 전제를 바꾸고 있다. 완비된 조리 공간을 시간 단위나 월 단위로 빌려주는 공유 상업 주방은 컨설팅 업체 포크라인 애널리틱스에 따르면 현재 북미 60여 개 도시에서 운영되고 있다.\n\n매력은 주로 비용에 있다. 토론토의 공유 주방에서 배달 전문 브랜드를 시작하는 요리사는 한 달에 약 4,000달러를 쓸 수 있는데, 일반 매장을 꾸미는 데 드는 초기 비용은 약 25만 달러로 추산된다. 한편 운영자는 시설을 24시간 쉬지 않고 가동해 꾸준한 수입을 올리며, 흔히 이른 아침 시간은 제빵사에게, 늦은 밤 시간은 케이터링 업체에 배정한다.\n\n그러나 이 모델에 회의적인 시각도 있다. 입주자들은 주문당 최대 30퍼센트의 수수료를 받는 외부 배달 앱에 크게 의존하기 때문에 이윤이 적다. 일부 주민 단체는 시설 밖에서 공회전하며 끊임없이 드나드는 배달 기사들에 대해 반대 의견을 내기도 했다.\n\n운영자들은 대응에 나서고 있다. 몇몇 운영자는 고객이 주문한 음식을 직접 찾아갈 수 있는 공용 매장 카운터를 도입해 앱 수수료를 아예 피하게 했다. (시카고의 그런 시설 한 곳에서 조지아식 만두 사업을 하는 타마르 레비는 현재 픽업 카운터가 매출의 4분의 1을 차지한다고 말한다.) 다른 운영자들은 입주자를 대신해 배달 플랫폼과 단체 요율을 협상했다.\n\n공유 주방이 업계를 재편할지, 틈새시장에 머물지는 아직 알 수 없다. 분명한 것은 10년 전이라면 결코 가게를 열 여유가 없었을 한 세대의 요리사들에게 진입 장벽을 낮춰 주었다는 점이다.","part":7},{"id":"p7-064","level":5,"kind":"single","passages":[{"doc_type":"온라인 채팅","title":"Online chat discussion","text":"Helena Voss [11:02 A.M.]: The Kinsella contract came back from their legal team. They've accepted everything except the payment terms.\nMarcus Adebayo [11:04 A.M.]: Let me guess. They want 90 days instead of 45.\nHelena Voss [11:04 A.M.]: Got it in one.\nMarcus Adebayo [11:06 A.M.]: Finance won't sign off on 90. Our cash flow in the first quarter is already tight because of the warehouse expansion.\nYuki Sato [11:08 A.M.]: What if we offered 60 days but added a 2 percent discount for payment within 30? Kinsella has paid early on smaller orders before.\nHelena Voss [11:09 A.M.]: I like that. It gives them flexibility and gives us a reason to expect cash sooner.\nMarcus Adebayo [11:11 A.M.]: I'd need to run the numbers. On a $1.2 million order, 2 percent is $24,000.\nYuki Sato [11:12 A.M.]: True, but that's less than what a short-term loan would cost us if they took 90 days.\nMarcus Adebayo [11:14 A.M.]: Fair point. Send me the draft language, and I'll take it to Olga this afternoon. She has the final say on anything beyond 45 days.\nHelena Voss [11:15 A.M.]: Will do. Kinsella wants an answer by Thursday, so there isn't much room to go back and forth."}],"questions":[{"q":"At 11:04 A.M., what does Ms. Voss mean when she writes, “Got it in one”?","choices":["She received a single reply from Kinsella's legal team.","Only one clause in the contract needs to be removed.","Kinsella has signed the contract on the first attempt.","Mr. Adebayo has correctly guessed Kinsella's request."],"answer":3,"type":"의도 파악","explanation":"아데바요 씨가 '45일 대신 90일을 원하겠죠'라고 추측하자 보스 씨가 'Got it in one(한 번에 맞혔다)'이라고 답했다. 즉 그의 추측이 정확하다는 뜻이다. 킨셀라는 결제 조건을 받아들이지 않았으므로 계약이 체결된 것이 아니다."},{"q":"Why is Mr. Adebayo unwilling to accept Kinsella's original request?","choices":["Kinsella has paid its invoices late in the past.","The warehouse expansion has been delayed.","The order is smaller than usual.","His company expects to have limited cash in the coming months."],"answer":3,"type":"세부 사항","explanation":"11시 6분에 창고 확장 때문에 1분기 현금 흐름이 이미 빠듯하다(tight)고 했으므로 자금 여유가 부족할 것이 이유이다. 오히려 사토 씨는 킨셀라가 작은 주문에서 일찍 결제한 적이 있다고 했다."},{"q":"At 11:14 A.M., what does Mr. Adebayo imply when he writes, “Fair point”?","choices":["He accepts that the discount may cost less than the alternative.","He thinks that Kinsella's request is fair.","He agrees that the contract should be signed immediately.","He believes that $24,000 is a reasonable fee for a loan."],"answer":0,"type":"의도 파악","explanation":"아데바요 씨가 2퍼센트 할인이면 24,000달러라고 우려하자, 사토 씨가 90일을 주면 들어갈 단기 대출 비용보다 적다고 반박했다. 'Fair point'는 그 반박을 인정한 것이며, 바로 초안을 보내 달라고 한 것도 이를 뒷받침한다."},{"q":"What is suggested about Olga?","choices":["She is managing the warehouse expansion.","She must approve the proposed payment terms.","She wrote the original contract.","She works in Kinsella's legal department."],"answer":1,"type":"추론","explanation":"아데바요 씨는 초안을 올가에게 가져가겠다며 45일을 넘는 조건은 그녀가 최종 결정권(final say)을 가진다고 했다. 제안된 조건은 60일이므로 올가의 승인이 필요하다. 그녀가 킨셀라 소속이라는 근거는 없다."}],"translation":"헬레나 보스 [오전 11:02]: 킨셀라 계약서가 그쪽 법무팀에서 돌아왔어요. 결제 조건만 빼고 전부 받아들였어요.\n마커스 아데바요 [오전 11:04]: 맞혀 볼게요. 45일 대신 90일을 원하죠?\n헬레나 보스 [오전 11:04]: 한 번에 맞히셨네요.\n마커스 아데바요 [오전 11:06]: 재무팀은 90일을 승인하지 않을 거예요. 창고 확장 때문에 1분기 현금 흐름이 이미 빠듯하거든요.\n유키 사토 [오전 11:08]: 60일을 제시하되 30일 안에 결제하면 2퍼센트 할인해 주면 어때요? 킨셀라는 전에 작은 주문에서 일찍 결제한 적이 있어요.\n헬레나 보스 [오전 11:09]: 좋네요. 그쪽엔 유연성을 주고, 우리는 현금을 더 빨리 받을 이유가 생기고요.\n마커스 아데바요 [오전 11:11]: 계산을 해 봐야겠어요. 120만 달러 주문이면 2퍼센트는 24,000달러예요.\n유키 사토 [오전 11:12]: 맞아요, 그래도 그쪽이 90일을 가져가면 우리가 단기 대출에 쓰는 비용보다는 적어요.\n마커스 아데바요 [오전 11:14]: 일리 있네요. 문구 초안을 보내 주세요. 오늘 오후에 올가에게 가져갈게요. 45일을 넘는 건 올가가 최종 결정하거든요.\n헬레나 보스 [오전 11:15]: 그럴게요. 킨셀라가 목요일까지 답을 달라고 해서 여러 번 주고받을 여유는 별로 없어요.","part":7},{"id":"p7-065","level":5,"kind":"single","passages":[{"doc_type":"계약서","title":"Equipment Rental and Service Agreement — Excerpt","text":"EQUIPMENT RENTAL AND SERVICE AGREEMENT (EXCERPT)\nBetween Meridian Medical Imaging Ltd. (\"Provider\") and Kovač Diagnostic Clinic (\"Client\")\n\n2.1 Equipment. The Provider shall supply one MR-7 ultrasound system, including installation and initial staff training of up to eight hours.\n\n2.2 Fees. The Client shall pay a monthly rental fee of $3,150. Fees are payable in advance on the first business day of each month. Payments more than ten days overdue shall accrue interest at 1.5 percent per month.\n\n3.1 Service. The Provider shall perform preventive maintenance every six months at no additional cost. Emergency repairs shall be carried out within 48 hours of notification. If a repair cannot be completed within that period, the Provider shall supply a replacement unit at its own expense until the original equipment is returned to service.\n\n3.2 Exclusions. Service obligations under Section 3.1 do not extend to damage resulting from relocation of the equipment by the Client, unauthorized software modifications, or power surges not attributable to the Provider.\n\n5.1 Termination. Either party may terminate this Agreement with 90 days' written notice. Should the Client terminate within the first 24 months, a fee equal to two months' rental shall apply."}],"questions":[{"q":"What is included in the Provider's obligations?","choices":["Repairs after the Client moves the equipment","Unlimited training for clinic staff","Free upgrades to the system's software","Routine maintenance twice a year"],"answer":3,"type":"사실 확인(NOT/TRUE)","explanation":"3.1항에서 6개월마다 추가 비용 없이 예방 정비를 한다고 했으므로 1년에 두 번 정기 정비가 포함된다. 교육은 최대 8시간이고, 고객이 장비를 옮겨 생긴 손상은 3.2항에서 제외되며, 소프트웨어 업그레이드는 언급되지 않았다."},{"q":"What would most likely happen if the ultrasound system could not be fixed within two days?","choices":["The clinic would temporarily receive substitute equipment.","The clinic's monthly fee would be reduced.","The clinic would pay for a replacement unit.","The agreement would be terminated automatically."],"answer":0,"type":"추론","explanation":"3.1항에서 48시간(이틀) 안에 수리를 끝내지 못하면 공급자가 자기 비용으로 대체 장비를 제공한다고 했다. 비용은 공급자가 부담하므로 클리닉이 내지 않으며, 요금 감액이나 자동 해지는 언급되지 않았다."},{"q":"The word “accrue” in Section 2.2 is closest in meaning to","choices":["reduce","accumulate","declare","request"],"answer":1,"type":"동의어","explanation":"'Payments more than ten days overdue shall accrue interest'는 연체된 금액에 이자가 '붙는다, 쌓인다'는 뜻이므로 'accumulate(누적되다)'가 가장 가깝다."},{"q":"If the Client ends the agreement after 18 months, what fee will it most likely have to pay?","choices":["$3,150","No fee","$6,300","$9,450"],"answer":2,"type":"추론","explanation":"5.1항에 따르면 고객이 처음 24개월 안에 해지하면 두 달치 임대료에 해당하는 수수료를 낸다. 18개월은 24개월 이내이므로 3,150×2=6,300달러이다. 3,150달러는 한 달치, 9,450달러는 석 달치이다."}],"translation":"장비 임대 및 서비스 계약서 (발췌)\n메리디언 메디컬 이미징(\"공급자\")과 코바치 진단 클리닉(\"고객\") 간\n\n2.1 장비. 공급자는 MR-7 초음파 시스템 1대를 설치 및 최대 8시간의 초기 직원 교육을 포함하여 공급한다.\n\n2.2 요금. 고객은 월 임대료 3,150달러를 지급한다. 요금은 매월 첫 영업일에 선불로 지급한다. 10일을 넘겨 연체된 금액에는 월 1.5퍼센트의 이자가 붙는다.\n\n3.1 서비스. 공급자는 6개월마다 추가 비용 없이 예방 정비를 실시한다. 긴급 수리는 통보 후 48시간 이내에 실시한다. 그 기간 안에 수리를 완료할 수 없으면 공급자는 원래 장비가 다시 사용 가능해질 때까지 자기 비용으로 대체 장비를 제공한다.\n\n3.2 예외. 3.1항의 서비스 의무는 고객이 장비를 이전하여 생긴 손상, 승인되지 않은 소프트웨어 변경, 공급자에게 책임이 없는 전력 과부하에는 적용되지 않는다.\n\n5.1 해지. 각 당사자는 90일 전 서면 통지로 이 계약을 해지할 수 있다. 고객이 처음 24개월 이내에 해지하는 경우 두 달치 임대료에 해당하는 수수료가 부과된다.","part":7},{"id":"p7-066","level":5,"kind":"single","passages":[{"doc_type":"보도 자료","title":"FOR IMMEDIATE RELEASE — Halcyon Maritime Group","text":"FOR IMMEDIATE RELEASE\n\nHALCYON MARITIME GROUP ANNOUNCES REALIGNMENT OF ITS CONTAINER OPERATIONS\n\nROTTERDAM, February 24 — Halcyon Maritime Group today announced plans to consolidate its three regional container divisions into a single global unit, a move the company expects to reduce annual operating costs by approximately €85 million by 2028. [1]\n\nUnder the new structure, route planning, vessel scheduling, and customer contracts, which until now have been handled separately in Rotterdam, Singapore, and Panama City, will be managed from a central operations center in Rotterdam. Regional offices will remain open but will concentrate on port relations and local sales. [2]\n\n\"Our customers have told us clearly that they want one point of contact, regardless of where their cargo travels,\" said Chief Executive Annelie de Vries. \"This realignment allows us to deliver exactly that.\"\n\nThe company indicated that the reorganization would affect roughly 400 administrative positions worldwide. [3] Halcyon intends to fill as many of the new roles as possible with existing employees and will offer relocation assistance to staff who move to Rotterdam.\n\nThe transition will be carried out in stages, beginning with the Asia-Pacific division in July. [4] Halcyon will release its full-year financial results on March 12."}],"questions":[{"q":"What is indicated about Halcyon's regional offices?","choices":["They will be closed by 2028.","They will take over vessel scheduling.","They will be moved to Rotterdam.","They will continue to operate with a narrower focus."],"answer":3,"type":"사실 확인(NOT/TRUE)","explanation":"둘째 단락에서 지역 사무소는 계속 운영되지만 항만 관계와 현지 영업에 집중한다고 했으므로 업무 범위가 좁아진 채 유지된다. 선박 일정 관리는 로테르담 중앙 운영 센터로 옮겨진다."},{"q":"The word “concentrate” in paragraph 2 is closest in meaning to","choices":["focus","reduce","thicken","gather"],"answer":0,"type":"동의어","explanation":"'will concentrate on port relations and local sales'는 해당 업무에 '집중하다'라는 뜻이므로 'focus'가 가장 가깝다. gather(모이다)나 thicken(농축하다)은 concentrate의 다른 뜻이라 이 문맥에 맞지 않는다."},{"q":"What can be inferred about the reorganization?","choices":["It was requested by the company's shareholders.","It has already been completed in Panama City.","Some employees may be asked to work in a different city.","The Singapore office will be closed in July."],"answer":2,"type":"추론","explanation":"넷째 단락에서 새 직무를 기존 직원으로 채우고 로테르담으로 옮기는 직원에게 이주 지원을 하겠다고 했으므로, 일부 직원은 다른 도시에서 일하게 될 수 있다. 지역 사무소는 계속 열려 있고, 전환은 7월 아시아태평양 부문부터 시작된다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? “Most of the savings will come from eliminating overlapping software systems and duplicated management functions.”","choices":["[1]","[2]","[3]","[4]"],"answer":0,"type":"문장 삽입","explanation":"'the savings(절감액)'는 연간 운영비를 약 8,500만 유로 줄인다는 내용을 가리키므로 그 문장 바로 뒤인 [1]이 알맞다. 다른 위치 앞에는 비용 절감이 언급되지 않았다."}],"translation":"즉시 배포용 보도 자료\n\n할시온 해운 그룹, 컨테이너 사업 재편 발표\n\n로테르담, 2월 24일 — 할시온 해운 그룹은 3개의 지역 컨테이너 부문을 하나의 글로벌 조직으로 통합할 계획이라고 오늘 발표했다. 회사는 이 조치로 2028년까지 연간 운영비를 약 8,500만 유로 줄일 수 있을 것으로 예상한다. (절감액의 대부분은 중복된 소프트웨어 시스템과 관리 기능을 없애는 데서 나올 것이다.)\n\n새 구조에서는 지금까지 로테르담, 싱가포르, 파나마시티에서 따로 처리해 온 항로 계획, 선박 일정 관리, 고객 계약을 로테르담의 중앙 운영 센터에서 관리한다. 지역 사무소는 계속 운영되지만 항만 관계와 현지 영업에 집중하게 된다.\n\n아넬리 더프리스 최고경영자는 \"고객들은 화물이 어디로 가든 연락 창구가 하나이기를 원한다고 분명히 말해 왔다\"며 \"이번 재편으로 바로 그것을 제공할 수 있게 되었다\"고 말했다.\n\n회사는 이번 조직 개편이 전 세계 약 400개의 관리직에 영향을 미칠 것이라고 밝혔다. 할시온은 새 직무를 가능한 한 기존 직원으로 채울 계획이며, 로테르담으로 옮기는 직원에게는 이주 지원을 제공할 예정이다.\n\n전환은 7월 아시아태평양 부문을 시작으로 단계적으로 진행된다. 할시온은 3월 12일에 연간 재무 실적을 발표할 예정이다.","part":7},{"id":"p7-067","level":5,"kind":"single","passages":[{"doc_type":"회람","title":"To: All Department Heads / From: Rosalind Achebe, Chief Compliance Officer / Date: May 5 / Subject: Revised records retention schedule","text":"Following last quarter's internal audit, Tessaline Insurance will adopt a revised records retention schedule, effective June 1. The audit found that several departments were keeping documents far longer than required, which increases storage costs as well as our exposure in the event of a data breach. [1]\n\nUnder the revised schedule, customer correspondence will be kept for five years after a policy ends, rather than indefinitely. Claims files will be retained for seven years, and internal meeting notes for two. [2] Records related to an ongoing legal matter must be preserved regardless of these periods until the Legal Department confirms in writing that they may be released.\n\nDepartment heads are asked to designate one records coordinator by May 16. Coordinators will attend a 90-minute briefing on May 22 and will then be responsible for reviewing their department's existing files. [3] Paper records scheduled for destruction must be placed in the locked bins provided by our shredding contractor; they should not be placed in ordinary recycling containers.\n\nThe first review must be completed by September 30. [4] Please direct any questions to the Compliance Office at extension 4410."}],"questions":[{"q":"Why was the memo written?","choices":["To announce the results of a customer survey","To introduce new rules for keeping documents","To request new storage equipment","To report a recent data breach"],"answer":1,"type":"주제·목적","explanation":"첫 문장에서 6월 1일부터 개정된 기록 보존 일정을 도입한다고 했고, 이어서 문서별 보존 기간과 절차를 설명했으므로 문서 보관에 관한 새 규정을 알리는 글이다. 데이터 유출은 위험 요인으로 언급되었을 뿐 실제로 발생한 것이 아니다."},{"q":"According to the memo, what is one risk of keeping records too long?","choices":["Slower processing of insurance claims","Penalties from government regulators","Difficulty finding important files","Greater harm if information is stolen"],"answer":3,"type":"세부 사항","explanation":"첫 단락에서 문서를 너무 오래 보관하면 보관 비용과 함께 'our exposure in the event of a data breach(데이터 유출 시 피해 위험)'가 커진다고 했다. 처리 속도, 파일 검색, 정부 제재는 언급되지 않았다."},{"q":"What is suggested about records related to a lawsuit?","choices":["They must be destroyed after two years.","They will be reviewed by records coordinators on May 22.","They may need to be kept longer than the standard periods.","They may be placed in recycling containers."],"answer":2,"type":"추론","explanation":"둘째 단락에서 진행 중인 법적 문제와 관련된 기록은 보존 기간과 관계없이 법무팀이 서면으로 확인할 때까지 보관해야 한다고 했으므로, 일반 기간보다 오래 보관될 수 있다. 5월 22일은 코디네이터 설명회 날짜이다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? “Personnel files are not covered by this change and will continue to follow the policy set by Human Resources.”","choices":["[1]","[2]","[3]","[4]"],"answer":1,"type":"문장 삽입","explanation":"주어진 문장은 인사 파일이 이번 보존 기간 변경에서 제외된다는 내용이므로, 고객 서신·청구 파일·회의록의 보존 기간을 나열한 문장 바로 뒤인 [2]가 알맞다. 다른 위치는 감사 결과, 코디네이터 업무, 검토 기한에 관한 내용 뒤라 어울리지 않는다."}],"translation":"수신: 전 부서장 / 발신: 로잘린드 아체베, 최고 준법 책임자 / 날짜: 5월 5일 / 제목: 기록 보존 일정 개정\n\n지난 분기 내부 감사에 따라 테살린 보험은 6월 1일부터 개정된 기록 보존 일정을 적용합니다. 감사 결과 여러 부서가 필요한 기간보다 훨씬 오래 문서를 보관하고 있었으며, 이는 보관 비용을 늘릴 뿐 아니라 데이터 유출이 일어났을 때 우리가 입을 피해 위험도 키웁니다.\n\n개정된 일정에 따라 고객 서신은 무기한이 아니라 보험 계약 종료 후 5년간 보관합니다. 청구 파일은 7년, 내부 회의록은 2년간 보관합니다. (인사 파일은 이번 변경의 대상이 아니며 인사부가 정한 규정을 계속 따릅니다.) 진행 중인 법적 문제와 관련된 기록은 이 기간과 관계없이 법무팀이 폐기해도 된다고 서면으로 확인할 때까지 보존해야 합니다.\n\n부서장은 5월 16일까지 기록 담당 코디네이터 1명을 지정해 주십시오. 코디네이터는 5월 22일 90분짜리 설명회에 참석한 뒤 부서의 기존 파일을 검토하는 일을 맡게 됩니다. 폐기 예정인 종이 기록은 파쇄 업체가 제공한 잠금 수거함에 넣어야 하며, 일반 재활용 수거함에 넣어서는 안 됩니다.\n\n첫 검토는 9월 30일까지 완료해야 합니다. 문의 사항은 준법 감시실(내선 4410)로 해 주십시오.","part":7},{"id":"p7-068","level":5,"kind":"double","passages":[{"doc_type":"공고","title":"Request for Proposals — Lindqvist Municipal Library: Digital Archive Project","text":"The Lindqvist Municipal Library invites proposals from qualified vendors to digitize its collection of historical newspapers (approximately 48,000 pages, 1890–1965).\n\nScope of work:\n- High-resolution scanning of all pages, with text made searchable through optical character recognition (OCR)\n- Online hosting of the archive for a minimum of five years\n- Training for library staff in managing the archive\n\nRequirements:\n- Because of their fragile condition, all materials must be scanned on library premises; no pages may be removed from the building.\n- Work must be completed by November 30.\n- The total project cost must not exceed $150,000.\n\nProposals are due by 5:00 P.M. on June 20. Preference will be given to vendors with prior experience working on public-sector archives."},{"doc_type":"이메일","title":"From: Dario Mancini, Archivia Solutions / To: Selection Committee, Lindqvist Municipal Library / Date: June 18 / Subject: Proposal — Digital Archive Project","text":"Dear Selection Committee,\n\nArchivia Solutions is pleased to submit the attached proposal for your digital archive project. Over the past eight years, we have digitized collections for the national archives of Malta and for four regional governments in Italy.\n\nOur pricing is as follows: scanning and OCR at $2.25 per page, five years of hosting at $9,000 per year, and staff training at a flat fee of $4,500.\n\nBecause our specialized scanners are too large to transport, we propose to carry out the scanning at our facility in Bologna, where climate-controlled conditions protect fragile paper. Materials would be shipped in insured, custom-built cases. We are confident that we could complete the project by the end of October.\n\nRespectfully,\nDario Mancini\nDirector, Archivia Solutions"}],"questions":[{"q":"What is NOT part of the work requested by the library?","choices":["Hosting the archive online","Training library employees","Making the newspaper text searchable","Repairing damaged newspapers"],"answer":3,"type":"사실 확인(NOT/TRUE)","explanation":"공고의 작업 범위(Scope of work)에는 OCR을 이용한 검색 가능한 스캔, 최소 5년간 온라인 호스팅, 직원 교육이 있다. 훼손된 신문을 복원하는 작업은 요청하지 않았다."},{"q":"What is suggested about Archivia Solutions?","choices":["It submitted its proposal after the deadline.","It plans to hire library staff for the project.","It has the type of experience the library prefers.","It has worked with the Lindqvist Municipal Library before."],"answer":2,"type":"연계 문제","explanation":"공고는 공공 부문 기록물 경험이 있는 업체를 우대한다고 했고, 이메일에서 아르키비아는 몰타 국립 기록원과 이탈리아 지방 정부 네 곳의 자료를 디지털화했다고 했다. 제안서는 마감(6월 20일) 전인 6월 18일에 제출했다."},{"q":"What would be the total cost of Archivia's proposal?","choices":["$112,500","$157,500","$153,000","$117,000"],"answer":1,"type":"연계 문제","explanation":"공고의 약 48,000쪽에 이메일의 쪽당 2.25달러를 곱하면 108,000달러, 5년 호스팅은 9,000×5=45,000달러, 교육비는 4,500달러이므로 합계 157,500달러이다. 이는 예산 한도 150,000달러를 넘는다. 153,000달러는 교육비를, 112,500달러는 호스팅비를 뺀 금액이다."},{"q":"Which of the library's requirements does Archivia's scanning plan fail to meet?","choices":["The requirement that scanning be done on site","The minimum hosting period","The completion deadline","The proposal submission deadline"],"answer":0,"type":"연계 문제","explanation":"공고는 자료가 약하므로 도서관 안에서 스캔해야 하며 어떤 페이지도 건물 밖으로 가져갈 수 없다고 했다. 그러나 아르키비아는 볼로냐 시설로 자료를 보내 스캔하겠다고 했다. 완료 시점(10월 말)은 11월 30일 기한보다 빠르고, 호스팅도 5년으로 조건을 충족한다."},{"q":"In the e-mail, the word “flat” in paragraph 2 is closest in meaning to","choices":["low","dull","fixed","level"],"answer":2,"type":"동의어","explanation":"'a flat fee of $4,500'은 조건에 따라 달라지지 않는 '고정' 요금을 뜻하므로 'fixed'가 가장 가깝다. level(평평한)과 dull(단조로운)은 flat의 다른 뜻이고, low(낮은)는 금액의 성격과 관계가 없다."}],"translation":"[공고]\n제안 요청서 — 린드크비스트 시립 도서관: 디지털 아카이브 프로젝트\n\n린드크비스트 시립 도서관은 소장 중인 옛 신문(약 48,000쪽, 1890~1965년)을 디지털화할 자격을 갖춘 업체의 제안을 받습니다.\n\n작업 범위:\n- 모든 페이지의 고해상도 스캔 및 광학 문자 인식(OCR)을 통한 텍스트 검색 기능\n- 최소 5년간 아카이브 온라인 호스팅\n- 도서관 직원 대상 아카이브 관리 교육\n\n요건:\n- 자료가 손상되기 쉬운 상태이므로 모든 자료는 도서관 안에서 스캔해야 하며, 어떤 페이지도 건물 밖으로 반출할 수 없습니다.\n- 작업은 11월 30일까지 완료해야 합니다.\n- 총 프로젝트 비용은 150,000달러를 넘을 수 없습니다.\n\n제안서 마감은 6월 20일 오후 5시입니다. 공공 부문 기록물 작업 경험이 있는 업체를 우대합니다.\n\n[이메일]\n발신: 다리오 만치니, 아르키비아 솔루션스 / 수신: 린드크비스트 시립 도서관 선정 위원회 / 날짜: 6월 18일 / 제목: 제안서 — 디지털 아카이브 프로젝트\n\n선정 위원회 귀중,\n\n아르키비아 솔루션스는 귀 도서관의 디지털 아카이브 프로젝트에 대한 제안서를 첨부하여 제출하게 되어 기쁩니다. 저희는 지난 8년 동안 몰타 국립 기록원과 이탈리아의 지방 정부 네 곳의 소장 자료를 디지털화했습니다.\n\n가격은 다음과 같습니다. 스캔 및 OCR은 쪽당 2.25달러, 5년간 호스팅은 연 9,000달러, 직원 교육은 고정 요금 4,500달러입니다.\n\n저희의 특수 스캐너는 너무 커서 옮길 수 없으므로, 온습도가 조절되어 약한 종이를 보호할 수 있는 볼로냐 시설에서 스캔할 것을 제안합니다. 자료는 보험에 가입된 맞춤 제작 상자에 담아 운송합니다. 10월 말까지 프로젝트를 완료할 수 있다고 확신합니다.\n\n다리오 만치니\n아르키비아 솔루션스 대표","part":7},{"id":"p7-069","level":5,"kind":"double","passages":[{"doc_type":"기사","title":"Coastal Town Weighs Cruise Ship Limits","text":"PORT AVELINE, April 9 — The Port Aveline Town Council will vote next month on a proposal to limit the number of cruise ships that may dock in the harbor to two per day, down from as many as five during the summer peak.\n\nSupporters argue that the historic town center, with a population of just 11,000, cannot absorb the 15,000 passengers who sometimes arrive on a single day. \"Residents can't get to the pharmacy or the post office on busy days,\" said council member Ilse Brandt, who drafted the proposal.\n\nBusiness owners are divided. Restaurants and souvenir shops near the harbor depend heavily on cruise visitors, while several hotel owners say the crowds discourage overnight guests, who spend considerably more per person. According to a 2025 study by the regional tourism office, overnight visitors spend an average of €210 a day in Port Aveline, compared with €38 for cruise passengers.\n\nIf approved, the limit would take effect next April, giving cruise lines a full season to adjust their schedules."},{"doc_type":"편지","title":"Letter to the Editor, Port Aveline Gazette / From: Mateo Ferrante / Date: April 14","text":"Your April 9 article on the proposed cruise limit presented the figures fairly, but it left out an important point. As the owner of Ferrante Bicycle Tours, I serve both types of visitors, and I can tell you that the spending gap is smaller than it looks. The study your reporter cited did not count the shore excursions that cruise passengers book through local companies like mine, which often cost €60 or more.\n\nThat said, I support the proposal. On five-ship days, my tours are so crowded that their quality suffers, and my regular customers stay away. A reasonable limit would benefit the town in the long run."}],"questions":[{"q":"What does the article mainly report on?","choices":["A proposed rule that is under consideration","A decision that has already taken effect","The opening of a new cruise terminal","A decline in the town's population"],"answer":0,"type":"주제·목적","explanation":"기사는 마을 의회가 다음 달 크루즈선 입항을 하루 두 척으로 제한하는 안건을 표결할 예정이라는 내용과 찬반 의견을 다룬다. 아직 표결 전이며, 승인되면 내년 4월에 시행된다."},{"q":"According to the article, why do some hotel owners favor the limit?","choices":["Their hotels are fully booked in summer.","Crowds may discourage visitors who spend more.","Cruise lines compete with them for guests.","Cruise passengers often complain about hotel prices."],"answer":1,"type":"세부 사항","explanation":"셋째 단락에서 일부 호텔 주인은 혼잡이 1인당 훨씬 많이 쓰는 숙박객을 멀어지게 한다고 말했다. 크루즈 승객의 불만이나 만실, 크루즈 회사와의 경쟁은 언급되지 않았다."},{"q":"What does Mr. Ferrante suggest about the 2025 study?","choices":["It has not been published yet.","It was conducted by the town council.","It exaggerated the number of cruise passengers.","It underestimated how much cruise passengers spend."],"answer":3,"type":"연계 문제","explanation":"기사에 따르면 이 연구는 크루즈 승객이 하루 평균 38유로를 쓴다고 했다. 페란테 씨는 이 연구가 승객들이 현지 업체를 통해 예약하는 60유로 이상의 관광 상품을 계산에 넣지 않았다고 했으므로, 크루즈 승객의 지출을 실제보다 적게 잡았다는 뜻이다. 연구 주체는 지역 관광청이다."},{"q":"What is indicated about Mr. Ferrante?","choices":["He agrees with the council member who wrote the proposal.","He owns a hotel near the harbor.","He was quoted in the April 9 article.","He opposes any limit on cruise ships."],"answer":0,"type":"연계 문제","explanation":"편지에서 페란테 씨는 제안을 지지한다(I support the proposal)고 했고, 기사에 따르면 이 제안을 작성한 사람은 의원 일제 브란트이다. 따라서 그는 브란트 의원과 같은 입장이다. 그는 호텔이 아니라 자전거 투어 업체를 운영한다."},{"q":"In the article, the word “absorb” in paragraph 2 is closest in meaning to","choices":["understand","purchase","accommodate","soak"],"answer":2,"type":"동의어","explanation":"'cannot absorb the 15,000 passengers'는 인구 11,000명의 구도심이 15,000명의 승객을 '수용할' 수 없다는 뜻이므로 'accommodate'가 가장 가깝다. soak(흡수하다)는 액체에, understand(이해하다)는 정보에 쓰는 뜻이다."}],"translation":"[기사]\n해안 마을, 크루즈선 제한 검토\n\n포트 아벨린, 4월 9일 — 포트 아벨린 마을 의회는 항구에 정박할 수 있는 크루즈선 수를 여름 성수기 최대 5척에서 하루 2척으로 제한하는 안건을 다음 달 표결에 부친다.\n\n찬성 측은 인구가 11,000명에 불과한 역사 지구가 하루에 많게는 15,000명씩 도착하는 승객을 수용할 수 없다고 주장한다. 이 안건을 작성한 일제 브란트 의원은 \"붐비는 날에는 주민들이 약국이나 우체국에도 갈 수 없다\"고 말했다.\n\n업주들의 의견은 엇갈린다. 항구 근처의 식당과 기념품 가게는 크루즈 관광객에 크게 의존하는 반면, 몇몇 호텔 주인은 혼잡 때문에 1인당 훨씬 많은 돈을 쓰는 숙박객이 오지 않는다고 말한다. 지역 관광청의 2025년 연구에 따르면 포트 아벨린에서 숙박 관광객은 하루 평균 210유로를 쓰는 데 비해 크루즈 승객은 38유로를 쓴다.\n\n승인되면 이 제한은 내년 4월부터 시행되며, 크루즈 회사들은 한 시즌 동안 일정을 조정할 시간을 갖게 된다.\n\n[편지]\n포트 아벨린 가제트 편집자께 / 보낸 사람: 마테오 페란테 / 날짜: 4월 14일\n\n크루즈 제한안에 관한 4월 9일 자 기사는 수치를 공정하게 제시했지만, 중요한 점을 빠뜨렸습니다. 저는 페란테 자전거 투어의 주인으로서 두 부류의 관광객을 모두 상대하는데, 지출 차이는 보이는 것보다 작다고 말씀드릴 수 있습니다. 기자가 인용한 연구는 크루즈 승객이 저희 같은 현지 업체를 통해 예약하는 육상 관광을 계산에 넣지 않았는데, 이 상품은 대개 60유로 이상입니다.\n\n그렇긴 해도 저는 이 안건을 지지합니다. 크루즈선이 5척 들어오는 날에는 투어가 너무 붐벼 질이 떨어지고, 단골손님들이 발길을 끊습니다. 합리적인 제한은 장기적으로 마을에 이로울 것입니다.","part":7},{"id":"p7-070","level":5,"kind":"triple","passages":[{"doc_type":"강좌 안내","title":"Corvell Professional Institute — Project Management Certificate Courses (Autumn)","text":"Course | Format | Dates | Fee\nPM 101: Foundations of Project Management | In person (Dublin) | Sept 8–10 | €950\nPM 205: Agile Methods in Practice | Online (live) | Sept 22–25 | €780\nPM 310: Risk and Budget Control | In person (Dublin) | Oct 13–15 | €1,100\nPM 420: Leading Complex Programs | In person (Cork) | Nov 3–5 | €1,250\n\n- PM 101 is a prerequisite for all other courses unless the participant holds an equivalent qualification.\n- Organizations enrolling three or more employees in the same course receive a 15% discount on that course.\n- Cancellations made more than 21 days before a course begins receive a full refund; later cancellations receive a 50% refund.\n- Group registrations can be made by e-mail at registrar@corvell.ie."},{"doc_type":"이메일","title":"From: Beatriz Almeida, HR Manager, Solenne Energy / To: registrar@corvell.ie / Date: August 20 / Subject: Group registration","text":"Dear Registrar,\n\nI would like to register four of our engineers for PM 310 in October. All four completed PM 101 at your institute last spring. In addition, our operations director, Owen Gallagher, wishes to take PM 420. Although he has not taken PM 101, he holds a PMP certification, which I understand your institute accepts in its place.\n\nPlease send a single invoice for all five registrations to my attention.\n\nKind regards,\nBeatriz Almeida"},{"doc_type":"청구서","title":"Invoice #CPI-7734 — Corvell Professional Institute","text":"Bill to: Solenne Energy, Attn: Beatriz Almeida\nDate: August 22\n\nPM 310 x 4 participants @ €1,100 | €4,400.00\nGroup discount (15%) | -€660.00\nPM 420 x 1 participant @ €1,250 | €1,250.00\nTotal | €4,990.00\n\nCourse materials are included in the fees.\n\nPayment due by September 30. Payment may be made by bank transfer or company credit card; please quote the invoice number. Participants will receive joining instructions two weeks before each course begins. Thank you for choosing Corvell Professional Institute."}],"questions":[{"q":"Why is Mr. Gallagher allowed to enroll in PM 420?","choices":["He completed PM 101 last spring.","PM 420 has no prerequisites.","He is registering together with his engineers.","He holds a qualification that replaces the required course."],"answer":3,"type":"연계 문제","explanation":"강좌 안내에 따르면 PM 101은 동등한 자격이 없는 한 다른 모든 과정의 선수 과목이다. 이메일에서 갤러거 씨는 PM 101을 듣지 않았지만 연구소가 대신 인정하는 PMP 자격증이 있다고 했다. PM 101을 들은 사람은 엔지니어 네 명이다."},{"q":"Why was a discount applied to the invoice?","choices":["The registration was made more than 21 days in advance.","Three or more employees are taking the same course.","Mr. Gallagher holds a PMP certification.","Solenne Energy is a new client."],"answer":1,"type":"연계 문제","explanation":"강좌 안내는 같은 과정에 직원 3명 이상을 등록하면 해당 과정을 15% 할인한다고 했다. 이메일에서 엔지니어 4명을 PM 310에 등록했고, 청구서에서도 PM 310에만 15% 할인(660유로)이 적용되었다. PM 420에는 할인이 없다."},{"q":"What is suggested about the engineers?","choices":["They have not met the prerequisite for PM 310.","They will take their next course online.","They have previously attended classes in Dublin.","They will travel to Cork in November."],"answer":2,"type":"추론","explanation":"이메일에서 엔지니어 네 명이 지난봄 PM 101을 수료했다고 했고, 강좌 안내에서 PM 101은 더블린 대면 과정이다. 따라서 더블린에서 수업을 들은 적이 있다고 추론할 수 있다. 다음 과정인 PM 310도 더블린 대면 수업이며, 코크는 갤러거 씨가 갈 곳이다."},{"q":"If one of the engineers cancels on October 1, what will Solenne Energy most likely receive for that registration?","choices":["A refund of half the fee","No refund","A credit for a future course","A full refund"],"answer":0,"type":"추론","explanation":"PM 310은 10월 13일에 시작하므로 10월 1일 취소는 시작 12일 전이다. 강좌 안내에 따르면 21일 이내에 취소하면 50% 환불이므로 수강료의 절반을 돌려받게 된다. 다음 과정 적립금은 언급되지 않았다."},{"q":"In the course information, the word “equivalent” in the first note is closest in meaning to","choices":["earlier","additional","official","comparable"],"answer":3,"type":"동의어","explanation":"'an equivalent qualification'은 PM 101과 '동등한, 맞먹는' 자격을 뜻하므로 'comparable'이 가장 가깝다. additional(추가의), official(공식의), earlier(이전의)는 동등하다는 뜻이 없다."}],"translation":"[강좌 안내]\n코벨 전문 교육원 — 프로젝트 관리 자격 과정 (가을)\n\n과정 | 형식 | 일정 | 수강료\nPM 101: 프로젝트 관리 기초 | 대면 (더블린) | 9월 8~10일 | 950유로\nPM 205: 애자일 방법론 실무 | 온라인 (실시간) | 9월 22~25일 | 780유로\nPM 310: 위험 및 예산 관리 | 대면 (더블린) | 10월 13~15일 | 1,100유로\nPM 420: 복합 프로그램 리더십 | 대면 (코크) | 11월 3~5일 | 1,250유로\n\n- PM 101은 동등한 자격을 갖추지 않은 한 다른 모든 과정의 선수 과목입니다.\n- 같은 과정에 직원 3명 이상을 등록하는 기관은 해당 과정 수강료를 15% 할인받습니다.\n- 과정 시작 21일 전보다 일찍 취소하면 전액 환불되며, 그 이후 취소는 50% 환불됩니다.\n- 단체 등록은 registrar@corvell.ie로 이메일을 보내 하실 수 있습니다.\n\n[이메일]\n발신: 베아트리스 알메이다, 솔렌 에너지 인사 담당 매니저 / 수신: registrar@corvell.ie / 날짜: 8월 20일 / 제목: 단체 등록\n\n학적 담당자께,\n\n저희 엔지니어 4명을 10월 PM 310 과정에 등록하고 싶습니다. 4명 모두 지난봄 귀 교육원에서 PM 101을 수료했습니다. 또한 저희 운영 이사 오언 갤러거 씨가 PM 420을 수강하고자 합니다. 그는 PM 101을 듣지 않았지만, 귀 교육원이 이를 대신해 인정하는 것으로 알고 있는 PMP 자격증을 보유하고 있습니다.\n\n5명의 등록에 대해 청구서 한 장으로 제 앞으로 보내 주십시오.\n\n베아트리스 알메이다 드림\n\n[청구서]\n청구서 #CPI-7734 — 코벨 전문 교육원\n청구 대상: 솔렌 에너지, 베아트리스 알메이다 앞\n날짜: 8월 22일\n\nPM 310 수강생 4명 x 1,100유로 | 4,400.00유로\n단체 할인 (15%) | -660.00유로\nPM 420 수강생 1명 x 1,250유로 | 1,250.00유로\n합계 | 4,990.00유로\n\n수강료에는 교재가 포함되어 있습니다.\n\n결제 기한: 9월 30일. 계좌 이체나 법인 신용카드로 결제할 수 있으며, 청구서 번호를 기재해 주십시오. 수강생은 각 과정 시작 2주 전에 참가 안내를 받게 됩니다. 코벨 전문 교육원을 선택해 주셔서 감사합니다.","part":7},{"id":"p7-071","level":1,"kind":"single","passages":[{"doc_type":"공지","title":"Notice — Kitchen Refrigerator Cleaning","text":"NOTICE: KITCHEN REFRIGERATOR CLEANING\n\nThe refrigerator in the third-floor kitchen will be cleaned this Friday, May 16. [1] Please take home any food or drinks you want to keep by 5:00 P.M. on Thursday. All items left in the refrigerator after that time will be thrown away. [2] The cleaning staff will wash the shelves and the door on Friday morning. [3] The refrigerator will be ready to use again at 1:00 P.M. on Friday. [4]\n\nThank you for helping us keep the kitchen clean!\n\n— Office Services Team"}],"questions":[{"q":"What is the notice mainly about?","choices":["A refrigerator will be cleaned.","A new kitchen will open.","Lunch will be served on Friday.","The third floor will be closed."],"answer":0,"type":"주제·목적","explanation":"첫 문장 'The refrigerator in the third-floor kitchen will be cleaned this Friday'에서 냉장고 청소를 알리는 공지임을 알 수 있다. 새 주방 개장, 점심 제공, 3층 폐쇄는 언급되지 않았다."},{"q":"When can employees use the refrigerator again?","choices":["On Thursday at 5:00 P.M.","On Friday morning","On Friday at 1:00 P.M.","On Monday morning"],"answer":2,"type":"세부 사항","explanation":"'The refrigerator will be ready to use again at 1:00 P.M. on Friday.'에서 금요일 오후 1시부터 다시 쓸 수 있다. 목요일 오후 5시는 음식을 가져가야 하는 마감 시간이고, 금요일 오전에는 청소를 한다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? “This includes items that are still unopened.”","choices":["[1]","[2]","[3]","[4]"],"answer":1,"type":"문장 삽입","explanation":"주어진 문장의 'This(이것)'는 '그 시간 이후 냉장고에 남은 모든 물건은 버려진다'는 내용을 가리키며, 뜯지 않은 물건도 포함된다는 보충 설명이다. 따라서 그 문장 바로 뒤인 [2]가 알맞다. [3], [4]는 청소와 재사용 시간 이야기 뒤라 어울리지 않는다."}],"translation":"[공지]\n공지: 주방 냉장고 청소\n\n3층 주방의 냉장고를 이번 주 금요일, 5월 16일에 청소합니다. 보관하고 싶은 음식이나 음료는 목요일 오후 5시까지 집으로 가져가 주세요. 그 시간 이후 냉장고에 남아 있는 모든 물품은 버려집니다. (이는 아직 뜯지 않은 물품도 포함합니다.) 청소 직원이 금요일 오전에 선반과 문을 닦을 예정입니다. 냉장고는 금요일 오후 1시에 다시 사용할 수 있습니다.\n\n주방을 깨끗하게 유지하는 데 협조해 주셔서 감사합니다!\n\n— 사무 지원팀","part":7},{"id":"p7-072","level":1,"kind":"single","passages":[{"doc_type":"문자 메시지","title":"Text-message chain","text":"Jenny Morales (8:40 A.M.): Hi, Daniel. I left my ID badge at home. Can you let me in through the side door?\nDaniel Kwon (8:41 A.M.): Sure. When will you get here?\nJenny Morales (8:42 A.M.): In about ten minutes. I'm on the bus now.\nDaniel Kwon (8:43 A.M.): OK. I have a meeting at 9:00, though.\nJenny Morales (8:44 A.M.): That's fine. I'll be there before then.\nDaniel Kwon (8:52 A.M.): I'm at the side door now.\nJenny Morales (8:53 A.M.): Great, I can see you. Later, I'll ask the front desk for a visitor pass for today."}],"questions":[{"q":"Why did Ms. Morales contact Mr. Kwon?","choices":["She will miss the meeting.","She lost her bus ticket.","She wants to borrow his badge.","She needs help getting into the building."],"answer":3,"type":"주제·목적","explanation":"8시 40분 메시지에서 신분증을 집에 두고 와서 옆문으로 들여보내 달라고(let me in through the side door) 했다. 버스표 분실이나 배지를 빌리는 이야기는 없다."},{"q":"At 8:44 A.M., what does Ms. Morales mean when she writes, “That's fine”?","choices":["She can wait until the meeting ends.","She will arrive before Mr. Kwon's meeting.","She does not need to use the side door.","She will join the meeting at 9:00."],"answer":1,"type":"의도 파악","explanation":"권 씨가 9시에 회의가 있다고 하자 'That's fine'이라고 한 뒤 'I'll be there before then(그 전에 도착할게요)'이라고 했다. 즉 회의 전에 도착하니 문제없다는 뜻이다. 회의가 끝날 때까지 기다리겠다는 뜻이 아니다."},{"q":"What will Ms. Morales most likely do later?","choices":["Get a visitor pass","Go back home","Take a different bus","Call the security company"],"answer":0,"type":"추론","explanation":"8시 53분에 'I'll ask the front desk for a visitor pass for today'라고 했으므로 나중에 방문객 출입증을 받을 것이다. 집에 돌아가거나 다른 버스를 탄다는 말은 없다."}],"translation":"[문자 메시지]\n제니 모랄레스 (오전 8:40): 안녕하세요, 대니얼. 사원증을 집에 두고 왔어요. 옆문으로 들여보내 줄 수 있어요?\n대니얼 권 (오전 8:41): 물론이죠. 언제 도착해요?\n제니 모랄레스 (오전 8:42): 10분쯤 후에요. 지금 버스 안이에요.\n대니얼 권 (오전 8:43): 알겠어요. 그런데 저 9시에 회의가 있어요.\n제니 모랄레스 (오전 8:44): 괜찮아요. 그 전에 도착할 거예요.\n대니얼 권 (오전 8:52): 지금 옆문에 와 있어요.\n제니 모랄레스 (오전 8:53): 좋아요, 보이네요. 이따가 안내 데스크에 오늘 쓸 방문객 출입증을 요청할게요.","part":7},{"id":"p7-073","level":1,"kind":"single","passages":[{"doc_type":"광고","title":"Fresh Press Dry Cleaning — Grand Opening","text":"FRESH PRESS DRY CLEANING — GRAND OPENING!\n\nFresh Press is now open at 27 Oak Street, next to Central Station.\n\n• Shirts: $3 each\n• Suits: $12 each\n• Same-day service: Bring your clothes before 9:00 A.M. and pick them up after 5:00 P.M.\n• Free delivery to offices in the downtown area on orders over $30\n\nOpen Monday to Saturday, 7:00 A.M. to 8:00 P.M.\n\nGrand opening special: Get 10% off your first order this month. Just show this ad!"}],"questions":[{"q":"Where is Fresh Press located?","choices":["Inside an office building","Across from a shopping mall","Next to a train station","Near a hotel"],"answer":2,"type":"세부 사항","explanation":"'27 Oak Street, next to Central Station'에서 중앙역 옆에 있음을 알 수 있다. 사무실 건물, 쇼핑몰, 호텔은 언급되지 않았다."},{"q":"What is NOT true about Fresh Press?","choices":["It is closed on Sundays.","It delivers all orders for free.","It can clean clothes in one day.","It charges $3 to clean a shirt."],"answer":1,"type":"사실 확인(NOT/TRUE)","explanation":"무료 배달은 시내 사무실로 가는 30달러 초과 주문에만 해당하므로 '모든 주문을 무료 배달한다'는 사실이 아니다. 월~토요일 영업(일요일 휴무), 당일 서비스, 셔츠 3달러는 모두 광고에 나온다."},{"q":"How can customers get a discount?","choices":["By ordering online","By bringing five shirts","By visiting before 9:00 A.M.","By showing the advertisement"],"answer":3,"type":"세부 사항","explanation":"마지막 줄 'Get 10% off your first order this month. Just show this ad!'에서 광고를 보여 주면 할인받는다. 오전 9시 전 방문은 당일 서비스 조건이다."}],"translation":"[광고]\n프레시 프레스 세탁소 — 개업!\n\n프레시 프레스가 중앙역 옆 오크가 27번지에 문을 열었습니다.\n\n• 셔츠: 한 벌당 3달러\n• 정장: 한 벌당 12달러\n• 당일 서비스: 오전 9시 전에 옷을 맡기시면 오후 5시 이후에 찾아가실 수 있습니다.\n• 30달러 초과 주문 시 시내 사무실로 무료 배달\n\n영업시간: 월요일~토요일, 오전 7시~오후 8시\n\n개업 특가: 이번 달 첫 주문 10% 할인. 이 광고를 보여 주기만 하세요!","part":7},{"id":"p7-074","level":1,"kind":"single","passages":[{"doc_type":"양식","title":"Meeting Room Request Form — Linwood Accounting","text":"MEETING ROOM REQUEST FORM — Linwood Accounting\n\nName: Priya Shah\nDepartment: Payroll\nDate of meeting: Tuesday, June 3\nTime: 2:00 P.M. – 3:30 P.M.\nNumber of people: 12\n\nRoom requested:\n☐ Room A (up to 6 people)\n☑ Room B (up to 15 people)\n☐ Room C (up to 30 people)\n\nEquipment needed: ☑ Projector ☐ Microphone ☑ Whiteboard\nFood and drinks: Coffee and water for 12 people\n\nNotes: We will be training new staff on the updated payroll software. Please set up the room 15 minutes early.\n\nSubmit this form to the front desk at least two days before the meeting."}],"questions":[{"q":"What is the purpose of Ms. Shah's meeting?","choices":["To train new employees","To interview job applicants","To plan a company party","To buy new software"],"answer":0,"type":"주제·목적","explanation":"Notes의 'We will be training new staff on the updated payroll software'에서 신입 직원 교육이 목적임을 알 수 있다. 소프트웨어는 이미 업데이트된 것을 교육하는 것이지 새로 사는 것이 아니다."},{"q":"How many people can Room B hold?","choices":["6","12","15","30"],"answer":2,"type":"세부 사항","explanation":"'Room B (up to 15 people)'에서 최대 15명이다. 12는 회의 참석 인원이고, 6과 30은 A실과 C실의 인원이다."},{"q":"What did Ms. Shah NOT request?","choices":["A projector","A whiteboard","Coffee","A microphone"],"answer":3,"type":"사실 확인(NOT/TRUE)","explanation":"장비 칸에서 프로젝터와 화이트보드에는 체크했지만 마이크(☐ Microphone)에는 체크하지 않았다. 커피와 물은 음료 칸에서 요청했다."}],"translation":"[양식]\n회의실 사용 신청서 — 린우드 회계법인\n\n이름: 프리야 샤\n부서: 급여팀\n회의 날짜: 6월 3일 화요일\n시간: 오후 2시~3시 30분\n인원: 12명\n\n신청 회의실:\n☐ A실 (최대 6명)\n☑ B실 (최대 15명)\n☐ C실 (최대 30명)\n\n필요 장비: ☑ 프로젝터 ☐ 마이크 ☑ 화이트보드\n음식 및 음료: 12명분 커피와 물\n\n비고: 업데이트된 급여 소프트웨어 사용법을 신입 직원들에게 교육할 예정입니다. 회의실을 15분 일찍 준비해 주세요.\n\n이 신청서는 회의 최소 이틀 전까지 안내 데스크에 제출하십시오.","part":7},{"id":"p7-075","level":1,"kind":"double","passages":[{"doc_type":"웹페이지","title":"www.quickcopycenter.com/prices","text":"QUICKCOPY CENTER — PRICE LIST\n\nBlack-and-white copies: $0.10 per page\nColor copies: $0.50 per page\nPoster printing (large size): $15 each\nBinding (plastic cover): $4 per book\n\n• Orders over $50 receive free delivery within the city.\n• Orders are usually ready in 24 hours.\n• Rush service (ready in 3 hours) costs an extra $10."},{"doc_type":"이메일","title":"From: Mark Ellison / To: orders@quickcopycenter.com / Date: April 2 / Subject: Order for Friday","text":"Hello,\n\nI would like to order 5 posters for our company's open house on Saturday. I also need 100 color copies of our new brochure. Could you please deliver everything to our office at 45 River Road? We need the items by Friday afternoon.\n\nI will send the files in a separate e-mail within an hour.\n\nThank you,\nMark Ellison\nBellmont Design"}],"questions":[{"q":"Why did Mr. Ellison write the e-mail?","choices":["To ask about a job","To place an order","To complain about a delivery","To change an address"],"answer":1,"type":"주제·목적","explanation":"이메일 첫 문장 'I would like to order 5 posters ...'에서 주문을 하려고 쓴 것임을 알 수 있다. 배달 불만이나 주소 변경은 언급되지 않았다."},{"q":"Why does Mr. Ellison need the posters?","choices":["For a store opening","For a job fair","For a training class","For an open house"],"answer":3,"type":"세부 사항","explanation":"'5 posters for our company's open house on Saturday'에서 토요일 회사 오픈 하우스용임을 알 수 있다."},{"q":"How much will Mr. Ellison's order most likely cost?","choices":["$80","$100","$115","$125"],"answer":3,"type":"연계 문제","explanation":"가격표에서 포스터는 장당 15달러, 컬러 복사는 장당 0.5달러이다. 이메일의 주문은 포스터 5장(75달러)과 컬러 복사 100장(50달러)이므로 합계 125달러이다. 80달러나 115달러는 계산이 맞지 않는다."},{"q":"What is true about Mr. Ellison's order?","choices":["It will be delivered for free.","It will need rush service.","It will be ready in three hours.","It will be picked up at the store."],"answer":0,"type":"연계 문제","explanation":"가격표에 50달러가 넘는 주문은 시내 무료 배달이라고 했고, 주문 금액이 125달러이며 이메일에서 사무실로 배달해 달라고 했으므로 무료로 배달된다. 4월 2일 주문에 금요일까지 받으면 되므로 급행 서비스는 필요 없다."},{"q":"What will Mr. Ellison send later?","choices":["A payment","A map","Some files","A price list"],"answer":2,"type":"세부 사항","explanation":"'I will send the files in a separate e-mail within an hour.'에서 한 시간 안에 파일을 따로 보내겠다고 했다. 결제나 지도 이야기는 없다."}],"translation":"[웹페이지]\n퀵카피 센터 — 가격표\n\n흑백 복사: 장당 0.10달러\n컬러 복사: 장당 0.50달러\n포스터 인쇄(대형): 장당 15달러\n제본(플라스틱 표지): 권당 4달러\n\n• 50달러 초과 주문은 시내 무료 배달됩니다.\n• 주문은 보통 24시간 안에 준비됩니다.\n• 급행 서비스(3시간 안에 준비)는 10달러가 추가됩니다.\n\n[이메일]\n보낸 사람: 마크 엘리슨 / 받는 사람: orders@quickcopycenter.com / 날짜: 4월 2일 / 제목: 금요일 주문\n\n안녕하세요,\n\n토요일에 있을 저희 회사 오픈 하우스용 포스터 5장을 주문하고 싶습니다. 새 안내 책자 컬러 복사본 100부도 필요합니다. 모두 리버 로드 45번지에 있는 저희 사무실로 배달해 주시겠어요? 금요일 오후까지 받아야 합니다.\n\n파일은 한 시간 안에 별도 이메일로 보내겠습니다.\n\n감사합니다.\n마크 엘리슨\n벨몬트 디자인","part":7},{"id":"p7-076","level":1,"kind":"double","passages":[{"doc_type":"공지","title":"Greenway Company Volunteer Day","text":"GREENWAY COMPANY VOLUNTEER DAY\n\nJoin us for Greenway's Volunteer Day on Saturday, October 4!\n\nThis year, we will help clean up Lakeside Park. Work will start at 9:00 A.M. and finish at 1:00 P.M. Gloves, bags, and tools will be provided. Lunch will be served in the park's picnic area after the work.\n\nEach volunteer will receive a free Greenway T-shirt. Please wear comfortable shoes.\n\nTo sign up, e-mail Ben Harper in Human Resources by September 26. Tell him your T-shirt size (S, M, L, or XL)."},{"doc_type":"이메일","title":"From: Olivia Grant / To: Ben Harper / Date: September 24 / Subject: Volunteer Day","text":"Hi Ben,\n\nI'd like to sign up for Volunteer Day. My T-shirt size is medium.\n\nMy husband would also like to help. He doesn't work for Greenway, but he loves being outdoors. Is it OK if he comes too? If so, he needs a large shirt.\n\nAlso, I have to leave at noon for a family event, so I won't be able to stay for lunch.\n\nThanks,\nOlivia"}],"questions":[{"q":"What will volunteers do on October 4?","choices":["Plant trees","Paint a building","Clean a park","Serve lunch"],"answer":2,"type":"세부 사항","explanation":"공지의 'we will help clean up Lakeside Park'에서 공원 청소를 한다는 것을 알 수 있다. 점심은 봉사자에게 제공되는 것이지 봉사자가 대접하는 것이 아니다."},{"q":"What will NOT be provided to volunteers?","choices":["Gloves","Lunch","A T-shirt","Shoes"],"answer":3,"type":"사실 확인(NOT/TRUE)","explanation":"공지에 장갑·봉투·도구, 점심, 티셔츠는 제공된다고 했지만 신발은 '편한 신발을 신고 오라(Please wear comfortable shoes)'고만 했으므로 제공되지 않는다."},{"q":"What does Ms. Grant ask about?","choices":["Whether her husband can join","Where the park is","What time lunch starts","How to get a bigger shirt"],"answer":0,"type":"세부 사항","explanation":"이메일에서 남편이 그린웨이 직원은 아니지만 함께 와도 되는지(Is it OK if he comes too?) 물었다. 공원 위치나 점심 시간은 묻지 않았다."},{"q":"What is true about Ms. Grant's e-mail?","choices":["It was sent to the wrong department.","It was sent before the deadline.","It did not include her shirt size.","It was sent after the event."],"answer":1,"type":"연계 문제","explanation":"공지는 9월 26일까지 신청하라고 했고, 이메일 날짜는 9월 24일이므로 마감 전에 보낸 것이다. 인사부 벤 하퍼에게 보냈고, 티셔츠 사이즈(medium)도 적었다."},{"q":"How long will Ms. Grant most likely work at the event?","choices":["One hour","Two hours","Three hours","Four hours"],"answer":2,"type":"연계 문제","explanation":"공지에 작업은 오전 9시에 시작한다고 했고, 이메일에서 그랜트 씨는 정오에 떠나야 한다고 했으므로 9시부터 12시까지 3시간 일할 것이다. 4시간은 행사 전체 작업 시간이다."}],"translation":"[공지]\n그린웨이 사 봉사의 날\n\n10월 4일 토요일, 그린웨이 봉사의 날에 함께하세요!\n\n올해는 레이크사이드 공원 청소를 돕습니다. 작업은 오전 9시에 시작해 오후 1시에 끝납니다. 장갑, 봉투, 도구가 제공됩니다. 작업 후 공원 피크닉 구역에서 점심이 제공됩니다.\n\n봉사자 전원에게 그린웨이 티셔츠를 무료로 드립니다. 편한 신발을 신고 오세요.\n\n신청하려면 9월 26일까지 인사부의 벤 하퍼에게 이메일을 보내 주세요. 티셔츠 사이즈(S, M, L, XL)를 알려 주세요.\n\n[이메일]\n보낸 사람: 올리비아 그랜트 / 받는 사람: 벤 하퍼 / 날짜: 9월 24일 / 제목: 봉사의 날\n\n안녕하세요, 벤.\n\n봉사의 날에 신청하고 싶어요. 제 티셔츠 사이즈는 M입니다.\n\n제 남편도 돕고 싶어 해요. 그린웨이 직원은 아니지만 야외 활동을 아주 좋아해요. 같이 가도 괜찮을까요? 괜찮다면 남편은 L 사이즈 셔츠가 필요해요.\n\n그리고 가족 행사 때문에 정오에 떠나야 해서 점심까지는 있을 수 없어요.\n\n고마워요.\n올리비아","part":7},{"id":"p7-077","level":1,"kind":"double","passages":[{"doc_type":"견적서","title":"Swift Movers — Moving Estimate","text":"SWIFT MOVERS — MOVING ESTIMATE\n\nCustomer: Harris Law Office\nMoving date: Saturday, July 12\nFrom: 200 King Street, 5th floor\nTo: 88 Pine Avenue, 2nd floor\n\nService | Cost\nTruck and 3 movers (6 hours) | $900\nFurniture wrapping | $150\nPacking boxes (50) | $100\nTotal | $1,150\n\nNotes:\n• Work on Sundays costs 20% more.\n• A $200 deposit is required to confirm the moving date."},{"doc_type":"이메일","title":"From: Rachel Harris / To: Swift Movers / Date: June 30 / Subject: Moving estimate","text":"Hello,\n\nThank you for the estimate. Unfortunately, the manager of our new building told us that moving is not allowed there on Saturdays. Could we change the date to Sunday, July 13? I understand that the price will be higher.\n\nAlso, we will pack everything ourselves, so we do not need the packing boxes.\n\nI will send the deposit after I hear from you.\n\nRachel Harris\nHarris Law Office"}],"questions":[{"q":"What is the main purpose of the e-mail?","choices":["To cancel a move","To change a moving date","To ask for more boxes","To hire more movers"],"answer":1,"type":"주제·목적","explanation":"'Could we change the date to Sunday, July 13?'에서 이사 날짜를 바꾸려는 것이 목적임을 알 수 있다. 상자는 오히려 필요 없다고 했다."},{"q":"Why can Harris Law Office NOT move on July 12?","choices":["Its new building does not allow it.","The movers are busy that day.","The office will be open that day.","The truck is too small."],"answer":0,"type":"세부 사항","explanation":"이메일에서 새 건물 관리인이 토요일에는 이사를 허용하지 않는다고 했다. 견적서에서 7월 12일은 토요일이다."},{"q":"Why will the new price most likely be higher?","choices":["The office has more furniture.","The move will take more than six hours.","The move will happen on a Sunday.","The new office is on a higher floor."],"answer":2,"type":"연계 문제","explanation":"견적서에 일요일 작업은 20% 더 비싸다고 했고, 이메일에서 7월 13일 일요일로 날짜를 바꾸고 싶다며 가격이 오를 것을 안다고 했다. 새 사무실은 2층으로 오히려 더 낮다."},{"q":"Which service does Ms. Harris say she no longer needs?","choices":["Truck and movers","Furniture wrapping","Weekend work","Packing boxes"],"answer":3,"type":"연계 문제","explanation":"이메일에서 직접 짐을 싸서 포장 상자가 필요 없다고 했으므로, 견적서의 'Packing boxes (50) | $100' 항목이 빠진다. 가구 포장이나 트럭 서비스는 그대로이다."},{"q":"How much will Ms. Harris send to confirm the date?","choices":["$100","$150","$200","$1,150"],"answer":2,"type":"세부 사항","explanation":"견적서에 날짜를 확정하려면 200달러 보증금이 필요하다고 했고, 해리스 씨는 답을 받은 뒤 보증금을 보내겠다고 했다. 1,150달러는 원래 견적 총액이다."}],"translation":"[견적서]\n스위프트 무버스 — 이사 견적서\n\n고객: 해리스 법률사무소\n이사 날짜: 7월 12일 토요일\n출발지: 킹가 200번지 5층\n도착지: 파인 애비뉴 88번지 2층\n\n서비스 | 비용\n트럭 및 이사 인부 3명 (6시간) | 900달러\n가구 포장 | 150달러\n포장 상자 (50개) | 100달러\n합계 | 1,150달러\n\n참고:\n• 일요일 작업은 20% 추가 요금이 붙습니다.\n• 이사 날짜를 확정하려면 보증금 200달러가 필요합니다.\n\n[이메일]\n보낸 사람: 레이철 해리스 / 받는 사람: 스위프트 무버스 / 날짜: 6월 30일 / 제목: 이사 견적\n\n안녕하세요,\n\n견적서 감사합니다. 안타깝게도 새 건물 관리인이 토요일에는 그곳에서 이사할 수 없다고 합니다. 날짜를 7월 13일 일요일로 바꿀 수 있을까요? 가격이 더 올라간다는 것은 알고 있습니다.\n\n또한 짐은 저희가 직접 쌀 예정이라 포장 상자는 필요 없습니다.\n\n답을 받은 뒤 보증금을 보내겠습니다.\n\n레이철 해리스\n해리스 법률사무소","part":7},{"id":"p7-078","level":1,"kind":"triple","passages":[{"doc_type":"광고","title":"Harbor Kitchen Cooking Classes — Summer","text":"HARBOR KITCHEN COOKING CLASSES — SUMMER\n\nLearn to cook with Chef Lina Park!\n\nClass | Day | Time | Price (per person)\nEasy Pasta | Monday | 6:00–8:00 P.M. | $40\nKorean Home Cooking | Wednesday | 6:00–8:00 P.M. | $45\nBaking Bread | Saturday | 10:00 A.M.–12:00 P.M. | $50\n\nAll ingredients are included. Each class is limited to 10 students.\nSign up online at www.harborkitchen.com."},{"doc_type":"신청서","title":"Harbor Kitchen — Online Registration Form","text":"HARBOR KITCHEN — ONLINE REGISTRATION FORM\n\nName: Tom Becker\nE-mail: tbecker@mailbox.com\nClass: Baking Bread\nPreferred date: June 14\nNumber of people: 2\nPayment: Credit card (paid in full)\nComments: My sister and I are both beginners. Is that OK?"},{"doc_type":"이메일","title":"From: Lina Park / To: Tom Becker / Subject: Your registration","text":"Dear Mr. Becker,\n\nThank you for signing up for my class. Beginners are always welcome! Please arrive 10 minutes early. Aprons will be provided, but you may bring your own if you like. You can take home all the bread you make.\n\nUnfortunately, the class on June 14 is now full. I have put you and your sister in the class on June 21 instead. If this date doesn't work for you, please let me know.\n\nSee you soon,\nLina Park"}],"questions":[{"q":"What is included in the price of each class?","choices":["Ingredients","A cookbook","Aprons to keep","Dinner"],"answer":0,"type":"세부 사항","explanation":"광고의 'All ingredients are included.'에서 재료가 포함되어 있다. 앞치마는 수업 중에 빌려주는 것이지 가져가는 것이 아니며, 요리책은 언급되지 않았다."},{"q":"How much did Mr. Becker most likely pay?","choices":["$50","$80","$90","$100"],"answer":3,"type":"연계 문제","explanation":"신청서에서 빵 굽기 수업에 2명을 신청해 전액 결제했고, 광고에서 빵 굽기 수업은 1인당 50달러이므로 50×2=100달러이다. 50달러는 한 사람 요금이다."},{"q":"At what time will Mr. Becker's class start?","choices":["At 6:00 P.M.","At 8:00 P.M.","At 10:00 A.M.","At 12:00 P.M."],"answer":2,"type":"연계 문제","explanation":"신청서에서 베커 씨는 빵 굽기(Baking Bread) 수업을 골랐고, 광고에 이 수업은 토요일 오전 10시~12시라고 나와 있다. 오후 6시는 파스타와 한식 수업 시간이다."},{"q":"Why was Mr. Becker's class date changed?","choices":["The chef was sick.","His first choice was full.","He asked for a later date.","The kitchen was closed."],"answer":1,"type":"세부 사항","explanation":"이메일의 'the class on June 14 is now full'에서 원래 원한 날짜가 마감되어 6월 21일로 옮겼음을 알 수 있다. 베커 씨가 날짜 변경을 요청한 것은 아니다."},{"q":"What does Ms. Park say students can do?","choices":["Take home the bread they make","Bring a friend for free","Pay at the door","Choose their own recipe"],"answer":0,"type":"세부 사항","explanation":"이메일의 'You can take home all the bread you make.'에서 만든 빵을 모두 가져갈 수 있다고 했다. 무료 동반이나 현장 결제는 언급되지 않았다."}],"translation":"[광고]\n하버 키친 요리 교실 — 여름\n\n리나 박 셰프와 함께 요리를 배우세요!\n\n수업 | 요일 | 시간 | 가격(1인)\n쉬운 파스타 | 월요일 | 오후 6~8시 | 40달러\n한국 가정식 | 수요일 | 오후 6~8시 | 45달러\n빵 굽기 | 토요일 | 오전 10시~낮 12시 | 50달러\n\n모든 재료가 포함되어 있습니다. 수업마다 정원은 10명입니다.\nwww.harborkitchen.com에서 온라인으로 신청하세요.\n\n[신청서]\n하버 키친 — 온라인 신청서\n\n이름: 톰 베커\n이메일: tbecker@mailbox.com\n수업: 빵 굽기\n희망 날짜: 6월 14일\n인원: 2명\n결제: 신용카드(전액 결제)\n요청 사항: 여동생과 저 모두 초보자입니다. 괜찮을까요?\n\n[이메일]\n보낸 사람: 리나 박 / 받는 사람: 톰 베커 / 제목: 수강 신청 건\n\n베커 씨께,\n\n제 수업에 신청해 주셔서 감사합니다. 초보자는 언제나 환영이에요! 10분 일찍 와 주세요. 앞치마는 제공되지만, 원하시면 직접 가져오셔도 됩니다. 만드신 빵은 모두 가져가실 수 있습니다.\n\n안타깝게도 6월 14일 수업은 이제 마감되었습니다. 대신 베커 씨와 여동생분을 6월 21일 수업에 등록해 두었습니다. 이 날짜가 맞지 않으시면 알려 주세요.\n\n곧 뵙겠습니다.\n리나 박","part":7},{"id":"p7-079","level":1,"kind":"triple","passages":[{"doc_type":"광고","title":"For Rent — 14 Elm Street, Unit 3B","text":"FOR RENT\n\nOne-bedroom apartment at 14 Elm Street, Unit 3B\n\n• Monthly rent: $950 (water included; electricity not included)\n• Available from August 1\n• Furnished with a bed, a desk, and a sofa\n• 5-minute walk to Park Street subway station\n• No pets\n\nContact: Sandra Lee, 555-0143, slee@elmhomes.com"},{"doc_type":"이메일","title":"From: Kevin Moore / To: Sandra Lee / Date: July 10 / Subject: Apartment on Elm Street","text":"Hello Ms. Lee,\n\nI saw your ad for the apartment on Elm Street. I am starting a new job downtown next month, and I will take the subway to work, so the location sounds perfect for me.\n\nI have a small cat. Would that be a problem?\n\nCould I see the apartment this week? I am free on Thursday or Friday after 6:00 P.M.\n\nBest regards,\nKevin Moore"},{"doc_type":"문자 메시지","title":"Text-message chain","text":"Sandra Lee (July 11, 9:15 A.M.): Hi, Kevin. This is Sandra Lee. I'm sorry, but I checked with the owner, and the answer is no.\nKevin Moore (9:20 A.M.): I understand. My parents can take care of my cat. I'd still like to see the apartment.\nSandra Lee (9:22 A.M.): Great. How about Friday at 6:30?\nKevin Moore (9:23 A.M.): Perfect. See you then."}],"questions":[{"q":"What is NOT included in the rent?","choices":["Water","Electricity","A bed","A sofa"],"answer":1,"type":"사실 확인(NOT/TRUE)","explanation":"광고에 'water included; electricity not included'라고 했으므로 전기료는 포함되지 않는다. 침대와 소파는 가구로 갖춰져 있다."},{"q":"Why does Mr. Moore think the location is good for him?","choices":["It is close to his parents' home.","It has a large parking lot.","It is near a subway station.","It is next to his new office."],"answer":2,"type":"연계 문제","explanation":"이메일에서 지하철로 출근할 것이라 위치가 좋다고 했고, 광고에 파크 스트리트 지하철역까지 걸어서 5분이라고 나와 있다. 새 사무실 바로 옆이라는 정보는 없다."},{"q":"Why did the owner most likely say no?","choices":["The apartment is not ready.","Mr. Moore wants to move in too early.","The rent is too low.","Pets are not allowed."],"answer":3,"type":"연계 문제","explanation":"이메일에서 무어 씨가 고양이를 키워도 되는지 물었고, 광고에는 'No pets(반려동물 금지)'라고 되어 있다. 문자에서 무어 씨가 고양이를 부모님께 맡기겠다고 답한 것도 이를 뒷받침한다."},{"q":"When will Mr. Moore see the apartment?","choices":["On Friday at 6:30 P.M.","On Thursday at 6:00 P.M.","On August 1","On Friday at 9:15 A.M."],"answer":0,"type":"세부 사항","explanation":"문자에서 리 씨가 금요일 6시 30분을 제안했고 무어 씨가 좋다고 했다. 8월 1일은 입주 가능 날짜이다."},{"q":"At 9:23 A.M., what does Mr. Moore mean when he writes, “Perfect”?","choices":["He likes the apartment very much.","The rent is acceptable to him.","The suggested time works for him.","His parents agreed to help him."],"answer":2,"type":"의도 파악","explanation":"리 씨가 'How about Friday at 6:30?'이라고 시간을 제안하자 'Perfect. See you then.'이라고 했으므로 제안한 시간이 좋다는 뜻이다. 아직 집을 보지 않았으므로 집이 마음에 든다는 뜻은 아니다."}],"translation":"[광고]\n임대\n\n엘름가 14번지 3B호 원룸(침실 1개) 아파트\n\n• 월세: 950달러 (수도료 포함, 전기료 별도)\n• 8월 1일부터 입주 가능\n• 침대, 책상, 소파 구비\n• 파크 스트리트 지하철역까지 도보 5분\n• 반려동물 불가\n\n연락처: 샌드라 리, 555-0143, slee@elmhomes.com\n\n[이메일]\n보낸 사람: 케빈 무어 / 받는 사람: 샌드라 리 / 날짜: 7월 10일 / 제목: 엘름가 아파트\n\n안녕하세요, 리 씨.\n\n엘름가 아파트 광고를 봤습니다. 다음 달부터 시내에서 새 일을 시작하는데 지하철로 출근할 예정이라 위치가 저에게 딱 맞을 것 같습니다.\n\n작은 고양이를 한 마리 키우는데, 문제가 될까요?\n\n이번 주에 아파트를 볼 수 있을까요? 목요일이나 금요일 오후 6시 이후에 시간이 됩니다.\n\n감사합니다.\n케빈 무어\n\n[문자 메시지]\n샌드라 리 (7월 11일 오전 9:15): 안녕하세요, 케빈. 샌드라 리예요. 죄송하지만 집주인에게 확인해 보니 안 된다고 하네요.\n케빈 무어 (오전 9:20): 알겠습니다. 고양이는 부모님이 돌봐 주실 수 있어요. 그래도 아파트를 보고 싶어요.\n샌드라 리 (오전 9:22): 좋아요. 금요일 6시 30분 어때요?\n케빈 무어 (오전 9:23): 좋습니다. 그때 봬요.","part":7},{"id":"p7-080","level":1,"kind":"triple","passages":[{"doc_type":"공지","title":"City of Brookfield — Road Closures for the Spring Marathon","text":"CITY OF BROOKFIELD — ROAD CLOSURES\n\nThe Brookfield Spring Marathon will take place on Sunday, April 20. The following roads will be closed from 6:00 A.M. to 2:00 P.M.:\n\n• Main Street (between 1st Avenue and 10th Avenue)\n• River Road\n• Hill Avenue\n\nBuses will not run on these roads during this time. Drivers should use Park Boulevard instead. For more information, visit www.brookfield.gov/marathon."},{"doc_type":"이메일","title":"From: Carla Diaz, Store Manager, Fresh Basket Market / To: All Staff / Date: April 15 / Subject: Sunday, April 20","text":"Hi everyone,\n\nAs you may know, some roads will be closed on Sunday for the marathon. Our store is on Main Street, so our delivery truck will not be able to arrive at the usual time of 7:00 A.M. The truck will come at 3:00 P.M. instead.\n\nAlso, the store will open at noon that day instead of 8:00 A.M. Morning staff, please come in at 11:30 A.M.\n\nThank you,\nCarla"},{"doc_type":"문자 메시지","title":"Text-message chain","text":"Mina Cho (April 19, 8:10 P.M.): Hi, Carla. My bus usually goes down Hill Avenue. I don't think I can get to work by 11:30 tomorrow.\nCarla Diaz (8:14 P.M.): No problem. Can you come in at 1:00 instead?\nMina Cho (8:15 P.M.): Sure. My brother can drive me after lunch. Thanks!"}],"questions":[{"q":"Why will the roads be closed?","choices":["For repair work","For a sports event","For a parade","For a music festival"],"answer":1,"type":"주제·목적","explanation":"공지 첫 문장에서 브룩필드 봄 마라톤이 열린다고 했으므로 스포츠 행사 때문에 도로가 통제된다. 공사나 퍼레이드는 언급되지 않았다."},{"q":"What is true about Fresh Basket Market?","choices":["It is on a road that will be closed.","It will be closed all day on April 20.","It is a sponsor of the marathon.","It is located on Park Boulevard."],"answer":0,"type":"연계 문제","explanation":"이메일에서 가게가 메인가(Main Street)에 있다고 했고, 공지에서 메인가는 통제되는 도로에 포함된다. 가게는 그날 문을 닫는 것이 아니라 정오에 연다."},{"q":"What time will the delivery truck arrive on April 20?","choices":["At 7:00 A.M.","At 8:00 A.M.","At 2:00 P.M.","At 3:00 P.M."],"answer":3,"type":"세부 사항","explanation":"이메일에 'The truck will come at 3:00 P.M. instead.'라고 했다. 오전 7시는 평소 도착 시간이고, 오후 2시는 도로 통제가 끝나는 시간이다."},{"q":"Why can't Ms. Cho arrive by 11:30?","choices":["Her car is being repaired.","She has to work at another store.","She has a family event that morning.","Her bus will not run on its usual road."],"answer":3,"type":"연계 문제","explanation":"문자에서 조 씨의 버스가 보통 힐 애비뉴를 지난다고 했고, 공지에 힐 애비뉴가 통제되며 그 시간에는 버스가 다니지 않는다고 했다. 그래서 11시 30분까지 출근하기 어렵다."},{"q":"When will Ms. Cho most likely start work on April 20?","choices":["At 8:00 A.M.","At 11:30 A.M.","At 12:00 P.M.","At 1:00 P.M."],"answer":3,"type":"세부 사항","explanation":"디아스 씨가 1시에 올 수 있는지 묻자 조 씨가 'Sure'라고 답했으므로 오후 1시에 일을 시작할 것이다. 11시 30분은 원래 오전 직원 출근 시간이다."}],"translation":"[공지]\n브룩필드시 — 도로 통제\n\n브룩필드 봄 마라톤이 4월 20일 일요일에 열립니다. 다음 도로는 오전 6시부터 오후 2시까지 통제됩니다.\n\n• 메인가 (1번 애비뉴와 10번 애비뉴 사이)\n• 리버 로드\n• 힐 애비뉴\n\n이 시간 동안 해당 도로에는 버스가 다니지 않습니다. 운전자는 대신 파크 대로를 이용하시기 바랍니다. 자세한 내용은 www.brookfield.gov/marathon을 방문하세요.\n\n[이메일]\n보낸 사람: 카를라 디아스, 프레시 바스켓 마켓 점장 / 받는 사람: 전 직원 / 날짜: 4월 15일 / 제목: 4월 20일 일요일\n\n안녕하세요, 여러분.\n\n아시다시피 일요일에 마라톤 때문에 일부 도로가 통제됩니다. 우리 가게는 메인가에 있어서 배송 트럭이 평소 시간인 오전 7시에 도착할 수 없습니다. 대신 트럭은 오후 3시에 옵니다.\n\n또한 그날 가게는 오전 8시가 아니라 정오에 문을 엽니다. 오전 근무자는 오전 11시 30분까지 출근해 주세요.\n\n감사합니다.\n카를라\n\n[문자 메시지]\n미나 조 (4월 19일 오후 8:10): 안녕하세요, 카를라. 제가 타는 버스가 보통 힐 애비뉴를 지나가요. 내일 11시 30분까지는 출근하기 어려울 것 같아요.\n카를라 디아스 (오후 8:14): 괜찮아요. 대신 1시에 올 수 있어요?\n미나 조 (오후 8:15): 물론이죠. 점심 먹고 오빠가 차로 데려다줄 수 있어요. 고마워요!","part":7},{"id":"p7-081","level":2,"kind":"single","passages":[{"doc_type":"기사","title":"Pinedale Launches Bike-Sharing Program","text":"PINEDALE (March 3) — Starting next Monday, residents of Pinedale will be able to rent bicycles at ten new stations around the city center. The program, called PedalPine, is run by the city's transportation office. [1]\n\nUsers can rent a bike through the PedalPine mobile app or by using a credit card at any station. The first 30 minutes of each ride are free, and each additional 30 minutes costs $1.50. [2] Monthly passes are also available for $20.\n\n“We hope the program will reduce traffic downtown and give people a healthy way to get around,” said Martin Reyes, the city's transportation director. [3] The city plans to add five more stations near Pinedale University by the end of the year.\n\nAll bicycles are checked for safety every week. Riders are encouraged, but not required, to wear helmets. [4]"}],"questions":[{"q":"What is the article mainly about?","choices":["A new bicycle rental service","A plan to build a new road","The opening of a bicycle shop","A university sports program"],"answer":0,"type":"주제·목적","explanation":"첫 단락에서 시내 10곳의 새 대여소에서 자전거를 빌릴 수 있는 PedalPine 프로그램이 시작된다고 했다. 자전거 가게 개업이나 도로 건설 이야기가 아니다."},{"q":"How much would a 90-minute ride cost without a monthly pass?","choices":["$1.50","$2.00","$3.00","$4.50"],"answer":2,"type":"세부 사항","explanation":"처음 30분은 무료이고 이후 30분마다 1.5달러이다. 90분 이용이면 무료 30분을 뺀 60분, 즉 30분 두 번이므로 1.5×2=3달러이다. 4.5달러는 처음 30분도 요금을 낸 것으로 계산한 값이다."},{"q":"The word “reduce” in paragraph 3 is closest in meaning to","choices":["repair","lower","measure","direct"],"answer":1,"type":"동의어","explanation":"'reduce traffic downtown'은 시내 교통량을 '줄이다'라는 뜻이므로 'lower(낮추다, 줄이다)'가 가장 가깝다. repair(고치다), measure(측정하다), direct(안내하다)는 뜻이 다르다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? “Helmets can be borrowed for free at the three largest stations.”","choices":["[1]","[2]","[3]","[4]"],"answer":3,"type":"문장 삽입","explanation":"주어진 문장은 헬멧을 무료로 빌릴 수 있다는 내용이므로, 헬멧 착용을 권장한다는 문장 바로 뒤인 [4]가 알맞다. [2]는 요금 설명 중간이라 헬멧 이야기가 나오기에 어색하다."}],"translation":"[기사]\n파인데일, 자전거 공유 프로그램 시작\n\n파인데일 (3월 3일) — 다음 주 월요일부터 파인데일 주민들은 시내 중심가 곳곳에 새로 생긴 대여소 10곳에서 자전거를 빌릴 수 있다. PedalPine이라는 이 프로그램은 시 교통과가 운영한다.\n\n이용자는 PedalPine 모바일 앱이나 대여소에서 신용카드로 자전거를 빌릴 수 있다. 매 이용의 처음 30분은 무료이고, 이후 30분마다 1.5달러가 부과된다. 월 이용권도 20달러에 구입할 수 있다.\n\n“이 프로그램이 시내 교통량을 줄이고 사람들에게 건강한 이동 수단을 제공하길 바랍니다.”라고 시 교통국장 마틴 레예스는 말했다. 시는 연말까지 파인데일 대학 근처에 대여소 5곳을 추가할 계획이다.\n\n모든 자전거는 매주 안전 점검을 받는다. 이용자는 헬멧 착용을 권장받지만 의무는 아니다. (가장 큰 대여소 세 곳에서는 헬멧을 무료로 빌릴 수 있다.)","part":7},{"id":"p7-082","level":2,"kind":"single","passages":[{"doc_type":"온라인 채팅","title":"Online chat discussion","text":"Hannah Brooks [11:05 A.M.]: Hi, everyone. As you know, Robert is retiring at the end of the month. I'd like us to buy him a gift from the whole team.\nLeo Martin [11:07 A.M.]: Great idea. He's always talking about his garden. Maybe some gardening tools?\nAisha Khan [11:08 A.M.]: He already has plenty of those. He showed me his shed once!\nHannah Brooks [11:09 A.M.]: Ha! OK, any other ideas?\nAisha Khan [11:11 A.M.]: He mentioned that he wants to travel around Italy with his wife next spring. What about a travel guidebook and a nice suitcase?\nLeo Martin [11:12 A.M.]: I like that. How much should everyone put in?\nHannah Brooks [11:14 A.M.]: If each of the eight of us gives $25, we'll have $200. That should be enough.\nAisha Khan [11:15 A.M.]: I'll pick up the suitcase at Dalton's this weekend.\nHannah Brooks [11:16 A.M.]: Thanks, Aisha. Everyone, please give me your money by Friday."}],"questions":[{"q":"What are the writers mainly discussing?","choices":["A trip to Italy","A gift for a coworker","A new team member","A gardening event"],"answer":1,"type":"주제·목적","explanation":"브룩스 씨가 은퇴하는 로버트에게 팀 전체로 선물을 사자고 제안하며 대화가 시작된다. 이탈리아 여행은 로버트의 계획으로 선물 아이디어의 근거일 뿐이다."},{"q":"At 11:08 A.M., what does Ms. Khan imply when she writes, “He already has plenty of those”?","choices":["Robert does not enjoy gardening.","She saw the tools at a store.","The tools would be too expensive.","Gardening tools are not a good gift idea."],"answer":3,"type":"의도 파악","explanation":"마틴 씨가 원예 도구를 제안하자 로버트가 이미 많이 가지고 있다고 답했고, 이어서 브룩스 씨가 다른 아이디어를 물었다. 즉 원예 도구는 좋은 선물이 아니라는 뜻이다. 로버트가 정원 가꾸기를 좋아하지 않는다는 뜻은 아니다."},{"q":"How much money will the team collect in total?","choices":["$200","$25","$100","$225"],"answer":0,"type":"세부 사항","explanation":"11시 14분에 8명이 각각 25달러씩 내면 200달러가 된다고 했다. 25달러는 한 사람이 내는 금액이다."},{"q":"What will Ms. Khan most likely do this weekend?","choices":["Visit Robert's garden","Book a trip to Italy","Buy a suitcase","Collect money from the team"],"answer":2,"type":"추론","explanation":"11시 15분에 'I'll pick up the suitcase at Dalton's this weekend'라고 했으므로 이번 주말에 여행 가방을 살 것이다. 돈은 브룩스 씨가 금요일까지 걷는다."}],"translation":"[온라인 채팅]\n해나 브룩스 [오전 11:05]: 안녕하세요, 여러분. 아시다시피 로버트가 이달 말에 은퇴해요. 팀 전체로 선물을 하나 사 드리면 좋겠어요.\n레오 마틴 [오전 11:07]: 좋은 생각이에요. 항상 자기 정원 얘기를 하시잖아요. 원예 도구는 어때요?\n아이샤 칸 [오전 11:08]: 그건 이미 많이 갖고 계세요. 창고를 한 번 보여 주신 적이 있거든요!\n해나 브룩스 [오전 11:09]: 하하! 좋아요, 다른 아이디어 있어요?\n아이샤 칸 [오전 11:11]: 내년 봄에 부인과 이탈리아 곳곳을 여행하고 싶다고 하셨어요. 여행 안내서랑 좋은 여행 가방은 어때요?\n레오 마틴 [오전 11:12]: 좋네요. 각자 얼마씩 내면 될까요?\n해나 브룩스 [오전 11:14]: 우리 8명이 25달러씩 내면 200달러가 돼요. 그 정도면 충분할 거예요.\n아이샤 칸 [오전 11:15]: 이번 주말에 달튼스에서 여행 가방을 사 올게요.\n해나 브룩스 [오전 11:16]: 고마워요, 아이샤. 여러분, 금요일까지 저에게 돈을 주세요.","part":7},{"id":"p7-083","level":2,"kind":"single","passages":[{"doc_type":"청구서","title":"Invoice — GreenSpace Office Plants","text":"INVOICE\nGreenSpace Office Plants\n310 Birch Lane, Maplewood | Tel. 555-0178\n\nInvoice number: GS-4471\nDate: November 30\nBill to: Carter & Webb Insurance, 22 Harbor Street, Suite 400\nService period: November 1–30\n\nDescription | Quantity | Unit price | Amount\nPlant rental (large floor plants) | 8 | $15.00 | $120.00\nPlant rental (small desk plants) | 20 | $4.00 | $80.00\nWeekly watering and care visits | 4 | $25.00 | $100.00\nReplacement of damaged plant (Nov. 18) | 1 | $0.00 | $0.00\nTotal due: $300.00\n\nPayment is due by December 15. A 5% late fee will be added to payments received after this date.\n\nNote: The floor plant replaced on November 18 was damaged when our technician's cart hit it during a care visit. Replacement is free of charge whenever damage is caused by our staff."}],"questions":[{"q":"What type of business is GreenSpace Office Plants?","choices":["A flower shop for events","A plant rental and care service","An office cleaning company","A furniture store"],"answer":1,"type":"주제·목적","explanation":"청구 항목이 대형·소형 식물 대여(Plant rental)와 주간 물 주기·관리 방문(watering and care visits)이므로 식물 대여 및 관리 업체이다."},{"q":"How many care visits were made in November?","choices":["1","8","20","4"],"answer":3,"type":"세부 사항","explanation":"'Weekly watering and care visits | 4'에서 11월에 관리 방문이 4회였다. 8과 20은 대형·소형 식물의 개수이다."},{"q":"Why was Carter & Webb not charged for the replacement plant?","choices":["GreenSpace caused the damage.","The plant was very small.","Carter & Webb used a coupon.","The plant was replaced late."],"answer":0,"type":"세부 사항","explanation":"비고에 11월 18일 교체된 식물은 그린스페이스 기술자의 카트에 부딪혀 손상되었고, 직원 때문에 생긴 손상은 무료로 교체한다고 했다."},{"q":"If Carter & Webb pays the invoice on December 20, how much will it most likely pay?","choices":["$300","$305","$315","$330"],"answer":2,"type":"추론","explanation":"납부 기한은 12월 15일이고, 이후에 내면 5% 연체료가 붙는다. 12월 20일은 기한 후이므로 300달러의 5%인 15달러가 더해져 315달러를 내야 한다."}],"translation":"[청구서]\n청구서\n그린스페이스 오피스 플랜츠\n메이플우드 버치 레인 310번지 | 전화 555-0178\n\n청구서 번호: GS-4471\n날짜: 11월 30일\n청구 대상: 카터 앤 웹 보험, 하버가 22번지 400호\n서비스 기간: 11월 1일~30일\n\n내역 | 수량 | 단가 | 금액\n식물 대여(대형 바닥용 화분) | 8 | 15.00달러 | 120.00달러\n식물 대여(소형 책상용 화분) | 20 | 4.00달러 | 80.00달러\n주간 물 주기 및 관리 방문 | 4 | 25.00달러 | 100.00달러\n손상된 식물 교체(11월 18일) | 1 | 0.00달러 | 0.00달러\n청구 총액: 300.00달러\n\n납부 기한은 12월 15일입니다. 이 날짜 이후에 받은 납부액에는 5%의 연체료가 추가됩니다.\n\n비고: 11월 18일 교체한 바닥용 화분은 관리 방문 중 저희 기술자의 카트에 부딪혀 손상되었습니다. 저희 직원으로 인한 손상은 언제나 무료로 교체해 드립니다.","part":7},{"id":"p7-084","level":2,"kind":"single","passages":[{"doc_type":"회람","title":"To: All Employees / From: Diane Fowler, Facilities Manager / Date: January 8 / Subject: New security badges","text":"MEMO\n\nStarting on Monday, February 3, our building will use a new card system for entry. Your current badge will stop working on that date, so everyone will need to pick up a new one. [1]\n\nNew badges will be handed out in the lobby from January 20 to January 31, between 10:00 A.M. and 4:00 P.M. [2] Please bring a photo ID. Your picture will be taken on the spot, so the process will take about five minutes.\n\nThe new badges will also let you use the printers on every floor. [3] You will simply tap your badge on a printer to release your documents. This should prevent confidential papers from being left in the trays.\n\nPlease return your old badge when you receive your new one. [4] If you have any questions, contact me at extension 214."}],"questions":[{"q":"Why was the memo written?","choices":["To announce a new printer model","To explain a change to building entry","To introduce a new facilities manager","To report a security problem"],"answer":1,"type":"주제·목적","explanation":"첫 문장에서 2월 3일부터 건물 출입에 새 카드 시스템을 쓴다고 하고, 새 배지를 받는 방법을 안내하고 있다. 프린터는 새 배지의 부가 기능으로 언급된 것이다."},{"q":"What are employees asked to bring when they get a new badge?","choices":["A photo ID","A recent photograph","A signed form","Their printer password"],"answer":0,"type":"세부 사항","explanation":"'Please bring a photo ID.'라고 했다. 사진은 현장에서 찍으므로(taken on the spot) 따로 가져올 필요가 없다."},{"q":"The word “confidential” in paragraph 3 is closest in meaning to","choices":["finished","lengthy","private","colorful"],"answer":2,"type":"동의어","explanation":"'confidential papers'는 다른 사람이 보면 안 되는 '기밀' 서류를 뜻하므로 'private(사적인, 비공개의)'이 가장 가깝다. finished(완성된), lengthy(긴), colorful(다채로운)은 뜻이 다르다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? “Employees who will be away during this period should contact me to arrange another time.”","choices":["[1]","[2]","[3]","[4]"],"answer":1,"type":"문장 삽입","explanation":"'this period(이 기간)'는 배지를 나눠 주는 1월 20~31일을 가리키므로 그 기간을 알린 문장 바로 뒤인 [2]가 알맞다. [1]은 아직 배포 기간이 나오기 전이고, [3]과 [4]는 프린터와 반납 이야기다."}],"translation":"[회람]\n수신: 전 직원 / 발신: 다이앤 파울러, 시설 관리 책임자 / 날짜: 1월 8일 / 제목: 새 보안 배지\n\n회람\n\n2월 3일 월요일부터 우리 건물은 출입에 새 카드 시스템을 사용합니다. 현재 배지는 그날부터 작동하지 않으므로 모든 분이 새 배지를 받아야 합니다.\n\n새 배지는 1월 20일부터 1월 31일까지 오전 10시~오후 4시에 로비에서 나눠 드립니다. (이 기간에 자리를 비우는 직원은 저에게 연락해 다른 시간을 잡으십시오.) 사진이 있는 신분증을 가져오십시오. 사진은 현장에서 촬영하므로 절차는 5분 정도 걸립니다.\n\n새 배지로 모든 층의 프린터도 사용할 수 있습니다. 프린터에 배지를 대기만 하면 문서가 출력됩니다. 이렇게 하면 기밀 서류가 용지함에 방치되는 일을 막을 수 있을 것입니다.\n\n새 배지를 받을 때 기존 배지를 반납해 주십시오. 문의 사항이 있으면 내선 214번으로 연락 주십시오.","part":7},{"id":"p7-085","level":2,"kind":"double","passages":[{"doc_type":"웹페이지","title":"www.roadwayrentals.com/rates","text":"ROADWAY RENTALS — DAILY RATES\n\nCar type | Example model | Daily rate\nCompact | Kato Swift | $38\nMidsize | Delmar Sedan | $52\nSUV | Travis Explorer | $75\nVan (8 seats) | Mova Family | $90\n\n• Rates include basic insurance.\n• A GPS unit can be added for $8 per day.\n• Cars returned more than one hour late will be charged for an extra day.\n• Members of our Roadway Plus program receive a free upgrade to the next car type when available."},{"doc_type":"이메일","title":"From: Grace Liu / To: support@roadwayrentals.com / Date: May 22 / Subject: Charge on my bill","text":"Hello,\n\nI rented a midsize car from your airport location from May 18 to May 20 for a business trip. When I picked it up, the agent gave me an SUV at no extra cost, which I really appreciated. I also added a GPS unit for the whole trip.\n\nHowever, my bill shows a charge for three days, not two. The rental period ended at 10:00 A.M. on May 20, and I returned the car at 10:40 A.M. I believe the extra day was charged by mistake. Please check your records and correct my bill.\n\nRegards,\nGrace Liu"}],"questions":[{"q":"Why did Ms. Liu write the e-mail?","choices":["To reserve a car for a trip","To ask about membership","To question a charge on her bill","To report damage to a car"],"answer":2,"type":"주제·목적","explanation":"이메일에서 청구서에 2일이 아니라 3일 요금이 청구되었으니 확인하고 바로잡아 달라고 요청했다. 예약이나 차량 손상 신고가 아니다."},{"q":"What is suggested about Ms. Liu?","choices":["She is a member of Roadway Plus.","She paid extra for an SUV.","She rented a van.","She did not use a GPS."],"answer":0,"type":"연계 문제","explanation":"요금표에 Roadway Plus 회원은 한 등급 위 차종으로 무료 업그레이드를 받는다고 했고, 이메일에서 류 씨는 중형차를 빌렸는데 추가 비용 없이 SUV를 받았다. 중형 바로 위 등급이 SUV이므로 회원이라고 추론할 수 있다."},{"q":"How much should Ms. Liu have been charged for the car itself for her trip?","choices":["$76","$104","$150","$156"],"answer":1,"type":"연계 문제","explanation":"무료 업그레이드이므로 SUV가 아니라 원래 빌린 중형차 요금(하루 52달러)이 적용된다. 2일이므로 52×2=104달러이다. 150달러는 SUV 요금으로 계산한 것이고, 156달러는 3일로 계산한 것이다."},{"q":"Why does Ms. Liu believe the extra charge is a mistake?","choices":["She returned the car early.","She was told the GPS was free.","She canceled one day of the rental.","She returned the car less than an hour late."],"answer":3,"type":"연계 문제","explanation":"요금표에 한 시간 넘게 늦게 반납해야 하루 요금이 추가된다고 했는데, 류 씨는 오전 10시까지인 차를 10시 40분에 반납해 40분만 늦었다. 따라서 추가 요금 대상이 아니다."},{"q":"In the e-mail, the word “appreciated” in paragraph 1 is closest in meaning to","choices":["increased in value","was grateful for","understood fully","noticed"],"answer":1,"type":"동의어","explanation":"추가 비용 없이 SUV를 받은 것을 'really appreciated'했다는 것은 그 호의에 '고마워했다'는 뜻이므로 'was grateful for'가 가장 가깝다. appreciate에는 '가치가 오르다'라는 뜻도 있지만 이 문맥과는 맞지 않는다."}],"translation":"[웹페이지]\n로드웨이 렌털 — 일일 요금\n\n차종 | 모델 예시 | 일일 요금\n소형 | 카토 스위프트 | 38달러\n중형 | 델마 세단 | 52달러\nSUV | 트래비스 익스플로러 | 75달러\n승합차(8인승) | 모바 패밀리 | 90달러\n\n• 요금에는 기본 보험이 포함됩니다.\n• GPS 장치는 하루 8달러에 추가할 수 있습니다.\n• 한 시간 넘게 늦게 반납된 차량은 하루 요금이 추가됩니다.\n• 로드웨이 플러스 회원은 가능한 경우 한 등급 위 차종으로 무료 업그레이드를 받습니다.\n\n[이메일]\n보낸 사람: 그레이스 류 / 받는 사람: support@roadwayrentals.com / 날짜: 5월 22일 / 제목: 청구서 요금 문의\n\n안녕하세요,\n\n출장 때문에 5월 18일부터 5월 20일까지 공항 지점에서 중형차를 빌렸습니다. 차를 받을 때 직원분이 추가 비용 없이 SUV를 주셔서 정말 감사했습니다. GPS 장치도 여행 기간 내내 추가했습니다.\n\n그런데 청구서에 2일이 아니라 3일 요금이 청구되어 있습니다. 대여 기간은 5월 20일 오전 10시에 끝났고, 저는 오전 10시 40분에 차를 반납했습니다. 추가 1일 요금은 실수로 청구된 것 같습니다. 기록을 확인하시고 청구서를 정정해 주십시오.\n\n그레이스 류 드림","part":7},{"id":"p7-086","level":2,"kind":"double","passages":[{"doc_type":"공고","title":"Talbot Industries Employee Photo Contest","text":"TALBOT INDUSTRIES EMPLOYEE PHOTO CONTEST\nTheme: “Our Work, Our Community”\n\nShow us what makes Talbot special! Photos may show our workplaces, our products, or our volunteer activities.\n\nRules:\n• All full-time and part-time employees may enter.\n• Each person may submit up to two photos.\n• Photos must have been taken within the last 12 months.\n• Send your photos to contest@talbot.com by August 15 with a short title for each.\n\nPrizes: The winning photo will appear on the cover of our annual report, and the photographer will receive a $300 gift card. Two runners-up will each receive a $100 gift card.\n\nWinners will be announced at the company picnic on September 6."},{"doc_type":"이메일","title":"From: Jonah Ferris / To: contest@talbot.com / Date: August 10 / Subject: Contest entry","text":"Hello,\n\nI work part-time in the shipping department, and I'm happy to enter the contest. Attached are three photos.\n\nThe first, “Morning Shift,” shows our loading dock at sunrise. The second, “Helping Hands,” was taken at the food bank where our team volunteered in March. The third, “Old Friends,” shows two of our first delivery trucks from 2015. I took it at the company museum last week.\n\nPlease let me know if you need anything else.\n\nJonah Ferris"}],"questions":[{"q":"What is the purpose of the notice?","choices":["To introduce a new product","To invite employees to a picnic","To announce a competition","To describe a volunteer program"],"answer":2,"type":"주제·목적","explanation":"공고 제목과 내용이 직원 사진 공모전(Photo Contest)의 규칙과 상품을 안내하고 있다. 회사 야유회는 수상자 발표 장소로만 언급된다."},{"q":"What will the winner receive?","choices":["A $100 gift card","A new camera","A day off from work","A $300 gift card"],"answer":3,"type":"세부 사항","explanation":"공고에 우승 사진은 연례 보고서 표지에 실리고 사진 작가는 300달러 상품권을 받는다고 했다. 100달러 상품권은 준우승자 2명이 받는다."},{"q":"What is true about Mr. Ferris?","choices":["He is allowed to enter the contest.","He works in the marketing department.","He missed the entry deadline.","He works full-time at Talbot."],"answer":0,"type":"연계 문제","explanation":"공고에 정규직과 시간제 직원 모두 참가할 수 있다고 했고, 이메일에서 페리스 씨는 배송부 시간제 직원이라고 했으므로 참가 자격이 있다. 8월 10일에 보냈으므로 마감(8월 15일) 전이다."},{"q":"What problem is there with Mr. Ferris's entry?","choices":["The photos have no titles.","He sent too many photos.","One photo is more than a year old.","He sent the photos to the wrong address."],"answer":1,"type":"연계 문제","explanation":"공고는 한 사람당 사진을 최대 2장까지 낼 수 있다고 했는데, 페리스 씨는 3장을 첨부했다. 각 사진에 제목이 있고, 트럭 사진도 지난주에 찍은 것이라 기간 조건은 문제없다."},{"q":"Which photo shows one of the activities mentioned in the notice's theme?","choices":["“Helping Hands”","“Morning Shift”","“Old Friends”","None of the photos"],"answer":0,"type":"세부 사항","explanation":"공고는 봉사 활동(volunteer activities) 사진도 가능하다고 했고, 'Helping Hands'는 팀이 3월에 봉사한 푸드뱅크에서 찍은 사진이다."}],"translation":"[공고]\n탤벗 인더스트리즈 직원 사진 공모전\n주제: “우리의 일, 우리의 지역 사회”\n\n탤벗을 특별하게 만드는 것을 보여 주세요! 사진에는 우리 일터, 제품, 봉사 활동 등을 담을 수 있습니다.\n\n규칙:\n• 모든 정규직 및 시간제 직원이 참가할 수 있습니다.\n• 1인당 최대 2장까지 제출할 수 있습니다.\n• 사진은 최근 12개월 이내에 찍은 것이어야 합니다.\n• 8월 15일까지 각 사진에 짧은 제목을 붙여 contest@talbot.com으로 보내 주세요.\n\n상품: 우승 사진은 연례 보고서 표지에 실리며, 촬영자는 300달러 상품권을 받습니다. 준우승자 2명은 각각 100달러 상품권을 받습니다.\n\n수상자는 9월 6일 회사 야유회에서 발표됩니다.\n\n[이메일]\n보낸 사람: 조나 페리스 / 받는 사람: contest@talbot.com / 날짜: 8월 10일 / 제목: 공모전 응모\n\n안녕하세요,\n\n저는 배송부에서 시간제로 일하고 있으며, 공모전에 기쁜 마음으로 응모합니다. 사진 세 장을 첨부합니다.\n\n첫 번째 “아침 근무”는 해 뜰 무렵의 우리 하역장을 담았습니다. 두 번째 “도움의 손길”은 3월에 우리 팀이 봉사한 푸드뱅크에서 찍었습니다. 세 번째 “오랜 친구들”은 2015년에 도입한 우리 회사 최초의 배송 트럭 두 대를 보여 줍니다. 지난주 회사 박물관에서 찍었습니다.\n\n더 필요한 것이 있으면 알려 주세요.\n\n조나 페리스","part":7},{"id":"p7-087","level":2,"kind":"double","passages":[{"doc_type":"고객 의견 카드","title":"Blue Harbor Grill — Customer Comment Card","text":"BLUE HARBOR GRILL — CUSTOMER COMMENT CARD\n\nDate of visit: Saturday, March 8   Time: 7:30 P.M.\nName: Paul Nguyen\nNumber in party: 6\n\nPlease rate us (1 = poor, 5 = excellent):\nFood: 5   Service: 2   Cleanliness: 4   Value: 4\n\nComments: We came to celebrate my mother's birthday. The seafood pasta and grilled salmon were wonderful. However, we waited almost 40 minutes for our main dishes, and our server never came back to refill our water. I had called ahead to say it was a birthday, but no one mentioned it.\n\nMay we contact you? ☑ Yes — Address: 19 Cedar Lane, Fairview"},{"doc_type":"편지","title":"Blue Harbor Grill / 5 Wharf Road, Fairview","text":"March 12\n\nDear Mr. Nguyen,\n\nThank you for taking the time to fill out a comment card during your visit. I'm glad you enjoyed our food, and I apologize for the rest of your experience. That evening, two of our servers called in sick, and we were not able to find anyone to replace them. Still, that is no excuse for the long wait.\n\nI have also spoken to our host about your phone call. From now on, special requests will be written in our reservation system so that all staff can see them.\n\nTo thank you for your feedback, I have enclosed a voucher for a free dinner for two. It can be used any day except Saturdays.\n\nSincerely,\nTeresa Alvarez\nGeneral Manager"}],"questions":[{"q":"What did Mr. Nguyen give the lowest rating to?","choices":["Food","Service","Cleanliness","Value"],"answer":1,"type":"세부 사항","explanation":"의견 카드에서 서비스(Service)에 2점을 주어 가장 낮았다. 음식은 5점, 청결과 가격 대비 가치는 4점이다."},{"q":"According to the letter, why was the service slow?","choices":["The kitchen equipment broke.","The restaurant was fully booked.","Some servers were absent.","A new menu was introduced."],"answer":2,"type":"세부 사항","explanation":"편지에서 그날 저녁 서버 두 명이 아파서 결근했고 대신할 사람을 구하지 못했다고 설명했다. 주방 장비 고장이나 새 메뉴는 언급되지 않았다."},{"q":"What change does Ms. Alvarez mention?","choices":["Special requests will be recorded for all staff to see.","More servers will be hired on weekends.","Customers will be able to reserve online.","Birthday guests will receive a free dessert."],"answer":0,"type":"세부 사항","explanation":"'special requests will be written in our reservation system so that all staff can see them'에서 특별 요청을 예약 시스템에 기록해 모든 직원이 보게 하겠다고 했다. 이는 응우옌 씨가 미리 전화로 생일이라고 알렸는데 아무도 몰랐던 문제에 대한 조치이다."},{"q":"What is indicated about the voucher?","choices":["It is valid for a party of six.","It must be used within a month.","It covers only the main dishes.","It cannot be used on the same day of the week as Mr. Nguyen's visit."],"answer":3,"type":"연계 문제","explanation":"편지에 상품권은 토요일을 제외한 모든 요일에 쓸 수 있다고 했고, 의견 카드에서 응우옌 씨가 방문한 날은 3월 8일 토요일이다. 상품권은 2인 저녁 식사용이다."},{"q":"In the letter, the word “enclosed” in paragraph 3 is closest in meaning to","choices":["surrounded","included","closed","printed"],"answer":1,"type":"동의어","explanation":"'I have enclosed a voucher'는 편지에 상품권을 '동봉했다'는 뜻이므로 'included(포함했다)'가 가장 가깝다. surrounded(둘러쌌다)는 물리적으로 에워싼다는 뜻이라 문맥에 맞지 않는다."}],"translation":"[고객 의견 카드]\n블루 하버 그릴 — 고객 의견 카드\n\n방문 날짜: 3월 8일 토요일   시간: 오후 7시 30분\n이름: 폴 응우옌\n일행 수: 6명\n\n평가해 주세요 (1 = 나쁨, 5 = 매우 좋음):\n음식: 5   서비스: 2   청결: 4   가격 대비 가치: 4\n\n의견: 어머니 생신을 축하하러 왔습니다. 해산물 파스타와 연어구이는 훌륭했습니다. 하지만 주요리를 거의 40분이나 기다렸고, 담당 서버는 물을 채워 주러 한 번도 다시 오지 않았습니다. 미리 전화해서 생일이라고 말했는데 아무도 언급하지 않았습니다.\n\n연락을 드려도 될까요? ☑ 예 — 주소: 페어뷰 시더 레인 19번지\n\n[편지]\n블루 하버 그릴 / 페어뷰 와프 로드 5번지\n\n3월 12일\n\n응우옌 씨께,\n\n방문 중에 시간을 내어 의견 카드를 작성해 주셔서 감사합니다. 음식을 맛있게 드셨다니 기쁘고, 그 밖의 경험에 대해서는 사과드립니다. 그날 저녁 서버 두 명이 병가를 냈고, 대신할 사람을 구하지 못했습니다. 그렇다 해도 오래 기다리시게 한 것은 변명의 여지가 없습니다.\n\n또한 고객님의 전화에 관해 저희 안내 직원과 이야기를 나누었습니다. 앞으로 특별 요청 사항은 모든 직원이 볼 수 있도록 예약 시스템에 기록하겠습니다.\n\n소중한 의견에 감사드리는 뜻으로 2인 무료 저녁 식사 상품권을 동봉했습니다. 토요일을 제외한 모든 요일에 사용하실 수 있습니다.\n\n테리사 알바레스\n총지배인 드림","part":7},{"id":"p7-088","level":2,"kind":"triple","passages":[{"doc_type":"일정표","title":"Training Schedule — ClearLedger Expense Software","text":"TRAINING SCHEDULE — CLEARLEDGER EXPENSE SOFTWARE\n\nAll staff must attend one 2-hour session. Sessions are held in Training Room 3.\n\nSession | Date | Time | For\n1 | Tuesday, May 6 | 9:00–11:00 A.M. | Sales\n2 | Wednesday, May 7 | 1:00–3:00 P.M. | Marketing\n3 | Thursday, May 8 | 9:00–11:00 A.M. | Finance and Human Resources\n4 | Friday, May 9 | 2:00–4:00 P.M. | Anyone who cannot attend an earlier session\n\nPlease bring your laptop. Staff who cannot attend their department's session should contact the trainer, Omar Reed, at least one day in advance."},{"doc_type":"이메일","title":"From: Julia Santos / To: Omar Reed / Date: May 5 / Subject: Training session","text":"Hi Omar,\n\nI'm in the marketing department, but on the day of our session, I'll be visiting a client in Ridgeville all afternoon. Could I attend the Thursday morning session instead? If not, I can come to the last session.\n\nAlso, my laptop is being repaired this week. Will there be a computer I can use?\n\nThanks,\nJulia"},{"doc_type":"문자 메시지","title":"Text-message chain","text":"Omar Reed (May 5, 4:30 P.M.): Hi, Julia. Sorry, Thursday morning's session is already full. I've added you to Friday's.\nJulia Santos (4:32 P.M.): OK, that works. What about a laptop?\nOmar Reed (4:33 P.M.): I'll bring a spare one for you.\nJulia Santos (4:34 P.M.): You're a lifesaver!"}],"questions":[{"q":"What is the purpose of the schedule?","choices":["To announce a sales meeting","To list times for software training","To introduce a new trainer","To explain a new expense policy"],"answer":1,"type":"주제·목적","explanation":"일정표는 클리어레저 경비 소프트웨어 교육(Training Schedule)의 부서별 날짜와 시간을 안내한다. 경비 규정 자체를 설명하는 것은 아니다."},{"q":"When will Ms. Santos visit a client in Ridgeville?","choices":["On May 6","On May 7","On May 8","On May 9"],"answer":1,"type":"연계 문제","explanation":"이메일에서 산토스 씨는 마케팅부이며 '우리 부서 교육 날' 오후 내내 고객을 방문한다고 했다. 일정표에서 마케팅부 교육은 5월 7일 수요일이다."},{"q":"At what time will Ms. Santos most likely attend training?","choices":["At 2:00 P.M.","At 9:00 A.M.","At 1:00 P.M.","At 11:00 A.M."],"answer":0,"type":"연계 문제","explanation":"문자에서 목요일 오전 교육이 꽉 차서 금요일 교육에 넣었다고 했고, 일정표에서 금요일(5월 9일) 교육은 오후 2~4시이다. 오전 9시는 목요일 교육 시간이다."},{"q":"What does Mr. Reed offer to do?","choices":["Repair Ms. Santos's laptop","Change the training room","Lend Ms. Santos a laptop","Send Ms. Santos the training notes"],"answer":2,"type":"세부 사항","explanation":"산토스 씨가 노트북을 묻자 리드 씨는 'I'll bring a spare one for you.'라고 여분 노트북을 가져오겠다고 했다. 노트북 수리는 이미 다른 곳에서 진행 중이다."},{"q":"At 4:34 P.M., what does Ms. Santos mean when she writes, “You're a lifesaver”?","choices":["She is worried about her health.","She is grateful for Mr. Reed's help.","She thinks the training is too long.","She wants to join a safety course."],"answer":1,"type":"의도 파악","explanation":"리드 씨가 교육 일정도 바꿔 주고 노트북도 가져다주겠다고 하자 'You're a lifesaver!(정말 큰 도움이 돼요)'라고 했으므로 고마움을 표현한 것이다. 건강이나 안전 교육과는 관계없다."}],"translation":"[일정표]\n교육 일정 — 클리어레저 경비 소프트웨어\n\n전 직원은 2시간짜리 교육 한 번에 반드시 참석해야 합니다. 교육은 교육실 3에서 진행됩니다.\n\n회차 | 날짜 | 시간 | 대상\n1 | 5월 6일 화요일 | 오전 9~11시 | 영업부\n2 | 5월 7일 수요일 | 오후 1~3시 | 마케팅부\n3 | 5월 8일 목요일 | 오전 9~11시 | 재무부 및 인사부\n4 | 5월 9일 금요일 | 오후 2~4시 | 앞선 교육에 참석하지 못하는 사람\n\n노트북을 지참하십시오. 자기 부서 교육에 참석할 수 없는 직원은 최소 하루 전에 강사 오마르 리드에게 연락하십시오.\n\n[이메일]\n보낸 사람: 줄리아 산토스 / 받는 사람: 오마르 리드 / 날짜: 5월 5일 / 제목: 교육 일정\n\n안녕하세요, 오마르.\n\n저는 마케팅부인데, 우리 부서 교육 날 오후 내내 리지빌에 있는 고객사를 방문해야 해요. 대신 목요일 오전 교육에 참석할 수 있을까요? 안 되면 마지막 교육에 갈게요.\n\n그리고 이번 주에 제 노트북이 수리 중이에요. 쓸 수 있는 컴퓨터가 있을까요?\n\n고마워요.\n줄리아\n\n[문자 메시지]\n오마르 리드 (5월 5일 오후 4:30): 안녕하세요, 줄리아. 미안하지만 목요일 오전 교육은 이미 꽉 찼어요. 금요일 교육에 넣어 뒀어요.\n줄리아 산토스 (오후 4:32): 네, 괜찮아요. 노트북은요?\n오마르 리드 (오후 4:33): 여분으로 하나 가져다줄게요.\n줄리아 산토스 (오후 4:34): 정말 큰 도움이 돼요!","part":7},{"id":"p7-089","level":2,"kind":"triple","passages":[{"doc_type":"웹페이지","title":"www.hivespace.com/membership","text":"HIVE SPACE — COWORKING MEMBERSHIPS\n\nPlan | Access | Monthly fee\nFlex | Any open desk, 10 days per month | $150\nRegular | Any open desk, unlimited days | $250\nDedicated | Your own desk with a locked drawer, unlimited days | $350\nPrivate Office | Office for up to 4 people | $900\n\nAll plans include high-speed Wi-Fi, free coffee and tea, and printing (up to 100 pages per month). Meeting rooms can be booked for $20 per hour; Regular, Dedicated, and Private Office members get 4 free hours each month.\n\nSign up for 6 months and get your first month free!"},{"doc_type":"이메일","title":"From: Adrian Wolfe / To: hello@hivespace.com / Date: June 2 / Subject: Membership question","text":"Hello,\n\nI'm a freelance graphic designer, and I'm tired of working at home. I'd like to work at Hive Space every weekday. I use expensive drawing tablets, so I need somewhere safe to leave my equipment overnight. I also meet clients about twice a month, usually for two hours each time.\n\nI plan to stay for at least six months. Which plan would you recommend?\n\nAdrian Wolfe"},{"doc_type":"영수증","title":"Hive Space — Payment Receipt","text":"HIVE SPACE — PAYMENT RECEIPT\n\nMember: Adrian Wolfe\nDate: June 5\nPlan: Dedicated (6-month contract: June 5 – December 4)\n\nJune fee | $0.00 (first month free)\nJuly fee (paid in advance) | $350.00\nKey deposit (refundable) | $50.00\nTotal paid | $400.00\n\nYour desk number is 14. Please pick up your key at the front desk."}],"questions":[{"q":"What does Mr. Wolfe say about himself?","choices":["He works for a large design firm.","He currently works from home.","He needs an office for four people.","He meets clients every week."],"answer":1,"type":"세부 사항","explanation":"이메일에서 프리랜서 그래픽 디자이너이며 집에서 일하는 것에 지쳤다(tired of working at home)고 했으므로 현재 재택근무를 하고 있다. 고객은 한 달에 두 번 정도 만난다."},{"q":"Why most likely did Mr. Wolfe choose the Dedicated plan?","choices":["It includes a place to lock up his equipment.","It is the cheapest plan.","It allows him to bring coworkers.","It includes unlimited printing."],"answer":0,"type":"연계 문제","explanation":"이메일에서 비싼 태블릿을 밤새 안전하게 둘 곳이 필요하다고 했고, 웹페이지에서 Dedicated 요금제만 잠금 서랍(locked drawer)이 있는 전용 책상을 제공한다. 가장 저렴한 요금제는 Flex이다."},{"q":"How much will Mr. Wolfe most likely pay for meeting rooms each month?","choices":["$40","$80","$20","$0"],"answer":3,"type":"연계 문제","explanation":"울프 씨는 한 달에 두 번, 매번 2시간씩 고객을 만나므로 월 4시간이 필요하다. 웹페이지에 Dedicated 회원은 매달 4시간을 무료로 쓸 수 있다고 했으므로 추가 비용이 없다. 80달러는 무료 시간을 고려하지 않은 금액이다."},{"q":"Why was Mr. Wolfe not charged for June?","choices":["He paid a key deposit.","He signed up for six months.","He was referred by a member.","He joined in the middle of the month."],"answer":1,"type":"연계 문제","explanation":"웹페이지에 6개월 가입 시 첫 달이 무료라고 했고, 영수증에 6개월 계약(June 5 – December 4)으로 6월 요금이 0달러로 표시되어 있다."},{"q":"According to the receipt, what will Mr. Wolfe get back later?","choices":["The July fee","The June fee","The key deposit","The printing fee"],"answer":2,"type":"세부 사항","explanation":"영수증에 열쇠 보증금 50달러가 'refundable(환불 가능)'이라고 되어 있다. 7월 요금은 미리 낸 이용료이다."}],"translation":"[웹페이지]\n하이브 스페이스 — 공유 오피스 회원권\n\n요금제 | 이용 범위 | 월 요금\n플렉스 | 빈 좌석 아무 곳, 월 10일 | 150달러\n레귤러 | 빈 좌석 아무 곳, 무제한 | 250달러\n전용석 | 잠금 서랍이 있는 개인 전용 책상, 무제한 | 350달러\n개인 사무실 | 최대 4인용 사무실 | 900달러\n\n모든 요금제에는 초고속 와이파이, 무료 커피와 차, 인쇄(월 100장까지)가 포함됩니다. 회의실은 시간당 20달러에 예약할 수 있으며, 레귤러·전용석·개인 사무실 회원은 매달 4시간을 무료로 이용합니다.\n\n6개월 가입 시 첫 달 무료!\n\n[이메일]\n보낸 사람: 에이드리언 울프 / 받는 사람: hello@hivespace.com / 날짜: 6월 2일 / 제목: 회원권 문의\n\n안녕하세요,\n\n저는 프리랜서 그래픽 디자이너인데 집에서 일하는 데 지쳤습니다. 평일마다 하이브 스페이스에서 일하고 싶습니다. 비싼 드로잉 태블릿을 쓰기 때문에 밤새 장비를 안전하게 둘 곳이 필요합니다. 또 한 달에 두 번 정도 고객을 만나는데, 보통 한 번에 두 시간씩입니다.\n\n최소 6개월은 이용할 계획입니다. 어떤 요금제를 추천하시나요?\n\n에이드리언 울프\n\n[영수증]\n하이브 스페이스 — 결제 영수증\n\n회원: 에이드리언 울프\n날짜: 6월 5일\n요금제: 전용석 (6개월 계약: 6월 5일~12월 4일)\n\n6월 요금 | 0.00달러 (첫 달 무료)\n7월 요금 (선납) | 350.00달러\n열쇠 보증금 (환불 가능) | 50.00달러\n총 결제액 | 400.00달러\n\n책상 번호는 14번입니다. 안내 데스크에서 열쇠를 받아 가세요.","part":7},{"id":"p7-090","level":2,"kind":"triple","passages":[{"doc_type":"기사","title":"New Ferry to Link Port Halsey and Crane Island","text":"PORT HALSEY (June 2) — A new passenger ferry service between Port Halsey and Crane Island will begin on June 16. The trip, which currently takes about two hours by car because drivers must go around the bay, will take just 40 minutes by ferry.\n\nThe service will be operated by BlueWave Ferries, which already runs three routes along the northern coast. Tickets will cost $12 one way for adults and $6 for children under 12. Bicycles can be brought on board for an additional $3.\n\n“Many people who live on Crane Island work in Port Halsey,” said BlueWave director Nora Quinlan. “We expect them to be our main customers.” Weekend service will be added in July."},{"doc_type":"시간표","title":"BlueWave Ferries — Weekday Timetable (from June 16)","text":"BLUEWAVE FERRIES — WEEKDAY TIMETABLE (from June 16)\n\nDeparts Port Halsey | Arrives Crane Island | Departs Crane Island | Arrives Port Halsey\n6:30 A.M. | 7:10 A.M. | 7:20 A.M. | 8:00 A.M.\n9:00 A.M. | 9:40 A.M. | 10:00 A.M. | 10:40 A.M.\n12:30 P.M. | 1:10 P.M. | 1:30 P.M. | 2:10 P.M.\n5:15 P.M. | 5:55 P.M. | 6:15 P.M. | 6:55 P.M.\n\nTickets can be purchased at the terminal or on the BlueWave app. App users save 10%."},{"doc_type":"이메일","title":"From: Leah Morgan / To: Tim Hughes / Date: June 20 / Subject: Thursday afternoon","text":"Hi Tim,\n\nGood news — I've stopped driving to work! I now take the new ferry from Crane Island every morning. It gets me to Port Halsey at 8:00, which gives me plenty of time to walk to the office before 8:30. On some days I even bring my bike.\n\nOn Thursday I have a dentist appointment on the island at 3:00 P.M., so I'll leave the office early and catch the 12:30 ferry. Could you cover the front desk after lunch that day?\n\nThanks,\nLeah"}],"questions":[{"q":"What is the article mainly about?","choices":["A new bridge to an island","A change in ferry ticket prices","A company's plan to hire drivers","The start of a new ferry route"],"answer":3,"type":"주제·목적","explanation":"기사 첫 문장에서 포트 홀지와 크레인섬을 잇는 새 여객선 운항이 6월 16일에 시작된다고 했다. 다리를 새로 짓는다는 내용이 아니다."},{"q":"In the article, the word “main” in paragraph 3 is closest in meaning to","choices":["primary","loud","complete","regular"],"answer":0,"type":"동의어","explanation":"'our main customers'는 '주된, 주요' 고객이라는 뜻이므로 'primary(주요한)'가 가장 가깝다. regular(단골의, 정기적인)는 뜻이 비슷해 보이지만 '가장 중요한'이라는 의미가 없다."},{"q":"At what time does Ms. Morgan most likely leave Crane Island in the morning?","choices":["At 6:30 A.M.","At 7:10 A.M.","At 8:00 A.M.","At 7:20 A.M."],"answer":3,"type":"연계 문제","explanation":"이메일에서 페리를 타면 포트 홀지에 8시에 도착한다고 했고, 시간표에서 포트 홀지 8시 도착 배는 크레인섬에서 7시 20분에 출발한다. 6시 30분은 포트 홀지 출발 시간이다."},{"q":"When will Ms. Morgan most likely arrive on Crane Island on Thursday?","choices":["At 12:30 P.M.","At 1:10 P.M.","At 1:30 P.M.","At 3:00 P.M."],"answer":1,"type":"연계 문제","explanation":"이메일에서 12시 30분 배를 타겠다고 했고, 시간표에서 포트 홀지 12시 30분 출발 배는 크레인섬에 오후 1시 10분에 도착한다. 3시는 치과 예약 시간이다."},{"q":"What is suggested about Ms. Morgan?","choices":["She lives in Port Halsey.","She buys tickets at the terminal.","She is the kind of customer Ms. Quinlan expected.","She works at BlueWave Ferries."],"answer":2,"type":"연계 문제","explanation":"기사에서 퀸런 씨는 크레인섬에 살면서 포트 홀지에서 일하는 사람들이 주요 고객이 될 것이라 했다. 이메일에서 모건 씨는 매일 아침 크레인섬에서 배를 타고 포트 홀지로 출근하므로 바로 그런 고객이다. 표를 어디서 사는지는 나오지 않는다."}],"translation":"[기사]\n포트 홀지와 크레인섬을 잇는 새 여객선\n\n포트 홀지 (6월 2일) — 포트 홀지와 크레인섬을 오가는 새 여객선 운항이 6월 16일 시작된다. 운전자가 만을 돌아가야 해서 현재 자동차로 약 두 시간이 걸리는 이 구간이 배로는 40분이면 된다.\n\n운항은 이미 북부 해안을 따라 세 개 노선을 운영하고 있는 블루웨이브 페리가 맡는다. 편도 요금은 성인 12달러, 12세 미만 어린이 6달러이다. 자전거는 3달러를 추가로 내면 배에 실을 수 있다.\n\n“크레인섬에 사는 많은 사람들이 포트 홀지에서 일합니다.”라고 블루웨이브의 노라 퀸런 이사는 말했다. “그분들이 저희의 주요 고객이 될 것으로 예상합니다.” 주말 운항은 7월에 추가된다.\n\n[시간표]\n블루웨이브 페리 — 평일 시간표 (6월 16일부터)\n\n포트 홀지 출발 | 크레인섬 도착 | 크레인섬 출발 | 포트 홀지 도착\n오전 6:30 | 오전 7:10 | 오전 7:20 | 오전 8:00\n오전 9:00 | 오전 9:40 | 오전 10:00 | 오전 10:40\n오후 12:30 | 오후 1:10 | 오후 1:30 | 오후 2:10\n오후 5:15 | 오후 5:55 | 오후 6:15 | 오후 6:55\n\n표는 터미널이나 블루웨이브 앱에서 구입할 수 있습니다. 앱 이용자는 10% 할인됩니다.\n\n[이메일]\n보낸 사람: 리아 모건 / 받는 사람: 팀 휴즈 / 날짜: 6월 20일 / 제목: 목요일 오후\n\n안녕하세요, 팀.\n\n좋은 소식이 있어요. 이제 차로 출근하지 않아요! 요즘 매일 아침 크레인섬에서 새 여객선을 타요. 포트 홀지에 8시에 도착해서 8시 30분 전까지 사무실로 걸어갈 시간이 충분해요. 어떤 날은 자전거도 가져가요.\n\n목요일 오후 3시에 섬에서 치과 예약이 있어서 사무실에서 일찍 나가 12시 30분 배를 탈 거예요. 그날 점심 이후에 안내 데스크를 좀 맡아 줄 수 있어요?\n\n고마워요.\n리아","part":7},{"id":"p7-091","level":3,"kind":"single","passages":[{"doc_type":"편지","title":"Page & Quill Stationers / 58 Lambert Street, Ashbury","text":"August 25\n\nDear Valued Customer,\n\nAfter fourteen years at 58 Lambert Street, Page & Quill Stationers is moving. [1] On October 1, we will reopen at 210 Carver Avenue, inside the newly renovated Carver Market building.\n\nOur new store is nearly twice the size of our current one. The extra space will allow us to expand our selection of fine papers and fountain pens and to add a workshop area, where we will hold calligraphy and bookbinding classes. [2] A schedule of classes will be posted on our Web site in September.\n\nTo make the move easier, our current store will close on September 20. [3] During this time, online orders will still be accepted, but they will be shipped after October 1.\n\nWe are also making a change to our loyalty program. Starting October 1, members will earn two points for every dollar spent instead of one. [4] Points earned before the move will not expire.\n\nWe look forward to welcoming you to our new home.\n\nSincerely,\nMartha Keane, Owner"}],"questions":[{"q":"What is the main purpose of the letter?","choices":["To announce a business's relocation","To advertise a new line of pens","To invite customers to a class","To explain a delay in online orders"],"answer":0,"type":"주제·목적","explanation":"첫 단락에서 14년 만에 가게가 이전하며 10월 1일 카버 애비뉴에서 다시 문을 연다고 알렸고, 나머지 내용도 이전에 따른 변화들이다. 수업과 온라인 주문은 세부 내용이다."},{"q":"What is NOT mentioned as a feature of the new store?","choices":["It is larger than the current store.","It will have space for classes.","It will include a café.","It will offer more fountain pens."],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"새 매장은 거의 두 배 크기이고, 만년필 등 상품을 늘리며, 서예·제본 수업 공간이 생긴다고 했다. 카페는 언급되지 않았다."},{"q":"The word “fine” in paragraph 2 is closest in meaning to","choices":["high-quality","thin","acceptable","penalty"],"answer":0,"type":"동의어","explanation":"'fine papers and fountain pens'에서 fine은 '고급의, 질 좋은'이라는 뜻이므로 'high-quality'가 가장 가깝다. fine은 '얇은', '괜찮은', '벌금'이라는 뜻도 있지만 이 문맥에는 맞지 않는다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? “We apologize for any inconvenience this temporary closure may cause.”","choices":["[1]","[2]","[3]","[4]"],"answer":2,"type":"문장 삽입","explanation":"'this temporary closure(이 일시 휴업)'는 9월 20일에 현재 매장을 닫고 10월 1일에 새로 여는 기간을 가리킨다. 따라서 9월 20일 폐점을 알린 문장 바로 뒤 [3]이 알맞다. [1]에서는 아직 휴업 기간이 나오지 않았다."}],"translation":"[편지]\n페이지 앤 퀼 문구점 / 애시버리 램버트가 58번지\n\n8월 25일\n\n소중한 고객님께,\n\n램버트가 58번지에서 14년을 보낸 페이지 앤 퀼 문구점이 이전합니다. 10월 1일, 새로 리모델링한 카버 마켓 건물 안 카버 애비뉴 210번지에서 다시 문을 엽니다.\n\n새 매장은 현재 매장의 거의 두 배 크기입니다. 넓어진 공간 덕분에 고급 종이와 만년필 제품군을 늘리고, 서예와 제본 수업을 열 작업 공간도 마련할 수 있게 되었습니다. 수업 일정은 9월 중 웹사이트에 게시하겠습니다.\n\n원활한 이전을 위해 현재 매장은 9월 20일에 문을 닫습니다. (이 일시 휴업으로 불편을 드리게 된 점 사과드립니다.) 이 기간에도 온라인 주문은 계속 받지만, 배송은 10월 1일 이후에 이루어집니다.\n\n적립 프로그램도 바뀝니다. 10월 1일부터 회원은 1달러를 쓸 때마다 1점이 아닌 2점을 적립하게 됩니다. 이전 전에 적립한 포인트는 소멸되지 않습니다.\n\n새 보금자리에서 여러분을 맞이하기를 기대합니다.\n\n마사 킨, 대표 드림","part":7},{"id":"p7-092","level":3,"kind":"single","passages":[{"doc_type":"온라인 채팅","title":"Online chat discussion","text":"Carmen Ruiz [8:02 A.M.]: Bad news. The shipping company just called. Our display panels for the Chicago Home Show are stuck in Denver because of the snowstorm.\nVictor Hale [8:03 A.M.]: The show opens tomorrow at 10. When will they get here?\nCarmen Ruiz [8:04 A.M.]: Friday at the earliest. That's two days into the show.\nVictor Hale [8:05 A.M.]: We can't have an empty booth on opening day.\nMin-jun Seo [8:07 A.M.]: What if we print large banners here in Chicago? There's a print shop near the convention center that does same-day orders.\nCarmen Ruiz [8:08 A.M.]: That could work. The design files are on the shared drive.\nTessa Blake [8:10 A.M.]: I'll call them now. I used them last year for the Midwest Kitchen Expo, and they did a great job.\nVictor Hale [8:11 A.M.]: Great. Min-jun, can you find out what size the booth walls are? We'll need exact measurements.\nMin-jun Seo [8:12 A.M.]: Already on it. The organizers' floor plan should have them.\nTessa Blake [8:20 A.M.]: The shop can have three banners ready by 5 P.M. today. I'll pick them up myself.\nVictor Hale [8:21 A.M.]: Perfect. Carmen, please tell the shipping company to deliver the panels to the convention center whenever they arrive. We'll put them up then."}],"questions":[{"q":"What problem are the writers discussing?","choices":["A booth was assigned to another company.","Some display materials will arrive late.","The trade show has been postponed.","A print shop made a mistake on an order."],"answer":1,"type":"주제·목적","explanation":"루이스 씨가 시카고 홈 쇼용 전시 패널이 눈보라 때문에 덴버에 묶여 있다고 알리며 대화가 시작된다. 박람회 연기나 인쇄소 실수는 언급되지 않았다."},{"q":"At 8:12 A.M., what does Mr. Seo mean when he writes, “Already on it”?","choices":["He has already started checking the booth size.","He has already placed a print order.","He is already at the convention center.","He already sent the design files."],"answer":0,"type":"의도 파악","explanation":"헤일 씨가 부스 벽 크기를 알아봐 달라고 하자 'Already on it'이라 하고 주최 측 평면도에 나와 있을 것이라고 덧붙였다. 즉 이미 치수를 확인하는 중이라는 뜻이다. 인쇄 주문은 블레이크 씨가 맡았다."},{"q":"What is suggested about Ms. Blake?","choices":["She designed the display panels.","She lives near the convention center.","She has used the print shop before.","She will attend the show only on Friday."],"answer":2,"type":"추론","explanation":"8시 10분에 블레이크 씨는 작년 미드웨스트 키친 엑스포 때 그 인쇄소를 이용했고 일을 잘해 주었다고 했다. 디자인 파일은 공유 드라이브에 있다고만 했을 뿐 누가 만들었는지는 나오지 않는다."},{"q":"What will most likely happen to the display panels?","choices":["They will be sent back to the company's office.","They will be replaced permanently by banners.","They will be stored in Denver until the show ends.","They will be set up after they reach the convention center."],"answer":3,"type":"추론","explanation":"헤일 씨가 마지막에 패널이 도착하는 대로 컨벤션 센터로 배달해 달라고 하며 'We'll put them up then(그때 설치할 것)'이라고 했다. 따라서 배너는 임시 대안이고 패널은 도착 후 설치된다."}],"translation":"[온라인 채팅]\n카르멘 루이스 [오전 8:02]: 안 좋은 소식이에요. 방금 운송 회사에서 전화가 왔는데, 시카고 홈 쇼용 전시 패널이 눈보라 때문에 덴버에 묶여 있대요.\n빅터 헤일 [오전 8:03]: 쇼는 내일 10시에 개막하잖아요. 언제 도착한대요?\n카르멘 루이스 [오전 8:04]: 빨라야 금요일이래요. 쇼가 시작되고 이틀 뒤예요.\n빅터 헤일 [오전 8:05]: 개막일에 부스를 텅 비워 둘 수는 없어요.\n서민준 [오전 8:07]: 여기 시카고에서 대형 배너를 인쇄하면 어때요? 컨벤션 센터 근처에 당일 주문을 해 주는 인쇄소가 있어요.\n카르멘 루이스 [오전 8:08]: 괜찮은 방법이네요. 디자인 파일은 공유 드라이브에 있어요.\n테사 블레이크 [오전 8:10]: 제가 지금 전화할게요. 작년 미드웨스트 키친 엑스포 때 거기를 이용했는데 아주 잘해 줬어요.\n빅터 헤일 [오전 8:11]: 좋아요. 민준 씨, 부스 벽 크기를 알아봐 줄래요? 정확한 치수가 필요해요.\n서민준 [오전 8:12]: 이미 하고 있어요. 주최 측 평면도에 나와 있을 거예요.\n테사 블레이크 [오전 8:20]: 인쇄소에서 오늘 오후 5시까지 배너 세 개를 준비할 수 있대요. 제가 직접 찾아올게요.\n빅터 헤일 [오전 8:21]: 완벽해요. 카르멘, 운송 회사에 패널이 도착하면 언제든 컨벤션 센터로 배달해 달라고 전해 줘요. 그때 설치하죠.","part":7},{"id":"p7-093","level":3,"kind":"single","passages":[{"doc_type":"웹페이지","title":"www.lotusleaftea.com/about","text":"ABOUT LOTUS LEAF TEA COMPANY\n\nLotus Leaf Tea Company was founded in 1998 by siblings Arun and Kavya Mehra, who began by selling teas from their grandfather's estate in Darjeeling at a weekend market in Toronto. [1] Today, we supply more than 400 cafés, hotels, and specialty grocers across Canada.\n\nWe buy directly from 23 small farms in India, Sri Lanka, Japan, and Kenya. By dealing with growers directly, we can pay them above-market prices while keeping our teas affordable. [2] Every spring, a member of our team visits each partner farm to taste the new harvest and review growing practices.\n\nAll of our teas are packed by hand at our warehouse in Mississauga. [3] Since 2019, our packaging has been fully compostable, and in 2022 we replaced our delivery vans with electric vehicles.\n\nBusiness customers can request a free sample box containing up to six teas. [4] For orders of over $500 per month, our wholesale team will also provide staff training on brewing techniques."}],"questions":[{"q":"What is NOT true about Lotus Leaf Tea Company?","choices":["It was started by a brother and sister.","It buys tea from farms in four countries.","Its packaging can be composted.","Its teas are packed by machines."],"answer":3,"type":"사실 확인(NOT/TRUE)","explanation":"세 번째 단락에서 모든 차는 창고에서 손으로 포장한다(packed by hand)고 했으므로 기계 포장은 사실이 아니다. 남매(siblings) 창업, 4개국 농장, 퇴비화 가능한 포장은 모두 사실이다."},{"q":"The word “review” in paragraph 2 is closest in meaning to","choices":["praise","write","examine","repeat"],"answer":2,"type":"동의어","explanation":"'review growing practices'는 재배 방식을 '점검하다, 살펴보다'라는 뜻이므로 'examine'이 가장 가깝다. review에 '비평을 쓰다'라는 뜻도 있지만 농장 방문 문맥에서는 점검의 의미이다."},{"q":"What is suggested about the staff training?","choices":["It is held at the Mississauga warehouse.","It is included in every sample box.","It is offered only to some business customers.","It is led by the company's founders."],"answer":2,"type":"추론","explanation":"마지막 문장에서 월 500달러 넘게 주문하는 경우에 도매팀이 직원 교육을 제공한다고 했으므로 일부 기업 고객에게만 제공된다고 추론할 수 있다. 교육 장소나 강사는 언급되지 않았다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? “Within three years, demand had grown enough for them to open their first shop.”","choices":["[1]","[2]","[3]","[4]"],"answer":0,"type":"문장 삽입","explanation":"주어진 문장은 1998년 주말 시장에서 시작한 뒤 3년 만에 첫 매장을 열었다는 성장 과정이다. 창업 이야기와 '오늘날 400곳 이상에 공급한다'는 현재 이야기 사이인 [1]이 시간 순서상 알맞다."}],"translation":"[웹페이지]\n로터스 리프 티 컴퍼니 소개\n\n로터스 리프 티 컴퍼니는 1998년 아룬 메라와 카비야 메라 남매가 설립했습니다. 두 사람은 할아버지의 다르질링 농원에서 난 차를 토론토의 주말 시장에서 파는 것으로 시작했습니다. (3년 만에 수요가 늘어 첫 매장을 열 수 있었습니다.) 오늘날 저희는 캐나다 전역의 400곳이 넘는 카페, 호텔, 고급 식료품점에 차를 공급합니다.\n\n저희는 인도, 스리랑카, 일본, 케냐의 소규모 농장 23곳에서 직접 차를 구매합니다. 재배자와 직거래하기 때문에 시장 가격보다 높은 값을 치르면서도 차를 적정한 가격에 공급할 수 있습니다. 매년 봄 저희 팀원이 각 협력 농장을 방문해 햇차를 맛보고 재배 방식을 점검합니다.\n\n저희 차는 모두 미시소거 창고에서 손으로 포장합니다. 2019년부터 포장재는 전부 퇴비화가 가능하며, 2022년에는 배송 차량을 전기차로 교체했습니다.\n\n기업 고객은 최대 여섯 가지 차가 담긴 무료 샘플 상자를 요청할 수 있습니다. 월 500달러 넘게 주문하시는 경우 도매팀이 차 우리는 법에 대한 직원 교육도 제공합니다.","part":7},{"id":"p7-094","level":3,"kind":"single","passages":[{"doc_type":"기사","title":"Old Mill Finds New Life as Startup Hub / By Jordan Pike","text":"HARLOW FALLS (August 14) — For nearly a century, the Weston Textile Mill was the largest employer in Harlow Falls. When it closed in 2011, the four-story brick building sat empty, and many residents assumed it would eventually be torn down. [1]\n\nInstead, on Tuesday the mill reopened as the Weston Works Innovation Center, a space where small technology and design companies can rent affordable offices. The $14 million renovation was paid for by a combination of state grants and private investment. [2]\n\nEighteen businesses have already signed leases, filling about 60 percent of the available space. Tenants will share a conference center, a workshop equipped with 3-D printers, and a ground-floor café run by a local bakery. [3]\n\n“We wanted to keep the character of the building,” said project architect Selena Ortiz. The original wooden beams and large factory windows were preserved, and several old weaving machines are displayed in the lobby. [4]\n\nThe center's manager, Paul Gregson, hopes to attract graduates of nearby Clifton University who might otherwise move to larger cities. Applications for the remaining space are being accepted on the center's Web site."}],"questions":[{"q":"What is the article mainly about?","choices":["The history of the textile industry","The opening of a new university","A company moving to a larger city","The reuse of an old factory building"],"answer":3,"type":"주제·목적","explanation":"2011년 문을 닫은 섬유 공장이 소규모 기업용 사무 공간인 혁신 센터로 다시 문을 열었다는 내용이므로 오래된 공장 건물의 재활용이 주제이다. 대학은 인재 유치 대상으로만 언급된다."},{"q":"What is indicated about the renovation?","choices":["It was funded by both public and private sources.","It took fourteen years to complete.","It was designed by a former mill worker.","It removed the building's original windows."],"answer":0,"type":"사실 확인(NOT/TRUE)","explanation":"리모델링 비용 1,400만 달러는 주 정부 보조금과 민간 투자를 합쳐 마련했다(a combination of state grants and private investment)고 했다. 원래 창문은 보존되었고, 14는 기간이 아니라 금액이다."},{"q":"The word “character” in paragraph 4 is closest in meaning to","choices":["letter","distinctive qualities","reputation","main figure"],"answer":1,"type":"동의어","explanation":"'keep the character of the building'은 건물 고유의 '특징, 개성'을 살린다는 뜻이며, 뒤이어 원래 목재 기둥과 창문을 보존했다고 설명한다. 따라서 'distinctive qualities'가 가장 가깝다. character의 '글자', '등장인물' 뜻은 맞지 않는다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? “As a result, some visitors say that walking into the building feels like entering a museum.”","choices":["[1]","[2]","[3]","[4]"],"answer":3,"type":"문장 삽입","explanation":"'As a result(그 결과)' 박물관에 들어가는 느낌이 든다는 것은 원래 목재 기둥과 창문을 보존하고 옛 직조기를 로비에 전시했다는 내용의 결과이다. 따라서 그 문장 바로 뒤인 [4]가 알맞다."}],"translation":"[기사]\n옛 방직 공장, 스타트업 거점으로 새 삶을 찾다 / 조던 파이크 기자\n\n할로 폴스 (8월 14일) — 웨스턴 방직 공장은 거의 한 세기 동안 할로 폴스에서 가장 큰 고용주였다. 2011년 공장이 문을 닫은 뒤 4층짜리 벽돌 건물은 비어 있었고, 많은 주민은 결국 철거될 것이라고 생각했다.\n\n그러나 지난 화요일 이 공장은 소규모 기술·디자인 회사들이 저렴한 사무실을 임대할 수 있는 공간인 ‘웨스턴 웍스 혁신 센터’로 다시 문을 열었다. 1,400만 달러의 리모델링 비용은 주 정부 보조금과 민간 투자를 합쳐 마련했다.\n\n이미 18개 기업이 임대 계약을 맺어 이용 가능한 공간의 약 60%가 찼다. 입주사들은 회의 센터, 3D 프린터를 갖춘 작업장, 그리고 지역 제과점이 운영하는 1층 카페를 함께 사용한다.\n\n“건물의 특징을 지키고 싶었습니다.”라고 프로젝트 건축가 셀레나 오르티스는 말했다. 원래의 목재 기둥과 커다란 공장 창문은 보존되었고, 옛 직조기 몇 대가 로비에 전시되어 있다. (그 결과 일부 방문객은 건물에 들어서면 박물관에 들어가는 느낌이 든다고 말한다.)\n\n센터 관리자 폴 그레그슨은 그러지 않으면 대도시로 떠날 수도 있는 인근 클리프턴 대학 졸업생들을 끌어들이길 바란다. 남은 공간에 대한 입주 신청은 센터 웹사이트에서 받고 있다.","part":7},{"id":"p7-095","level":3,"kind":"double","passages":[{"doc_type":"비교표","title":"Autumn Team Retreat — Venue Options (prepared by Nadia Petrov)","text":"AUTUMN TEAM RETREAT — VENUE OPTIONS\nPrepared by Nadia Petrov, Office Manager\n\nVenue | Travel from office | Capacity | Cost per person (per day) | Notes\nCedar Ridge Lodge | 90 minutes by car | 40 | $110 | Hiking trails; no projector\nLakeview Conference Inn | 45 minutes by train | 60 | $140 | Full audio-visual equipment; lake cruise available\nMillbrook Farm Retreat | 2 hours by car | 50 | $95 | Meals made with farm produce; limited mobile phone signal\nSummit City Hotel (downtown) | 15 minutes by subway | 120 | $160 | Rooftop meeting space\n\nAll prices include meals and meeting space. Overnight rooms are not included."},{"doc_type":"이메일","title":"From: Grant Whitaker / To: Nadia Petrov / Date: August 12 / Subject: Re: Retreat venues","text":"Nadia,\n\nThanks for putting together the comparison. Here are a few points after my talk with the department heads.\n\nWe now expect 48 people, not 35 as originally planned, since the design team will be joining us. Also, the main goal of the retreat is to get people away from the office, so let's rule out anything in the city itself. Several sessions will include video presentations from our overseas partners, so we'll need proper audio-visual equipment. And everyone must be reachable by phone in case of client emergencies.\n\nPlease go ahead and book the venue that meets these needs for October 9 and 10. Our budget allows up to $150 per person per day, so we should be fine.\n\nGrant"}],"questions":[{"q":"Why did Mr. Whitaker write the e-mail?","choices":["To ask Ms. Petrov to compare more venues","To explain why the retreat was canceled","To invite the design team to a meeting","To set requirements and approve a booking"],"answer":3,"type":"주제·목적","explanation":"휘터커 씨는 인원, 장소, 장비, 휴대폰 연결 등 조건을 제시한 뒤 이에 맞는 장소를 예약하라(Please go ahead and book)고 했다. 장소를 더 비교해 달라거나 행사를 취소한다는 내용이 아니다."},{"q":"Which venue will Ms. Petrov most likely book?","choices":["Cedar Ridge Lodge","Lakeview Conference Inn","Millbrook Farm Retreat","Summit City Hotel"],"answer":1,"type":"연계 문제","explanation":"48명을 수용해야 하므로 40명인 시더 리지가 빠지고, 시내 장소는 제외하라고 했으므로 서밋 시티 호텔이 빠진다. 휴대폰 연결이 필요하므로 신호가 약한 밀브룩도 빠진다. 남은 레이크뷰는 60명 수용, 시청각 장비 완비, 1인 140달러로 예산 안이다."},{"q":"Why is Millbrook Farm Retreat NOT suitable?","choices":["It cannot hold 48 people.","It is over budget.","Its mobile phone service is poor.","It is located downtown."],"answer":2,"type":"연계 문제","explanation":"이메일에서 고객 긴급 상황에 대비해 모두 전화로 연락이 되어야 한다고 했는데, 비교표에서 밀브룩은 휴대폰 신호가 약하다(limited mobile phone signal)고 했다. 밀브룩은 50명 수용에 1인 95달러로 인원과 예산 조건은 충족한다."},{"q":"What is indicated about the retreat?","choices":["More people will attend than first expected.","It will be held at the company's office.","Overnight rooms are included in the budget.","It will last three days."],"answer":0,"type":"사실 확인(NOT/TRUE)","explanation":"이메일에서 디자인팀이 합류해 처음 계획한 35명이 아닌 48명이 참석할 것이라고 했다. 일정은 10월 9~10일 이틀이고, 숙박비는 가격에 포함되지 않는다."},{"q":"In the e-mail, the phrase “rule out” in paragraph 2 is closest in meaning to","choices":["exclude","measure","govern","draw"],"answer":0,"type":"동의어","explanation":"'rule out anything in the city itself'는 시내에 있는 장소를 '제외하다'라는 뜻이므로 'exclude'가 가장 가깝다. rule의 '다스리다(govern)', '줄을 긋다(draw)'라는 뜻과 혼동하지 않도록 한다."}],"translation":"[비교표]\n가을 팀 워크숍 — 장소 후보 / 작성: 나디아 페트로프, 총무 담당\n\n장소 | 사무실에서 이동 | 수용 인원 | 1인당 비용(1일) | 비고\n시더 리지 로지 | 차로 90분 | 40명 | 110달러 | 등산로 있음, 프로젝터 없음\n레이크뷰 컨퍼런스 인 | 기차로 45분 | 60명 | 140달러 | 시청각 장비 완비, 호수 유람선 이용 가능\n밀브룩 농장 리트리트 | 차로 2시간 | 50명 | 95달러 | 농장 농산물로 만든 식사, 휴대폰 신호 약함\n서밋 시티 호텔(시내) | 지하철로 15분 | 120명 | 160달러 | 옥상 회의 공간\n\n모든 가격에는 식사와 회의 공간이 포함됩니다. 숙박은 포함되지 않습니다.\n\n[이메일]\n보낸 사람: 그랜트 휘터커 / 받는 사람: 나디아 페트로프 / 날짜: 8월 12일 / 제목: Re: 워크숍 장소\n\n나디아,\n\n비교표를 만들어 줘서 고마워요. 부서장들과 이야기한 뒤 정리한 몇 가지 사항이에요.\n\n디자인팀이 합류하게 되어 처음 계획한 35명이 아니라 48명이 올 것으로 예상해요. 또 워크숍의 주목적은 사람들을 사무실에서 벗어나게 하는 것이니 시내에 있는 곳은 제외합시다. 여러 세션에 해외 협력사의 영상 발표가 있어서 제대로 된 시청각 장비가 필요해요. 그리고 고객 긴급 상황에 대비해 모두 전화 연락이 가능해야 해요.\n\n이 조건에 맞는 장소를 10월 9일과 10일로 예약해 주세요. 예산은 1인당 하루 150달러까지 가능하니 문제없을 거예요.\n\n그랜트","part":7},{"id":"p7-096","level":3,"kind":"double","passages":[{"doc_type":"공고","title":"City of Norwood — Storefront Improvement Grant","text":"CITY OF NORWOOD — STOREFRONT IMPROVEMENT GRANT\n\nThe City of Norwood is now accepting applications for its Storefront Improvement Grant. The program helps small businesses improve the appearance of their buildings on Norwood's main shopping streets.\n\nEligibility:\n• The business must have fewer than 25 employees.\n• The business must be located on Grand Street, Fulton Avenue, or Market Lane.\n• The business must have operated in Norwood for at least two years.\n\nGrants cover 50 percent of project costs, up to a maximum of $10,000. Eligible projects include new signs, exterior painting, window replacement, and outdoor lighting. Interior renovations are not eligible.\n\nApplications, including two contractor estimates, must be submitted by March 31. Recipients will be notified by May 15, and all work must be completed by November 30."},{"doc_type":"이메일","title":"From: Irene Castillo, Castillo Florist / To: grants@norwood.gov / Date: March 18 / Subject: Application questions","text":"Hello,\n\nI own Castillo Florist at 412 Fulton Avenue. We opened in Norwood three years ago and now have 11 employees. I am planning to replace our front windows and install a new sign. One contractor has estimated the total cost at $26,000, and I have a second estimate of $24,000 from another company.\n\nI would also like to remodel the cooler room inside the shop at the same time. Could that be included in my application?\n\nFinally, our busiest season runs from late April through June. Would it be possible to begin the work in July?\n\nIrene Castillo"}],"questions":[{"q":"What is the purpose of the notice?","choices":["To announce a funding program for businesses","To introduce new rules for store signs","To request bids from building contractors","To report on a completed street project"],"answer":0,"type":"주제·목적","explanation":"공고는 소규모 업체의 외관 개선 비용을 지원하는 보조금 신청을 받는다고 알리고 자격과 조건을 설명한다. 간판 규정을 새로 정하거나 시공업체 입찰을 받는 것이 아니다."},{"q":"What is true about Castillo Florist?","choices":["It has too many employees to apply.","It is not on one of the listed streets.","It has operated for less than two years.","It meets all of the eligibility requirements."],"answer":3,"type":"연계 문제","explanation":"공고의 자격 조건은 직원 25명 미만, 지정 거리(풀턴 애비뉴 포함) 위치, 노우드에서 2년 이상 영업이다. 이메일에서 카스티요 꽃집은 직원 11명, 풀턴 애비뉴 412번지, 3년 전 개업이므로 모두 충족한다."},{"q":"If Ms. Castillo uses the lower estimate, what is the largest grant she could receive?","choices":["$12,000","$10,000","$13,000","$24,000"],"answer":1,"type":"연계 문제","explanation":"낮은 견적 24,000달러의 50%는 12,000달러이지만, 공고에 보조금 상한이 10,000달러라고 했으므로 최대 10,000달러를 받을 수 있다. 13,000달러는 높은 견적의 50%이다."},{"q":"What will Ms. Castillo most likely be told about the cooler room?","choices":["It must be finished by May 15.","It needs a third estimate.","It cannot be paid for by the grant.","It will be fully covered."],"answer":2,"type":"연계 문제","explanation":"이메일에서 가게 안 냉장실을 리모델링하고 싶다고 했는데, 공고에 실내 리모델링(Interior renovations)은 지원 대상이 아니라고 했다. 따라서 보조금으로 비용을 댈 수 없다는 답을 받을 것이다."},{"q":"What is suggested about Ms. Castillo's plan to begin work in July?","choices":["It would start after grant recipients are notified.","It would miss the completion deadline.","It would conflict with her busiest season.","It would require a new application."],"answer":0,"type":"추론","explanation":"공고에 수혜자는 5월 15일까지 통보받고 공사는 11월 30일까지 끝내야 한다고 했다. 7월 착공은 통보 이후이고 마감 전까지 시간도 충분하다. 바쁜 시기는 4월 말~6월이므로 7월은 겹치지 않는다."}],"translation":"[공고]\n노우드시 — 점포 외관 개선 보조금\n\n노우드시는 점포 외관 개선 보조금 신청을 받고 있습니다. 이 프로그램은 소규모 업체가 노우드 주요 상가 거리에 있는 건물의 외관을 개선하도록 돕습니다.\n\n자격 요건:\n• 직원이 25명 미만이어야 합니다.\n• 그랜드가, 풀턴 애비뉴, 마켓 레인 중 한 곳에 있어야 합니다.\n• 노우드에서 최소 2년 이상 영업해야 합니다.\n\n보조금은 공사비의 50%를 최대 10,000달러까지 지원합니다. 지원 대상 공사는 새 간판, 외벽 도색, 창문 교체, 옥외 조명입니다. 실내 리모델링은 지원 대상이 아닙니다.\n\n시공업체 견적서 두 부를 포함한 신청서를 3월 31일까지 제출해야 합니다. 선정자는 5월 15일까지 통보받으며, 모든 공사는 11월 30일까지 완료해야 합니다.\n\n[이메일]\n보낸 사람: 아이린 카스티요, 카스티요 꽃집 / 받는 사람: grants@norwood.gov / 날짜: 3월 18일 / 제목: 신청 관련 문의\n\n안녕하세요,\n\n저는 풀턴 애비뉴 412번지에서 카스티요 꽃집을 운영하고 있습니다. 3년 전 노우드에서 문을 열었고 현재 직원은 11명입니다. 가게 앞 창문을 교체하고 새 간판을 달 계획입니다. 한 시공업체는 총비용을 26,000달러로 견적을 냈고, 다른 업체로부터 24,000달러 견적도 받았습니다.\n\n같은 시기에 가게 안 냉장실도 리모델링하고 싶습니다. 이것도 신청에 포함할 수 있을까요?\n\n마지막으로, 저희 가게는 4월 말부터 6월까지가 가장 바쁩니다. 공사를 7월에 시작해도 될까요?\n\n아이린 카스티요","part":7},{"id":"p7-097","level":3,"kind":"double","passages":[{"doc_type":"후기","title":"Review of Northwind Bike Tours ★★★☆☆ — Posted by Lukas Brandt, June 3","text":"My wife and I booked the full-day “Vineyards and Villages” tour for May 28. The route was beautiful, and our guide, Elena, knew a great deal about the region's history. The electric bikes made the hills easy, even for my wife, who hadn't cycled in years.\n\nHowever, a few things were disappointing. The tour description on the Web site promised lunch at a family-run winery, but we ate packed sandwiches by the roadside because, we were told, the winery was closed for a private event. Nobody told us about the change before the tour. Also, the tour ended an hour later than advertised, and we nearly missed our train back to the city.\n\nI'd recommend the scenery and the guide, but the organization needs work."},{"doc_type":"웹페이지 답글","title":"Response from the owner — June 5","text":"Dear Mr. Brandt,\n\nThank you for your detailed review. I'm delighted you enjoyed Elena's commentary; she has been leading our tours for nine years.\n\nYou're right that you should have been told about the lunch change in advance. The winery informed us only the evening before, but we still had time to contact you and failed to do so. We have since set up an automatic text-message system that alerts guests to any last-minute changes.\n\nRegarding the late finish, a flat tire on one of our support vans delayed the group. I understand how stressful that must have been with a train to catch.\n\nI have refunded the difference in price between the lunch we promised and the one we provided, and I'd like to offer you and your wife 30 percent off any future tour. I hope you'll give us another chance.\n\nRolf Jansen, Owner"}],"questions":[{"q":"What did Mr. Brandt like about the tour?","choices":["The lunch at the winery","The guide's knowledge","The early finish","The price of the tour"],"answer":1,"type":"세부 사항","explanation":"후기에서 가이드 엘레나가 지역 역사에 대해 많이 알고 있었다(knew a great deal about the region's history)고 칭찬했다. 와이너리 점심은 취소되었고, 투어는 오히려 늦게 끝났다."},{"q":"What is suggested about Elena?","choices":["She recently joined Northwind Bike Tours.","She owns a family-run winery.","She is an experienced tour guide.","She was driving the support van."],"answer":2,"type":"연계 문제","explanation":"후기에서 엘레나가 지역 역사에 정통했다고 했고, 답글에서 그녀가 9년째 투어를 이끌고 있다고 했으므로 경험 많은 가이드임을 알 수 있다. 최근 입사했다는 것과는 반대이다."},{"q":"According to Mr. Jansen, why did the tour end late?","choices":["A vehicle had a mechanical problem.","The guide took a wrong turn.","The group stopped for a long lunch.","Some riders were too slow on the hills."],"answer":0,"type":"세부 사항","explanation":"답글에서 지원 차량 한 대의 타이어가 펑크 나서(a flat tire on one of our support vans) 일행이 늦어졌다고 했다. 전기 자전거 덕에 언덕은 쉬웠다고 후기에 나와 있다."},{"q":"What change has Northwind Bike Tours made since Mr. Brandt's tour?","choices":["It now serves lunch at a different winery.","It has shortened its full-day tours.","It has hired more guides.","It now informs guests of changes by text message."],"answer":3,"type":"세부 사항","explanation":"답글에서 이후 막판 변경 사항을 고객에게 자동으로 알리는 문자 메시지 시스템을 도입했다고 했다. 이는 점심 변경을 미리 알리지 않았다는 후기의 불만에 대한 조치이다."},{"q":"What is NOT something Mr. Jansen offers Mr. Brandt?","choices":["A partial refund","A discount on a future tour","An apology","Free train tickets"],"answer":3,"type":"사실 확인(NOT/TRUE)","explanation":"얀선 씨는 점심 가격 차액을 환불하고, 다음 투어 30% 할인을 제안했으며, 사전 연락을 못 한 잘못을 인정했다. 기차표 제공은 언급되지 않았다."}],"translation":"[후기]\n노스윈드 자전거 투어 후기 ★★★☆☆ — 루카스 브란트 작성, 6월 3일\n\n아내와 저는 5월 28일 종일 코스인 “포도밭과 마을” 투어를 예약했습니다. 코스는 아름다웠고, 가이드 엘레나는 이 지역 역사에 대해 아주 많이 알고 있었습니다. 전기 자전거 덕분에 몇 년 동안 자전거를 타지 않은 아내도 언덕을 쉽게 올랐습니다.\n\n하지만 실망스러운 점도 몇 가지 있었습니다. 웹사이트의 투어 설명에는 가족이 운영하는 와이너리에서 점심을 먹는다고 되어 있었는데, 와이너리가 개인 행사로 문을 닫았다는 이유로 저희는 길가에서 포장 샌드위치를 먹었습니다. 투어 전에 아무도 이 변경을 알려 주지 않았습니다. 또 투어가 안내된 시간보다 한 시간 늦게 끝나서 시내로 돌아가는 기차를 놓칠 뻔했습니다.\n\n경치와 가이드는 추천하지만, 운영은 개선이 필요합니다.\n\n[웹페이지 답글]\n업체 대표의 답글 — 6월 5일\n\n브란트 씨께,\n\n자세한 후기에 감사드립니다. 엘레나의 해설을 즐기셨다니 기쁩니다. 엘레나는 9년째 저희 투어를 이끌고 있습니다.\n\n점심 변경을 미리 알려 드렸어야 한다는 말씀이 옳습니다. 와이너리가 전날 저녁에야 알려 왔지만, 그래도 연락드릴 시간이 있었는데 그러지 못했습니다. 이후 저희는 막판 변경 사항을 고객에게 알리는 자동 문자 메시지 시스템을 마련했습니다.\n\n늦게 끝난 것은 지원 차량 한 대의 타이어가 펑크 나 일행이 지체되었기 때문입니다. 기차 시간이 있으셨으니 얼마나 초조하셨을지 이해합니다.\n\n약속드린 점심과 실제 제공한 점심의 가격 차액을 환불해 드렸으며, 두 분께 다음 투어 30% 할인을 드리고 싶습니다. 저희에게 다시 한번 기회를 주시길 바랍니다.\n\n롤프 얀선, 대표","part":7},{"id":"p7-098","level":3,"kind":"triple","passages":[{"doc_type":"회의록","title":"Harwick Energy — Communications Team Meeting Minutes, April 3","text":"COMMUNICATIONS TEAM MEETING — MINUTES\nDate: April 3\nAttendees: H. Lindqvist (chair), R. Osei, M. Carrillo, J. Tan\n\n1. Newsletter redesign: The team agreed that the quarterly customer newsletter looks outdated. R. Osei will contact freelance designer Priya Nair, who redesigned our annual report last year, to request a quote.\n2. Budget: H. Lindqvist confirmed that up to $3,000 is available for the redesign. Printing costs are covered by a separate budget.\n3. Timeline: The redesigned summer issue must go to the printer by June 10.\n4. Content: M. Carrillo will collect articles from each department by May 15. J. Tan will arrange new staff photos.\n\nNext meeting: April 17"},{"doc_type":"이메일","title":"From: Rafael Osei / To: Priya Nair / Date: April 4 / Subject: Newsletter redesign","text":"Dear Priya,\n\nYour work on our annual report received so much praise that we would love to work with you again. We are planning to redesign our quarterly customer newsletter, starting with the summer issue. We would need a new layout template, a new cover design, and a set of icons for the regular sections.\n\nYour final files would need to reach us at least one week before our printing deadline.\n\nCould you send us a quote? If possible, please keep in mind that our budget is limited.\n\nBest regards,\nRafael Osei\nHarwick Energy"},{"doc_type":"청구서","title":"Invoice #PN-0612 — Priya Nair Design Studio","text":"INVOICE #PN-0612\nPriya Nair Design Studio\n\nBill to: Harwick Energy, Communications Team, Attn: Rafael Osei\nDate: June 3\n\nLayout template (12 pages) | $1,400\nCover design | $650\nSection icons (set of 8) | $480\nAdditional revisions (2 rounds, requested May 20) | $300\nTotal | $2,830\n\nFinal files were delivered on June 2. Payment is due within 30 days."}],"questions":[{"q":"Why did Mr. Osei send the e-mail?","choices":["To request a price estimate","To approve a final design","To ask for articles for the newsletter","To schedule a photo session"],"answer":0,"type":"주제·목적","explanation":"이메일에서 뉴스레터 개편에 필요한 작업을 설명한 뒤 'Could you send us a quote?'라고 견적을 요청했다. 이는 회의록에서 오세이 씨가 맡은 일(디자이너에게 견적 요청)과 일치한다."},{"q":"What is suggested about Ms. Nair?","choices":["She will write articles for the newsletter.","She has worked for Harwick Energy before.","She attended the meeting on April 3.","She is a full-time Harwick Energy employee."],"answer":1,"type":"추론","explanation":"회의록에 니어 씨는 작년에 회사 연례 보고서를 새로 디자인한 프리랜서라고 나와 있고, 이메일에서도 그 작업이 호평을 받았다고 했다. 따라서 전에 하윅 에너지의 일을 한 적이 있다. 회의 참석자 명단에는 없다."},{"q":"By what date did Mr. Osei want to receive the final files?","choices":["May 15","June 2","June 3","June 10"],"answer":2,"type":"연계 문제","explanation":"이메일에서 인쇄 마감 최소 일주일 전까지 최종 파일을 받아야 한다고 했고, 회의록에서 인쇄 마감은 6월 10일이다. 따라서 6월 3일까지이다. 6월 2일은 실제로 파일이 전달된 날이다."},{"q":"What is indicated about the invoice total?","choices":["It is higher than the approved budget.","It includes printing costs.","It will be paid by Ms. Nair.","It is within the amount approved for the redesign."],"answer":3,"type":"연계 문제","explanation":"회의록에서 개편 예산은 최대 3,000달러였고, 청구서 총액은 2,830달러이므로 예산 범위 안이다. 인쇄비는 별도 예산이며 청구서에도 포함되지 않았다."},{"q":"Which charge on the invoice was NOT part of Mr. Osei's original request?","choices":["The layout template","The cover design","The additional revisions","The section icons"],"answer":2,"type":"연계 문제","explanation":"이메일에서 요청한 것은 레이아웃 템플릿, 표지 디자인, 고정 섹션용 아이콘이다. 청구서의 추가 수정(2회)은 5월 20일에 따로 요청된 것이므로 처음 요청에 없었다."}],"translation":"[회의록]\n하윅 에너지 — 홍보팀 회의록\n날짜: 4월 3일\n참석자: H. 린드크비스트(의장), R. 오세이, M. 카리요, J. 탄\n\n1. 뉴스레터 개편: 분기별 고객 뉴스레터가 낡아 보인다는 데 팀이 동의함. R. 오세이가 작년에 우리 연례 보고서를 새로 디자인한 프리랜서 디자이너 프리야 니어에게 연락해 견적을 요청하기로 함.\n2. 예산: H. 린드크비스트가 개편에 최대 3,000달러를 쓸 수 있다고 확인함. 인쇄비는 별도 예산으로 처리함.\n3. 일정: 개편된 여름호는 6월 10일까지 인쇄소에 넘겨야 함.\n4. 콘텐츠: M. 카리요가 5월 15일까지 각 부서에서 기사를 모음. J. 탄이 새 직원 사진 촬영을 준비함.\n\n다음 회의: 4월 17일\n\n[이메일]\n보낸 사람: 라파엘 오세이 / 받는 사람: 프리야 니어 / 날짜: 4월 4일 / 제목: 뉴스레터 개편\n\n프리야 씨께,\n\n저희 연례 보고서 작업이 아주 좋은 평가를 받아서 다시 함께 일하고 싶습니다. 여름호부터 분기별 고객 뉴스레터를 개편하려고 합니다. 새 레이아웃 템플릿, 새 표지 디자인, 고정 섹션용 아이콘 한 세트가 필요합니다.\n\n최종 파일은 인쇄 마감 최소 일주일 전까지 저희에게 도착해야 합니다.\n\n견적을 보내 주시겠어요? 가능하면 저희 예산이 한정되어 있다는 점을 고려해 주세요.\n\n라파엘 오세이\n하윅 에너지\n\n[청구서]\n청구서 #PN-0612\n프리야 니어 디자인 스튜디오\n\n청구 대상: 하윅 에너지 홍보팀, 라파엘 오세이 앞\n날짜: 6월 3일\n\n레이아웃 템플릿 (12페이지) | 1,400달러\n표지 디자인 | 650달러\n섹션 아이콘 (8개 세트) | 480달러\n추가 수정 (2회, 5월 20일 요청) | 300달러\n합계 | 2,830달러\n\n최종 파일은 6월 2일에 전달되었습니다. 대금은 30일 이내에 지급해 주십시오.","part":7},{"id":"p7-099","level":3,"kind":"triple","passages":[{"doc_type":"웹페이지","title":"www.safekeepstorage.com/units","text":"SAFEKEEP STORAGE — UNIT SIZES AND MONTHLY RATES\n\nSize | Suitable for | Standard | Climate-controlled\nSmall (1.5 m × 1.5 m) | Boxes, seasonal items | $45 | $60\nMedium (3 m × 3 m) | Contents of a one-bedroom apartment | $95 | $125\nLarge (3 m × 6 m) | Office furniture, business inventory | $180 | $230\nExtra Large (6 m × 6 m) | Vehicles, large equipment | $310 | Not available\n\n• Climate-controlled units maintain a temperature between 15°C and 25°C and are recommended for paper documents, electronics, and wooden furniture.\n• Business customers who prepay for 12 months receive two months free.\n• Access hours: 6 A.M.–10 P.M. daily. 24-hour access is available for an extra $15 per month."},{"doc_type":"양식","title":"SafeKeep Storage — Rental Agreement Summary","text":"SAFEKEEP STORAGE — RENTAL AGREEMENT SUMMARY\n\nCustomer: Fenwick Architects (contact: Laura Fenwick)\nUnit number: L-208\nUnit size: Large, climate-controlled\nStart date: February 1\nPayment plan: 12 months, prepaid\nAdditional services: 24-hour access\nAmount paid: $2,480"},{"doc_type":"이메일","title":"From: Laura Fenwick / To: service@safekeepstorage.com / Date: March 9 / Subject: Unit L-208","text":"Hello,\n\nLast month we moved our archive of building plans and several wooden drafting tables into unit L-208, and everything has been fine. However, our office is expanding onto a second floor in May, so we will take the drafting tables back then. After that, we will only be storing boxes of plans, which would fit into a medium unit.\n\nWould it be possible to move to a smaller climate-controlled unit in May without losing the discount on our prepaid plan? Also, our staff sometimes pick up plans late at night before early-morning site visits, so we would like to keep the 24-hour access.\n\nLaura Fenwick"}],"questions":[{"q":"Why did Fenwick Architects most likely choose a climate-controlled unit?","choices":["It is cheaper than a standard unit.","It is the only unit with 24-hour access.","It is recommended for the items they store.","It is the largest size available."],"answer":2,"type":"연계 문제","explanation":"웹페이지에 온도 조절 창고는 종이 문서, 전자제품, 목재 가구에 권장된다고 했고, 이메일에서 펜윅 건축사무소는 건축 도면(종이)과 목재 제도대를 보관한다고 했다. 온도 조절 창고는 일반 창고보다 비싸다."},{"q":"What is indicated about Fenwick Architects' payment?","choices":["It covers only the first six months.","It includes two free months of rent.","It was made on a monthly basis.","It did not include 24-hour access."],"answer":1,"type":"연계 문제","explanation":"웹페이지에 12개월을 선납하는 기업 고객은 두 달을 무료로 받는다고 했고, 계약 요약에 12개월 선납으로 되어 있다. 실제로 230달러×10개월+24시간 이용료 15달러×12개월=2,480달러로 결제액과 일치한다."},{"q":"Why does Ms. Fenwick want to change units?","choices":["Some items will be removed from storage.","The current unit is too small.","The company is moving to another city.","The temperature in the unit is too low."],"answer":0,"type":"세부 사항","explanation":"이메일에서 5월에 사무실이 2층으로 확장되면 제도대를 다시 가져가고 도면 상자만 남으므로 중형 창고로 충분하다고 했다. 현재 창고에 문제가 있다는 말은 없다(everything has been fine)."},{"q":"What is the monthly rate for the type of unit Ms. Fenwick wants to move to, before any extra services?","choices":["$95","$140","$230","$125"],"answer":3,"type":"연계 문제","explanation":"펜윅 씨는 더 작은 온도 조절 창고, 즉 중형(medium) 크기를 원한다. 웹페이지에서 중형 온도 조절 창고는 월 125달러이다. 95달러는 일반 중형이고, 140달러는 24시간 이용료를 더한 금액이다."},{"q":"On the Web page, the word “maintain” in the first note is closest in meaning to","choices":["repair","keep","claim","support"],"answer":1,"type":"동의어","explanation":"'maintain a temperature between 15°C and 25°C'는 온도를 일정 범위로 '유지하다'라는 뜻이므로 'keep'이 가장 가깝다. maintain의 '수리·정비하다(repair)', '주장하다(claim)' 뜻은 이 문맥과 맞지 않는다."}],"translation":"[웹페이지]\n세이프킵 스토리지 — 창고 크기 및 월 요금\n\n크기 | 적합한 물품 | 일반 | 온도 조절\n소형 (1.5m × 1.5m) | 상자, 계절용품 | 45달러 | 60달러\n중형 (3m × 3m) | 침실 1개 아파트 살림 | 95달러 | 125달러\n대형 (3m × 6m) | 사무용 가구, 업무용 재고 | 180달러 | 230달러\n특대형 (6m × 6m) | 차량, 대형 장비 | 310달러 | 없음\n\n• 온도 조절 창고는 15~25°C를 유지하며 종이 문서, 전자제품, 목재 가구 보관에 권장됩니다.\n• 12개월을 선납하는 기업 고객은 두 달을 무료로 이용합니다.\n• 이용 시간: 매일 오전 6시~오후 10시. 24시간 이용은 월 15달러를 추가하면 가능합니다.\n\n[양식]\n세이프킵 스토리지 — 임대 계약 요약\n\n고객: 펜윅 건축사무소 (담당자: 로라 펜윅)\n창고 번호: L-208\n창고 크기: 대형, 온도 조절\n시작일: 2월 1일\n결제 방식: 12개월 선납\n추가 서비스: 24시간 이용\n결제 금액: 2,480달러\n\n[이메일]\n보낸 사람: 로라 펜윅 / 받는 사람: service@safekeepstorage.com / 날짜: 3월 9일 / 제목: L-208 창고\n\n안녕하세요,\n\n지난달 저희 건축 도면 보관 자료와 목재 제도대 몇 개를 L-208 창고로 옮겼는데, 지금까지 아무 문제가 없습니다. 그런데 5월에 사무실이 2층까지 확장되어 그때 제도대를 다시 가져갈 예정입니다. 그 후에는 도면 상자만 보관할 텐데, 중형 창고면 충분할 것 같습니다.\n\n선납 요금제 할인을 잃지 않고 5월에 더 작은 온도 조절 창고로 옮길 수 있을까요? 또한 직원들이 이른 아침 현장 방문 전에 밤늦게 도면을 가지러 가기도 해서 24시간 이용은 유지하고 싶습니다.\n\n로라 펜윅","part":7},{"id":"p7-100","level":3,"kind":"triple","passages":[{"doc_type":"공고","title":"Retail Technology Summit — Call for Speakers","text":"RETAIL TECHNOLOGY SUMMIT — CALL FOR SPEAKERS\n\nThe Retail Technology Summit will take place on November 12 and 13 at the Rosemont Convention Center. We invite retail professionals to propose 30-minute talks on one of this year's themes: in-store technology, online-to-offline shopping, or supply chain data.\n\nProposals should include a title, a 200-word summary, and a short speaker biography. Priority will be given to talks that present real results from a company's own projects rather than general trends. Proposals received by July 31 will be reviewed first; those received after that date will be considered only if spaces remain.\n\nAccepted speakers receive free admission to both days of the summit (a $650 value) and one night's accommodation at the Rosemont Hotel."},{"doc_type":"이메일","title":"From: Daniel Okafor, Hartley Home Stores / To: speakers@rtsummit.com / Date: July 28 / Subject: Speaker proposal","text":"Dear Program Committee,\n\nPlease find attached my proposal, “Smart Shelves: What We Learned in 40 Stores.” Last year, Hartley Home Stores installed shelf sensors that alert staff when products are running low. In my talk, I would share data on how the system changed our restocking times and sales.\n\nI head the operations team at Hartley, and I have spoken at several regional industry events. As I live in Rosemont, I would not need the hotel stay.\n\nBecause of a board meeting, I would be available only on the second day of the summit.\n\nSincerely,\nDaniel Okafor"},{"doc_type":"행사 일정표","title":"Retail Technology Summit — Day 2 Program","text":"RETAIL TECHNOLOGY SUMMIT — DAY 2 PROGRAM\n\n9:00 A.M. | Keynote: “The Store of 2030” — Amelia Crane, Brightline Research\n10:00 A.M. | “Smart Shelves: What We Learned in 40 Stores” — Daniel Okafor, Hartley Home Stores\n10:45 A.M. | “Tracking Every Pallet: Data in the Warehouse” — Sun-hee Park, Kordel Logistics\n11:30 A.M. | Panel: “Click, Then Collect” — moderated by Luis Ferreira\n12:30 P.M. | Lunch (Exhibition Hall B)\n\nNote: The 10:45 session was moved from Day 1 at the speaker's request."}],"questions":[{"q":"What is NOT required in a speaker proposal?","choices":["A title","A summary of the talk","A short biography","A video of a past talk"],"answer":3,"type":"사실 확인(NOT/TRUE)","explanation":"공고에 제안서에는 제목, 200단어 요약, 짧은 발표자 약력이 들어가야 한다고 했다. 과거 발표 영상은 요구하지 않았다."},{"q":"Which of this year's themes does Mr. Okafor's talk most likely address?","choices":["Supply chain data","Online-to-offline shopping","In-store technology","Customer service training"],"answer":2,"type":"연계 문제","explanation":"이메일에서 오카포 씨의 발표는 매장 선반에 설치한 센서로 재고 부족을 알리는 시스템에 관한 것이므로, 공고의 세 주제 중 매장 내 기술(in-store technology)에 해당한다. 창고 데이터를 다루는 박선희 씨의 발표가 공급망 데이터 주제에 가깝다."},{"q":"What is suggested about Mr. Okafor's proposal?","choices":["It was reviewed in the first group of proposals.","It was submitted after the deadline.","It focused on general industry trends.","It was sent by a colleague on his behalf."],"answer":0,"type":"연계 문제","explanation":"공고에 7월 31일까지 받은 제안서를 먼저 검토한다고 했고, 오카포 씨의 이메일은 7월 28일에 보냈으므로 첫 검토 대상이었다. 또 자사 프로젝트의 실제 결과를 다루므로 일반적인 추세 이야기가 아니다."},{"q":"What will Mr. Okafor most likely receive as a speaker?","choices":["Free admission and a hotel room","A hotel room only","Free admission only","A payment of $650"],"answer":2,"type":"연계 문제","explanation":"공고에 발표자는 이틀 무료 입장권과 1박 숙박을 받는다고 했지만, 오카포 씨는 로즈먼트에 살아서 숙박이 필요 없다고 했다. 따라서 무료 입장권만 받을 것이다. 650달러는 입장권의 가치이지 현금 지급이 아니다."},{"q":"What is indicated about Ms. Park?","choices":["She will give the keynote speech.","She originally was scheduled for November 12.","She works for Hartley Home Stores.","She will moderate a panel."],"answer":1,"type":"연계 문제","explanation":"일정표에 10시 45분 세션은 발표자 요청으로 첫째 날에서 옮겨졌다고 했고, 공고에서 첫째 날은 11월 12일이다. 따라서 박 씨의 발표는 원래 11월 12일 예정이었다. 기조연설은 크레인 씨, 패널 사회는 페헤이라 씨이다."}],"translation":"[공고]\n리테일 테크놀로지 서밋 — 발표자 모집\n\n리테일 테크놀로지 서밋이 11월 12일과 13일 로즈먼트 컨벤션 센터에서 열립니다. 소매업 전문가 여러분께 올해의 주제 중 하나로 30분 발표를 제안해 주시기 바랍니다. 주제: 매장 내 기술, 온라인-오프라인 연계 쇼핑, 공급망 데이터.\n\n제안서에는 제목, 200단어 요약, 짧은 발표자 약력이 포함되어야 합니다. 일반적인 추세보다 회사가 직접 진행한 프로젝트의 실제 결과를 소개하는 발표를 우선 선정합니다. 7월 31일까지 접수된 제안서를 먼저 검토하며, 그 이후 접수된 제안서는 자리가 남는 경우에만 검토합니다.\n\n선정된 발표자는 서밋 이틀 무료 입장(650달러 상당)과 로즈먼트 호텔 1박 숙박을 제공받습니다.\n\n[이메일]\n보낸 사람: 대니얼 오카포, 하틀리 홈 스토어스 / 받는 사람: speakers@rtsummit.com / 날짜: 7월 28일 / 제목: 발표 제안\n\n프로그램 위원회 귀중,\n\n제 발표 제안서 “스마트 선반: 40개 매장에서 배운 것”을 첨부합니다. 작년에 하틀리 홈 스토어스는 상품이 떨어져 갈 때 직원에게 알려 주는 선반 센서를 설치했습니다. 발표에서는 이 시스템이 재입고 시간과 매출을 어떻게 바꾸었는지 데이터를 공유하려 합니다.\n\n저는 하틀리의 운영팀을 이끌고 있으며, 여러 지역 업계 행사에서 발표한 경험이 있습니다. 로즈먼트에 살고 있어 호텔 숙박은 필요하지 않습니다.\n\n이사회 회의 때문에 서밋 둘째 날에만 참석할 수 있습니다.\n\n대니얼 오카포 드림\n\n[행사 일정표]\n리테일 테크놀로지 서밋 — 둘째 날 프로그램\n\n오전 9:00 | 기조연설: “2030년의 매장” — 어밀리아 크레인, 브라이트라인 리서치\n오전 10:00 | “스마트 선반: 40개 매장에서 배운 것” — 대니얼 오카포, 하틀리 홈 스토어스\n오전 10:45 | “모든 팰릿 추적하기: 창고 속 데이터” — 박선희, 코델 로지스틱스\n오전 11:30 | 패널 토론: “클릭 후 픽업” — 사회: 루이스 페헤이라\n오후 12:30 | 점심 (전시장 B홀)\n\n참고: 10시 45분 세션은 발표자 요청으로 첫째 날에서 옮겨졌습니다.","part":7},{"id":"p7-101","level":4,"kind":"single","passages":[{"doc_type":"연구 보고서","title":"Summary of Findings — Staggered-Start Pilot / Prepared by: Operations Research Team, Dunmore Mutual Insurance / Date: August 3","text":"From March through June, the claims contact center in Brantford tested a staggered-start schedule. Instead of all 64 agents beginning at 8:00 A.M., agents were divided into three groups starting at 7:00, 8:30, and 10:00 A.M. Closing time was extended from 5:00 to 7:30 P.M. [1]\n\nResults were mixed but largely positive. The average time callers waited on hold fell from 4 minutes 10 seconds to 2 minutes 35 seconds, and the share of calls abandoned before reaching an agent dropped from 11 percent to 6 percent. [2] Evening coverage proved especially valuable: nearly a fifth of all calls during the pilot were received after 5:00 P.M., most from policyholders who said they could not call during their own working hours.\n\nHowever, agents in the 10:00 A.M. group reported feeling disconnected from colleagues, since the weekly team briefing was held at 8:30 A.M. [3] Supervisors also noted that coaching sessions were harder to arrange across three start times.\n\nWe recommend adopting the schedule permanently at Brantford, with two adjustments: moving team briefings to 11:00 A.M., when all three groups are present, and rotating agents among the groups every quarter. [4] The Hamilton center, which handles a similar volume of calls, could begin using the same schedule in January."}],"questions":[{"q":"What is the main purpose of the report?","choices":["To announce the opening of a new contact center","To propose hiring additional agents","To evaluate a trial change in working hours","To compare two call centers' customer ratings"],"answer":2,"type":"주제·목적","explanation":"보고서는 브랜트퍼드 콜센터가 3~6월에 시험한 시차 출근제(staggered-start schedule)의 결과를 정리하고 정식 도입을 권고한다. 새 센터 개설이나 추가 채용, 두 센터의 고객 평가 비교는 다루지 않는다."},{"q":"What is indicated about calls received after 5:00 P.M.?","choices":["Many came from people who were busy earlier in the day.","They were handled mainly by supervisors.","They had longer hold times than morning calls.","They made up about half of all the calls received during the pilot."],"answer":0,"type":"세부 사항","explanation":"둘째 단락에 오후 5시 이후 전화는 전체의 약 5분의 1이며, 대부분 자신의 근무 시간에는 전화할 수 없었다는 가입자들이었다고 나온다. '절반'은 수치가 틀리고, 감독자가 처리했다거나 대기 시간이 길었다는 내용은 없다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“This also meant that they missed announcements that were shared only in person.”","choices":["[1]","[2]","[3]","[4]"],"answer":2,"type":"문장 삽입","explanation":"[3] 앞 문장은 10시 출근조가 오전 8시 30분에 열리는 주간 팀 브리핑 때문에 동료들과 단절감을 느꼈다는 내용이다. 주어 they(10시 조)가 브리핑에 참석하지 못해 대면으로만 전달된 공지를 놓쳤다는 삽입 문장이 이어지기에 자연스럽다."},{"q":"What is NOT mentioned as a result of the pilot?","choices":["Shorter waiting times for callers","Lower overtime costs for the company","Fewer calls ending before an agent answered","Difficulty in scheduling coaching sessions"],"answer":1,"type":"사실 확인(NOT/TRUE)","explanation":"대기 시간 단축(4분 10초→2분 35초), 연결 전 포기 전화 감소(11%→6%), 코칭 일정 조율의 어려움은 모두 언급된다. 초과 근무 비용 절감은 보고서 어디에도 없다."}],"translation":"조사 결과 요약 — 시차 출근 시범 운영 / 작성: 운영 연구팀, 던모어 뮤추얼 보험 / 날짜: 8월 3일\n\n3월부터 6월까지 브랜트퍼드의 보험금 청구 콜센터는 시차 출근 일정을 시험했다. 상담원 64명 전원이 오전 8시에 시작하는 대신, 상담원을 오전 7시, 8시 30분, 10시에 시작하는 세 조로 나누었다. 마감 시간은 오후 5시에서 7시 30분으로 연장되었다. [1]\n\n결과는 엇갈렸지만 대체로 긍정적이었다. 발신자의 평균 대기 시간은 4분 10초에서 2분 35초로 줄었고, 상담원과 연결되기 전에 끊긴 전화의 비율은 11%에서 6%로 떨어졌다. [2] 저녁 시간대 운영이 특히 가치가 있었다. 시범 기간 전체 전화의 약 5분의 1이 오후 5시 이후에 걸려 왔으며, 대부분 자신의 근무 시간에는 전화할 수 없었다고 말한 가입자들이었다.\n\n그러나 10시 조 상담원들은 주간 팀 브리핑이 오전 8시 30분에 열려 동료들과 단절된 느낌을 받았다고 보고했다. [3] (이는 또한 그들이 대면으로만 공유된 공지를 놓쳤다는 뜻이었다.) 감독자들도 세 가지 출근 시간에 걸쳐 코칭 시간을 잡기가 더 어려웠다고 지적했다.\n\n우리는 두 가지를 조정하여 브랜트퍼드에서 이 일정을 정식으로 채택할 것을 권고한다. 세 조가 모두 있는 오전 11시로 팀 브리핑을 옮기고, 분기마다 상담원의 조를 순환시키는 것이다. [4] 비슷한 양의 전화를 처리하는 해밀턴 센터도 1월부터 같은 일정을 시작할 수 있을 것이다.","part":7},{"id":"p7-102","level":4,"kind":"single","passages":[{"doc_type":"온라인 채팅","title":"Online chat discussion — Nadia Farouk, Ben Osei, Carla Reyes","text":"Nadia Farouk [9:02 A.M.]: Heads-up: Polyform Packaging just told us the molded trays for our blenders go up 14 percent on October 1.\nBen Osei [9:04 A.M.]: Ouch. That's for the whole Tessa line?\nNadia Farouk [9:05 A.M.]: All three models. They're blaming the rising cost of resin.\nCarla Reyes [9:07 A.M.]: That wipes out most of what we saved on the new freight contract. Any chance they'd phase it in?\nNadia Farouk [9:09 A.M.]: I asked. They'll hold the current price on anything we order before September 20.\nBen Osei [9:10 A.M.]: Then let's pull the whole fourth-quarter order forward. We have warehouse space now that the Kessler shipment has gone out.\nCarla Reyes [9:12 A.M.]: Not so fast. A full quarter's worth of trays is about $86,000, paid up front. I'd have to borrow from the Q4 marketing budget.\nBen Osei [9:13 A.M.]: What about ordering half now?\nNadia Farouk [9:15 A.M.]: That could work. Meanwhile, Greenloop sent us samples of their paper-pulp trays last spring. They were a bit bulkier, but I think they'd pass our drop tests.\nBen Osei [9:16 A.M.]: Customers have been asking for plastic-free packaging anyway.\nCarla Reyes [9:18 A.M.]: If Greenloop can match what we pay Polyform now, I'm all for it. Nadia, can you get a quote by Friday?\nNadia Farouk [9:19 A.M.]: On it."}],"questions":[{"q":"According to Ms. Farouk, why is Polyform Packaging raising its prices?","choices":["Its freight contract with the carrier has expired and costs more now.","Demand for its trays has grown.","It is redesigning its product line.","The material it uses has become more expensive."],"answer":3,"type":"세부 사항","explanation":"9시 5분에 파루크 씨는 폴리폼이 수지(resin) 가격 상승을 이유로 들었다고 말한다. 운송 계약은 이 회사(화자들)의 계약이며, 수요 증가나 제품 재설계는 언급되지 않는다."},{"q":"At 9:12 A.M., what does Ms. Reyes most likely mean when she writes, “Not so fast”?","choices":["She thinks the warehouse is already full.","She is concerned about the cost of paying for a large order early.","She wants to wait until the price increase is confirmed.","She believes the order must be approved by Polyform first."],"answer":1,"type":"의도 파악","explanation":"오세이 씨가 4분기 물량 전체를 앞당겨 주문하자고 하자 레예스 씨는 이 말 뒤에 한 분기 물량이 약 86,000달러이고 선불이며 마케팅 예산에서 돈을 빌려야 한다고 설명한다. 즉 큰 금액을 미리 지출하는 부담을 우려한 것이다. 창고 공간은 오히려 있다고 했다."},{"q":"At 9:16 A.M., why does Mr. Osei write, “Customers have been asking for plastic-free packaging anyway”?","choices":["To express support for considering another supplier","To explain why sales of the Tessa line have fallen","To suggest that the drop tests should be repeated","To object to the size of Greenloop's trays"],"answer":0,"type":"의도 파악","explanation":"파루크 씨가 그린루프의 종이 펄프 트레이를 대안으로 꺼내자, 오세이 씨는 고객들이 어차피 플라스틱 없는 포장을 원해 왔다고 말하며 그 대안에 힘을 싣는다. 판매 감소, 재시험, 크기에 대한 반대의 뜻은 없다."},{"q":"What will Ms. Farouk most likely do next?","choices":["Cancel the order with Polyform","Arrange for new drop tests","Request pricing from another supplier","Move money from the marketing budget into the order"],"answer":2,"type":"추론","explanation":"레예스 씨가 금요일까지 (그린루프의) 견적을 받아 달라고 하자 파루크 씨는 'On it(바로 하겠다)'이라고 답한다. 폴리폼 주문 취소나 예산 이동은 그녀가 맡은 일이 아니다."}],"translation":"나디아 파루크 [오전 9:02]: 알려 드려요. 폴리폼 패키징이 방금 우리 블렌더용 성형 트레이 가격을 10월 1일부터 14% 올린다고 알려 왔어요.\n벤 오세이 [오전 9:04]: 아이고. 테사 라인 전체요?\n나디아 파루크 [오전 9:05]: 세 모델 모두요. 수지 가격 상승 탓이래요.\n카를라 레예스 [오전 9:07]: 그러면 새 운송 계약으로 절감한 금액 대부분이 날아가요. 단계적으로 올려 줄 가능성은 없나요?\n나디아 파루크 [오전 9:09]: 물어봤어요. 9월 20일 전에 주문하는 건 현재 가격을 유지해 준대요.\n벤 오세이 [오전 9:10]: 그럼 4분기 주문 전체를 앞당깁시다. 케슬러 물량이 나가서 이제 창고 공간이 있어요.\n카를라 레예스 [오전 9:12]: 잠깐만요. 한 분기 분량 트레이면 약 86,000달러를 선불로 내야 해요. 4분기 마케팅 예산에서 빌려 와야 할 거예요.\n벤 오세이 [오전 9:13]: 지금 절반만 주문하면요?\n나디아 파루크 [오전 9:15]: 그건 되겠네요. 그리고 그린루프가 지난봄에 종이 펄프 트레이 샘플을 보내왔어요. 조금 더 부피가 크긴 했지만 우리 낙하 시험은 통과할 것 같아요.\n벤 오세이 [오전 9:16]: 어차피 고객들이 플라스틱 없는 포장을 요청해 왔잖아요.\n카를라 레예스 [오전 9:18]: 그린루프가 지금 폴리폼에 내는 가격을 맞춰 줄 수 있다면 전 대찬성이에요. 나디아, 금요일까지 견적 받아 줄 수 있어요?\n나디아 파루크 [오전 9:19]: 바로 할게요.","part":7},{"id":"p7-103","level":4,"kind":"single","passages":[{"doc_type":"청구서","title":"Invoice #CP-2718 — Castellan Print Works / Client: Norhaven Outdoor Supply / Invoice date: October 3","text":"Description | Quantity | Unit price | Amount\nProduct catalogs, 48 pages, full color | 2,000 | $3.40 | $6,800.00\nOrder forms, single sheet | 2,000 | $0.25 | $500.00\nDesign revisions, third round | 2 hours | $65.00 | $130.00\nSubtotal: $7,430.00\nVolume discount (10% on catalog orders of 2,000 units or more): −$680.00\nRush fee: $0.00\nAmount due: $6,750.00\n\nPayment terms: A 2% discount applies to the amount due if payment is received within 10 days of the invoice date. Otherwise, the full amount is due within 30 days.\n\nNotes: The first two rounds of design revisions are included in the quoted price; additional rounds are billed at our standard hourly rate. Your order was delivered on October 2, one day after the date promised in our quote because of an unexpected press repair. We have therefore removed the rush fee shown in the quote. We apologize for the delay and thank you for your business."}],"questions":[{"q":"How much will Norhaven Outdoor Supply pay if its payment is received on October 10?","choices":["$6,080.00","$6,615.00","$6,750.00","$7,281.40"],"answer":1,"type":"세부 사항","explanation":"청구일(10월 3일)로부터 10일 이내 입금이면 청구액의 2%가 할인된다. 6,750달러 × 0.98 = 6,615달러이다. 7,281.40달러는 할인 전 소계에 2%를 적용한 잘못된 값이다."},{"q":"What is suggested about Norhaven Outdoor Supply?","choices":["It asked for more changes to the design than the quote covered.","It paid a rush fee in advance.","It ordered fewer catalogs than it originally planned to save on printing costs","It has not used Castellan Print Works before."],"answer":0,"type":"추론","explanation":"견적가에는 디자인 수정 두 번까지만 포함되고, 청구서에 '세 번째 수정' 2시간이 따로 청구되었다. 따라서 고객이 견적 범위를 넘는 수정을 요청했음을 알 수 있다. 급행료는 오히려 면제되었다."},{"q":"What is true about the delivery of the order?","choices":["It was delayed at the client's request.","It was split into two shipments.","It arrived later than the printer had promised.","It required an additional delivery charge."],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"비고에 인쇄기 수리로 약속일보다 하루 늦은 10월 2일에 배송되었다고 나온다. 그래서 급행료를 뺐다. 고객 요청 지연, 분할 배송, 추가 배송비는 없다."}],"translation":"청구서 #CP-2718 — 카스텔란 프린트 웍스 / 고객: 노헤이븐 아웃도어 서플라이 / 청구일: 10월 3일\n\n품목 | 수량 | 단가 | 금액\n제품 카탈로그, 48쪽, 풀컬러 | 2,000 | 3.40달러 | 6,800.00달러\n주문서, 낱장 | 2,000 | 0.25달러 | 500.00달러\n디자인 수정, 3차 | 2시간 | 65.00달러 | 130.00달러\n소계: 7,430.00달러\n수량 할인(2,000부 이상 카탈로그 주문 시 10%): −680.00달러\n급행료: 0.00달러\n청구 금액: 6,750.00달러\n\n지불 조건: 청구일로부터 10일 이내에 입금되면 청구 금액의 2%가 할인됩니다. 그렇지 않으면 30일 이내에 전액을 내셔야 합니다.\n\n비고: 디자인 수정 1·2차는 견적가에 포함되어 있으며, 추가 수정은 당사의 표준 시간당 요금으로 청구됩니다. 고객님의 주문은 예기치 못한 인쇄기 수리로 인해 견적서에 약속한 날짜보다 하루 늦은 10월 2일에 배송되었습니다. 따라서 견적서에 표시된 급행료를 삭제했습니다. 지연에 사과드리며 거래에 감사드립니다.","part":7},{"id":"p7-104","level":4,"kind":"single","passages":[{"doc_type":"회람","title":"To: All Employees / From: Mariam Castell, Director of People Operations, Quillon Analytics / Date: May 12 / Subject: Home-office equipment allowance","text":"Beginning June 1, employees approved for hybrid or fully remote work will be eligible for a one-time home-office allowance of up to $600. [1] The allowance may be used for a desk, an ergonomic chair, a monitor, or a headset. Laptops and phones will continue to be issued by the IT department and may not be purchased with the allowance.\n\nTo claim the allowance, submit itemized receipts through the Expenses portal within 60 days of purchase. [2] Items bought before June 1 are not eligible, even if they meet all other requirements. Employees who leave the company within twelve months of receiving the allowance will be asked to return any monitor purchased with it; other items need not be returned.\n\nEmployees who work in the office four or more days per week do not qualify. [3] However, any employee may request an ergonomic assessment from Facilities, regardless of work arrangement. If the assessment recommends specialized equipment, such as a sit-stand desk, the cost will be covered separately and will not count toward the $600 limit. [4]\n\nQuestions may be directed to peopleops@quillon.com."}],"questions":[{"q":"What is the purpose of the memo?","choices":["To remind staff to return company laptops","To introduce a benefit for certain employees","To announce new office furniture at headquarters","To explain changes to the expense portal"],"answer":1,"type":"주제·목적","explanation":"회람은 6월 1일부터 하이브리드·원격 근무 승인자에게 최대 600달러의 재택 사무 장비 지원금을 준다는 새 혜택을 알린다. 노트북 반납, 본사 가구, 경비 포털 변경은 목적이 아니다."},{"q":"What can NOT be purchased with the allowance?","choices":["A headset","A monitor","A laptop computer","An ergonomic chair"],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"책상, 인체공학 의자, 모니터, 헤드셋은 사용할 수 있지만 노트북과 전화기는 IT 부서가 계속 지급하므로 지원금으로 살 수 없다고 명시되어 있다."},{"q":"What is indicated about employees who leave the company within a year of receiving the allowance?","choices":["They must repay the full $600 within thirty days of leaving the company","They may have to give back one type of equipment.","They lose access to ergonomic assessments.","They must submit their receipts again."],"answer":1,"type":"세부 사항","explanation":"지원금을 받은 뒤 12개월 안에 퇴사하면 지원금으로 산 모니터만 반납하고 다른 물품은 반납하지 않아도 된다고 했다. 600달러 전액 상환은 사실이 아니다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“Their workstations are already provided and maintained at our offices.”","choices":["[1]","[2]","[3]","[4]"],"answer":2,"type":"문장 삽입","explanation":"[3] 앞 문장은 주 4일 이상 사무실에서 근무하는 직원은 대상이 아니라는 내용이다. 그들의 업무 공간은 이미 사무실에 마련·관리되어 있다는 문장이 그 이유를 설명하므로 [3]이 알맞다. Their가 가리킬 대상도 바로 앞의 employees다."}],"translation":"수신: 전 직원 / 발신: 마리암 카스텔, 인사 운영 이사, 퀼론 애널리틱스 / 날짜: 5월 12일 / 제목: 재택 사무 장비 지원금\n\n6월 1일부터 하이브리드 또는 전면 원격 근무를 승인받은 직원은 최대 600달러의 1회성 재택 사무 지원금을 받을 수 있습니다. [1] 지원금은 책상, 인체공학 의자, 모니터, 헤드셋 구입에 쓸 수 있습니다. 노트북과 전화기는 계속 IT 부서에서 지급하며 지원금으로 구입할 수 없습니다.\n\n지원금을 청구하려면 구입 후 60일 이내에 경비 포털을 통해 항목별 영수증을 제출하십시오. [2] 6월 1일 이전에 구입한 물품은 다른 요건을 모두 충족하더라도 대상이 아닙니다. 지원금을 받은 뒤 12개월 안에 퇴사하는 직원은 지원금으로 구입한 모니터를 반납해야 하며, 다른 물품은 반납할 필요가 없습니다.\n\n주 4일 이상 사무실에서 근무하는 직원은 해당되지 않습니다. [3] (그들의 업무 공간은 이미 사무실에 마련되어 관리되고 있습니다.) 다만 근무 형태와 관계없이 모든 직원은 시설팀에 인체공학 평가를 요청할 수 있습니다. 평가에서 높이 조절 책상 같은 특수 장비를 권고하면 그 비용은 별도로 지원되며 600달러 한도에 포함되지 않습니다. [4]\n\n문의는 peopleops@quillon.com으로 보내 주십시오.","part":7},{"id":"p7-105","level":4,"kind":"double","passages":[{"doc_type":"제안 요청서","title":"Request for Proposals — Employee Café Operations, Merriweather Biotech, Ashby Campus","text":"Merriweather Biotech invites qualified food-service companies to submit proposals to operate the employee café at our Ashby campus for a three-year term beginning March 1.\n\nScope: breakfast and lunch service, Monday to Friday, for approximately 450 employees on site; catering for up to eight internal events per month.\n\nRequirements:\n• At least two vegetarian hot entrées daily\n• Cashless payment, including payroll deduction\n• Menus reviewed quarterly by a registered dietitian\n\nMerriweather will provide the kitchen, equipment, and utilities at no charge. The operator will pay a monthly concession fee equal to 5 percent of gross sales.\n\nProposals are due by 5:00 P.M. on November 15. Finalists will be invited to host a tasting for our selection panel during the week of December 2. Questions must be submitted in writing to Aaron Pike, Facilities Manager, by November 1."},{"doc_type":"이메일","title":"From: Lucia Brenner, Harvest Table Catering / To: Aaron Pike / Date: October 29 / Subject: RFP question","text":"Dear Mr. Pike,\n\nHarvest Table Catering intends to respond to your request for proposals. We currently run staff cafés for two hospitals in the region, each serving roughly 600 people a day, so the size of your site is well within our experience.\n\nBefore we finalize our pricing, I would like to clarify two points. Our standard model includes a dinner service for employees who work late, which several of our clients value highly. Would a proposal that includes this option be considered, or should we limit it to the services described? We would also like to know whether the 5 percent fee applies to event catering.\n\nFor your information, our in-house nutritionist, a registered dietitian, already reviews all of our menus every month.\n\nBest regards,\nLucia Brenner"}],"questions":[{"q":"What is the purpose of the request for proposals?","choices":["To sell kitchen equipment to local restaurants","To recruit a registered dietitian","To find a company to run a food service","To plan a series of internal events"],"answer":2,"type":"주제·목적","explanation":"메리웨더 바이오테크는 애슈비 캠퍼스 직원 카페를 3년간 운영할 식음료 업체의 제안서를 받는다. 영양사 채용이나 행사 기획이 목적이 아니다."},{"q":"According to the request for proposals, what will Merriweather Biotech provide?","choices":["Payment processing systems","Cooking facilities","Staff for events","Menu planning services"],"answer":1,"type":"세부 사항","explanation":"주방, 장비, 공공요금을 무상으로 제공한다(provide the kitchen, equipment, and utilities at no charge)고 했다. 결제 시스템(비현금 결제)은 운영사가 갖춰야 할 요건이다."},{"q":"What is indicated about Ms. Brenner's e-mail?","choices":["It was sent after proposals were due.","It was sent within the period allowed for questions.","It was addressed to the selection panel rather than to a single named contact","It includes Harvest Table's final pricing."],"answer":1,"type":"연계 문제","explanation":"요청서에 질문은 11월 1일까지 서면으로 에런 파이크에게 보내야 한다고 했고, 브레너 씨의 이메일은 10월 29일에 파이크 씨에게 보내졌다. 따라서 질문 기한 안에 보낸 것이다. 가격은 아직 확정 전이라고 했다."},{"q":"Which requirement does Harvest Table Catering already exceed?","choices":["The number of vegetarian dishes","The size of the workforce served","The type of payment accepted","The frequency of menu reviews"],"answer":3,"type":"연계 문제","explanation":"요청서는 등록 영양사가 분기마다 메뉴를 검토하도록 요구하지만, 이메일에 따르면 하비스트 테이블은 이미 매달 검토한다. 채식 요리나 결제 방식에 대한 언급은 없고, 급식 인원은 요건이 아니라 현장 규모다."},{"q":"In the e-mail, the word “run” in paragraph 1 is closest in meaning to","choices":["manage","hurry","extend","publish"],"answer":0,"type":"동의어","explanation":"'run staff cafés for two hospitals'는 병원 두 곳의 직원 카페를 '운영한다'는 뜻이므로 manage가 가장 가깝다. hurry(서두르다)나 extend(연장하다)는 이 문맥에 맞지 않는다."}],"translation":"[제안 요청서]\n직원 카페 운영 제안 요청 — 메리웨더 바이오테크, 애슈비 캠퍼스\n\n메리웨더 바이오테크는 3월 1일부터 3년간 애슈비 캠퍼스의 직원 카페를 운영할 자격 있는 식음료 업체의 제안서를 받습니다.\n\n범위: 현장 직원 약 450명을 위한 월~금 아침·점심 제공, 월 최대 8회의 사내 행사 케이터링.\n\n요건:\n• 매일 채식 따뜻한 주요리 최소 2가지\n• 급여 공제를 포함한 비현금 결제\n• 등록 영양사의 분기별 메뉴 검토\n\n메리웨더는 주방, 장비, 공공요금을 무상으로 제공합니다. 운영사는 총매출의 5%에 해당하는 월 영업권료를 냅니다.\n\n제안서 마감은 11월 15일 오후 5시입니다. 최종 후보는 12월 2일 주에 선정 위원단을 위한 시식회를 열도록 초청됩니다. 질문은 11월 1일까지 시설 관리자 에런 파이크에게 서면으로 제출해야 합니다.\n\n[이메일]\n발신: 루시아 브레너, 하비스트 테이블 케이터링 / 수신: 에런 파이크 / 날짜: 10월 29일 / 제목: 제안 요청 관련 질문\n\n파이크 씨께,\n\n하비스트 테이블 케이터링은 귀사의 제안 요청에 응할 계획입니다. 저희는 현재 이 지역 병원 두 곳에서 각각 하루 약 600명이 이용하는 직원 카페를 운영하고 있어, 귀사 현장 규모는 충분히 저희 경험 범위 안에 있습니다.\n\n가격을 확정하기 전에 두 가지를 확인하고 싶습니다. 저희 표준 모델에는 늦게까지 일하는 직원을 위한 저녁 식사 서비스가 포함되어 있는데, 여러 고객사가 이를 높이 평가합니다. 이 선택 사항을 포함한 제안서도 검토 대상이 되는지, 아니면 명시된 서비스로만 한정해야 하는지 알려 주십시오. 또한 5% 수수료가 행사 케이터링에도 적용되는지 알고 싶습니다.\n\n참고로 저희 사내 영양 전문가는 등록 영양사로서 이미 모든 메뉴를 매달 검토하고 있습니다.\n\n루시아 브레너 드림","part":7},{"id":"p7-106","level":4,"kind":"double","passages":[{"doc_type":"웹페이지","title":"www.pacifichomeexpo.ca/exhibit — Exhibitor Packages, Pacific Home & Garden Expo (March 14–16)","text":"Standard Booth (3 m × 3 m) — $2,400\nIncludes carpet, one table, two chairs, and a company sign.\n\nCorner Booth (3 m × 3 m, open on two sides) — $2,900\nIncludes everything in the Standard package plus additional lighting.\n\nIsland Booth (6 m × 6 m, open on all four sides) — $8,800\nFurniture is not included.\n\nConditions\n• Exhibitors who book by December 31 receive 10 percent off any package.\n• An electrical connection is included only in the Corner and Island packages. Standard exhibitors may add one for $180.\n• Companies exhibiting at the Expo for the first time may apply for a booth on Innovators' Row, a discounted section offering Standard booths for $1,600. Early-booking discounts do not apply to Innovators' Row.\n• Cancellations made more than 60 days before the Expo are refunded minus a $300 fee. Later cancellations are not refunded."},{"doc_type":"이메일","title":"From: Owen Tate, Greenspire Planters / To: exhibitors@pacifichomeexpo.ca / Date: January 8 / Subject: Booth booking","text":"Hello,\n\nGreenspire Planters would like to reserve a booth at this year's Expo. Although our staff have attended the Expo as visitors for years, this will be the first time we exhibit. We make self-watering planters, and we plan to run a live demonstration using a small water pump, so we will definitely need power at our booth.\n\nWe are a small company and would like to keep our costs down. At the same time, visibility matters a great deal to us, so if possible we'd prefer a location that visitors can approach from more than one side.\n\nCould you tell me what options remain? We are ready to pay a deposit this week.\n\nOwen Tate"}],"questions":[{"q":"In the e-mail, the word “remain” in paragraph 3 is closest in meaning to","choices":["stay unchanged","wait patiently","continue","are still available"],"answer":3,"type":"동의어","explanation":"'what options remain'은 (이미 예약된 것을 제외하고) 어떤 선택지가 '아직 남아 있는지', 즉 이용 가능한지를 묻는 표현이다. stay unchanged(변하지 않다)는 remain의 다른 뜻으로 여기서는 맞지 않는다."},{"q":"What is suggested about Greenspire Planters?","choices":["It is eligible for a booth on Innovators' Row.","It exhibited at last year's Expo.","It has reserved an Island Booth.","It has canceled a previous booking."],"answer":0,"type":"연계 문제","explanation":"웹페이지에 따르면 처음 전시하는 회사는 이노베이터스 로에 지원할 수 있다. 이메일에서 테이트 씨는 방문객으로만 왔고 이번이 첫 전시라고 했으므로 자격이 있다. 작년에 전시한 적은 없다."},{"q":"Why will Greenspire Planters most likely not receive a 10 percent discount?","choices":["It is a small company.","It needs an electrical connection.","It wants a booth open on two sides rather than a standard inline booth","It is booking after the deadline for the discount."],"answer":3,"type":"연계 문제","explanation":"10% 할인은 12월 31일까지 예약한 전시 업체에만 적용되는데, 테이트 씨의 이메일은 1월 8일에 보내졌다. 회사 규모나 전기 필요 여부는 할인 조건과 관계없다."},{"q":"Why does Mr. Tate mention a water pump?","choices":["To explain why his booth will need power","To request a larger booth","To describe a product he plans to sell at the exhibition","To ask about safety regulations"],"answer":0,"type":"세부 사항","explanation":"작은 물 펌프로 시연을 할 계획이라 부스에 전원이 꼭 필요하다(so we will definitely need power)고 했다. 펌프는 판매 제품이 아니라 시연 장비다."},{"q":"If Greenspire Planters takes a booth on Innovators' Row, how much will it most likely pay for the booth and the service it needs?","choices":["$1,600","$2,580","$2,900","$1,780"],"answer":3,"type":"연계 문제","explanation":"이노베이터스 로의 스탠더드 부스는 1,600달러이고, 스탠더드 부스에는 전기가 포함되지 않아 180달러를 추가해야 한다. 이메일에서 전원이 꼭 필요하다고 했으므로 1,600 + 180 = 1,780달러이다. 조기 예약 할인은 이노베이터스 로에 적용되지 않는다."}],"translation":"[웹페이지]\n전시 업체 패키지 — 퍼시픽 홈 앤드 가든 엑스포(3월 14~16일)\n\n스탠더드 부스(3m × 3m) — 2,400달러\n카펫, 테이블 1개, 의자 2개, 회사 간판 포함.\n\n코너 부스(3m × 3m, 두 면 개방) — 2,900달러\n스탠더드 패키지 전체에 추가 조명 포함.\n\n아일랜드 부스(6m × 6m, 네 면 개방) — 8,800달러\n가구 미포함.\n\n조건\n• 12월 31일까지 예약하는 전시 업체는 모든 패키지를 10% 할인받습니다.\n• 전기 연결은 코너와 아일랜드 패키지에만 포함됩니다. 스탠더드 전시 업체는 180달러에 추가할 수 있습니다.\n• 엑스포에 처음 전시하는 회사는 스탠더드 부스를 1,600달러에 제공하는 할인 구역인 '이노베이터스 로'에 지원할 수 있습니다. 조기 예약 할인은 이노베이터스 로에는 적용되지 않습니다.\n• 엑스포 60일 전보다 앞서 취소하면 300달러 수수료를 뺀 금액을 환불합니다. 그 이후 취소는 환불되지 않습니다.\n\n[이메일]\n발신: 오언 테이트, 그린스파이어 플랜터스 / 수신: exhibitors@pacifichomeexpo.ca / 날짜: 1월 8일 / 제목: 부스 예약\n\n안녕하세요.\n\n그린스파이어 플랜터스는 올해 엑스포에 부스를 예약하고 싶습니다. 저희 직원들은 수년간 방문객으로 엑스포에 참석했지만, 전시는 이번이 처음입니다. 저희는 자동 급수 화분을 만드는데, 작은 물 펌프를 이용한 실시간 시연을 할 계획이라 부스에 전원이 꼭 필요합니다.\n\n저희는 작은 회사라 비용을 줄이고 싶습니다. 동시에 눈에 잘 띄는 것이 저희에게 매우 중요하므로, 가능하다면 방문객이 한쪽 이상에서 다가올 수 있는 위치를 원합니다.\n\n어떤 선택지가 남아 있는지 알려 주시겠습니까? 이번 주에 보증금을 낼 준비가 되어 있습니다.\n\n오언 테이트","part":7},{"id":"p7-107","level":4,"kind":"double","passages":[{"doc_type":"재무 요약","title":"Kittering Home Bakeries — Second-Quarter Results Summary (April–June)","text":"Revenue: $18.4 million (up 6% from the same quarter last year)\n• Retail stores: $11.2 million (up 2%)\n• Wholesale to grocery chains: $5.1 million (up 9%)\n• Online orders: $2.1 million (up 31%)\n\nOperating costs rose 8%, driven mainly by a 12% increase in the price of flour and butter. Operating profit was $1.6 million, down from $1.9 million a year earlier.\n\nStore count: 42 (two stores in Leeds closed in May; one store in York opened in June)\n\nOutlook: Management expects ingredient costs to stabilize in the fourth quarter. A new distribution center in Sheffield, scheduled to open in September, is expected to cut delivery costs for wholesale and online orders by about 15%."},{"doc_type":"이메일","title":"From: Priya Nandakumar, Ridgefield Capital / To: investor.relations@kittering.co.uk / Date: July 29 / Subject: Q2 questions","text":"Dear Investor Relations Team,\n\nThank you for the second-quarter summary. I have two questions ahead of the results call on August 5.\n\nFirst, the summary attributes most of the cost increase to ingredients. Were the costs of the two store closures included in the second quarter, or will they appear in the third-quarter figures?\n\nSecond, your fastest-growing channel is still your smallest. Does the Sheffield facility change your targets for that channel, and will it also serve the area around your newest store?\n\nI would also appreciate receiving the presentation slides before the call, if they are available.\n\nKind regards,\nPriya Nandakumar"}],"questions":[{"q":"What is indicated about Kittering Home Bakeries' second quarter?","choices":["Its profit fell even though its revenue grew.","Its wholesale revenue declined.","It opened more stores than it closed.","Its delivery costs fell by 15 percent."],"answer":0,"type":"사실 확인(NOT/TRUE)","explanation":"매출은 6% 늘었지만 영업이익은 190만 달러에서 160만 달러로 줄었다. 도매는 9% 늘었고, 매장은 2곳 폐점·1곳 개점이며, 배송비 15% 절감은 9월 개장 예정인 센터에 대한 전망일 뿐이다."},{"q":"According to the summary, what was the main cause of higher operating costs?","choices":["The opening of a new store","Higher prices for ingredients","Expanded delivery services","The construction of a distribution center"],"answer":1,"type":"세부 사항","explanation":"영업 비용 증가는 주로 밀가루와 버터 가격 12% 상승 때문이라고 했다(driven mainly by a 12% increase in the price of flour and butter)."},{"q":"Which channel does Ms. Nandakumar refer to in her second question?","choices":["Retail stores","Wholesale to grocery chains","Online orders","Corporate catering"],"answer":2,"type":"연계 문제","explanation":"그녀는 '가장 빠르게 성장하지만 여전히 가장 작은 채널'을 언급한다. 요약에서 온라인 주문은 31% 성장으로 가장 빠르고 매출 210만 달러로 가장 작다."},{"q":"Which location does Ms. Nandakumar ask about in connection with the Sheffield facility?","choices":["Leeds","Sheffield","Ridgefield","York"],"answer":3,"type":"연계 문제","explanation":"이메일에서 셰필드 시설이 '가장 최근에 연 매장' 주변 지역도 담당하는지 묻는다. 요약에 따르면 6월에 요크에 매장 1곳이 새로 열렸다. 리즈 매장은 문을 닫았다."},{"q":"What will most likely happen on August 5?","choices":["A new store will open.","Company results will be discussed with investors.","The Sheffield center will begin handling deliveries to stores","Third-quarter figures will be released."],"answer":1,"type":"추론","explanation":"난다쿠마르 씨는 8월 5일 실적 발표 통화(results call) 전에 질문한다고 했으므로 그날 투자자와 실적을 논의하는 자리가 있다. 셰필드 센터는 9월 개장 예정이다."}],"translation":"[재무 요약]\n키터링 홈 베이커리 — 2분기 실적 요약(4~6월)\n\n매출: 1,840만 달러(전년 동기 대비 6% 증가)\n• 소매 매장: 1,120만 달러(2% 증가)\n• 식료품 체인 도매: 510만 달러(9% 증가)\n• 온라인 주문: 210만 달러(31% 증가)\n\n영업 비용은 주로 밀가루와 버터 가격 12% 상승으로 8% 늘었다. 영업이익은 전년 190만 달러에서 줄어든 160만 달러였다.\n\n매장 수: 42개(5월에 리즈 매장 2곳 폐점, 6월에 요크 매장 1곳 개점)\n\n전망: 경영진은 4분기에 원재료 비용이 안정될 것으로 예상한다. 9월 개장 예정인 셰필드의 새 물류 센터는 도매와 온라인 주문의 배송비를 약 15% 줄일 것으로 기대된다.\n\n[이메일]\n발신: 프리야 난다쿠마르, 리지필드 캐피털 / 수신: investor.relations@kittering.co.uk / 날짜: 7월 29일 / 제목: 2분기 관련 질문\n\n투자자 관계팀께,\n\n2분기 요약 자료 감사합니다. 8월 5일 실적 발표 통화에 앞서 두 가지 질문이 있습니다.\n\n첫째, 요약은 비용 증가의 대부분을 원재료 탓으로 돌리고 있습니다. 매장 2곳 폐점 비용이 2분기에 포함되었습니까, 아니면 3분기 수치에 반영됩니까?\n\n둘째, 가장 빠르게 성장하는 채널이 여전히 가장 작습니다. 셰필드 시설로 그 채널의 목표가 달라집니까? 그리고 그 시설이 가장 최근에 연 매장 주변 지역도 담당하게 됩니까?\n\n가능하다면 통화 전에 발표 슬라이드를 받아 보고 싶습니다.\n\n프리야 난다쿠마르 드림","part":7},{"id":"p7-108","level":4,"kind":"triple","passages":[{"doc_type":"견적서","title":"Estimate — Stellar Commercial Movers / Client: Fenwick & Doyle Architects / Move: 220 Harlow Street to 15 Canal Quay / Date: February 2","text":"Packing of files and equipment (2 days) — $3,200\nMoving crew and trucks (Saturday, March 8) — $5,400\nDisassembly and reassembly of 30 workstations — $1,500\nCrating of large-format plotters (2 units) — $600\nTotal estimate: $10,700\n\nNotes: The crew rate above applies to weekend moves. A weekday move reduces the crew-and-truck cost by 15 percent but must begin after 6:00 P.M. Any item valued at more than $5,000 must be declared in writing at least seven days before the move to be covered by our full-value protection. Undeclared items are covered at $10 per kilogram."},{"doc_type":"회람","title":"To: All Staff / From: Gemma Doyle, Managing Partner / Date: February 10 / Subject: Canal Quay move","text":"As you know, we will move to our new office at 15 Canal Quay next month. To keep costs within budget, we have rescheduled the move to the evening of Thursday, March 6, instead of the weekend. Please note the following:\n\n• Pack your personal items in the labeled boxes by noon on March 6. Files and equipment will be packed by the movers.\n• The office will close at 3:00 P.M. that day. Please work from home on Friday, March 7.\n• Hamid Rostami of the IT group will coordinate the move of the two plotters and the server, and he will send the movers the list of high-value items."},{"doc_type":"이메일","title":"From: Hamid Rostami / To: Gemma Doyle / Date: March 11 / Subject: Plotter damage","text":"Gemma,\n\nUnfortunately, one of our plotters arrived at Canal Quay with a cracked print head. Stellar has asked for a copy of our declaration form, and here I have to admit a problem: I didn't send it until March 3. The plotter is valued at $14,000, and the repair quote is $2,300. Stellar says that without a timely declaration it can offer compensation based only on weight, which for a 90-kilogram unit is well below the repair cost.\n\nThe good news is that the server and all the workstations were set up without any issues, and everyone was able to log in on Monday morning. I'll call the manufacturer today to ask about a faster repair.\n\nHamid"}],"questions":[{"q":"According to the estimate, what is a condition of a weekday move?","choices":["It must be completed in one day.","It must start in the evening.","It requires extra packing time.","It is available only for small offices."],"answer":1,"type":"세부 사항","explanation":"견적서 비고에 평일 이사는 인력·트럭 비용이 15% 줄지만 오후 6시 이후에 시작해야 한다고 나온다."},{"q":"How much will Fenwick & Doyle Architects most likely be charged for the moving crew and trucks?","choices":["$9,095","$5,400","$4,590","$4,860"],"answer":2,"type":"연계 문제","explanation":"회람에 따르면 이사를 주말에서 3월 6일 목요일 저녁으로 옮겼다. 견적서상 평일 이사는 인력·트럭 비용 5,400달러가 15% 줄어 5,400 × 0.85 = 4,590달러가 된다. 9,095달러는 총액 전체에 할인을 적용한 잘못된 값이다."},{"q":"Why will the damaged plotter not be covered at its full value?","choices":["It was packed by office staff.","Its value was below the $5,000 threshold for written declaration","It was moved on a weekday.","Its declaration was sent too close to the moving date."],"answer":3,"type":"연계 문제","explanation":"견적서는 5,000달러 초과 물품을 이사 최소 7일 전에 서면 신고해야 전액 보상한다고 했다. 이사일은 3월 6일인데 로스타미 씨는 3월 3일에야 신고서를 보냈으므로 3일 전에 불과했다. 플로터 가격은 14,000달러다."},{"q":"How much compensation will Stellar most likely offer for the plotter?","choices":["$900","$2,300","$1,400","$14,000"],"answer":0,"type":"연계 문제","explanation":"미신고 물품은 킬로그램당 10달러로 보상되며(견적서), 플로터 무게는 90kg이다(이메일). 따라서 90 × 10 = 900달러로, 수리비 2,300달러에 훨씬 못 미친다."},{"q":"In the estimate, the word “declared” is closest in meaning to","choices":["announced publicly","promised","formally reported","proven"],"answer":2,"type":"동의어","explanation":"'must be declared in writing'은 고가 물품을 서면으로 '신고해야' 한다는 뜻이므로 formally reported가 가장 가깝다. announced publicly(공개 발표하다)는 대중에게 알린다는 의미라 맞지 않는다."}],"translation":"[견적서]\n견적서 — 스텔라 상업 이사 / 고객: 펜윅 앤드 도일 건축 / 이사: 할로 스트리트 220번지 → 커낼 키 15번지 / 날짜: 2월 2일\n\n서류 및 장비 포장(2일) — 3,200달러\n이사 인력 및 트럭(3월 8일 토요일) — 5,400달러\n업무용 책상 30개 분해 및 재조립 — 1,500달러\n대형 플로터 나무 상자 포장(2대) — 600달러\n총 견적: 10,700달러\n\n비고: 위의 인력 요금은 주말 이사 기준입니다. 평일 이사는 인력·트럭 비용이 15% 줄지만 오후 6시 이후에 시작해야 합니다. 5,000달러를 넘는 물품은 전액 보상을 받으려면 이사 최소 7일 전에 서면으로 신고해야 합니다. 신고하지 않은 물품은 킬로그램당 10달러로 보상됩니다.\n\n[회람]\n수신: 전 직원 / 발신: 젬마 도일, 대표 파트너 / 날짜: 2월 10일 / 제목: 커낼 키 이전\n\n아시다시피 우리는 다음 달 커낼 키 15번지의 새 사무실로 이전합니다. 예산 안에서 비용을 맞추기 위해 이사를 주말 대신 3월 6일 목요일 저녁으로 변경했습니다. 다음 사항에 유의해 주십시오.\n\n• 3월 6일 정오까지 개인 물품을 라벨이 붙은 상자에 싸 주십시오. 서류와 장비는 이사 업체가 포장합니다.\n• 그날 사무실은 오후 3시에 문을 닫습니다. 3월 7일 금요일에는 재택근무를 해 주십시오.\n• IT팀의 하미드 로스타미가 플로터 2대와 서버 이전을 조율하고, 고가 물품 목록을 이사 업체에 보낼 것입니다.\n\n[이메일]\n발신: 하미드 로스타미 / 수신: 젬마 도일 / 날짜: 3월 11일 / 제목: 플로터 파손\n\n젬마,\n\n안타깝게도 플로터 한 대가 인쇄 헤드에 금이 간 채 커낼 키에 도착했습니다. 스텔라가 우리 신고서 사본을 요청했는데, 여기서 문제를 인정해야겠습니다. 제가 3월 3일에야 신고서를 보냈습니다. 플로터 가격은 14,000달러이고 수리 견적은 2,300달러입니다. 스텔라는 기한 내 신고가 없으면 무게 기준으로만 보상할 수 있다고 하는데, 90킬로그램짜리 장비라 수리비에 한참 못 미칩니다.\n\n좋은 소식은 서버와 모든 업무용 책상이 문제없이 설치되어 월요일 아침 모두 로그인할 수 있었다는 점입니다. 오늘 제조사에 전화해 더 빠른 수리가 가능한지 알아보겠습니다.\n\n하미드","part":7},{"id":"p7-109","level":4,"kind":"triple","passages":[{"doc_type":"웹페이지","title":"www.harbourlightwork.com/membership — Harbourlight Workspace Membership Plans","text":"Flex — $190 per month\n10 day passes per month; access from 8:00 A.M. to 6:00 P.M.\n\nResident — $340 per month\nUnlimited 24-hour access; dedicated desk and locker\n\nStudio — $1,150 per month\nPrivate office for up to four people; 24-hour access; 10 hours of meeting-room time per month\n\nAll plans include Wi-Fi, coffee, and up to 200 printed pages per month. Additional printing is charged at $0.10 per page. Flex and Resident members may book meeting rooms at $25 per hour. Members who pay for twelve months in advance receive two months free."},{"doc_type":"이메일","title":"From: Tomasz Wierzbicki / To: membership@harbourlightwork.com / Date: April 3 / Subject: Changing my plan","text":"Hello,\n\nI've been a Flex member since January. Since my consulting work picked up, I've been using all my passes by the third week of the month, and I've started meeting clients in the evenings, which isn't possible under my current plan. I would like to switch to a plan with round-the-clock access starting this month, but I don't need a private office. I'll be traveling for most of next winter, so please don't sign me up for a full year.\n\nAlso, could you confirm that my April invoice will reflect the change? I had already booked a meeting room for four hours on April 10.\n\nThanks,\nTomasz Wierzbicki"},{"doc_type":"청구서","title":"Invoice — Harbourlight Workspace / Member: Tomasz Wierzbicki / Billing period: April","text":"Resident membership (April) — $340.00\nMeeting room, April 10 (4 hours × $25.00) — $100.00\nPrinting: 350 pages (200 included) — $15.00\nCredit: Flex fee already paid for April — ($190.00)\nTotal due: $265.00"}],"questions":[{"q":"Why does Mr. Wierzbicki want to change his membership?","choices":["He needs to use the space outside regular hours.","He has hired an assistant.","He wants a private office for client meetings.","He will be traveling during the winter."],"answer":0,"type":"세부 사항","explanation":"저녁에 고객을 만나기 시작했는데 현재 플랜(오전 8시~오후 6시)으로는 불가능해 24시간 이용 플랜으로 바꾸고 싶다고 했다. 개인 사무실은 필요 없다고 했고, 겨울 출장은 1년 선납을 원하지 않는 이유다."},{"q":"Why was Mr. Wierzbicki charged for the meeting room?","choices":["He booked it before paying his April membership fee in full","His new plan does not include meeting-room hours.","He used it for more than ten hours.","He booked it on a weekend."],"answer":1,"type":"연계 문제","explanation":"웹페이지에 따르면 회의실 이용 시간은 스튜디오 플랜에만 포함되고, 플렉스·레지던트 회원은 시간당 25달러를 낸다. 청구서상 그는 레지던트로 바꿨으므로 4시간 × 25달러 = 100달러가 청구되었다."},{"q":"Why most likely did Mr. Wierzbicki not receive two free months?","choices":["He changed plans in the middle of the month.","He has been a member for less than a year.","He chose not to pay for a full year in advance.","The offer does not apply to the Resident plan."],"answer":2,"type":"연계 문제","explanation":"12개월을 선납하면 두 달이 무료지만(웹페이지), 그는 다음 겨울 대부분 출장을 가므로 1년 단위로 가입시키지 말라고 했다(이메일). 레지던트 플랜이 제외된다는 말은 없다."},{"q":"What is indicated about Mr. Wierzbicki's printing in April?","choices":["It was included in the monthly Resident fee, with no extra charge","It was charged at a discounted rate.","It was mostly for client meetings.","It exceeded the monthly allowance by 150 pages."],"answer":3,"type":"연계 문제","explanation":"청구서에 350쪽 중 200쪽이 포함되어 있다고 나오므로 150쪽을 초과했다. 웹페이지의 추가 요금 쪽당 0.10달러를 적용하면 150 × 0.10 = 15달러로 청구서 금액과 일치한다."},{"q":"In the e-mail, the phrase “picked up” in paragraph 1 is closest in meaning to","choices":["collected","increased","lifted","answered"],"answer":1,"type":"동의어","explanation":"'my consulting work picked up'은 컨설팅 일이 '늘었다'는 뜻이다. 그래서 이용권을 셋째 주면 다 쓴다고 이어진다. collected(모으다)나 lifted(들어 올리다)는 pick up의 다른 뜻이다."}],"translation":"[웹페이지]\n하버라이트 워크스페이스 멤버십 플랜\n\n플렉스 — 월 190달러\n월 10일 이용권, 오전 8시~오후 6시 이용\n\n레지던트 — 월 340달러\n24시간 무제한 이용, 전용 책상과 사물함\n\n스튜디오 — 월 1,150달러\n최대 4인용 개인 사무실, 24시간 이용, 월 10시간 회의실 이용\n\n모든 플랜에는 와이파이, 커피, 월 200쪽까지의 인쇄가 포함됩니다. 추가 인쇄는 쪽당 0.10달러입니다. 플렉스와 레지던트 회원은 시간당 25달러에 회의실을 예약할 수 있습니다. 12개월을 선납하는 회원은 두 달을 무료로 받습니다.\n\n[이메일]\n발신: 토마시 비에르즈비츠키 / 수신: membership@harbourlightwork.com / 날짜: 4월 3일 / 제목: 플랜 변경\n\n안녕하세요.\n\n저는 1월부터 플렉스 회원입니다. 컨설팅 일이 늘어서 매달 셋째 주면 이용권을 다 쓰고 있고, 저녁에 고객을 만나기 시작했는데 현재 플랜으로는 그게 불가능합니다. 이번 달부터 24시간 이용할 수 있는 플랜으로 바꾸고 싶지만 개인 사무실은 필요 없습니다. 다음 겨울 대부분은 출장을 다닐 예정이니 1년 단위로 가입시키지는 말아 주세요.\n\n또한 4월 청구서에 변경 사항이 반영되는지 확인해 주시겠어요? 4월 10일에 이미 회의실을 4시간 예약해 두었습니다.\n\n감사합니다.\n토마시 비에르즈비츠키\n\n[청구서]\n청구서 — 하버라이트 워크스페이스 / 회원: 토마시 비에르즈비츠키 / 청구 기간: 4월\n\n레지던트 멤버십(4월) — 340.00달러\n회의실, 4월 10일(4시간 × 25.00달러) — 100.00달러\n인쇄: 350쪽(200쪽 포함) — 15.00달러\n차감: 이미 낸 4월 플렉스 요금 — (190.00달러)\n청구 금액: 265.00달러","part":7},{"id":"p7-110","level":4,"kind":"triple","passages":[{"doc_type":"일정표","title":"Carmody Institute — Supply Chain Webinar Series (November)","text":"All sessions last one hour.\n\nTue., Nov. 4, 10:00 A.M. — Demand Forecasting Basics (Dr. Ana Weller)\nThu., Nov. 6, 2:00 P.M. — Negotiating with Overseas Suppliers (Rahul Iyer)\nTue., Nov. 11, 10:00 A.M. — Inventory Metrics That Matter (Dr. Ana Weller)\nThu., Nov. 13, 2:00 P.M. — Customs Compliance Update (Sofia Lindgren)\n\nFees: $75 per session, or $240 for all four. Members of the Carmody Alumni Network pay $60 per session or $200 for all four.\n\nRecordings are available for 14 days, to registered participants only. A certificate of completion is issued only to participants who attend all four sessions live."},{"doc_type":"이메일","title":"From: Registration Office, Carmody Institute / To: Diane Okoro / Date: October 29 / Subject: Registration confirmed","text":"Dear Ms. Okoro,\n\nThank you for registering for the complete Supply Chain Webinar Series. As a member of the Carmody Alumni Network, you have been charged the member rate. Your access link, which is valid for all sessions, appears below.\n\nPlease note that Ms. Lindgren's session has been moved from November 13 to November 14 at 9:00 A.M. because of a scheduling conflict. We apologize for any inconvenience.\n\nAccess link: carmody.edu/live/SC-4471\n\nRegistration Office\nCarmody Institute"},{"doc_type":"문자 메시지","title":"Text-message chain — Diane Okoro, Felix Grant","text":"Diane Okoro [1:48 P.M.]: Felix, I'm logging into the customs webinar now in case you want to join from your desk.\nFelix Grant [1:50 P.M.]: Didn't you see the e-mail?\nDiane Okoro [1:51 P.M.]: What e-mail?\nFelix Grant [1:52 P.M.]: The one from Carmody. That session is tomorrow morning now.\nDiane Okoro [1:53 P.M.]: Oh no. I have the quarterly review with the Delhi team then.\nFelix Grant [1:54 P.M.]: Can't you just watch the recording afterward?\nDiane Okoro [1:56 P.M.]: I could, but then I wouldn't get the certificate. I'll ask Marta whether we can push the review to the afternoon."}],"questions":[{"q":"What is true about the webinar series?","choices":["Each session is led by a different instructor.","Recordings can be viewed by anyone for 14 days.","One instructor leads more than one session.","All sessions begin in the morning."],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"애나 웰러 박사가 11월 4일과 11일 두 세션을 진행한다. 녹화본은 등록자만 볼 수 있고, 2시 세션도 있으므로 다른 선택지는 틀리다."},{"q":"How much less did Ms. Okoro pay than a nonmember registering for the same sessions?","choices":["$15","$60","$100","$40"],"answer":3,"type":"연계 문제","explanation":"이메일에 따르면 오코로 씨는 시리즈 전체를 동문 회원가로 등록했다. 일정표상 네 세션 전체는 비회원 240달러, 회원 200달러이므로 40달러 적게 냈다. 15달러는 한 세션 기준 차이다."},{"q":"At 1:50 P.M., what does Mr. Grant most likely mean when he writes, “Didn't you see the e-mail?”","choices":["He sent Ms. Okoro the access link earlier.","The session is not taking place at that time.","He wants Ms. Okoro to reply to a client.","The webinar has been canceled."],"answer":1,"type":"의도 파악","explanation":"오코로 씨가 세관 웨비나에 접속하려 하자 그랜트 씨는 이메일을 못 봤느냐고 되묻고, 곧 그 세션이 내일 아침으로 바뀌었다고 설명한다. 즉 지금은 세션이 열리지 않는다는 뜻이다. 취소가 아니라 일정 변경이다."},{"q":"What is suggested about Ms. Okoro?","choices":["She has attended the earlier sessions live.","She works in the Delhi office.","She is a speaker in the series.","She registered for only one session in the series"],"answer":0,"type":"연계 문제","explanation":"수료증은 네 세션을 모두 실시간으로 들은 사람에게만 주어진다(일정표). 오코로 씨가 녹화본을 보면 수료증을 못 받는다고 걱정하는 것은 앞의 세 세션을 이미 실시간으로 들었기 때문이라고 추론할 수 있다. 그녀는 전체 시리즈에 등록했다."},{"q":"What will Ms. Okoro most likely do next?","choices":["Watch a recording of the session","Request a refund for one session","Try to reschedule a meeting","Contact Ms. Lindgren"],"answer":2,"type":"추론","explanation":"마지막 메시지에서 마르타에게 분기 검토 회의를 오후로 미룰 수 있는지 물어보겠다고 했다. 녹화본을 보면 수료증을 못 받으므로 그 방법은 택하지 않으려 한다."}],"translation":"[일정표]\n카모디 인스티튜트 — 공급망 웨비나 시리즈(11월)\n\n모든 세션은 1시간입니다.\n\n11월 4일(화) 오전 10시 — 수요 예측 기초(애나 웰러 박사)\n11월 6일(목) 오후 2시 — 해외 공급업체와의 협상(라훌 아이어)\n11월 11일(화) 오전 10시 — 중요한 재고 지표(애나 웰러 박사)\n11월 13일(목) 오후 2시 — 통관 규정 최신 정보(소피아 린드그렌)\n\n수강료: 세션당 75달러, 네 세션 전체 240달러. 카모디 동문 네트워크 회원은 세션당 60달러, 전체 200달러.\n\n녹화본은 등록한 참가자에 한해 14일간 제공됩니다. 수료증은 네 세션을 모두 실시간으로 참석한 참가자에게만 발급됩니다.\n\n[이메일]\n발신: 카모디 인스티튜트 등록처 / 수신: 다이앤 오코로 / 날짜: 10월 29일 / 제목: 등록 확인\n\n오코로 님께,\n\n공급망 웨비나 시리즈 전체에 등록해 주셔서 감사합니다. 카모디 동문 네트워크 회원이시므로 회원가가 청구되었습니다. 모든 세션에 유효한 접속 링크는 아래에 있습니다.\n\n일정 충돌로 인해 린드그렌 씨의 세션이 11월 13일에서 11월 14일 오전 9시로 옮겨졌음을 알려 드립니다. 불편을 드려 죄송합니다.\n\n접속 링크: carmody.edu/live/SC-4471\n\n카모디 인스티튜트 등록처\n\n[문자 메시지]\n다이앤 오코로 [오후 1:48]: 펠릭스, 지금 통관 웨비나에 접속하려는데 자리에서 같이 들을래요?\n펠릭스 그랜트 [오후 1:50]: 이메일 못 봤어요?\n다이앤 오코로 [오후 1:51]: 무슨 이메일이요?\n펠릭스 그랜트 [오후 1:52]: 카모디에서 온 거요. 그 세션은 이제 내일 아침이에요.\n다이앤 오코로 [오후 1:53]: 이런. 그때 델리팀과 분기 검토 회의가 있어요.\n펠릭스 그랜트 [오후 1:54]: 나중에 녹화본을 보면 되지 않아요?\n다이앤 오코로 [오후 1:56]: 그럴 수는 있지만 그러면 수료증을 못 받아요. 마르타에게 검토 회의를 오후로 미룰 수 있는지 물어볼게요.","part":7},{"id":"p7-111","level":5,"kind":"single","passages":[{"doc_type":"계약서","title":"Software Subscription Agreement — Excerpt / Between Novaleaf Systems Ltd. (“Provider”) and Arden & Co. Retail (“Customer”)","text":"4. Term and Renewal\n4.1 The initial term of this Agreement is 24 months from the Effective Date. Thereafter, it will renew automatically for successive 12-month periods unless either party gives written notice of non-renewal at least 90 days before the end of the then-current term.\n4.2 Subscription fees for any renewal term may be increased by no more than the lower of (a) 5 percent or (b) the annual change in the national consumer price index, provided that the Provider notifies the Customer of the increase at least 120 days before the renewal date.\n\n5. Service Levels\n5.1 The Provider will make the platform available 99.5 percent of each calendar month, excluding scheduled maintenance announced at least 48 hours in advance.\n5.2 If availability falls below that level, the Customer will receive a credit against the next invoice equal to 10 percent of that month's fee for each full 0.5 percentage point of shortfall, up to a maximum of 50 percent. Such credits are the Customer's sole financial remedy for unavailability, except as provided in Section 9.\n\n6. Data\n6.1 Upon termination, the Provider will, at the Customer's request made within 30 days, export all Customer data in a standard format at no additional charge. After that period, the Provider may delete the data."}],"questions":[{"q":"If the platform is available 98.4 percent of a month, what credit will the Customer receive?","choices":["20 percent of that month's fee","10 percent of that month's fee","22 percent of that month's fee","50 percent of that month's fee"],"answer":0,"type":"세부 사항","explanation":"기준 99.5%에서 98.4%를 빼면 부족분은 1.1%포인트다. 크레딧은 '완전한' 0.5%포인트마다 10%이므로 0.5포인트 두 개분, 즉 20%다. 22%는 나머지 0.1포인트까지 비례 계산한 잘못된 값이다."},{"q":"If the consumer price index rose by 3.2 percent and the Provider gives notice 150 days before the renewal date, what is the largest fee increase allowed?","choices":["No increase","5 percent","8.2 percent","3.2 percent"],"answer":3,"type":"추론","explanation":"4.2항에 따라 인상 한도는 5%와 물가지수 변동률 중 '낮은 쪽'이므로 3.2%다. 통보도 120일 전보다 앞선 150일 전이므로 요건을 충족해 인상이 가능하다."},{"q":"What is indicated about the Agreement?","choices":["It ends automatically after 24 months.","It continues unless one party chooses to end it.","It allows the Provider to delete data immediately upon termination.","It charges a fee for exporting data."],"answer":1,"type":"사실 확인(NOT/TRUE)","explanation":"최초 24개월 이후 어느 한쪽이 90일 전까지 서면으로 갱신 거절을 통보하지 않으면 12개월씩 자동 갱신된다. 데이터는 종료 후 30일 요청 기간이 지나야 삭제할 수 있고, 추출은 무료다."},{"q":"In section 5.2, the word “sole” is closest in meaning to","choices":["lonely","underlying","only","unique"],"answer":2,"type":"동의어","explanation":"'the Customer's sole financial remedy'는 크레딧이 고객이 받을 수 있는 '유일한' 금전적 구제 수단이라는 뜻이므로 only가 가장 가깝다. unique는 '독특한'이라는 뜻이 강해 이 문맥에 맞지 않는다."}],"translation":"소프트웨어 구독 계약서 — 발췌 / 노바리프 시스템즈(“공급자”)와 아든 앤드 코 리테일(“고객”) 간\n\n4. 기간 및 갱신\n4.1 본 계약의 최초 기간은 발효일로부터 24개월이다. 그 이후에는 어느 한 당사자가 당시 기간 만료 최소 90일 전에 서면으로 갱신 거절을 통보하지 않는 한 12개월 단위로 자동 갱신된다.\n4.2 갱신 기간의 구독료는 (a) 5% 또는 (b) 국가 소비자물가지수의 연간 변동률 중 낮은 쪽을 넘지 않는 범위에서 인상될 수 있다. 단, 공급자는 갱신일 최소 120일 전에 고객에게 인상을 통보해야 한다.\n\n5. 서비스 수준\n5.1 공급자는 최소 48시간 전에 공지한 정기 점검을 제외하고 매월 99.5%의 시간 동안 플랫폼을 이용 가능하게 한다.\n5.2 가용성이 그 수준에 못 미치면, 고객은 부족분 0.5%포인트마다 그달 요금의 10%에 해당하는 크레딧을 다음 청구서에서 받으며, 최대 50%까지로 한다. 이러한 크레딧은 제9조에 규정된 경우를 제외하고 서비스 불가에 대한 고객의 유일한 금전적 구제 수단이다.\n\n6. 데이터\n6.1 계약 종료 시 공급자는 30일 이내에 고객이 요청하면 모든 고객 데이터를 표준 형식으로 추가 비용 없이 추출해 준다. 그 기간이 지나면 공급자는 데이터를 삭제할 수 있다.","part":7},{"id":"p7-112","level":5,"kind":"single","passages":[{"doc_type":"기사","title":"Study Finds Fitting Tools Cut Returns — But Not for Everyone / By Hannah Liebermann","text":"Online clothing retailers have long struggled with return rates that can exceed 30 percent, far higher than in most other retail categories. A new study from the Vestry School of Business suggests that virtual fitting tools, which recommend a size based on a shopper's measurements, can reduce returns substantially, though the benefit is unevenly distributed. [1]\n\nResearchers tracked 1.2 million orders at three mid-sized retailers over eighteen months. Among shoppers who used a fitting tool, the return rate for trousers and jackets fell by nearly a third. For knitwear and loose-fitting items, however, the difference was negligible. [2]\n\nMore surprising was the tools' effect on repeat customers. Shoppers who had previously returned at least two items for sizing reasons were the most likely to use the tools — and the most likely to benefit. [3] First-time buyers, by contrast, often skipped the tool entirely, and those who did use it saw only modest gains.\n\nThe authors caution that fitting tools address only one cause of returns. In surveys, nearly 40 percent of respondents said they had returned items because the color or fabric differed from what they had expected. [4] “Retailers who invest only in sizing technology may be disappointed,” said lead author Dr. Tomas Ekberg. “Better photography and more accurate descriptions matter just as much.”"}],"questions":[{"q":"What is the article mainly about?","choices":["Research on how a technology affects returned merchandise","A retailer's decision to stop accepting returns of worn clothing","Changes in how clothing sizes are labeled","The launch of a new online clothing store"],"answer":0,"type":"주제·목적","explanation":"기사는 가상 피팅 도구가 온라인 의류 반품률에 미치는 영향을 조사한 경영대학원 연구를 소개한다. 반품 중단 결정이나 사이즈 표기 변경, 매장 개점은 다루지 않는다."},{"q":"What is indicated about knitwear?","choices":["It is returned more often than jackets.","It was not included in the study.","Fitting tools had little effect on its return rate.","Most customers buy it without using a size chart."],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"둘째 단락에서 니트웨어와 헐렁한 옷은 피팅 도구 사용 여부에 따른 차이가 '무시할 만했다(negligible)'고 했다. 연구에는 포함되었고, 재킷보다 반품이 많다는 비교는 없다."},{"q":"In paragraph 4, the word “address” is closest in meaning to","choices":["deliver","deal with","label","lecture"],"answer":1,"type":"동의어","explanation":"'fitting tools address only one cause of returns'는 피팅 도구가 반품의 여러 원인 중 하나만 '해결한다/다룬다'는 뜻이므로 deal with가 가장 가깝다. deliver(배달하다), lecture(강연하다)는 address의 다른 뜻과 관련된 함정이다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“This, the researchers believe, is because such shoppers had already learned that standard size charts were unreliable for them.”","choices":["[1]","[2]","[3]","[4]"],"answer":2,"type":"문장 삽입","explanation":"[3] 앞 문장은 사이즈 문제로 두 번 이상 반품한 고객이 도구를 가장 많이 쓰고 가장 큰 효과를 봤다는 내용이다. 삽입 문장의 such shoppers가 이들을 가리키며, 그 이유(표준 사이즈표를 믿을 수 없다는 경험)를 설명하므로 [3]이 알맞다."}],"translation":"연구 결과, 피팅 도구가 반품을 줄이지만 모두에게 그런 것은 아니다 / 해나 리버만 기자\n\n온라인 의류 소매업체들은 대부분의 다른 소매 분야보다 훨씬 높은, 30%를 넘기도 하는 반품률로 오랫동안 어려움을 겪어 왔다. 베스트리 경영대학원의 새 연구는 쇼핑객의 신체 치수를 바탕으로 사이즈를 추천하는 가상 피팅 도구가 반품을 상당히 줄일 수 있지만, 그 혜택이 고르게 분포하지는 않는다고 시사한다. [1]\n\n연구진은 18개월 동안 중형 소매업체 세 곳의 주문 120만 건을 추적했다. 피팅 도구를 사용한 쇼핑객 사이에서 바지와 재킷의 반품률은 거의 3분의 1 줄었다. 그러나 니트웨어와 헐렁한 옷은 차이가 무시할 만한 수준이었다. [2]\n\n더 놀라운 것은 재구매 고객에 대한 효과였다. 이전에 사이즈 문제로 두 개 이상 반품한 적이 있는 쇼핑객이 도구를 사용할 가능성이 가장 높았고, 효과를 볼 가능성도 가장 높았다. [3] (연구진은 이들이 표준 사이즈표가 자신에게 맞지 않는다는 것을 이미 알게 되었기 때문이라고 본다.) 반면 첫 구매자는 도구를 아예 건너뛰는 경우가 많았고, 사용한 사람도 효과가 크지 않았다.\n\n저자들은 피팅 도구가 반품 원인 중 하나만 해결한다고 경고한다. 설문에서 응답자의 약 40%는 색상이나 원단이 예상과 달라 반품한 적이 있다고 답했다. [4] 제1저자 토마스 에크베리 박사는 “사이즈 기술에만 투자하는 소매업체는 실망할 수 있다”며 “더 나은 사진과 더 정확한 설명도 똑같이 중요하다”고 말했다.","part":7},{"id":"p7-113","level":5,"kind":"single","passages":[{"doc_type":"온라인 채팅","title":"Online chat discussion — Joanna Pryce, Kwame Asante, Stefan Moll, Lin Feng","text":"Joanna Pryce [10:14 A.M.]: The lab has confirmed it. The latches on batch 2207 of the Orbit strollers can open under load. We need to stop all shipments of that batch today.\nKwame Asante [10:16 A.M.]: Batch 2207 went to three distributors. Two still have most of it in their warehouses. The third, Brightlane, has already delivered to stores.\nStefan Moll [10:18 A.M.]: Under the regulations, we must notify the product safety authority within two business days of confirming a defect. So Thursday at the latest.\nLin Feng [10:19 A.M.]: And customers? My team will get calls the minute this is public.\nJoanna Pryce [10:21 A.M.]: We'll offer free replacement latches. The fix takes five minutes with a screwdriver.\nStefan Moll [10:22 A.M.]: I'd be careful there. If we ask parents to do the repair themselves and one goes wrong...\nJoanna Pryce [10:23 A.M.]: Point taken. Kwame, could the stores do the swap?\nKwame Asante [10:25 A.M.]: Brightlane's stores could, if we get them the parts by next week. Our supplier has 4,000 latches ready, but batch 2207 was 6,500 units.\nLin Feng [10:26 A.M.]: Then people who've already bought one come first. Stock in warehouses can wait.\nJoanna Pryce [10:27 A.M.]: Agreed. Lin, please draft a script for customer calls and send it to Stefan before anything goes out.\nStefan Moll [10:28 A.M.]: I'll have comments back within an hour of receiving it."}],"questions":[{"q":"What problem are the writers discussing?","choices":["A shipment was sent to the wrong distributor.","A part of a product may fail.","A lab test was delayed.","A supplier has stopped making latches."],"answer":1,"type":"세부 사항","explanation":"프라이스 씨가 첫 메시지에서 2207 배치 유모차의 잠금 걸쇠가 하중을 받으면 열릴 수 있다고 실험실이 확인했다고 말한다. 공급업체는 오히려 걸쇠 4,000개를 준비해 두었다."},{"q":"At 10:22 A.M., what does Mr. Moll imply when he writes, “I'd be careful there”?","choices":["He doubts that the repair takes only five minutes.","He thinks the replacement latches are too expensive.","He is worried about the risks of customers making repairs themselves.","He wants to delay the announcement until Thursday."],"answer":2,"type":"의도 파악","explanation":"프라이스 씨가 드라이버로 5분이면 되는 수리라며 교체 걸쇠를 제공하자고 하자, 몰 씨는 이렇게 말한 뒤 부모에게 직접 수리를 맡겼다가 잘못되는 경우를 언급한다. 즉 고객 자가 수리의 위험을 우려한 것이다. 그래서 프라이스 씨가 매장에서 교체할 수 있는지 묻는다."},{"q":"At 10:26 A.M., why most likely does Ms. Feng write, “Stock in warehouses can wait”?","choices":["There are not enough replacement parts for every affected unit.","The distributors have refused to return their stock.","Warehouse staff are not trained to install the parts.","The warehouses will be closed until next week."],"answer":0,"type":"의도 파악","explanation":"아산테 씨가 걸쇠는 4,000개뿐인데 배치 물량은 6,500대라고 하자, 펑 씨는 이미 구매한 고객을 우선하고 창고 재고는 나중에 처리하자고 한다. 부품이 모든 물량에 부족하기 때문에 우선순위를 정한 것이다."},{"q":"On what day does the online chat most likely take place?","choices":["Monday","Wednesday","Thursday","Tuesday"],"answer":3,"type":"추론","explanation":"몰 씨는 결함을 확인한 뒤 영업일 기준 2일 이내에 신고해야 하므로 '늦어도 목요일'이라고 했다. 결함은 오늘 확인되었으므로(The lab has confirmed it), 오늘부터 2영업일 뒤가 목요일인 날은 화요일이다."}],"translation":"조애나 프라이스 [오전 10:14]: 실험실에서 확인했어요. 오빗 유모차 2207 배치의 잠금 걸쇠가 하중을 받으면 열릴 수 있대요. 오늘 그 배치의 출고를 모두 멈춰야 해요.\n콰메 아산테 [오전 10:16]: 2207 배치는 유통업체 세 곳에 갔어요. 두 곳은 아직 대부분을 창고에 갖고 있어요. 세 번째인 브라이트레인은 이미 매장에 납품했어요.\n슈테판 몰 [오전 10:18]: 규정상 결함을 확인한 뒤 영업일 기준 2일 이내에 제품안전 당국에 신고해야 해요. 그러니 늦어도 목요일이에요.\n린 펑 [오전 10:19]: 고객은요? 이게 알려지는 순간 우리 팀에 전화가 올 거예요.\n조애나 프라이스 [오전 10:21]: 교체용 걸쇠를 무료로 제공할 거예요. 드라이버로 5분이면 고칠 수 있어요.\n슈테판 몰 [오전 10:22]: 그건 조심해야 해요. 부모들에게 직접 수리하라고 했다가 하나라도 잘못되면...\n조애나 프라이스 [오전 10:23]: 일리 있네요. 콰메, 매장에서 교체해 줄 수 있을까요?\n콰메 아산테 [오전 10:25]: 다음 주까지 부품을 보내 주면 브라이트레인 매장은 할 수 있어요. 공급업체에 걸쇠 4,000개가 준비되어 있지만 2207 배치는 6,500대였어요.\n린 펑 [오전 10:26]: 그럼 이미 구매한 분들이 먼저예요. 창고 재고는 기다려도 돼요.\n조애나 프라이스 [오전 10:27]: 동의해요. 린, 고객 전화 응대 스크립트 초안을 써서 뭐든 나가기 전에 슈테판에게 보내 주세요.\n슈테판 몰 [오전 10:28]: 받으면 한 시간 안에 의견 드릴게요.","part":7},{"id":"p7-114","level":5,"kind":"single","passages":[{"doc_type":"회람","title":"To: All Staff / From: Imogen Vance, Chief Operating Officer, Lattimer Consulting / Date: December 2 / Subject: Revised travel policy","text":"Following the board's decision to cut our business-travel emissions by 25 percent by the end of next year, the following changes to the travel policy will take effect on January 1. [1]\n\nFirst, each practice group will receive an annual carbon budget, measured in tonnes of CO2, equal to its average travel emissions over the past three years minus 25 percent. Group leaders will receive monthly reports showing how much of their budget has been used. [2]\n\nSecond, rail travel will be mandatory for any trip on which the train journey takes five hours or less, regardless of fare. Exceptions require written approval from the group leader and will be reviewed quarterly.\n\nThird, business-class air travel will be limited to flights of more than nine hours. [3] The current threshold is six hours.\n\nGroups that finish the year under budget may carry up to half of the unused amount into the following year. Groups that exceed their budget will not face penalties this year, but their leaders will be asked to present a reduction plan to the operations committee. [4]\n\nTravel booked before January 1 will be honored under the current policy, even for trips taking place after that date."}],"questions":[{"q":"Why was the memo written?","choices":["To explain how a company target will be put into practice","To announce the results of an emissions audit","To request suggestions for reducing travel costs","To introduce a new travel booking service"],"answer":0,"type":"주제·목적","explanation":"이사회가 정한 출장 배출량 25% 감축 목표를 실행하기 위해 1월 1일부터 바뀌는 출장 규정(탄소 예산, 철도 의무화, 비즈니스석 제한)을 설명하는 회람이다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“Travel for client projects will be counted against the budget of the group that manages the client relationship.”","choices":["[1]","[2]","[3]","[4]"],"answer":1,"type":"문장 삽입","explanation":"[2] 앞에서 부서(프랙티스 그룹)별 연간 탄소 예산과 사용량 보고를 설명한다. 고객 프로젝트 출장이 어느 그룹 예산에서 차감되는지 정하는 문장은 이 예산 설명에 이어지는 것이 자연스럽다."},{"q":"What is suggested about a seven-hour flight that is booked on December 20 for a trip in March?","choices":["It must be replaced by rail travel.","It requires the group leader's written approval.","It may be taken in business class.","It will not count toward any group's budget."],"answer":2,"type":"추론","explanation":"1월 1일 이전에 예약한 출장은 현행 규정을 따르고, 현행 규정의 비즈니스석 기준은 6시간이다. 따라서 12월 20일에 예약한 7시간 비행은 3월 출장이라도 비즈니스석을 이용할 수 있다. 새 기준(9시간 초과)은 적용되지 않는다."},{"q":"In the last paragraph, the word “honored” is closest in meaning to","choices":["praised","awarded","respected personally","accepted as valid"],"answer":3,"type":"동의어","explanation":"'Travel booked before January 1 will be honored under the current policy'는 기존 예약이 현행 규정에 따라 '유효한 것으로 인정된다'는 뜻이다. praised(칭찬받다)나 awarded(수여되다)는 honor의 다른 뜻이다."}],"translation":"수신: 전 직원 / 발신: 이모젠 밴스, 최고운영책임자, 래티머 컨설팅 / 날짜: 12월 2일 / 제목: 출장 규정 개정\n\n내년 말까지 출장 배출량을 25% 줄이기로 한 이사회 결정에 따라, 다음과 같은 출장 규정 변경이 1월 1일부터 시행됩니다. [1]\n\n첫째, 각 프랙티스 그룹은 이산화탄소 톤 단위로 측정한 연간 탄소 예산을 받으며, 이는 지난 3년간 평균 출장 배출량에서 25%를 뺀 양입니다. 그룹장은 예산 사용량을 보여 주는 월간 보고서를 받게 됩니다. [2] (고객 프로젝트 출장은 해당 고객 관계를 관리하는 그룹의 예산에서 차감됩니다.)\n\n둘째, 기차로 5시간 이하 걸리는 출장은 요금과 관계없이 철도 이용이 의무입니다. 예외는 그룹장의 서면 승인이 필요하며 분기마다 검토됩니다.\n\n셋째, 비즈니스석 항공 이용은 9시간을 넘는 비행으로 제한됩니다. [3] 현재 기준은 6시간입니다.\n\n연말에 예산보다 적게 쓴 그룹은 남은 양의 절반까지 다음 해로 이월할 수 있습니다. 예산을 초과한 그룹은 올해에는 불이익을 받지 않지만, 그룹장은 운영위원회에 감축 계획을 발표해야 합니다. [4]\n\n1월 1일 이전에 예약한 출장은 그 이후에 이루어지더라도 현행 규정에 따라 인정됩니다.","part":7},{"id":"p7-115","level":5,"kind":"double","passages":[{"doc_type":"재무 요약","title":"Aldermoor Springs plc — Full-Year Results Summary","text":"Net sales: £142.6 million (previous year: £131.0 million), up 8.9%\nVolume: 612 million litres (previous year: 598 million)\nGross margin: 38.1% (previous year: 40.4%)\nOperating profit: £17.2 million (previous year: £18.9 million)\nDividend per share: 6.0p (previous year: 6.0p)\n\nChair's commentary: Sales growth was driven chiefly by price increases in our premium glass-bottle range, which now accounts for 27% of net sales. Margins came under pressure from a 22% rise in the cost of glass and from one-off expenses of £2.3 million related to the closure of our Fellbridge bottling line. Excluding those one-off costs, operating profit would have risen modestly. The Board has decided to hold the dividend flat and to direct surplus cash toward a new returnable-bottle facility in Kendal, due to open in the second half of next year."},{"doc_type":"이메일","title":"From: Gordon Achterberg / To: Company Secretary, Aldermoor Springs plc / Date: March 14 / Subject: Question for the annual general meeting","text":"Dear Sir or Madam,\n\nAs a shareholder of some twenty years, I will attend the annual general meeting on April 9, and I would like the following question put to the Board.\n\nThe results summary shows that sales volume grew by only about two percent, while net sales rose far faster. I understand that premium products carry higher prices, but I am concerned that the company is relying on price rather than on attracting new customers. Is the Board confident that its higher prices can be sustained if competitors do not follow?\n\nI am also disappointed that the dividend has not increased, for the first time in over a decade. I would ask the Board to confirm that this is a temporary decision tied to the investment it describes, and not a change in policy.\n\nYours faithfully,\nGordon Achterberg"}],"questions":[{"q":"What is indicated in the results summary?","choices":["Operating profit was lower than in the previous year.","Gross margin improved.","Sales volume declined.","The dividend per share was reduced to fund the new Kendal facility"],"answer":0,"type":"사실 확인(NOT/TRUE)","explanation":"영업이익은 전년 1,890만 파운드에서 1,720만 파운드로 줄었다. 매출총이익률은 40.4%에서 38.1%로 낮아졌고, 판매량은 늘었으며, 배당은 6.0펜스로 동결되었다."},{"q":"According to the summary, what is one reason margins were lower?","choices":["Sales of the premium range fell sharply during the year.","A new facility opened in Kendal.","Packaging material became more expensive.","The company lowered its prices."],"answer":2,"type":"세부 사항","explanation":"의장 논평에 유리 가격 22% 상승과 펠브리지 병입 라인 폐쇄에 따른 일회성 비용이 이익률을 압박했다고 나온다. 유리는 병(포장재) 재료다. 켄달 시설은 내년 하반기 개장 예정이다."},{"q":"What does Mr. Achterberg want the Board to confirm about the dividend?","choices":["That it will be paid earlier than usual","That it will rise next year by a fixed amount","That it was reduced because of lower sales","That it is linked to building a returnable-bottle plant"],"answer":3,"type":"연계 문제","explanation":"그는 배당 동결이 '이사회가 설명한 투자'와 연결된 일시적 결정인지 확인해 달라고 했다. 요약에 따르면 이사회는 잉여 현금을 켄달의 재사용 병 시설에 투입하기로 했다. 배당은 삭감이 아니라 동결이다."},{"q":"Which part of the business is Mr. Achterberg most likely concerned about?","choices":["The Fellbridge bottling line","The premium glass-bottle range","The returnable-bottle facility","The company's overseas sales"],"answer":1,"type":"연계 문제","explanation":"그는 판매량보다 매출이 훨씬 빨리 늘어 회사가 가격에 의존한다고 우려한다. 요약에 따르면 매출 성장은 주로 프리미엄 유리병 제품군의 가격 인상에서 나왔으므로 그의 걱정은 이 제품군의 가격 유지 가능성이다."},{"q":"In the e-mail, the word “sustained” in paragraph 2 is closest in meaning to","choices":["supported physically","suffered","maintained","confirmed"],"answer":2,"type":"동의어","explanation":"'higher prices can be sustained'는 높은 가격이 경쟁사가 따라오지 않아도 '유지될' 수 있느냐는 뜻이므로 maintained가 가장 가깝다. suffered(입다, 겪다)는 sustain damage 같은 다른 용법에서 온 함정이다."}],"translation":"[재무 요약]\n올더무어 스프링스 — 연간 실적 요약\n\n순매출: 1억 4,260만 파운드(전년 1억 3,100만 파운드), 8.9% 증가\n판매량: 6억 1,200만 리터(전년 5억 9,800만 리터)\n매출총이익률: 38.1%(전년 40.4%)\n영업이익: 1,720만 파운드(전년 1,890만 파운드)\n주당 배당금: 6.0펜스(전년 6.0펜스)\n\n의장 논평: 매출 성장은 주로 프리미엄 유리병 제품군의 가격 인상에서 비롯되었으며, 이 제품군은 현재 순매출의 27%를 차지합니다. 이익률은 유리 가격 22% 상승과 펠브리지 병입 라인 폐쇄에 따른 230만 파운드의 일회성 비용으로 압박을 받았습니다. 이 일회성 비용을 제외하면 영업이익은 소폭 증가했을 것입니다. 이사회는 배당금을 동결하고 잉여 현금을 내년 하반기 개장 예정인 켄달의 새 재사용 병 시설에 투입하기로 결정했습니다.\n\n[이메일]\n발신: 고든 아흐터베르크 / 수신: 올더무어 스프링스 회사 비서 / 날짜: 3월 14일 / 제목: 정기 주주총회 질문\n\n담당자께,\n\n약 20년간 주주로 있어 온 저는 4월 9일 정기 주주총회에 참석할 예정이며, 다음 질문을 이사회에 전달해 주시기 바랍니다.\n\n실적 요약을 보면 판매량은 약 2%밖에 늘지 않은 반면 순매출은 훨씬 빠르게 증가했습니다. 프리미엄 제품이 더 비싸다는 것은 이해하지만, 회사가 새 고객을 끌어들이기보다 가격에 의존하는 것이 아닌가 우려됩니다. 경쟁사들이 따라오지 않더라도 이사회는 높은 가격이 유지될 수 있다고 확신합니까?\n\n또한 10여 년 만에 처음으로 배당금이 오르지 않아 실망스럽습니다. 이것이 이사회가 설명한 투자와 연관된 일시적 결정이며 정책 변경이 아니라는 점을 확인해 주시기 바랍니다.\n\n고든 아흐터베르크 드림","part":7},{"id":"p7-116","level":5,"kind":"double","passages":[{"doc_type":"계약서","title":"Supply Agreement — Excerpt / Kovač Dairy Cooperative (“Supplier”) and Brennan Foodservice Ltd. (“Buyer”)","text":"7. Pricing\n7.1 The base price for whole milk is €0.46 per litre, delivered.\n7.2 Either party may request a price review if the regional farm-gate milk index published by the Agricultural Statistics Office moves by more than 8 percent from its level on the date of signing (index value: 112.0). A request must be made in writing and supported by the most recently published index figure.\n7.3 Following a valid request, the base price will be adjusted by half of the percentage change in the index. The adjusted price will apply to deliveries beginning on the first day of the month following the request.\n7.4 No more than one price review may be requested in any six-month period.\n\n8. Volumes\n8.1 The Buyer will purchase no fewer than 180,000 litres per month. A shortfall in any month may be made up in the following month without penalty."},{"doc_type":"이메일","title":"From: Marta Kovač, Kovač Dairy Cooperative / To: Declan Brennan, Brennan Foodservice Ltd. / Date: September 18 / Subject: Price review request under Section 7","text":"Dear Mr. Brennan,\n\nI am writing to request a price review under Section 7.2 of our agreement. The Agricultural Statistics Office's August figure for the regional farm-gate index, published on September 12, is 127.68, up from 112.0 when we signed in March. A copy of the publication is attached.\n\nAs you know, feed and energy costs for our member farms have risen sharply this year, and the index reflects this. We value our partnership with Brennan Foodservice and have not sought any changes to the terms until now.\n\nIn line with the adjustment method we agreed on, we would expect the new price to take effect with the October deliveries. I would be glad to discuss this by phone if that would be helpful.\n\nRegards,\nMarta Kovač"}],"questions":[{"q":"Why did Ms. Kovač write to Mr. Brennan?","choices":["To report a delay in deliveries","To propose increasing the monthly volume","To ask about the Buyer's shortfall","To formally request a change in price"],"answer":3,"type":"주제·목적","explanation":"첫 문장에서 계약 7.2항에 따른 가격 재검토를 요청한다고 밝히고 근거가 되는 지수 자료를 첨부했다. 배송 지연이나 물량 변경, 구매자의 부족분은 언급하지 않는다."},{"q":"If the review is carried out as the agreement specifies, what will the new base price per litre be?","choices":["€0.4922","€0.5244","€0.4600","€0.5060"],"answer":0,"type":"연계 문제","explanation":"지수가 112.0에서 127.68로 14% 올랐다(127.68 ÷ 112 = 1.14). 7.3항에 따라 기본 가격은 변동률의 절반인 7%만 조정되므로 0.46 × 1.07 = 0.4922유로다. 0.5244유로는 14%를 그대로 적용한 값이다."},{"q":"What is indicated about Ms. Kovač's request?","choices":["It was made by telephone.","It will apply to September deliveries.","It was submitted by the Buyer.","It meets the conditions described in Section 7.2."],"answer":3,"type":"연계 문제","explanation":"7.2항은 지수가 8% 넘게 움직이면 서면으로, 최신 지수 자료를 근거로 요청할 수 있다고 한다. 이메일의 요청은 서면이고 최신(8월) 수치를 첨부했으며 변동률이 14%이므로 조건을 충족한다. 적용은 다음 달인 10월 배송부터다."},{"q":"According to the agreement, when is the earliest that another price review could be requested?","choices":["In March of the following year","At the end of October","Immediately after the October deliveries","Once the Buyer's volume exceeds 180,000 litres"],"answer":0,"type":"추론","explanation":"7.4항에 따라 6개월 동안 가격 재검토는 한 번만 요청할 수 있다. 이번 요청이 9월 18일이므로 다음 요청은 그로부터 6개월 뒤인 이듬해 3월 이후에야 가능하다."},{"q":"In the e-mail, the word “reflects” in paragraph 2 is closest in meaning to","choices":["considers","shows","bounces","returns"],"answer":1,"type":"동의어","explanation":"'the index reflects this'는 지수가 사료·에너지 비용 상승을 '보여 준다/나타낸다'는 뜻이므로 shows가 가장 가깝다. considers(숙고하다)는 reflect on의 뜻, bounces는 빛의 반사와 관련된 함정이다."}],"translation":"[계약서]\n공급 계약서 — 발췌 / 코바치 낙농 협동조합(“공급자”)과 브레넌 푸드서비스(“구매자”) 간\n\n7. 가격\n7.1 전유의 기본 가격은 배송 포함 리터당 0.46유로이다.\n7.2 농업통계청이 발표하는 지역 산지 우유 지수가 계약 체결일 수준(지수 112.0)에서 8%를 넘게 움직이면 어느 당사자든 가격 재검토를 요청할 수 있다. 요청은 서면으로 해야 하며 가장 최근에 발표된 지수 수치로 뒷받침되어야 한다.\n7.3 유효한 요청이 있으면 기본 가격은 지수 변동률의 절반만큼 조정된다. 조정된 가격은 요청한 다음 달 1일부터의 배송에 적용된다.\n7.4 6개월 동안 가격 재검토는 한 번만 요청할 수 있다.\n\n8. 물량\n8.1 구매자는 매월 최소 180,000리터를 구매한다. 어느 달의 부족분은 다음 달에 불이익 없이 채울 수 있다.\n\n[이메일]\n발신: 마르타 코바치, 코바치 낙농 협동조합 / 수신: 데클런 브레넌, 브레넌 푸드서비스 / 날짜: 9월 18일 / 제목: 제7조에 따른 가격 재검토 요청\n\n브레넌 씨께,\n\n계약서 7.2항에 따라 가격 재검토를 요청드립니다. 9월 12일에 발표된 농업통계청의 지역 산지 지수 8월 수치는 127.68로, 3월 계약 당시의 112.0에서 올랐습니다. 발표 자료 사본을 첨부합니다.\n\n아시다시피 올해 저희 조합원 농가의 사료비와 에너지 비용이 급격히 올랐고, 지수가 이를 보여 줍니다. 저희는 브레넌 푸드서비스와의 협력을 소중히 여기며 지금까지 조건 변경을 요청한 적이 없습니다.\n\n합의한 조정 방식에 따라 새 가격이 10월 배송부터 적용되기를 기대합니다. 도움이 된다면 전화로 기꺼이 논의하겠습니다.\n\n마르타 코바치 드림","part":7},{"id":"p7-117","level":5,"kind":"double","passages":[{"doc_type":"공고","title":"Wexley Foundation — Small Business Export Grants: Guidelines","text":"The Wexley Foundation offers matching grants of up to $25,000 to help manufacturers with fewer than 50 employees enter their first overseas market.\n\nEligible costs include trade-show fees, product certification required by the target market, and translation of marketing materials. Travel costs are eligible, but they may make up no more than 20 percent of the total grant. Salaries and equipment purchases are not eligible.\n\nGrants are matching: the Foundation pays 50 cents for every dollar the applicant spends on eligible costs. For example, a company with $30,000 in eligible expenses would receive $15,000.\n\nApplicants must not have exported to any country in the past three years. Applications are reviewed in two rounds each year, with deadlines of March 31 and September 30. Decisions are announced within eight weeks of each deadline. Expenses incurred before a grant is approved cannot be reimbursed."},{"doc_type":"이메일","title":"From: Farah Siddiqui, Tallis Ceramics / To: grants@wexleyfoundation.org / Date: April 2 / Subject: Eligibility question","text":"To the Grants Team,\n\nTallis Ceramics, a maker of commercial kitchen tiles with 34 employees, plans to enter the Canadian market. Our budget for the project is as follows: $24,000 to exhibit at the Toronto Hospitality Show in November, $9,000 for Canadian safety certification, $6,000 for travel, and $12,000 for a new kiln to meet the demand we expect.\n\nWe made a single shipment to a distributor in Ireland six years ago, but that relationship ended the same year.\n\nI realize we have just missed the spring deadline. Could you tell me whether our plans would qualify, and whether it would still be possible to receive support for the November show if we apply in the next round?\n\nSincerely,\nFarah Siddiqui"}],"questions":[{"q":"What is the purpose of the guidelines?","choices":["To describe the conditions for receiving financial support","To announce the winners of a grant competition for small exporters","To invite companies to exhibit at a trade show","To explain new export regulations"],"answer":0,"type":"주제·목적","explanation":"웩슬리 재단의 소기업 수출 보조금 지침으로, 대상 기업, 인정 비용, 매칭 방식, 신청 자격과 일정 등 지원 조건을 설명한다."},{"q":"Which item in Tallis Ceramics' budget is not eligible for a grant?","choices":["The trade-show fee","The safety certification","The travel costs","The new kiln"],"answer":3,"type":"연계 문제","explanation":"지침상 급여와 장비 구입은 인정되지 않는다. 시딕 씨의 예산 중 새 가마(kiln) 12,000달러가 장비 구입에 해당한다. 전시회비, 인증, 출장비(한도 내)는 인정 비용이다."},{"q":"What is the largest grant Tallis Ceramics could receive for its budget?","choices":["$19,500","$25,000","$16,500","$25,500"],"answer":0,"type":"연계 문제","explanation":"인정 비용은 전시회 24,000 + 인증 9,000 + 출장 6,000 = 39,000달러이고, 재단은 그 절반인 19,500달러를 지원한다. 출장비 몫 3,000달러는 보조금의 20%(3,900달러)를 넘지 않는다. 25,500달러는 가마까지 포함한 잘못된 계산이며 한도 25,000달러도 넘는다."},{"q":"What is indicated about Tallis Ceramics?","choices":["It has too many employees to apply.","It currently sells products in Ireland.","It has already received an export grant from the foundation in a previous round","It meets the foundation's requirement regarding past exports."],"answer":3,"type":"연계 문제","explanation":"신청자는 최근 3년간 수출 실적이 없어야 한다(지침). 탈리스는 6년 전에 아일랜드로 한 번 선적했을 뿐이므로 요건을 충족한다. 직원 34명은 50명 미만 기준에도 맞는다."},{"q":"What problem might Tallis Ceramics face if it applies in the next round?","choices":["Its application would be reviewed by a different committee.","The Canadian certification might expire.","It might have to pay some show costs before a decision is made.","Travel costs would no longer be eligible."],"answer":2,"type":"추론","explanation":"다음 마감은 9월 30일이고 결정은 마감 후 8주 이내, 즉 11월 말까지 나올 수 있다. 11월 전시회 비용은 그 전에 지출될 가능성이 높은데, 승인 전 지출은 보전되지 않으므로 전시회 비용을 지원받지 못할 수 있다."}],"translation":"[공고]\n웩슬리 재단 — 소기업 수출 보조금: 지침\n\n웩슬리 재단은 직원 50명 미만 제조업체가 첫 해외 시장에 진출하도록 돕기 위해 최대 25,000달러의 매칭 보조금을 제공합니다.\n\n인정 비용에는 무역 전시회 참가비, 대상 시장이 요구하는 제품 인증, 마케팅 자료 번역이 포함됩니다. 출장비도 인정되지만 총 보조금의 20%를 넘을 수 없습니다. 급여와 장비 구입은 인정되지 않습니다.\n\n보조금은 매칭 방식입니다. 재단은 신청자가 인정 비용에 쓰는 1달러마다 50센트를 지급합니다. 예를 들어 인정 비용이 30,000달러인 회사는 15,000달러를 받게 됩니다.\n\n신청자는 최근 3년간 어느 나라에도 수출한 적이 없어야 합니다. 신청서는 매년 두 차례 심사하며 마감일은 3월 31일과 9월 30일입니다. 결정은 각 마감일로부터 8주 이내에 발표됩니다. 보조금 승인 전에 발생한 비용은 보전되지 않습니다.\n\n[이메일]\n발신: 파라 시딕, 탈리스 세라믹스 / 수신: grants@wexleyfoundation.org / 날짜: 4월 2일 / 제목: 자격 문의\n\n보조금 담당팀께,\n\n직원 34명의 상업용 주방 타일 제조업체인 탈리스 세라믹스는 캐나다 시장 진출을 계획하고 있습니다. 프로젝트 예산은 다음과 같습니다. 11월 토론토 호스피탈리티 쇼 참가 24,000달러, 캐나다 안전 인증 9,000달러, 출장비 6,000달러, 예상 수요에 대비한 새 가마 12,000달러입니다.\n\n저희는 6년 전 아일랜드의 유통업체에 한 번 선적한 적이 있지만, 그 관계는 같은 해에 끝났습니다.\n\n봄 마감을 막 놓친 것을 알고 있습니다. 저희 계획이 자격이 되는지, 그리고 다음 차수에 신청해도 11월 전시회에 대한 지원을 받을 수 있는지 알려 주시겠습니까?\n\n파라 시딕 드림","part":7},{"id":"p7-118","level":5,"kind":"triple","passages":[{"doc_type":"일정표","title":"Project Schedule — Renovation of Halberd Public Library, East Wing / Contractor: Ostrander Build Group","text":"Phase 1: Roof replacement — April 7 to May 2\nPhase 2: Window installation — May 5 to May 23\nPhase 3: Interior finishing (flooring, lighting, shelving) — May 26 to June 27\nPhase 4: Inspection and furniture delivery — June 30 to July 11\nReopening: July 14\n\nConditions:\n• Roof work cannot proceed on days when the chance of rain is forecast above 60 percent. Each such day extends Phase 1 by one working day.\n• Window installation may begin only after the roof has been inspected and approved.\n• Interior finishing may overlap with window installation by no more than one week, provided the affected rooms are sealed from dust.\n• Any delay of more than ten working days in total must be formally reported to the Library Board."},{"doc_type":"이메일","title":"From: Keith Ostrander / To: Rosa Delgado, Library Director / Date: May 5 / Subject: Schedule update","text":"Dear Ms. Delgado,\n\nApril was wetter than expected. We lost eight working days to rain, so the roof will not be finished until May 14. The roof inspector has confirmed that she can visit on May 15, and if the roof is approved, the window crew will start the following Monday, May 19. Window installation will still take three weeks.\n\nTo limit the effect on the reopening date, I propose starting interior finishing on May 26 as planned, beginning with the ground-floor reading rooms, which will be sealed off from the upper floors. We would also add a Saturday crew throughout June. I believe we can still hand over the building in time for furniture delivery to begin by July 7.\n\nBest regards,\nKeith Ostrander"},{"doc_type":"회의록","title":"Halberd Public Library Board — Meeting Minutes, May 12 (Excerpt)","text":"Present: R. Delgado (Director), P. Huang (Chair), S. Abara, T. Lind\n\nItem 3: East Wing renovation\nMs. Delgado reported that roof work had been delayed by rain. Although the delay is below the level that requires a formal report, she wished to keep the Board informed. She noted that the contractor's proposal to begin interior finishing on May 26 would exceed the overlap permitted under the schedule, and she has asked the contractor to begin on June 2 instead. Mr. Abara asked whether the summer reading program, scheduled to begin on July 14, should be moved to the West Wing. The Board agreed to decide the matter on June 9, once the revised schedule is known.\n\nAction: Ms. Delgado to circulate the revised schedule to Board members by June 6."}],"questions":[{"q":"According to the schedule, what must happen before window installation can begin?","choices":["The interior rooms must be sealed.","The Library Board must approve a new date.","Furniture must be ordered.","The roof must pass an inspection."],"answer":3,"type":"세부 사항","explanation":"일정표 조건에 창문 설치는 지붕이 점검을 받고 승인된 뒤에만 시작할 수 있다고 명시되어 있다. 방 밀폐는 내부 마감을 창문 공사와 겹쳐 진행할 때의 조건이다."},{"q":"What is suggested about the delay described in Mr. Ostrander's e-mail?","choices":["It did not reach the level that requires a formal report.","It was caused by a late inspection.","It will postpone the reopening to August.","It affected only the window installation."],"answer":0,"type":"연계 문제","explanation":"이메일에 따르면 비로 8일(작업일)을 잃었고, 일정표상 공식 보고는 총 10일 넘는 지연부터 필요하다. 회의록에서도 공식 보고 대상 수준에 못 미친다고 했다. 원인은 점검이 아니라 비였다."},{"q":"Why did Ms. Delgado ask the contractor to start interior finishing on June 2?","choices":["The reading rooms could not be sealed from dust.","Starting on May 26 would overlap window work by more than one week.","The Saturday crew would not be available until the middle of June because of other jobs","The roof inspection was rescheduled."],"answer":1,"type":"연계 문제","explanation":"이메일상 창문 공사는 5월 19일부터 3주, 즉 6월 6일경까지 진행된다. 내부 마감을 5월 26일에 시작하면 2주가 겹쳐, 일정표가 허용하는 최대 1주를 넘는다. 6월 2일에 시작하면 겹치는 기간이 1주가 된다. 회의록도 허용 범위를 넘는다고 했다."},{"q":"What is indicated about the summer reading program?","choices":["It has been moved to the West Wing.","It was canceled because of the renovation work on the East Wing.","It will be led by Mr. Abara.","It was planned to start on the East Wing's reopening date."],"answer":3,"type":"연계 문제","explanation":"회의록에 여름 독서 프로그램이 7월 14일 시작 예정이라고 나오고, 일정표상 동관 재개관일도 7월 14일이다. 서관 이전 여부는 6월 9일에 결정하기로 했으므로 아직 옮겨지지 않았다."},{"q":"In the minutes, the word “circulate” is closest in meaning to","choices":["rotate","distribute","surround","travel"],"answer":1,"type":"동의어","explanation":"'circulate the revised schedule to Board members'는 수정된 일정표를 이사들에게 '배포하다/돌리다'는 뜻이므로 distribute가 가장 가깝다. rotate(회전하다)나 travel(이동하다)은 circulate의 물리적 의미와 관련된 함정이다."}],"translation":"[일정표]\n공사 일정 — 핼버드 공공도서관 동관 리모델링 / 시공사: 오스트랜더 빌드 그룹\n\n1단계: 지붕 교체 — 4월 7일~5월 2일\n2단계: 창문 설치 — 5월 5일~5월 23일\n3단계: 내부 마감(바닥, 조명, 서가) — 5월 26일~6월 27일\n4단계: 점검 및 가구 반입 — 6월 30일~7월 11일\n재개관: 7월 14일\n\n조건:\n• 강수 확률이 60%를 넘게 예보된 날에는 지붕 작업을 할 수 없다. 그런 날마다 1단계가 작업일 하루씩 연장된다.\n• 창문 설치는 지붕이 점검을 받고 승인된 뒤에만 시작할 수 있다.\n• 내부 마감은 해당 공간을 먼지로부터 밀폐하는 조건으로 창문 설치와 최대 1주까지 겹칠 수 있다.\n• 총 작업일 10일을 넘는 지연은 도서관 이사회에 공식 보고해야 한다.\n\n[이메일]\n발신: 키스 오스트랜더 / 수신: 로사 델가도, 도서관장 / 날짜: 5월 5일 / 제목: 일정 업데이트\n\n델가도 관장님께,\n\n4월은 예상보다 비가 많았습니다. 비로 작업일 8일을 잃어 지붕은 5월 14일에야 끝납니다. 지붕 점검관이 5월 15일에 방문할 수 있다고 확인했으며, 지붕이 승인되면 창문 작업팀이 그다음 월요일인 5월 19일에 시작합니다. 창문 설치는 여전히 3주가 걸립니다.\n\n재개관일에 미치는 영향을 줄이기 위해, 위층과 밀폐해 차단할 1층 열람실부터 내부 마감을 예정대로 5월 26일에 시작할 것을 제안합니다. 또한 6월 내내 토요일 작업팀을 추가하겠습니다. 가구 반입이 7월 7일까지 시작될 수 있도록 건물을 넘겨 드릴 수 있다고 생각합니다.\n\n키스 오스트랜더 드림\n\n[회의록]\n핼버드 공공도서관 이사회 — 회의록, 5월 12일(발췌)\n\n참석: R. 델가도(관장), P. 황(의장), S. 아바라, T. 린드\n\n안건 3: 동관 리모델링\n델가도 관장은 지붕 공사가 비로 지연되었다고 보고했다. 지연이 공식 보고가 필요한 수준에는 못 미치지만 이사회에 알리고 싶었다고 했다. 그녀는 5월 26일에 내부 마감을 시작하겠다는 시공사의 제안이 일정표에서 허용하는 중복 기간을 넘는다고 지적하고, 대신 6월 2일에 시작하도록 시공사에 요청했다. 아바라 이사는 7월 14일 시작 예정인 여름 독서 프로그램을 서관으로 옮겨야 하는지 물었다. 이사회는 수정 일정이 나온 뒤인 6월 9일에 이 문제를 결정하기로 했다.\n\n조치 사항: 델가도 관장은 6월 6일까지 수정 일정을 이사들에게 배포한다.","part":7},{"id":"p7-119","level":5,"kind":"triple","passages":[{"doc_type":"제안 요청서","title":"Request for Proposals — Vehicle Tracking System / Issued by: Marlow County Transit Authority","text":"Marlow County Transit Authority (MCTA) seeks a vendor to supply and maintain GPS tracking units and software for its fleet of 140 buses.\n\nProposals will be scored as follows:\n• Total five-year cost: 40 points\n• Technical capability, including real-time passenger information: 35 points\n• Experience with public-sector clients: 15 points\n• Implementation timeline: 10 points\n\nVendors must be able to equip the entire fleet within 120 days of contract signing. Proposals that do not meet this requirement will not be scored. Pricing must include hardware, installation, software licenses, and support for five years."},{"doc_type":"평가표","title":"Evaluation Summary — Vehicle Tracking System Proposals","text":"Vendor | Five-year cost | Installation time | Cost | Technical | Experience | Timeline | Total\nRoutewise | $912,000 | 90 days | 34 | 30 | 15 | 8 | 87\nTransitrack | $760,000 | 150 days | — | — | — | — | Not scored\nGeoline Systems | $798,000 | 100 days | 40 | 26 | 9 | 7 | 82\nPaxmap | $1,030,000 | 60 days | 30 | 33 | 12 | 10 | 85"},{"doc_type":"이메일","title":"From: Grace Mbeki, Procurement Director / To: MCTA Board Members / Date: February 3 / Subject: Recommendation — vehicle tracking contract","text":"Board members,\n\nThe evaluation panel recommends awarding the contract to the highest-scoring vendor. Although its price is not the lowest among the scored proposals, it has installed similar systems for four transit agencies of comparable size, and its passenger information app received the second-highest technical score.\n\nThe lowest-priced proposal was excluded from scoring, and some Board members have asked whether we could negotiate a longer installation period with that vendor. Our legal counsel advises against this: changing a mandatory requirement after proposals have been opened would be unfair to the other bidders and could expose MCTA to a legal challenge.\n\nIf the Board approves the recommendation on February 10, installation should be complete by mid-May, before the summer timetable begins.\n\nGrace Mbeki"}],"questions":[{"q":"According to the request for proposals, which criterion carries the most weight?","choices":["Total cost over five years","Technical capability","Public-sector experience","Speed of implementation"],"answer":0,"type":"세부 사항","explanation":"배점은 5년 총비용 40점, 기술력 35점, 공공 부문 경험 15점, 구축 기간 10점이므로 5년 총비용의 비중이 가장 크다."},{"q":"Which vendor does the evaluation panel recommend?","choices":["Paxmap","Geoline Systems","Transitrack","Routewise"],"answer":3,"type":"연계 문제","explanation":"이메일은 최고 득점 업체를 추천한다고 했고, 평가표에서 루트와이즈가 87점으로 가장 높다. 경험 점수 만점(15점)과 기술 점수 2위(30점)도 이메일 설명과 일치한다. 팩스맵은 기술 점수 1위지만 총점 85점이다."},{"q":"Why was Transitrack's proposal not scored?","choices":["Its price did not include software licenses.","It lacked experience with public-sector clients.","It could not equip the fleet within the required period.","It was submitted after the deadline."],"answer":2,"type":"연계 문제","explanation":"요청서는 계약 후 120일 안에 전 차량 설치가 가능해야 하며 그렇지 않으면 채점하지 않는다고 했다. 평가표상 트랜시트랙의 설치 기간은 150일이다. 이메일에서도 가장 저렴한 제안이 채점에서 제외되었다고 했다."},{"q":"What does Ms. Mbeki's legal counsel advise against?","choices":["Altering a required condition to accommodate one bidder","Awarding the contract before the summer timetable has been finalized","Asking vendors to lower their prices","Delaying the Board's vote until February 10"],"answer":0,"type":"세부 사항","explanation":"일부 이사가 최저가 업체와 설치 기간 연장을 협상할 수 있는지 묻자, 법률 고문은 제안서 개봉 후 필수 요건을 바꾸면 다른 입찰자에게 불공정하고 법적 이의 제기를 받을 수 있다며 반대했다."},{"q":"In the e-mail, the word “expose” in paragraph 2 is closest in meaning to","choices":["reveal","make vulnerable","display","uncover"],"answer":1,"type":"동의어","explanation":"'could expose MCTA to a legal challenge'는 교통청을 법적 이의 제기에 '노출시킬/취약하게 만들' 수 있다는 뜻이다. reveal, display, uncover는 '드러내다'라는 expose의 다른 뜻이라 이 문맥에 맞지 않는다."}],"translation":"[제안 요청서]\n차량 위치 추적 시스템 제안 요청 / 발행: 말로 카운티 교통청\n\n말로 카운티 교통청(MCTA)은 버스 140대에 GPS 추적 장치와 소프트웨어를 공급하고 유지 관리할 업체를 찾습니다.\n\n제안서는 다음과 같이 채점합니다.\n• 5년 총비용: 40점\n• 실시간 승객 정보를 포함한 기술력: 35점\n• 공공 부문 고객 경험: 15점\n• 구축 일정: 10점\n\n업체는 계약 체결 후 120일 이내에 전 차량에 장비를 설치할 수 있어야 합니다. 이 요건을 충족하지 못하는 제안서는 채점하지 않습니다. 가격에는 하드웨어, 설치, 소프트웨어 라이선스, 5년간의 지원이 포함되어야 합니다.\n\n[평가표]\n차량 위치 추적 시스템 제안 평가 요약\n\n업체 | 5년 비용 | 설치 기간 | 비용 | 기술 | 경험 | 일정 | 총점\n루트와이즈 | 912,000달러 | 90일 | 34 | 30 | 15 | 8 | 87\n트랜시트랙 | 760,000달러 | 150일 | — | — | — | — | 채점 제외\n지오라인 시스템즈 | 798,000달러 | 100일 | 40 | 26 | 9 | 7 | 82\n팩스맵 | 1,030,000달러 | 60일 | 30 | 33 | 12 | 10 | 85\n\n[이메일]\n발신: 그레이스 음베키, 구매 이사 / 수신: MCTA 이사회 / 날짜: 2월 3일 / 제목: 추천 — 차량 추적 계약\n\n이사님들께,\n\n평가 위원단은 최고 득점 업체에 계약을 주도록 추천합니다. 채점된 제안 중 가격이 가장 낮지는 않지만, 이 업체는 비슷한 규모의 교통 기관 네 곳에 유사한 시스템을 설치했으며 승객 정보 앱은 기술 점수 2위를 받았습니다.\n\n가장 저렴한 제안은 채점에서 제외되었고, 일부 이사님들은 그 업체와 설치 기간 연장을 협상할 수 있는지 물으셨습니다. 법률 고문은 이에 반대합니다. 제안서를 개봉한 뒤 필수 요건을 바꾸면 다른 입찰자에게 불공정하며 MCTA가 법적 이의 제기에 노출될 수 있기 때문입니다.\n\n이사회가 2월 10일에 추천안을 승인하면 여름 시간표가 시작되기 전인 5월 중순까지 설치가 완료될 것입니다.\n\n그레이스 음베키","part":7},{"id":"p7-120","level":5,"kind":"triple","passages":[{"doc_type":"요금표","title":"Pelham Freight Forwarding — Air Freight Rates, Shanghai (PVG) to Frankfurt (FRA), effective October 1","text":"Chargeable weight is the greater of the actual weight and the volumetric weight (length × width × height in centimeters ÷ 6,000).\n\nRate per chargeable kg: 100–499 kg: $4.20 | 500–999 kg: $3.80 | 1,000 kg and above: $3.40\nFuel surcharge: $0.65 per chargeable kg\nSecurity screening: $45 per shipment\nCustoms clearance at destination: $120 per shipment (waived for clients who use Pelham's bonded warehouse)\nStorage: free for 3 days after arrival; thereafter $0.15 per kg per day, based on actual weight"},{"doc_type":"청구서","title":"Invoice #PF-50318 — Pelham Freight Forwarding / Client: Aurelio Lighting GmbH / Shipment: 12 cartons, PVG–FRA, arrived October 14, collected October 20","text":"Actual weight: 640 kg | Volumetric weight: 820 kg\nFreight (820 kg × $3.80): $3,116.00\nFuel surcharge (820 kg × $0.65): $533.00\nSecurity screening: $45.00\nCustoms clearance: $120.00\nStorage (3 days × 820 kg × $0.15): $369.00\nTotal: $4,183.00"},{"doc_type":"이메일","title":"From: Jonas Keller, Aurelio Lighting GmbH / To: billing@pelhamfreight.com / Date: October 27 / Subject: Invoice PF-50318","text":"Hello,\n\nWe have reviewed invoice PF-50318 and found two items that do not match your published rates. First, the storage charge appears to have been calculated incorrectly. Second, since August we have routed all of our Frankfurt shipments through your bonded warehouse, so we should not have been charged for one of the services listed.\n\nI would also point out that our truck arrived to collect the cartons on October 17, but your warehouse was closed that day and the next for an inventory count, and our next available truck could not come until October 20. We therefore ask that the storage charge be removed altogether.\n\nPlease send a corrected invoice. We will pay it immediately upon receipt.\n\nJonas Keller"}],"questions":[{"q":"Why was the freight charge calculated using 820 kg?","choices":["The shipment was over 1,000 kg.","The client requested express service.","The fuel surcharge applies to the volumetric weight only.","The volumetric weight was greater than the actual weight."],"answer":3,"type":"연계 문제","explanation":"요금표에 따르면 과금 중량은 실제 중량과 부피 중량 중 큰 값이다. 청구서상 실제 중량은 640kg, 부피 중량은 820kg이므로 820kg이 적용되었다."},{"q":"Which charge does Mr. Keller say should not have been billed?","choices":["Customs clearance","Security screening","Fuel surcharge","Freight"],"answer":0,"type":"연계 문제","explanation":"켈러 씨는 8월부터 모든 프랑크푸르트 화물을 펠럼의 보세 창고로 보내고 있다고 했다. 요금표상 보세 창고 이용 고객은 도착지 통관 수수료 120달러가 면제된다."},{"q":"What error was made in the storage charge?","choices":["The free period was not applied.","The wrong daily rate was used.","It was based on volumetric rather than actual weight.","The charge was applied to a different shipment held in the same warehouse"],"answer":2,"type":"연계 문제","explanation":"요금표는 보관료를 실제 중량 기준으로 계산한다고 했는데, 청구서는 820kg(부피 중량)으로 계산했다. 무료 3일 이후 3일(18~20일)과 일일 요율 0.15달러는 맞게 적용되었다."},{"q":"If Pelham corrects both errors according to its published rates but does not remove the storage charge altogether, what will the new total be?","choices":["$3,694.00","$4,063.00","$4,102.00","$3,982.00"],"answer":3,"type":"연계 문제","explanation":"통관 수수료 120달러를 빼고, 보관료를 실제 중량으로 다시 계산하면 3일 × 640kg × 0.15달러 = 288달러로 기존 369달러보다 81달러 줄어든다. 4,183 − 120 − 81 = 3,982달러다. 3,694달러는 보관료 전체를 뺀 금액이다."},{"q":"Why does Mr. Keller mention the inventory count?","choices":["To request a discount on future shipments","To argue that the delay in collection was not his company's fault","To explain why the cartons were damaged","To complain that the warehouse was understaffed"],"answer":1,"type":"추론","explanation":"켈러 씨는 10월 17일에 트럭을 보냈지만 재고 조사로 창고가 이틀간 문을 닫아 20일에야 수거할 수 있었다며 보관료 전액 삭제를 요구한다. 수거 지연이 자사 책임이 아니라고 주장하려는 것이다."}],"translation":"[요금표]\n펠럼 화물 운송 — 항공 화물 요금, 상하이(PVG)→프랑크푸르트(FRA), 10월 1일부 적용\n\n과금 중량은 실제 중량과 부피 중량(가로 × 세로 × 높이(cm) ÷ 6,000) 중 큰 값입니다.\n\n과금 kg당 요금: 100~499kg: 4.20달러 | 500~999kg: 3.80달러 | 1,000kg 이상: 3.40달러\n유류 할증료: 과금 kg당 0.65달러\n보안 검색: 건당 45달러\n도착지 통관: 건당 120달러(펠럼 보세 창고 이용 고객은 면제)\n보관료: 도착 후 3일간 무료, 이후 실제 중량 기준 kg당 하루 0.15달러\n\n[청구서]\n청구서 #PF-50318 — 펠럼 화물 운송 / 고객: 아우렐리오 라이팅 / 화물: 12상자, PVG–FRA, 10월 14일 도착, 10월 20일 수거\n\n실제 중량: 640kg | 부피 중량: 820kg\n운임(820kg × 3.80달러): 3,116.00달러\n유류 할증료(820kg × 0.65달러): 533.00달러\n보안 검색: 45.00달러\n통관: 120.00달러\n보관료(3일 × 820kg × 0.15달러): 369.00달러\n합계: 4,183.00달러\n\n[이메일]\n발신: 요나스 켈러, 아우렐리오 라이팅 / 수신: billing@pelhamfreight.com / 날짜: 10월 27일 / 제목: 청구서 PF-50318\n\n안녕하세요.\n\n청구서 PF-50318을 검토한 결과 귀사의 공시 요금과 맞지 않는 항목 두 개를 발견했습니다. 첫째, 보관료가 잘못 계산된 것 같습니다. 둘째, 저희는 8월부터 모든 프랑크푸르트 화물을 귀사의 보세 창고를 통해 보내고 있으므로, 목록에 있는 서비스 중 하나는 청구되지 말았어야 합니다.\n\n또한 저희 트럭이 10월 17일에 상자를 수거하러 갔지만 귀사 창고가 재고 조사로 그날과 다음 날 문을 닫았고, 다음으로 가능한 트럭은 10월 20일에야 갈 수 있었다는 점도 말씀드립니다. 따라서 보관료 전액을 삭제해 주실 것을 요청합니다.\n\n수정된 청구서를 보내 주십시오. 받는 즉시 지불하겠습니다.\n\n요나스 켈러","part":7},{"id":"p7-121","level":1,"kind":"single","passages":[{"doc_type":"문자 메시지","title":"Text-message chain","text":"Nora Kim [1:15 P.M.]: Hi, Sam. Are you still going to the airport to pick up Mr. Alvarez?\nSam Porter [1:16 P.M.]: Yes. I'm leaving the office at 2:30. His flight lands at 3:20.\nNora Kim [1:17 P.M.]: I just checked the airline's Web site. His flight is delayed by an hour.\nSam Porter [1:18 P.M.]: Thanks for telling me. I'll leave at 3:30, then.\nNora Kim [1:19 P.M.]: Sounds good. Please take him straight to the Grand Hotel. The meeting is tomorrow morning."}],"questions":[{"q":"Why did Ms. Kim send the message?","choices":["To ask Mr. Porter to book a hotel","To ask for a ride to the airport","To cancel a meeting with Mr. Alvarez","To report a change in a flight time"],"answer":3,"type":"주제·목적","explanation":"김 씨는 항공사 웹사이트를 확인했더니 알바레즈 씨의 비행기가 한 시간 늦어졌다고 알려 준다. 호텔 예약이나 회의 취소 이야기는 없다."},{"q":"At 1:19 P.M., what does Ms. Kim mean when she writes, “Sounds good”?","choices":["She likes the hotel's location.","She wants to join Mr. Porter.","She agrees with Mr. Porter's new plan.","She enjoyed the meeting with the hotel manager earlier"],"answer":2,"type":"의도 파악","explanation":"포터 씨가 3시 30분에 출발하겠다고 하자 김 씨가 'Sounds good(좋아요)'이라고 답했다. 바뀐 출발 계획에 동의한다는 뜻이다."}],"translation":"[문자 메시지]\n노라 김 [오후 1:15]: 안녕하세요, 샘. 알바레즈 씨 마중하러 아직 공항에 가실 거죠?\n샘 포터 [오후 1:16]: 네. 2시 30분에 사무실에서 출발해요. 그분 비행기가 3시 20분에 도착해요.\n노라 김 [오후 1:17]: 방금 항공사 웹사이트를 확인했는데요. 비행기가 한 시간 늦어졌어요.\n샘 포터 [오후 1:18]: 알려 줘서 고마워요. 그럼 3시 30분에 출발할게요.\n노라 김 [오후 1:19]: 좋아요. 그분을 바로 그랜드 호텔로 모셔다 주세요. 회의는 내일 아침이에요.","part":7},{"id":"p7-122","level":1,"kind":"single","passages":[{"doc_type":"공지","title":"Notice — Elevator Maintenance","text":"NOTICE TO ALL VISITORS AND STAFF\n\nThe east elevator in the Carter Building will be closed for maintenance on Tuesday, May 6, from 8 A.M. to 4 P.M.\n\nDuring this time, please use the west elevator or the stairs. People who need help moving heavy items may ask the security desk in the lobby for a cart.\n\nWe are sorry for any trouble this may cause.\n\nCarter Building Management"}],"questions":[{"q":"What is the purpose of the notice?","choices":["To announce a new elevator","To introduce a new security guard","To ask staff to clean the lobby","To explain a temporary closure"],"answer":3,"type":"주제·목적","explanation":"동쪽 엘리베이터가 5월 6일 하루 동안 정비로 운행하지 않는다고 알리는 공지이다. 새 엘리베이터 설치나 경비원 소개 내용은 없다."},{"q":"How long will the east elevator be closed?","choices":["For one hour","For four hours","For eight hours","For two days"],"answer":2,"type":"세부 사항","explanation":"오전 8시부터 오후 4시까지이므로 8시간이다. '4'라는 숫자만 보고 고르면 함정에 걸린다."},{"q":"What can people get at the security desk?","choices":["A cart","A parking pass","A building map","A visitor badge"],"answer":0,"type":"세부 사항","explanation":"무거운 물건 옮기는 데 도움이 필요하면 로비 경비 데스크에 카트를 요청할 수 있다고 했다."}],"translation":"[공지]\n방문객 및 직원 여러분께 알립니다\n\n카터 빌딩 동쪽 엘리베이터가 5월 6일 화요일 오전 8시부터 오후 4시까지 정비를 위해 운행을 중단합니다.\n\n이 시간 동안에는 서쪽 엘리베이터나 계단을 이용해 주십시오. 무거운 물건을 옮기는 데 도움이 필요하신 분은 로비 경비 데스크에 카트를 요청하시면 됩니다.\n\n불편을 드려 죄송합니다.\n\n카터 빌딩 관리사무소","part":7},{"id":"p7-123","level":1,"kind":"single","passages":[{"doc_type":"광고","title":"Pageturner Used Books — Moving Sale","text":"PAGETURNER USED BOOKS — MOVING SALE!\n\nWe are moving to a bigger store at 210 Main Street next month. Before we move, everything must go!\n\n• All paperback books: 50% off\n• All children's books: buy two, get one free\n• Bookshelves and display tables are also for sale.\n\nSale dates: June 1–15\nStore hours: Monday to Saturday, 10 A.M. to 7 P.M. (closed on Sundays)\n\nOur new store will open on July 1."}],"questions":[{"q":"Why is Pageturner Used Books having a sale?","choices":["It is celebrating its first anniversary.","It is closing permanently.","It is moving to a new location.","It has just opened."],"answer":2,"type":"주제·목적","explanation":"다음 달에 메인 스트리트 210번지의 더 큰 매장으로 이전하기 전에 하는 '이사 세일'이다. 영구 폐업은 아니며 7월 1일에 새 매장이 연다."},{"q":"What is NOT mentioned as being on sale?","choices":["Paperback books","Children's books","Bookshelves","Magazines"],"answer":3,"type":"사실 확인(NOT/TRUE)","explanation":"페이퍼백, 아동 도서, 책장·진열대는 언급되지만 잡지는 나오지 않는다."},{"q":"When is the store closed?","choices":["On Saturdays","On Sundays","On Mondays","Every evening after 5 P.M."],"answer":1,"type":"세부 사항","explanation":"영업시간은 월~토 오전 10시~오후 7시이고 일요일은 휴무(closed on Sundays)라고 했다."}],"translation":"[광고]\n페이지터너 중고 서점 — 이전 세일!\n\n다음 달에 메인 스트리트 210번지의 더 큰 매장으로 이전합니다. 이전 전에 모든 상품을 정리합니다!\n\n• 모든 페이퍼백 도서: 50% 할인\n• 모든 아동 도서: 두 권 사면 한 권 무료\n• 책장과 진열대도 판매합니다.\n\n세일 기간: 6월 1일~15일\n영업시간: 월~토 오전 10시~오후 7시 (일요일 휴무)\n\n새 매장은 7월 1일에 문을 엽니다.","part":7},{"id":"p7-124","level":1,"kind":"single","passages":[{"doc_type":"이메일","title":"From: Helen Ward / To: Daniel Cho / Date: March 2 / Subject: Your first day","text":"Dear Daniel,\n\nWelcome to Brightline Design! We are happy that you are joining our team. [1]\n\nYour first day is Monday, March 9. Please come to the front desk on the second floor at 9 A.M. [2] I will meet you there and show you around the office.\n\nIn the morning, you will get your laptop and employee ID card. [3] In the afternoon, you will have lunch with the rest of the design team.\n\nIf you have any questions before Monday, please call me at 555-0148. [4]\n\nBest regards,\nHelen Ward\nOffice Manager"}],"questions":[{"q":"Who most likely is Daniel Cho?","choices":["A new employee","A client","A delivery driver","An office manager"],"answer":0,"type":"추론","explanation":"브라이트라인 디자인에 온 것을 환영하며 '첫 출근일'을 안내하는 이메일이므로 조 씨는 신입 직원이다. 사무실 관리자는 이메일을 보낸 워드 씨이다."},{"q":"What will Mr. Cho do in the afternoon on March 9?","choices":["Receive a new laptop and a security badge","Meet a client","Have lunch with coworkers","Visit the front desk"],"answer":2,"type":"세부 사항","explanation":"오후에는 디자인팀의 다른 직원들과 점심을 먹는다고 했다. 노트북은 오전에 받는다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“Please bring a photo of yourself for the card.”","choices":["[1]","[2]","[3]","[4]"],"answer":2,"type":"문장 삽입","explanation":"'카드용 사진을 가져오라'는 문장은 사원증(employee ID card)을 받는다는 내용 바로 뒤인 [3]에 와야 자연스럽다. 'the card'가 가리키는 대상이 앞에 있어야 한다."}],"translation":"[이메일]\n보낸 사람: 헬렌 워드 / 받는 사람: 대니얼 조 / 날짜: 3월 2일 / 제목: 첫 출근일\n\n대니얼 씨께,\n\n브라이트라인 디자인에 오신 것을 환영합니다! 저희 팀에 합류하시게 되어 기쁩니다.\n\n첫 출근일은 3월 9일 월요일입니다. 오전 9시에 2층 안내 데스크로 와 주세요. 제가 거기서 맞이하고 사무실을 안내해 드리겠습니다.\n\n오전에는 노트북과 사원증을 받으실 겁니다. (카드에 쓸 본인 사진을 한 장 가져와 주세요.) 오후에는 디자인팀의 다른 직원들과 점심을 함께하실 겁니다.\n\n월요일 전에 궁금한 점이 있으면 555-0148로 전화 주세요.\n\n감사합니다.\n헬렌 워드\n사무실 관리자","part":7},{"id":"p7-125","level":1,"kind":"single","passages":[{"doc_type":"온라인 채팅","title":"Online chat discussion","text":"Maria Lopez [11:02 A.M.]: Hi, everyone. I'm ordering lunch for our 12:30 meeting. Is pizza OK?\nKevin Brooks [11:03 A.M.]: Pizza is fine with me.\nAnna Price [11:04 A.M.]: I don't eat meat. Could you get one vegetable pizza?\nMaria Lopez [11:05 A.M.]: Of course. I'll order two cheese pizzas and one vegetable pizza.\nKevin Brooks [11:06 A.M.]: What about drinks?\nMaria Lopez [11:07 A.M.]: There's plenty of juice and water in the kitchen.\nKevin Brooks [11:08 A.M.]: Great. I'll bring them to the meeting room."}],"questions":[{"q":"What is Ms. Lopez doing?","choices":["Planning a party","Ordering food for a meeting","Cleaning the kitchen","Booking a meeting room"],"answer":1,"type":"주제·목적","explanation":"로페즈 씨는 12시 30분 회의를 위해 점심(피자)을 주문하고 있다고 했다."},{"q":"What does Ms. Price ask for?","choices":["A different meeting time","More drinks","A pizza without meat","A larger meeting room"],"answer":2,"type":"세부 사항","explanation":"프라이스 씨는 고기를 먹지 않아서 채소 피자를 하나 주문해 달라고 했다."},{"q":"At 11:07 A.M., what does Ms. Lopez mean when she writes, “There's plenty of juice and water in the kitchen”?","choices":["She does not need to order drinks.","The kitchen needs to be cleaned.","She wants Mr. Brooks to buy more drinks.","The meeting will be held in the kitchen."],"answer":0,"type":"의도 파악","explanation":"음료는 어떻게 하느냐는 질문에 주방에 주스와 물이 충분하다고 답했으므로 음료는 따로 주문할 필요가 없다는 뜻이다. 그러자 브룩스 씨가 그것을 회의실로 가져가겠다고 했다."}],"translation":"[온라인 채팅]\n마리아 로페즈 [오전 11:02]: 안녕하세요, 여러분. 12시 30분 회의 때 먹을 점심을 주문하려고 해요. 피자 괜찮아요?\n케빈 브룩스 [오전 11:03]: 저는 피자 좋아요.\n애나 프라이스 [오전 11:04]: 저는 고기를 안 먹어요. 채소 피자 하나 시켜 줄 수 있어요?\n마리아 로페즈 [오전 11:05]: 물론이죠. 치즈 피자 두 판이랑 채소 피자 한 판 주문할게요.\n케빈 브룩스 [오전 11:06]: 음료는요?\n마리아 로페즈 [오전 11:07]: 주방에 주스랑 물이 충분히 있어요.\n케빈 브룩스 [오전 11:08]: 좋아요. 제가 회의실로 가져갈게요.","part":7},{"id":"p7-126","level":1,"kind":"single","passages":[{"doc_type":"안내문","title":"Westgate Parking Garage — Rates","text":"WESTGATE PARKING GARAGE\n\nRates\nUp to 1 hour: $3\n1 to 3 hours: $7\n3 to 6 hours: $12\nAll day (over 6 hours): $18\n\n• Open 24 hours a day, 7 days a week\n• Pay at the machines near the elevators before returning to your car. Cash and credit cards accepted.\n• Customers of Westgate Shopping Mall receive 2 free hours. Show your receipt at the mall's information desk."}],"questions":[{"q":"How much does it cost to park for two hours?","choices":["$3","$7","$12","$18"],"answer":1,"type":"세부 사항","explanation":"1~3시간 요금이 7달러이므로 두 시간 주차는 7달러이다."},{"q":"What is indicated about the parking garage?","choices":["It closes at midnight.","It accepts only cash payments from all visitors","It offers free parking to some shoppers.","It is located inside a hotel."],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"웨스트게이트 쇼핑몰 고객은 영수증을 보여 주면 2시간 무료라고 했다. 24시간 운영하며 현금과 신용카드 모두 받는다."}],"translation":"[안내문]\n웨스트게이트 주차장\n\n요금\n1시간까지: 3달러\n1~3시간: 7달러\n3~6시간: 12달러\n종일(6시간 초과): 18달러\n\n• 연중무휴 24시간 운영\n• 차로 돌아가기 전에 엘리베이터 옆 정산기에서 요금을 내 주십시오. 현금과 신용카드 모두 가능합니다.\n• 웨스트게이트 쇼핑몰 고객은 2시간 무료입니다. 쇼핑몰 안내 데스크에 영수증을 보여 주세요.","part":7},{"id":"p7-127","level":1,"kind":"double","passages":[{"doc_type":"웹페이지","title":"www.teamwearplus.com/shirts","text":"TEAMWEAR PLUS — CUSTOM SHIRTS\n\nAdd your company logo to our comfortable cotton shirts!\n\nT-shirt: $9 each\nPolo shirt: $15 each\nLong-sleeve shirt: $18 each\n\nColors: white, black, navy, and green\nSizes: S, M, L, XL\n\n• Orders of 50 shirts or more get 10% off.\n• Delivery takes 7 business days after you approve the design."},{"doc_type":"이메일","title":"From: Grace Lee / To: orders@teamwearplus.com / Date: April 3 / Subject: Shirt order","text":"Hello,\n\nI would like to order polo shirts for the staff at our three cafés. We need 60 shirts in navy: 20 in size S, 25 in size M, and 15 in size L. I have attached our logo.\n\nWe would like to wear the shirts at our spring event on April 20. Could you send me the design for approval this week?\n\nThank you,\nGrace Lee\nManager, Hilltop Coffee"}],"questions":[{"q":"What does the Web page say about Teamwear Plus?","choices":["It sells shirts in five colors.","It adds logos to shirts.","It offers free delivery.","It has a store on Hill Street."],"answer":1,"type":"사실 확인(NOT/TRUE)","explanation":"웹페이지 첫 줄에 회사 로고를 셔츠에 넣어 준다고 했다. 색상은 네 가지이며 무료 배송은 언급되지 않았다."},{"q":"Why did Ms. Lee write the e-mail?","choices":["To place an order","To complain about a delivery","To ask about prices","To change the color of some shirts"],"answer":0,"type":"주제·목적","explanation":"리 씨는 카페 직원용 폴로 셔츠 60장을 주문하고 로고를 첨부했다. 주문을 하려는 것이다."},{"q":"What size will Ms. Lee order the most of?","choices":["S","M","L","XL"],"answer":1,"type":"세부 사항","explanation":"S 20장, M 25장, L 15장이므로 M이 가장 많다."},{"q":"What will Ms. Lee most likely receive?","choices":["A free T-shirt","A 10% discount","A coupon for her cafés","A refund"],"answer":1,"type":"연계 문제","explanation":"웹페이지에 50장 이상 주문하면 10% 할인이라고 했고, 리 씨는 셔츠 60장을 주문했으므로 10% 할인을 받게 된다."},{"q":"What does Ms. Lee ask Teamwear Plus to do?","choices":["Deliver the shirts by April 3","Send a design for her approval","Call her at her café","Make the shirts in green"],"answer":1,"type":"세부 사항","explanation":"이메일 끝에서 이번 주에 승인할 수 있도록 디자인을 보내 달라고 요청했다. 색상은 남색(navy)이다."}],"translation":"[웹페이지]\n팀웨어 플러스 — 맞춤 셔츠\n\n편안한 면 셔츠에 회사 로고를 넣어 보세요!\n\n티셔츠: 장당 9달러\n폴로 셔츠: 장당 15달러\n긴소매 셔츠: 장당 18달러\n\n색상: 흰색, 검은색, 남색, 초록색\n사이즈: S, M, L, XL\n\n• 50장 이상 주문 시 10% 할인됩니다.\n• 디자인을 승인하신 후 배송까지 영업일 기준 7일이 걸립니다.\n\n[이메일]\n보낸 사람: 그레이스 리 / 받는 사람: orders@teamwearplus.com / 날짜: 4월 3일 / 제목: 셔츠 주문\n\n안녕하세요,\n\n저희 카페 세 곳 직원들이 입을 폴로 셔츠를 주문하고 싶습니다. 남색으로 60장이 필요합니다. S 20장, M 25장, L 15장입니다. 로고를 첨부했습니다.\n\n4월 20일 봄 행사 때 셔츠를 입고 싶습니다. 이번 주에 승인할 수 있도록 디자인을 보내 주시겠습니까?\n\n감사합니다.\n그레이스 리\n힐탑 커피 매니저","part":7},{"id":"p7-128","level":1,"kind":"double","passages":[{"doc_type":"메뉴","title":"Dalton Industries Cafeteria — Lunch Menu, Week of October 6","text":"DALTON INDUSTRIES CAFETERIA\nLunch Menu — Week of October 6\n\nMonday: Chicken soup and salad\nTuesday: Beef noodles\nWednesday: Fish and rice\nThursday: Vegetable curry\nFriday: Pasta with tomato sauce\n\nAll meals are $6 and come with fruit and a drink.\nLunch is served from 11:30 A.M. to 1:30 P.M."},{"doc_type":"이메일","title":"From: Peter Hall / To: Cafeteria Office / Date: October 6 / Subject: Lunch request","text":"Hello,\n\nI work in the sales department. Our team has a long meeting on Wednesday, and it will not finish until 2:00 P.M. Could you keep eight lunches for us that day? We can pick them up at 2:10.\n\nAlso, two people on my team do not eat fish. Would it be possible to give them the meal from Thursday's menu instead?\n\nThank you,\nPeter Hall"}],"questions":[{"q":"What is included with every lunch?","choices":["Soup","Bread","Fruit and a drink","A salad"],"answer":2,"type":"세부 사항","explanation":"메뉴 아래에 모든 식사는 6달러이며 과일과 음료가 함께 나온다고 했다."},{"q":"Why is Mr. Hall's team unable to eat during normal lunch hours on Wednesday?","choices":["The cafeteria will be closed.","They are working on a sales event.","They will be out of the office.","They will be in a meeting."],"answer":3,"type":"세부 사항","explanation":"수요일에 긴 회의가 있어 오후 2시까지 끝나지 않는다고 했다. 점심시간은 1시 30분에 끝난다."},{"q":"How many lunches does Mr. Hall ask the cafeteria to keep?","choices":["Two","Six","Eight","Ten"],"answer":2,"type":"세부 사항","explanation":"수요일에 점심 여덟 개를 남겨 달라고 요청했다. 2명은 생선을 먹지 않는 사람의 수이다."},{"q":"What meal does Mr. Hall want for two team members?","choices":["Chicken soup and salad","Beef noodles","Vegetable curry","Pasta with tomato sauce"],"answer":2,"type":"연계 문제","explanation":"생선을 먹지 않는 두 명에게 목요일 메뉴를 달라고 했고, 메뉴표에서 목요일은 채소 카레이다."},{"q":"In the e-mail, the word “keep” in paragraph 1 is closest in meaning to","choices":["save","follow","continue","own"],"answer":0,"type":"동의어","explanation":"'keep eight lunches for us'는 점심을 따로 '남겨 두다'라는 뜻이므로 save가 가장 가깝다."}],"translation":"[메뉴]\n돌턴 인더스트리 구내식당\n점심 메뉴 — 10월 6일 주간\n\n월요일: 닭고기 수프와 샐러드\n화요일: 소고기 국수\n수요일: 생선과 밥\n목요일: 채소 카레\n금요일: 토마토소스 파스타\n\n모든 식사는 6달러이며 과일과 음료가 함께 나옵니다.\n점심은 오전 11시 30분부터 오후 1시 30분까지 제공됩니다.\n\n[이메일]\n보낸 사람: 피터 홀 / 받는 사람: 구내식당 사무실 / 날짜: 10월 6일 / 제목: 점심 요청\n\n안녕하세요,\n\n저는 영업부에서 일합니다. 저희 팀이 수요일에 긴 회의가 있는데 오후 2시까지는 끝나지 않을 것 같습니다. 그날 저희 몫으로 점심 여덟 개를 남겨 주실 수 있을까요? 2시 10분에 가지러 가겠습니다.\n\n또한 저희 팀 두 명은 생선을 먹지 않습니다. 그 두 사람에게는 목요일 메뉴로 대신 주실 수 있을까요?\n\n감사합니다.\n피터 홀","part":7},{"id":"p7-129","level":1,"kind":"triple","passages":[{"doc_type":"광고","title":"FixIt Laptop Repair","text":"FIXIT LAPTOP REPAIR\n\nScreen replacement: $120\nBattery replacement: $80\nKeyboard repair: $60\nCleaning and speed check: $40\n\n• Most repairs are finished in 2 days.\n• Students get $10 off any repair. Just show your student card.\n• Open Monday to Saturday, 9 A.M.–6 P.M.\n\n45 River Road (next to Central Station)"},{"doc_type":"영수증","title":"FixIt Laptop Repair — Customer Receipt","text":"FIXIT LAPTOP REPAIR — CUSTOMER RECEIPT\n\nCustomer: Ellen Park\nDate received: Tuesday, November 4\nRepair: Battery replacement\nPrice: $80\nDiscount: –$10\nTotal paid: $70\nReady for pickup: Thursday, November 6, after 1 P.M."},{"doc_type":"문자 메시지","title":"Text-message chain","text":"Ellen Park [9:40 A.M.]: Hi, Jun. My laptop is at the repair shop, so I can't bring the slides to class today. Could you bring your laptop?\nJun Seo [9:42 A.M.]: Sure. Send me the file and I'll bring my laptop.\nEllen Park [9:43 A.M.]: Thanks! I'll get my laptop back tomorrow afternoon.\nJun Seo [9:44 A.M.]: Great. See you at 11."}],"questions":[{"q":"Where is FixIt Laptop Repair located?","choices":["Inside the main hall of Central Station","On Station Road","Near a university","Next to a train station"],"answer":3,"type":"세부 사항","explanation":"광고 마지막 줄에 리버 로드 45번지(센트럴 역 옆)라고 나와 있다."},{"q":"What is suggested about Ms. Park?","choices":["She is a student.","She works at FixIt.","She paid $80.","She bought a new laptop."],"answer":0,"type":"연계 문제","explanation":"광고에 학생은 학생증을 보여 주면 10달러를 할인받는다고 했고, 영수증에 10달러 할인을 받아 70달러를 냈다. 문자에서 수업(class)도 언급하므로 학생임을 알 수 있다."},{"q":"What problem did Ms. Park's laptop most likely have?","choices":["A bad battery","A broken screen","A broken keyboard","It was very slow."],"answer":0,"type":"세부 사항","explanation":"영수증의 수리 내용이 배터리 교체(Battery replacement)이다."},{"q":"Why does Ms. Park write to Mr. Seo?","choices":["To ask him to borrow a laptop","To ask him to bring his laptop to class","To change the time of a class","To recommend a repair shop"],"answer":1,"type":"주제·목적","explanation":"노트북이 수리점에 있어 슬라이드를 가져갈 수 없으니 서 씨에게 노트북을 가져와 달라고 부탁했다."},{"q":"On what day was the text-message chain most likely written?","choices":["Monday","Tuesday","Wednesday","Thursday"],"answer":2,"type":"연계 문제","explanation":"박 씨는 '내일 오후'에 노트북을 돌려받는다고 했고, 영수증에 따르면 찾는 날은 11월 6일 목요일 오후이다. 따라서 문자는 그 전날인 수요일에 쓴 것이다."}],"translation":"[광고]\n픽스잇 노트북 수리\n\n화면 교체: 120달러\n배터리 교체: 80달러\n키보드 수리: 60달러\n청소 및 속도 점검: 40달러\n\n• 대부분의 수리는 2일 안에 끝납니다.\n• 학생은 모든 수리 10달러 할인. 학생증만 보여 주세요.\n• 월~토 오전 9시~오후 6시 영업\n\n리버 로드 45번지 (센트럴 역 옆)\n\n[영수증]\n픽스잇 노트북 수리 — 고객 영수증\n\n고객: 엘런 박\n접수일: 11월 4일 화요일\n수리 내용: 배터리 교체\n가격: 80달러\n할인: -10달러\n결제 금액: 70달러\n찾는 날: 11월 6일 목요일 오후 1시 이후\n\n[문자 메시지]\n엘런 박 [오전 9:40]: 안녕, 준. 내 노트북이 수리점에 있어서 오늘 수업에 슬라이드를 가져갈 수가 없어. 네 노트북 좀 가져와 줄 수 있어?\n서준 [오전 9:42]: 물론이지. 파일 보내 주면 노트북 가져갈게.\n엘런 박 [오전 9:43]: 고마워! 노트북은 내일 오후에 찾아.\n서준 [오전 9:44]: 잘됐다. 11시에 보자.","part":7},{"id":"p7-130","level":1,"kind":"triple","passages":[{"doc_type":"광고","title":"Lakeview City Bus Tours","text":"LAKEVIEW CITY BUS TOURS\n\nMorning Tour: 9:00 A.M.–12:00 P.M. — Old Town, City Hall, and the Art Museum — $25\nAfternoon Tour: 1:30 P.M.–4:30 P.M. — Lake Park, the Harbor, and the Fish Market — $25\nNight Tour: 7:00 P.M.–9:00 P.M. — City lights from Tower Hill — $30\n\nAll tours leave from the Visitor Center on Park Avenue.\nGroups of 10 or more: $20 per person for any tour.\nBook online at www.lakeviewtours.com."},{"doc_type":"이메일","title":"From: Tom Reyes / To: bookings@lakeviewtours.com / Date: August 12 / Subject: Group booking","text":"Hello,\n\nI would like to book a tour for 12 people from my company on Friday, August 22. We are visiting Lakeview for a conference, and we are free only in the afternoon. Some of us would also like to buy seafood during the tour.\n\nPlease let me know if there are seats available.\n\nTom Reyes"},{"doc_type":"이메일","title":"From: Lakeview City Bus Tours / To: Tom Reyes / Date: August 13 / Subject: RE: Group booking","text":"Dear Mr. Reyes,\n\nThank you for your e-mail. We have reserved 12 seats for you on the tour you asked about. Please arrive at the Visitor Center 15 minutes before the tour starts. You can pay on the day by cash or card.\n\nWe look forward to seeing you!\n\nAmy Clark\nLakeview City Bus Tours"}],"questions":[{"q":"What is true about all the tours?","choices":["They all last about three hours each","They start at the same place.","They visit the Art Museum.","They cost $25."],"answer":1,"type":"사실 확인(NOT/TRUE)","explanation":"모든 투어는 파크 애비뉴의 방문자 센터에서 출발한다고 했다. 야간 투어는 2시간, 30달러이다."},{"q":"Why is Mr. Reyes visiting Lakeview?","choices":["To go on vacation","To attend a conference","To visit his family","To open a new office"],"answer":1,"type":"세부 사항","explanation":"첫 이메일에서 회의(conference) 때문에 레이크뷰를 방문한다고 했다."},{"q":"Which tour did Mr. Reyes most likely book?","choices":["The Morning Tour","The Afternoon Tour","The Night Tour","A private tour arranged for his group"],"answer":1,"type":"연계 문제","explanation":"레이즈 씨 일행은 오후에만 시간이 있고 해산물을 사고 싶다고 했다. 광고에서 오후 투어가 어시장(Fish Market)에 들른다."},{"q":"How much will each person in Mr. Reyes's group most likely pay?","choices":["$20","$25","$30","$12"],"answer":0,"type":"연계 문제","explanation":"10명 이상 단체는 어떤 투어든 1인당 20달러이고, 레이즈 씨 일행은 12명이다."},{"q":"What does Ms. Clark ask Mr. Reyes to do?","choices":["Pay online in advance","Call the Visitor Center","Send the names of the group members","Arrive early"],"answer":3,"type":"세부 사항","explanation":"투어 시작 15분 전에 방문자 센터에 도착해 달라고 했다. 결제는 당일 현금이나 카드로 하면 된다."}],"translation":"[광고]\n레이크뷰 시티 버스 투어\n\n오전 투어: 오전 9시~오후 12시 — 구시가지, 시청, 미술관 — 25달러\n오후 투어: 오후 1시 30분~4시 30분 — 레이크 공원, 항구, 어시장 — 25달러\n야간 투어: 오후 7시~9시 — 타워 힐에서 보는 도시 야경 — 30달러\n\n모든 투어는 파크 애비뉴의 방문자 센터에서 출발합니다.\n10명 이상 단체: 모든 투어 1인당 20달러.\nwww.lakeviewtours.com에서 온라인 예약하세요.\n\n[이메일 1]\n보낸 사람: 톰 레이즈 / 받는 사람: bookings@lakeviewtours.com / 날짜: 8월 12일 / 제목: 단체 예약\n\n안녕하세요,\n\n8월 22일 금요일에 저희 회사 직원 12명의 투어를 예약하고 싶습니다. 회의 때문에 레이크뷰를 방문하는데 오후에만 시간이 있습니다. 몇 명은 투어 중에 해산물도 사고 싶어 합니다.\n\n자리가 있는지 알려 주세요.\n\n톰 레이즈\n\n[이메일 2]\n보낸 사람: 레이크뷰 시티 버스 투어 / 받는 사람: 톰 레이즈 / 날짜: 8월 13일 / 제목: RE: 단체 예약\n\n레이즈 씨께,\n\n이메일 감사합니다. 문의하신 투어에 12석을 예약해 두었습니다. 투어 시작 15분 전까지 방문자 센터에 도착해 주세요. 결제는 당일 현금이나 카드로 하시면 됩니다.\n\n뵙기를 기대합니다!\n\n에이미 클라크\n레이크뷰 시티 버스 투어","part":7},{"id":"p7-131","level":2,"kind":"single","passages":[{"doc_type":"문자 메시지","title":"Text-message chain","text":"Ravi Patel [7:48 A.M.]: Good morning, Lisa. The truck from Fenton Paper hasn't arrived yet. It was supposed to be here at 7:30.\nLisa Grant [7:50 A.M.]: I'll call their dispatch office. Do we have enough boxes for the morning orders?\nRavi Patel [7:51 A.M.]: Only for about two hours.\nLisa Grant [7:58 A.M.]: The driver is stuck in traffic on Route 9. He should be there by 8:45.\nRavi Patel [7:59 A.M.]: That works. I'll start packing the smaller orders first.\nLisa Grant [8:00 A.M.]: Good idea. Let me know when the boxes come in."}],"questions":[{"q":"What is the problem?","choices":["A delivery is late.","Some boxes are damaged.","A driver is sick.","An order was sent to the wrong address."],"answer":0,"type":"주제·목적","explanation":"7시 30분에 오기로 한 펜턴 페이퍼 트럭이 아직 도착하지 않았다는 것이 문제이다. 상자가 손상되었다는 말은 없다."},{"q":"At 7:59 A.M., what does Mr. Patel mean when he writes, “That works”?","choices":["The truck has just arrived.","He is able to work late.","The packing machine is working again.","The new arrival time is acceptable."],"answer":3,"type":"의도 파악","explanation":"그랜트 씨가 기사가 8시 45분까지 도착할 것이라고 하자, 상자가 두 시간 정도는 버틸 수 있으므로 그 시간이면 괜찮다는 뜻이다."},{"q":"What will Mr. Patel most likely do next?","choices":["Call Fenton Paper","Drive to Route 9","Pack small orders","Order more boxes from another company"],"answer":2,"type":"추론","explanation":"파텔 씨는 작은 주문부터 포장하기 시작하겠다고 했다. 운송사에 전화한 사람은 그랜트 씨이다."}],"translation":"[문자 메시지]\n라비 파텔 [오전 7:48]: 좋은 아침이에요, 리사. 펜턴 페이퍼 트럭이 아직 안 왔어요. 7시 30분에 오기로 했거든요.\n리사 그랜트 [오전 7:50]: 제가 그쪽 배차 사무실에 전화해 볼게요. 오전 주문 처리할 상자는 충분해요?\n라비 파텔 [오전 7:51]: 두 시간 정도 쓸 분량밖에 없어요.\n리사 그랜트 [오전 7:58]: 기사가 9번 도로에서 차가 막혀 있대요. 8시 45분까지는 도착할 거래요.\n라비 파텔 [오전 7:59]: 그 정도면 괜찮아요. 작은 주문부터 포장을 시작할게요.\n리사 그랜트 [오전 8:00]: 좋은 생각이에요. 상자가 들어오면 알려 줘요.","part":7},{"id":"p7-132","level":2,"kind":"single","passages":[{"doc_type":"기사","title":"Local Bakery Wins National Prize","text":"MILLBROOK (May 14) — Golden Crust Bakery, a small family business on Elm Street, has won first prize in the National Bread Competition. [1] The bakery's owner, Clara Hoffman, entered her whole-wheat honey bread, a recipe that her grandmother created more than 50 years ago.\n\n“I was very surprised,” said Ms. Hoffman. “More than 300 bakeries took part this year.” [2]\n\nSince the news was announced, the bakery has been busier than ever. [3] To meet the demand, Ms. Hoffman has hired two new bakers and now opens at 6 A.M. instead of 7 A.M.\n\nThe winning bread will also be sold at Fresh Way supermarkets across the state starting in July. [4]"}],"questions":[{"q":"What is the article mainly about?","choices":["A new supermarket opening","A change in bread prices","A cooking class for families","A bakery that won a competition"],"answer":3,"type":"주제·목적","explanation":"골든 크러스트 베이커리가 전국 빵 대회에서 1등을 한 소식이 기사의 중심이다."},{"q":"What is indicated about the winning bread?","choices":["It was created by Ms. Hoffman's grandmother.","It is made with white flour and no honey at all","It is sold only on weekends.","It has won prizes before."],"answer":0,"type":"사실 확인(NOT/TRUE)","explanation":"할머니가 50여 년 전에 만든 레시피라고 했다. 꿀이 들어간 통밀 빵이며, 이전 수상 경력은 나오지 않는다."},{"q":"What change has the bakery made?","choices":["It moved to a new location.","It lowered its prices.","It opens earlier in the morning.","It closed on Sundays."],"answer":2,"type":"세부 사항","explanation":"수요를 맞추기 위해 제빵사 두 명을 새로 고용하고 오전 7시 대신 6시에 문을 연다고 했다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“On some mornings, customers have waited in line for over an hour.”","choices":["[1]","[2]","[3]","[4]"],"answer":2,"type":"문장 삽입","explanation":"수상 소식 이후 가게가 그 어느 때보다 바빠졌다는 문장 뒤인 [3]에 '손님들이 한 시간 넘게 줄을 섰다'는 구체적인 예가 와야 자연스럽다."}],"translation":"[기사]\n지역 빵집, 전국 대회 우승\n\n밀브룩 (5월 14일) — 엘름 스트리트의 작은 가족 사업체인 골든 크러스트 베이커리가 전국 빵 대회에서 1등을 차지했다. 빵집 주인 클라라 호프먼 씨는 50여 년 전 할머니가 만든 레시피인 통밀 꿀빵을 출품했다.\n\n호프먼 씨는 \"정말 놀랐어요. 올해 300곳이 넘는 빵집이 참가했거든요\"라고 말했다.\n\n소식이 발표된 뒤로 빵집은 그 어느 때보다 바빠졌다. (어떤 날 아침에는 손님들이 한 시간 넘게 줄을 서서 기다렸다.) 수요를 맞추기 위해 호프먼 씨는 제빵사 두 명을 새로 고용했고, 이제 오전 7시가 아닌 6시에 문을 연다.\n\n수상한 빵은 7월부터 주 전역의 프레시 웨이 슈퍼마켓에서도 판매될 예정이다.","part":7},{"id":"p7-133","level":2,"kind":"single","passages":[{"doc_type":"회람","title":"To: All Staff / From: Martin Ross, Office Manager / Date: September 8 / Subject: Visitor sign-in","text":"Starting Monday, September 15, all visitors to our office must sign in using the new tablet at the reception desk. Visitors will enter their name, company, and the name of the employee they are meeting. The tablet will then print a visitor badge and send a message to that employee.\n\nIf you are expecting a visitor, please enter their name in the online calendar the day before. This will make the sign-in process faster.\n\nThe paper sign-in book will no longer be used. If you have any questions, please contact me at extension 214."}],"questions":[{"q":"What is the main purpose of the memo?","choices":["To introduce a new receptionist","To explain a new process for visitors","To announce a change in office hours","To ask employees to update their calendars weekly"],"answer":1,"type":"주제·목적","explanation":"9월 15일부터 방문객은 안내 데스크의 태블릿으로 방문 등록을 해야 한다는 새 절차를 설명하는 회람이다."},{"q":"What will the tablet do after a visitor signs in?","choices":["Take a photo of the visitor","Call the security office","Notify the employee being visited","Print a parking pass"],"answer":2,"type":"세부 사항","explanation":"태블릿이 방문증을 출력하고 방문 대상 직원에게 메시지를 보낸다고 했다."},{"q":"What are employees asked to do?","choices":["Enter visitors' names in advance","Meet visitors in the lobby","Collect visitor badges","Sign the paper book"],"answer":0,"type":"세부 사항","explanation":"방문객이 올 예정이면 전날 온라인 달력에 이름을 입력해 달라고 했다. 종이 방문 기록부는 더 이상 쓰지 않는다."}],"translation":"[회람]\n받는 사람: 전 직원 / 보낸 사람: 마틴 로스, 사무실 관리자 / 날짜: 9월 8일 / 제목: 방문객 등록\n\n9월 15일 월요일부터 사무실을 찾는 모든 방문객은 안내 데스크에 있는 새 태블릿으로 방문 등록을 해야 합니다. 방문객은 이름, 회사, 만날 직원의 이름을 입력합니다. 그러면 태블릿이 방문증을 출력하고 해당 직원에게 메시지를 보냅니다.\n\n방문객이 올 예정이라면 전날 온라인 달력에 그 사람의 이름을 입력해 주십시오. 그러면 등록 과정이 더 빨라집니다.\n\n종이 방문 기록부는 더 이상 사용하지 않습니다. 궁금한 점이 있으면 내선 214번으로 연락해 주십시오.","part":7},{"id":"p7-134","level":2,"kind":"single","passages":[{"doc_type":"온라인 채팅","title":"Live Chat — SkyWest Airlines Customer Service","text":"Agent (Paula) [2:14 P.M.]: Hello, this is Paula. How can I help you today?\nJames Okoye [2:15 P.M.]: Hi. I'm flying from Toronto to Vancouver tomorrow on flight SW 418. I'd like to change my seat. I have a window seat near the back.\nAgent (Paula) [2:16 P.M.]: Let me check. Would you prefer an aisle seat?\nJames Okoye [2:16 P.M.]: Yes, and closer to the front if possible. I have a meeting right after we land.\nAgent (Paula) [2:18 P.M.]: I can offer you seat 6C. It's an aisle seat in row 6. There's a $15 fee for seats in rows 1 to 8.\nJames Okoye [2:19 P.M.]: I'll take it.\nAgent (Paula) [2:20 P.M.]: Done. Your new boarding pass has been sent to your e-mail."}],"questions":[{"q":"Why does Mr. Okoye contact the airline?","choices":["To cancel a flight","To ask about baggage rules","To change his seat","To book a hotel in Vancouver"],"answer":2,"type":"주제·목적","explanation":"내일 항공편의 좌석을 바꾸고 싶다고 했다."},{"q":"Why does Mr. Okoye want to sit near the front?","choices":["He needs extra legroom for his long legs.","He would like a better view.","He is traveling with a colleague.","He wants to leave the plane quickly."],"answer":3,"type":"추론","explanation":"착륙 직후 회의가 있다고 했으므로 빨리 내리기 위해 앞쪽 좌석을 원하는 것으로 볼 수 있다."},{"q":"At 2:19 P.M., what does Mr. Okoye mean when he writes, “I'll take it”?","choices":["He will pay the fee for seat 6C.","He will take an earlier flight.","He will pick up his boarding pass at the airport.","He will keep his window seat."],"answer":0,"type":"의도 파악","explanation":"상담원이 6C 좌석을 제안하며 15달러 요금이 있다고 하자 'I'll take it'이라고 했으므로 요금을 내고 그 좌석으로 바꾸겠다는 뜻이다."}],"translation":"[온라인 채팅 — 스카이웨스트 항공 고객 서비스]\n상담원(폴라) [오후 2:14]: 안녕하세요, 폴라입니다. 무엇을 도와드릴까요?\n제임스 오코예 [오후 2:15]: 안녕하세요. 내일 SW 418편으로 토론토에서 밴쿠버로 가는데요. 좌석을 바꾸고 싶어요. 뒤쪽 창가 좌석이에요.\n상담원(폴라) [오후 2:16]: 확인해 볼게요. 통로 좌석을 원하세요?\n제임스 오코예 [오후 2:16]: 네, 가능하면 앞쪽으로요. 착륙하자마자 회의가 있어서요.\n상담원(폴라) [오후 2:18]: 6C 좌석을 드릴 수 있어요. 6열 통로 좌석입니다. 1~8열 좌석은 15달러의 요금이 있습니다.\n제임스 오코예 [오후 2:19]: 그걸로 할게요.\n상담원(폴라) [오후 2:20]: 처리됐습니다. 새 탑승권을 이메일로 보내 드렸습니다.","part":7},{"id":"p7-135","level":2,"kind":"single","passages":[{"doc_type":"입장권","title":"Admission Ticket — Northern Business Expo","text":"NORTHERN BUSINESS EXPO\nRiverside Convention Center, Halls A–C\n\nTicket type: Two-Day Pass\nName: Sofia Marquez\nCompany: Brightpath Logistics\nValid: October 21–22, 9 A.M.–6 P.M.\n\n• This ticket includes entry to all exhibition halls and free coffee at the Main Lounge.\n• Seminars in Room 101 require a separate reservation.\n• Please wear your badge at all times. Lost badges can be replaced at the registration desk for $5.\n• This ticket cannot be transferred to another person."}],"questions":[{"q":"What is included with the ticket?","choices":["Lunch at the Main Lounge","Entry to the seminars","Free coffee","Parking at the convention center"],"answer":2,"type":"세부 사항","explanation":"입장권에는 모든 전시장 입장과 메인 라운지 무료 커피가 포함된다고 했다. 세미나는 별도 예약이 필요하다."},{"q":"What is indicated about the ticket?","choices":["It is valid for three days.","It can be exchanged for a seminar ticket.","It was free of charge.","It can be used by Ms. Marquez only."],"answer":3,"type":"사실 확인(NOT/TRUE)","explanation":"이 입장권은 다른 사람에게 양도할 수 없다(cannot be transferred)고 했으므로 마르케스 씨만 사용할 수 있다. 유효 기간은 이틀이다."}],"translation":"[입장권]\n노던 비즈니스 엑스포\n리버사이드 컨벤션 센터, A~C홀\n\n입장권 종류: 2일권\n이름: 소피아 마르케스\n회사: 브라이트패스 물류\n유효: 10월 21~22일, 오전 9시~오후 6시\n\n• 이 입장권으로 모든 전시장에 입장할 수 있으며 메인 라운지에서 무료 커피가 제공됩니다.\n• 101호 세미나는 별도 예약이 필요합니다.\n• 배지는 항상 착용해 주십시오. 분실한 배지는 등록 데스크에서 5달러에 재발급받을 수 있습니다.\n• 이 입장권은 다른 사람에게 양도할 수 없습니다.","part":7},{"id":"p7-136","level":2,"kind":"single","passages":[{"doc_type":"후기","title":"Customer Review — Printeck P50 Office Printer ★★★★☆ / Posted by Daniel Wu, March 3","text":"Our small accounting office bought the Printeck P50 two months ago to replace an old printer that kept jamming. The P50 is fast — about 40 pages per minute — and the print quality is excellent. Setting it up on our office network took only ten minutes.\n\nMy only complaint is the price of the ink cartridges. They are more expensive than those for our old printer, and they need to be replaced about once a month. Still, I would recommend the P50 to other small offices because it has saved us a lot of time."}],"questions":[{"q":"Why did Mr. Wu's office buy the P50?","choices":["Their old printer often had problems.","They opened a second office.","Their old printer was too slow.","The P50 was on sale."],"answer":0,"type":"세부 사항","explanation":"자주 종이가 걸리던(kept jamming) 오래된 프린터를 바꾸려고 샀다고 했다."},{"q":"What does Mr. Wu NOT mention about the P50?","choices":["Its printing speed","Its print quality","Its size","How easy it is to set up"],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"속도(분당 40쪽), 인쇄 품질, 설치 시간(10분)은 언급했지만 크기는 말하지 않았다."},{"q":"What does Mr. Wu dislike about the printer?","choices":["It is noisy.","Its ink is costly.","It is hard to connect to a network.","It uses too much paper."],"answer":1,"type":"세부 사항","explanation":"유일한 불만은 잉크 카트리지 가격이 비싸다는 것이라고 했다."}],"translation":"[후기]\n고객 후기 — 프린텍 P50 사무용 프린터 ★★★★☆ / 대니얼 우, 3월 3일 작성\n\n저희 작은 회계 사무소는 계속 종이가 걸리던 오래된 프린터를 교체하려고 두 달 전에 프린텍 P50을 샀습니다. P50은 분당 약 40쪽으로 빠르고 인쇄 품질도 훌륭합니다. 사무실 네트워크에 연결하는 데 10분밖에 안 걸렸습니다.\n\n유일한 불만은 잉크 카트리지 가격입니다. 예전 프린터용보다 비싸고 한 달에 한 번 정도 갈아야 합니다. 그래도 시간을 많이 절약해 주었기 때문에 다른 소규모 사무실에도 P50을 추천합니다.","part":7},{"id":"p7-137","level":2,"kind":"double","passages":[{"doc_type":"양식","title":"Maple Court Apartments — Maintenance Request Form","text":"MAPLE COURT APARTMENTS — MAINTENANCE REQUEST FORM\n\nResident name: Irene Novak\nUnit: 4B\nPhone: 555-0172\nDate submitted: Monday, February 10\n\nProblem: The heater in the bedroom is not working. It makes a loud noise when I turn it on, but the room stays cold. The heater in the living room works fine.\n\nBest time to visit: Weekdays after 5 P.M. or any time on Saturday\nMay staff enter when you are not home? ☐ Yes ☒ No"},{"doc_type":"이메일","title":"From: Carl Benson, Maple Court Maintenance / To: Irene Novak / Date: February 11 / Subject: Your request","text":"Dear Ms. Novak,\n\nThank you for your request. Our technician, Luis, needs to replace a part in your heater. Unfortunately, the part will not arrive until Thursday. Luis can visit your apartment on Thursday at 5:30 P.M. Please let me know if this time is convenient for you.\n\nIn the meantime, we can lend you a portable electric heater. You can pick one up at the management office, which is open until 6 P.M. on weekdays.\n\nBest regards,\nCarl Benson\nMaintenance Supervisor"}],"questions":[{"q":"What problem does Ms. Novak report?","choices":["A window will not close.","A heater does not warm a room.","The living room is too hot.","Her phone line is not working."],"answer":1,"type":"세부 사항","explanation":"침실 히터가 켜면 큰 소리가 나지만 방은 계속 춥다고 했다. 거실 히터는 잘 작동한다."},{"q":"What is indicated about Ms. Novak on the form?","choices":["She lives on the second floor.","She is available on weekday mornings.","She is moving out of her apartment.","She wants to be home during the repair."],"answer":3,"type":"사실 확인(NOT/TRUE)","explanation":"집에 없을 때 직원이 들어가도 되느냐는 질문에 '아니요'에 표시했으므로 수리할 때 집에 있기를 원한다. 방문 가능 시간은 평일 오후 5시 이후나 토요일이다."},{"q":"Why can the repair not be done right away?","choices":["The technician is on vacation.","The management office is closed.","Ms. Novak is not at home.","A part has to be delivered."],"answer":3,"type":"세부 사항","explanation":"히터 부품을 교체해야 하는데 그 부품이 목요일에야 도착한다고 했다."},{"q":"Why most likely did Mr. Benson suggest 5:30 P.M. on Thursday?","choices":["It is when the office closes.","Luis works only in the evenings.","It fits the time Ms. Novak said she is available.","Ms. Novak asked for that exact time."],"answer":2,"type":"연계 문제","explanation":"양식에서 노박 씨는 평일 오후 5시 이후에 방문 가능하다고 했고, 벤슨 씨는 목요일 오후 5시 30분을 제안했다. 노박 씨가 정확히 그 시간을 요청한 것은 아니다."},{"q":"What does Mr. Benson offer Ms. Novak?","choices":["A portable heater to use for now","A discount on her rent for this month","A new apartment","A visit on Saturday"],"answer":0,"type":"세부 사항","explanation":"그동안(in the meantime) 쓸 휴대용 전기 히터를 빌려줄 수 있다고 했다."}],"translation":"[양식]\n메이플 코트 아파트 — 수리 요청서\n\n입주자 이름: 아이린 노박\n호수: 4B\n전화: 555-0172\n제출일: 2월 10일 월요일\n\n문제: 침실 히터가 작동하지 않습니다. 켜면 큰 소리가 나는데 방은 계속 춥습니다. 거실 히터는 잘 작동합니다.\n\n방문하기 좋은 시간: 평일 오후 5시 이후 또는 토요일 아무 때나\n부재 시 직원 출입 허용? ☐ 예 ☒ 아니요\n\n[이메일]\n보낸 사람: 칼 벤슨, 메이플 코트 관리실 / 받는 사람: 아이린 노박 / 날짜: 2월 11일 / 제목: 요청하신 건\n\n노박 씨께,\n\n요청해 주셔서 감사합니다. 저희 기술자 루이스가 히터 부품을 하나 교체해야 합니다. 안타깝게도 그 부품이 목요일에야 도착합니다. 루이스가 목요일 오후 5시 30분에 방문할 수 있습니다. 이 시간이 괜찮으신지 알려 주세요.\n\n그동안 휴대용 전기 히터를 빌려 드릴 수 있습니다. 평일 오후 6시까지 여는 관리 사무소에서 가져가시면 됩니다.\n\n감사합니다.\n칼 벤슨\n시설 관리 책임자","part":7},{"id":"p7-138","level":2,"kind":"double","passages":[{"doc_type":"광고","title":"Smart Money for Small Businesses — Free Seminar","text":"SMART MONEY FOR SMALL BUSINESSES\nA free seminar presented by Harbor Bank\n\nDate: Thursday, June 12\nTime: 6:30 P.M.–8:30 P.M.\nPlace: Harbor Bank Community Room, 75 Bay Street\n\nTopics:\n• Keeping simple financial records\n• Planning for taxes\n• Getting a small business loan\n\nSpeaker: Monica Fields, Harbor Bank business adviser\nSpace is limited to 40 people. Register by June 9 at www.harborbank.com/events.\nLight snacks will be served."},{"doc_type":"이메일","title":"From: Owen Hart / To: events@harborbank.com / Date: June 10 / Subject: Seminar on June 12","text":"Hello,\n\nI own a small flower shop on Bay Street, and I just saw your poster for the seminar on Thursday. I am especially interested in learning about loans, because I hope to open a second shop next year.\n\nI know I have missed the registration deadline, but is there still space for me? If not, will there be another seminar later this year?\n\nThank you,\nOwen Hart\nHart's Flowers"}],"questions":[{"q":"What is NOT a topic of the seminar?","choices":["Financial records","Taxes","Hiring employees","Business loans"],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"재무 기록, 세금 계획, 소상공인 대출이 주제이고, 직원 채용은 없다."},{"q":"Who is Ms. Fields?","choices":["A flower shop owner","A tax officer","A bank employee","An event planner"],"answer":2,"type":"세부 사항","explanation":"강연자 모니카 필즈 씨는 하버 은행의 기업 상담사(business adviser)이다."},{"q":"Why is Mr. Hart interested in the seminar?","choices":["He wants to become a bank adviser.","He plans to expand his business.","He needs help with his taxes.","He wants to sell flowers at the event."],"answer":1,"type":"세부 사항","explanation":"내년에 두 번째 가게를 열고 싶어서 특히 대출에 관심이 있다고 했다."},{"q":"What problem does Mr. Hart mention?","choices":["He cannot attend on Thursday.","He lost his registration number.","The seminar room is too small.","He registered too late."],"answer":3,"type":"연계 문제","explanation":"광고에 6월 9일까지 등록하라고 했는데 하트 씨는 6월 10일에 이메일을 보내며 등록 마감을 놓쳤다고 했다."},{"q":"What is suggested about Mr. Hart's shop?","choices":["It is near the seminar location.","It opened last year.","It has two locations.","It supplies flowers to Harbor Bank."],"answer":0,"type":"연계 문제","explanation":"세미나 장소는 베이 스트리트 75번지이고, 하트 씨의 꽃집도 베이 스트리트에 있다. 두 번째 가게는 내년에 열 계획이다."}],"translation":"[광고]\n소상공인을 위한 똑똑한 자금 관리\n하버 은행이 진행하는 무료 세미나\n\n날짜: 6월 12일 목요일\n시간: 오후 6시 30분~8시 30분\n장소: 하버 은행 커뮤니티룸, 베이 스트리트 75번지\n\n주제:\n• 간단한 재무 기록 관리\n• 세금 계획 세우기\n• 소상공인 대출 받기\n\n강연자: 모니카 필즈, 하버 은행 기업 상담사\n정원은 40명입니다. 6월 9일까지 www.harborbank.com/events에서 등록하세요.\n가벼운 간식이 제공됩니다.\n\n[이메일]\n보낸 사람: 오언 하트 / 받는 사람: events@harborbank.com / 날짜: 6월 10일 / 제목: 6월 12일 세미나\n\n안녕하세요,\n\n저는 베이 스트리트에서 작은 꽃집을 운영하는데, 방금 목요일 세미나 포스터를 봤습니다. 내년에 두 번째 가게를 열고 싶어서 특히 대출에 대해 배우고 싶습니다.\n\n등록 마감을 놓친 것은 알지만 아직 자리가 있을까요? 없다면 올해 안에 다른 세미나가 열리나요?\n\n감사합니다.\n오언 하트\n하트 꽃집","part":7},{"id":"p7-139","level":2,"kind":"triple","passages":[{"doc_type":"웹페이지","title":"www.netlinkbiz.com/plans","text":"NETLINK BUSINESS INTERNET PLANS\n\nBasic — 100 Mbps — $45/month — Good for 1–5 users\nStandard — 300 Mbps — $70/month — Good for 6–15 users\nPremium — 1 Gbps — $110/month — Good for 16–40 users\n\n• All plans include a free router and 24-hour technical support.\n• Installation fee: $60 (free if you sign a two-year contract)\n• Add a backup mobile connection for $15/month."},{"doc_type":"주문서","title":"NetLink Order Form","text":"NETLINK ORDER FORM\n\nBusiness name: Rivera Dental Clinic\nContact: Marco Rivera\nNumber of users: 12\nPlan: Standard\nContract length: 1 year\nBackup mobile connection: Yes\nPreferred installation date: April 3"},{"doc_type":"이메일","title":"From: Marco Rivera / To: support@netlinkbiz.com / Date: March 27 / Subject: My order","text":"Hello,\n\nI placed an order for our clinic yesterday. After reading your Web site again, I realized that I could save money on installation with a longer contract. Could you change my contract to two years? Everything else in my order can stay the same.\n\nAlso, our clinic is closed on April 3 for a holiday. Would it be possible for the technician to come on April 4 instead?\n\nThank you,\nMarco Rivera"}],"questions":[{"q":"What do all NetLink plans include?","choices":["A backup mobile connection","Free installation","A free router","Speeds of 1 Gbps"],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"모든 요금제에 무료 라우터와 24시간 기술 지원이 포함된다. 백업 회선은 월 15달러 추가이다."},{"q":"Why did Mr. Rivera most likely choose the Standard plan?","choices":["It is the cheapest plan.","It is the fastest plan.","It includes free installation.","It fits the number of people who will use it."],"answer":3,"type":"연계 문제","explanation":"주문서에 사용자 수가 12명이고, 웹페이지에서 스탠더드 요금제는 6~15명에 적합하다고 했다."},{"q":"What change does Mr. Rivera request?","choices":["A faster plan","A different contact person","A lower monthly fee","A longer contract"],"answer":3,"type":"주제·목적","explanation":"설치비를 아끼기 위해 계약 기간을 2년으로 바꿔 달라고 요청했다."},{"q":"If the change is made, how much will Mr. Rivera pay for installation?","choices":["$0","$15","$45","$60"],"answer":0,"type":"연계 문제","explanation":"웹페이지에 2년 계약을 하면 설치비 60달러가 무료라고 했다. 리베라 씨는 2년으로 바꿔 달라고 했으므로 설치비는 0달러이다."},{"q":"Why does Mr. Rivera ask to change the installation date?","choices":["He will be traveling.","He needs more time to prepare.","The technician is not available.","The clinic will be closed."],"answer":3,"type":"세부 사항","explanation":"4월 3일은 휴일이라 병원이 문을 닫기 때문에 4월 4일로 바꿔 달라고 했다."}],"translation":"[웹페이지]\n넷링크 기업용 인터넷 요금제\n\n베이식 — 100Mbps — 월 45달러 — 1~5명에 적합\n스탠더드 — 300Mbps — 월 70달러 — 6~15명에 적합\n프리미엄 — 1Gbps — 월 110달러 — 16~40명에 적합\n\n• 모든 요금제에 무료 라우터와 24시간 기술 지원이 포함됩니다.\n• 설치비: 60달러 (2년 계약 시 무료)\n• 백업 모바일 회선은 월 15달러에 추가할 수 있습니다.\n\n[주문서]\n넷링크 주문서\n\n업체명: 리베라 치과\n담당자: 마르코 리베라\n사용자 수: 12명\n요금제: 스탠더드\n계약 기간: 1년\n백업 모바일 회선: 예\n희망 설치일: 4월 3일\n\n[이메일]\n보낸 사람: 마르코 리베라 / 받는 사람: support@netlinkbiz.com / 날짜: 3월 27일 / 제목: 제 주문\n\n안녕하세요,\n\n어제 저희 병원 주문을 넣었습니다. 웹사이트를 다시 읽어 보니 계약 기간을 길게 하면 설치비를 아낄 수 있다는 걸 알았습니다. 계약을 2년으로 바꿔 주실 수 있을까요? 나머지 주문 내용은 그대로 두셔도 됩니다.\n\n또한 4월 3일은 휴일이라 병원이 문을 닫습니다. 기술자분이 대신 4월 4일에 오실 수 있을까요?\n\n감사합니다.\n마르코 리베라","part":7},{"id":"p7-140","level":2,"kind":"triple","passages":[{"doc_type":"웹페이지","title":"www.claytonmuseum.org/membership","text":"CLAYTON MUSEUM OF MODERN ART — MEMBERSHIP\n\nIndividual — $60 per year: Free entry for one person, 10% off at the museum shop\nFamily — $110 per year: Free entry for two adults and up to three children, 10% off at the museum shop\nPatron — $250 per year: All Family benefits, plus invitations to exhibition opening nights and 20% off at the museum shop\n\nNew members who join online before September 30 receive a free museum tote bag."},{"doc_type":"신청서","title":"Clayton Museum Membership Application","text":"CLAYTON MUSEUM MEMBERSHIP APPLICATION\n\nName: Yuki Tanaka\nAddress: 18 Willow Lane, Clayton\nMembership level: Family\nNumber of adults: 2  Number of children: 2\nPayment: Credit card\nApplication date: September 24 (submitted online)"},{"doc_type":"이메일","title":"From: Yuki Tanaka / To: members@claytonmuseum.org / Date: October 15 / Subject: Membership question","text":"Hello,\n\nMy family has enjoyed visiting the museum since we became members last month, and we love the bag we received. I have a question, though. A friend told me about the opening night for the new photography exhibition on November 2. Could my family attend? If not, would it be possible to upgrade our membership?\n\nThank you,\nYuki Tanaka"}],"questions":[{"q":"What do all members receive?","choices":["Invitations to opening nights","A free tote bag","Free entry for children","A discount at the museum shop"],"answer":3,"type":"사실 확인(NOT/TRUE)","explanation":"세 등급 모두 박물관 기념품점 할인(10% 또는 20%)을 받는다. 개막 행사 초대는 패트런만, 토트백은 9월 30일 전 온라인 가입자만 받는다."},{"q":"How much did Ms. Tanaka most likely pay?","choices":["$60","$110","$220","$250"],"answer":1,"type":"연계 문제","explanation":"신청서에서 가족(Family) 등급을 골랐고, 웹페이지에서 가족 회원은 연 110달러이다."},{"q":"Why did Ms. Tanaka receive a bag?","choices":["She joined online before the deadline.","She bought it at the museum shop on opening day","She attended an opening night.","She chose the Patron level."],"answer":0,"type":"연계 문제","explanation":"9월 30일 전에 온라인으로 가입하면 토트백을 준다고 했고, 다나카 씨는 9월 24일에 온라인으로 신청했다."},{"q":"Why did Ms. Tanaka write the e-mail?","choices":["To cancel her membership","To report a lost card","To ask about an event","To buy photographs"],"answer":2,"type":"주제·목적","explanation":"11월 2일 사진전 개막 행사에 가족이 참석할 수 있는지 문의하려고 이메일을 썼다."},{"q":"What will Ms. Tanaka most likely need to do to attend the opening night?","choices":["Buy tickets for her children","Change to the Patron level","Join before September 30","Visit on a weekday"],"answer":1,"type":"추론","explanation":"개막 행사 초대는 패트런 회원 혜택이므로 가족 회원인 다나카 씨는 패트런으로 등급을 올려야 할 것이다."}],"translation":"[웹페이지]\n클레이턴 현대미술관 — 회원 안내\n\n개인 — 연 60달러: 1인 무료 입장, 미술관 기념품점 10% 할인\n가족 — 연 110달러: 성인 2명과 어린이 최대 3명 무료 입장, 기념품점 10% 할인\n후원(패트런) — 연 250달러: 가족 회원 혜택 전부 + 전시 개막 행사 초대, 기념품점 20% 할인\n\n9월 30일 전에 온라인으로 가입하는 신규 회원에게는 미술관 토트백을 드립니다.\n\n[신청서]\n클레이턴 미술관 회원 가입 신청서\n\n이름: 유키 다나카\n주소: 클레이턴, 윌로 레인 18번지\n회원 등급: 가족\n성인 수: 2 어린이 수: 2\n결제: 신용카드\n신청일: 9월 24일 (온라인 제출)\n\n[이메일]\n보낸 사람: 유키 다나카 / 받는 사람: members@claytonmuseum.org / 날짜: 10월 15일 / 제목: 회원 관련 문의\n\n안녕하세요,\n\n지난달 회원이 된 이후 저희 가족은 미술관 방문을 즐기고 있고, 받은 가방도 아주 마음에 듭니다. 그런데 질문이 하나 있습니다. 친구에게서 11월 2일 새 사진전 개막 행사 이야기를 들었습니다. 저희 가족도 참석할 수 있을까요? 안 된다면 회원 등급을 올릴 수 있을까요?\n\n감사합니다.\n유키 다나카","part":7},{"id":"p7-141","level":3,"kind":"single","passages":[{"doc_type":"기사","title":"Ashwood Furniture Moves Online / By Kendra Mills","text":"BRANTFORD (August 3) — For 40 years, Ashwood Furniture sold its handmade oak tables and chairs only through its showroom on Lake Road. That is about to change. [1] Starting next month, customers anywhere in the country will be able to order Ashwood products through the company's new Web site.\n\n“Many of our customers moved away but still wanted our furniture,” said Ashwood's president, Neil Carver. “They used to call us and ask us to ship pieces to them, which was difficult to arrange.” [2]\n\nTo prepare for the change, Ashwood has partnered with Haldane Freight, a delivery company that specializes in large household items. [3] Customers will be able to choose a delivery date and track their order online.\n\nThe showroom will remain open. [4] In fact, Mr. Carver plans to add a workshop area there so that visitors can watch the company's craftspeople at work."}],"questions":[{"q":"What is the article mainly about?","choices":["A furniture company's plan to sell products online","The opening of a new delivery company","A furniture showroom that is closing","A craftsperson who won an award"],"answer":0,"type":"주제·목적","explanation":"40년간 전시장에서만 팔던 애시우드 가구가 다음 달부터 웹사이트로 전국에 판매한다는 내용이 중심이다. 전시장은 계속 운영된다."},{"q":"According to Mr. Carver, why did the company make the change?","choices":["The showroom rent increased and the company needed another source of income","Customers who had moved still wanted to buy its products.","A competitor started selling online.","Its oak supplier closed."],"answer":1,"type":"세부 사항","explanation":"카버 사장은 이사 간 고객들이 여전히 가구를 원했고 배송을 부탁했지만 처리하기 어려웠다고 말했다."},{"q":"What will happen at the showroom?","choices":["It will be moved to a larger building.","It will open only on weekends.","A space for watching furniture being made will be added.","It will be used as a delivery center."],"answer":2,"type":"세부 사항","explanation":"카버 사장은 방문객이 장인들의 작업을 볼 수 있도록 전시장에 작업 공간을 추가할 계획이라고 했다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“Its two-person teams will carry each piece into the customer's home and set it up.”","choices":["[1]","[2]","[3]","[4]"],"answer":2,"type":"문장 삽입","explanation":"'Its'는 바로 앞에 소개된 배송 회사 할데인 프레이트를 가리킨다. 따라서 할데인 프레이트와 제휴했다는 문장 뒤인 [3]이 알맞다."}],"translation":"[기사]\n애시우드 가구, 온라인 판매 시작 / 켄드라 밀스 기자\n\n브랜트퍼드 (8월 3일) — 애시우드 가구는 40년 동안 수제 참나무 탁자와 의자를 레이크 로드의 전시장에서만 팔아 왔다. 이것이 곧 바뀐다. 다음 달부터 전국 어디서든 고객이 회사의 새 웹사이트로 애시우드 제품을 주문할 수 있다.\n\n애시우드의 닐 카버 사장은 \"많은 고객이 이사를 갔지만 여전히 저희 가구를 원했습니다. 전화로 가구를 보내 달라고 부탁하곤 했는데, 그걸 처리하기가 어려웠어요\"라고 말했다.\n\n이 변화를 준비하기 위해 애시우드는 대형 가정용품을 전문으로 하는 배송 회사 할데인 프레이트와 제휴했다. (이 회사의 2인 1조 팀이 각 가구를 고객의 집 안까지 옮겨 설치해 준다.) 고객은 배송 날짜를 고르고 온라인으로 주문을 추적할 수 있다.\n\n전시장은 계속 문을 연다. 오히려 카버 사장은 방문객이 장인들의 작업 모습을 볼 수 있도록 그곳에 작업 공간을 추가할 계획이다.","part":7},{"id":"p7-142","level":3,"kind":"single","passages":[{"doc_type":"온라인 채팅","title":"Online chat discussion","text":"Hannah Moss [10:05 A.M.]: The photographer for the Brisa sunglasses campaign just canceled. She has a family emergency.\nOliver Grant [10:06 A.M.]: The shoot is Thursday! The models and the beach location are already booked.\nHannah Moss [10:07 A.M.]: I know. Does anyone know another photographer who is free on short notice?\nPriya Shah [10:09 A.M.]: Diego Ferreira did our winter catalog. He's very flexible.\nOliver Grant [10:10 A.M.]: He was great, but he mostly works in studios.\nPriya Shah [10:11 A.M.]: Actually, his Web site shows a lot of outdoor work from this year.\nHannah Moss [10:12 A.M.]: Then let's ask him. Priya, could you send me his contact information?\nPriya Shah [10:13 A.M.]: I'll do better than that. I'm calling him right now.\nOliver Grant [10:15 A.M.]: OK. I'll let the models' agency know the shoot is still on, but we may need to start a bit later."}],"questions":[{"q":"What problem are the writers discussing?","choices":["A beach location is unavailable.","A photographer can no longer do a job.","Some models canceled their contracts at the last minute","A catalog was printed with errors."],"answer":1,"type":"주제·목적","explanation":"선글라스 광고 촬영을 맡은 사진작가가 가족 사정으로 취소했다는 것이 문제이다."},{"q":"Why does Mr. Grant hesitate about hiring Mr. Ferreira at first?","choices":["Mr. Ferreira charges high fees.","Mr. Ferreira is not available on Thursday.","Mr. Ferreira usually works indoors.","Mr. Ferreira has never worked with the company."],"answer":2,"type":"세부 사항","explanation":"그랜트 씨는 페헤이라 씨가 훌륭했지만 주로 스튜디오에서 일한다고 했다. 해변 야외 촬영이기 때문에 망설인 것이다."},{"q":"At 10:13 A.M., what does Ms. Shah mean when she writes, “I'll do better than that”?","choices":["She will contact Mr. Ferreira herself.","She will find a cheaper photographer.","She will take the photographs herself.","She will update Mr. Ferreira's Web site."],"answer":0,"type":"의도 파악","explanation":"모스 씨가 연락처를 보내 달라고 하자 '그보다 더 나은 걸 하겠다'며 지금 바로 그에게 전화하겠다고 했다. 연락처만 주는 대신 직접 연락하겠다는 뜻이다."},{"q":"What will Mr. Grant most likely do next?","choices":["Cancel the beach reservation","Reschedule the shoot for next week","Review Mr. Ferreira's Web site","Contact a modeling agency"],"answer":3,"type":"추론","explanation":"그랜트 씨는 모델 에이전시에 촬영이 그대로 진행된다고 알리겠다고 했다."}],"translation":"[온라인 채팅]\n해나 모스 [오전 10:05]: 브리사 선글라스 캠페인 사진작가가 방금 취소했어요. 가족에게 급한 일이 생겼대요.\n올리버 그랜트 [오전 10:06]: 촬영이 목요일인데요! 모델이랑 해변 장소도 다 예약해 놨어요.\n해나 모스 [오전 10:07]: 알아요. 급하게라도 시간 되는 다른 사진작가 아는 분 있어요?\n프리야 샤 [오전 10:09]: 디에고 페헤이라 씨가 우리 겨울 카탈로그를 찍었잖아요. 일정 조정을 잘해 줘요.\n올리버 그랜트 [오전 10:10]: 그분 정말 잘했죠. 그런데 주로 스튜디오에서 작업하잖아요.\n프리야 샤 [오전 10:11]: 사실 그분 웹사이트를 보면 올해 야외 작업이 많아요.\n해나 모스 [오전 10:12]: 그럼 그분께 부탁해 봐요. 프리야, 연락처 좀 보내 줄래요?\n프리야 샤 [오전 10:13]: 그보다 더 확실하게 할게요. 지금 바로 전화하고 있어요.\n올리버 그랜트 [오전 10:15]: 좋아요. 모델 에이전시에는 촬영이 예정대로 진행된다고 알릴게요. 다만 조금 늦게 시작할 수도 있다고요.","part":7},{"id":"p7-143","level":3,"kind":"single","passages":[{"doc_type":"이메일","title":"From: Gloria Feng, Property Manager / To: All Tenants, Kessler Office Park / Date: January 20 / Subject: Parking permits","text":"Dear Tenants,\n\nBeginning March 1, Kessler Office Park will use electronic parking permits. Instead of hanging paper permits from their mirrors, employees will register their license plate numbers, and cameras at the entrances will recognize registered vehicles automatically.\n\nEach company is asked to send a list of its employees' names and license plate numbers to the management office by February 14. Companies will receive the same number of parking spaces as they have now. Visitors will continue to park in the area near Building C and should get a pass from the receptionist of the company they are visiting.\n\nPaper permits will no longer be valid after February 28. Vehicles without a registered plate may be asked to move.\n\nThank you for your cooperation.\n\nGloria Feng"}],"questions":[{"q":"What is the purpose of the e-mail?","choices":["To announce an increase in parking fees","To describe a change to the parking system","To report the opening of Building C","To ask tenants to hire more security staff"],"answer":1,"type":"주제·목적","explanation":"3월 1일부터 종이 주차증 대신 번호판 등록 방식의 전자 주차 허가제로 바뀐다고 알리는 이메일이다."},{"q":"What must each company do by February 14?","choices":["Pay for new parking spaces","Collect paper permits from employees","Submit employee vehicle information","Install cameras at its entrance"],"answer":2,"type":"세부 사항","explanation":"2월 14일까지 직원 이름과 차량 번호판 목록을 관리 사무소에 보내야 한다고 했다."},{"q":"What is indicated about visitors?","choices":["Their parking area will not change.","They will need to register their plates online.","They can no longer park at the office park.","They must pay a daily fee."],"answer":0,"type":"사실 확인(NOT/TRUE)","explanation":"방문객은 계속(continue to) C동 근처에 주차하고 방문하는 회사의 접수 담당자에게 주차권을 받으면 된다고 했으므로 주차 구역은 그대로이다."}],"translation":"[이메일]\n보낸 사람: 글로리아 펑, 건물 관리자 / 받는 사람: 케슬러 오피스 파크 전 입주사 / 날짜: 1월 20일 / 제목: 주차 허가증\n\n입주사 여러분께,\n\n3월 1일부터 케슬러 오피스 파크는 전자 주차 허가증을 사용합니다. 직원들은 종이 허가증을 백미러에 거는 대신 차량 번호를 등록하게 되며, 입구의 카메라가 등록된 차량을 자동으로 인식합니다.\n\n각 회사는 2월 14일까지 직원 이름과 차량 번호 목록을 관리 사무소에 보내 주시기 바랍니다. 회사별 주차 면수는 지금과 같습니다. 방문객은 계속 C동 근처 구역에 주차하며, 방문하는 회사의 접수 담당자에게 주차권을 받으면 됩니다.\n\n종이 허가증은 2월 28일 이후 효력이 없습니다. 번호판이 등록되지 않은 차량은 이동을 요청받을 수 있습니다.\n\n협조해 주셔서 감사합니다.\n\n글로리아 펑","part":7},{"id":"p7-144","level":3,"kind":"single","passages":[{"doc_type":"공지","title":"Fairmont Public Library — Temporary Relocation","text":"FAIRMONT PUBLIC LIBRARY — TEMPORARY RELOCATION\n\nThe main library on Grove Street will close on April 5 for a six-month renovation that will add a children's wing and a computer lab. During the renovation, library services will be provided at the former Fairmont Post Office building, 12 Market Square.\n\nThe temporary location will offer book borrowing and returns, printing, and free Wi-Fi. Because of limited space, however, the reading room and meeting rooms will not be available. Story time for children will move to the Fairmont Community Center on Saturdays at 10 A.M.\n\nBooks borrowed before April 5 may be returned to either location. The outdoor return box on Grove Street will be removed on April 4."}],"questions":[{"q":"Why will the library on Grove Street close?","choices":["It is being sold.","It has a problem with its heating.","It is moving permanently.","It is going to be improved."],"answer":3,"type":"주제·목적","explanation":"어린이 전용 공간과 컴퓨터실을 추가하는 6개월 리모델링을 위해 문을 닫는다고 했다. 임시 이전이다."},{"q":"What service will NOT be available at 12 Market Square?","choices":["Borrowing books","Printing","Wireless Internet","Meeting rooms"],"answer":3,"type":"사실 확인(NOT/TRUE)","explanation":"공간이 부족해 열람실과 회의실은 이용할 수 없다고 했다. 도서 대출, 인쇄, 무료 와이파이는 제공된다."},{"q":"What is suggested about the outdoor return box?","choices":["It should not be used after April 4.","It will be moved to Market Square.","It accepts only children's books.","It was recently repaired."],"answer":0,"type":"추론","explanation":"그로브 스트리트의 야외 반납함은 4월 4일에 철거된다고 했으므로 그 이후에는 이용할 수 없다. 임시 장소로 옮긴다는 말은 없다."}],"translation":"[공지]\n페어몬트 공공도서관 — 임시 이전 안내\n\n그로브 스트리트의 중앙 도서관이 어린이 전용 공간과 컴퓨터실을 추가하는 6개월간의 리모델링을 위해 4월 5일에 휴관합니다. 공사 기간 동안 도서관 서비스는 마켓 스퀘어 12번지의 옛 페어몬트 우체국 건물에서 제공됩니다.\n\n임시 장소에서는 도서 대출·반납, 인쇄, 무료 와이파이를 이용할 수 있습니다. 다만 공간이 부족하여 열람실과 회의실은 이용할 수 없습니다. 어린이 이야기 시간은 토요일 오전 10시에 페어몬트 커뮤니티 센터에서 진행됩니다.\n\n4월 5일 이전에 빌린 책은 두 곳 어디에서나 반납할 수 있습니다. 그로브 스트리트의 야외 반납함은 4월 4일에 철거됩니다.","part":7},{"id":"p7-145","level":3,"kind":"single","passages":[{"doc_type":"문자 메시지","title":"Text-message chain","text":"Jason Reed [2:31 P.M.]: Hi, Molly. I'm at Corbin Hardware for the sales presentation. The manager wants printed brochures for the new garden tools, and I only brought my tablet.\nMolly Turner [2:32 P.M.]: How many does he need?\nJason Reed [2:33 P.M.]: Ten would be enough. The meeting starts at 3:30.\nMolly Turner [2:34 P.M.]: I'm afraid nobody here can drive them over that fast.\nJason Reed [2:35 P.M.]: There's a copy shop across the street. Could you e-mail the brochure file to them?\nMolly Turner [2:36 P.M.]: Sure. What's their address?\nJason Reed [2:37 P.M.]: I'll text it to you in a minute. I'll pay when I pick them up and submit the receipt later."}],"questions":[{"q":"Why is Mr. Reed at Corbin Hardware?","choices":["To buy some garden tools for the weekend","To give a sales presentation","To repair a tablet","To pick up some brochures"],"answer":1,"type":"세부 사항","explanation":"첫 메시지에서 영업 프레젠테이션 때문에 코빈 하드웨어에 와 있다고 했다."},{"q":"At 2:34 P.M., what does Ms. Turner imply when she writes, “I'm afraid nobody here can drive them over that fast”?","choices":["The brochures have not been printed yet.","Mr. Reed should postpone the meeting.","The office has run out of brochures.","No one can deliver the brochures in time."],"answer":3,"type":"의도 파악","explanation":"회의가 3시 30분에 시작하는데 그 시간 안에 브로슈어를 차로 갖다줄 사람이 없다는 뜻이다. 그래서 리드 씨가 근처 복사점을 대안으로 제시한다."},{"q":"What will Ms. Turner most likely do?","choices":["Print ten brochures at the office","Send a file to a copy shop","Call the manager of Corbin Hardware","Drive to Corbin Hardware"],"answer":1,"type":"추론","explanation":"리드 씨가 길 건너 복사점에 브로슈어 파일을 이메일로 보내 달라고 하자 터너 씨가 그러겠다며 주소를 물었다."}],"translation":"[문자 메시지]\n제이슨 리드 [오후 2:31]: 안녕하세요, 몰리. 영업 프레젠테이션 때문에 코빈 하드웨어에 와 있어요. 매니저가 신제품 원예 도구 브로슈어를 인쇄본으로 원하는데, 저는 태블릿만 가져왔어요.\n몰리 터너 [오후 2:32]: 몇 부나 필요하대요?\n제이슨 리드 [오후 2:33]: 열 부면 충분해요. 회의는 3시 30분에 시작해요.\n몰리 터너 [오후 2:34]: 아쉽지만 여기서 그렇게 빨리 차로 갖다줄 수 있는 사람이 없어요.\n제이슨 리드 [오후 2:35]: 길 건너에 복사점이 있어요. 거기로 브로슈어 파일을 이메일로 보내 줄 수 있어요?\n몰리 터너 [오후 2:36]: 물론이죠. 주소가 어떻게 돼요?\n제이슨 리드 [오후 2:37]: 곧 문자로 보낼게요. 찾을 때 제가 결제하고 영수증은 나중에 제출할게요.","part":7},{"id":"p7-146","level":3,"kind":"single","passages":[{"doc_type":"웹페이지","title":"www.korvaceramics.com/about","text":"ABOUT KORVA CERAMICS\n\nKorva Ceramics began in 1998 in a small garage in Port Elden, where founder Ingrid Korva made plates and bowls for local restaurants. [1] Her simple designs and strong, chip-resistant glazes quickly became popular with chefs.\n\nToday, Korva employs 85 people at its factory on Harbor Road and supplies more than 600 restaurants and hotels in five countries. [2] Every piece is still shaped and glazed by hand.\n\nIn 2019, the company opened a retail shop next to the factory so that home cooks could buy the same dishes used by professionals. [3] The shop also sells pieces with small flaws at reduced prices.\n\nKorva Ceramics is committed to reducing waste. [4] Broken pieces are ground up and mixed into new clay, and the factory's kilns are now powered partly by solar energy."}],"questions":[{"q":"Who were Korva Ceramics' first customers?","choices":["Home cooks","Hotels in other countries","Local restaurants","Retail shops"],"answer":2,"type":"세부 사항","explanation":"창업자가 처음에 지역 식당을 위해 접시와 그릇을 만들었다고 했다."},{"q":"What is indicated about Korva Ceramics' products?","choices":["They are made by machine.","They are sold only to professionals.","They are still made by hand.","They are no longer glazed."],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"모든 제품은 여전히 손으로 성형하고 유약을 바른다고 했다. 2019년부터 일반 가정 요리사에게도 판매한다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“Visitors to the shop can also take a short tour of the production floor.”","choices":["[1]","[2]","[3]","[4]"],"answer":2,"type":"문장 삽입","explanation":"'the shop'이 처음 등장하는 공장 옆 매장 개설 문장 뒤인 [3]에 와야 한다. 매장이 공장 옆에 있으므로 생산 현장 견학도 자연스럽다."}],"translation":"[웹페이지]\n코르바 세라믹스 소개\n\n코르바 세라믹스는 1998년 포트 엘던의 작은 차고에서 시작했습니다. 창업자 잉그리드 코르바는 그곳에서 지역 식당을 위한 접시와 그릇을 만들었습니다. 단순한 디자인과 이가 잘 빠지지 않는 튼튼한 유약은 곧 요리사들 사이에서 인기를 얻었습니다.\n\n현재 코르바는 하버 로드의 공장에서 85명을 고용하고 있으며, 5개국 600곳이 넘는 식당과 호텔에 제품을 공급합니다. 모든 제품은 여전히 손으로 성형하고 유약을 바릅니다.\n\n2019년에는 가정에서 요리하는 사람들도 전문가가 쓰는 그릇을 살 수 있도록 공장 옆에 소매점을 열었습니다. (매장 방문객은 생산 현장을 짧게 견학할 수도 있습니다.) 매장에서는 작은 흠이 있는 제품을 할인된 가격에 판매하기도 합니다.\n\n코르바 세라믹스는 폐기물을 줄이기 위해 노력합니다. 깨진 제품은 갈아서 새 점토에 섞고, 공장 가마는 현재 일부 태양 에너지로 가동됩니다.","part":7},{"id":"p7-147","level":3,"kind":"double","passages":[{"doc_type":"웹페이지","title":"www.pacificfoodsafety.org/conference/registration","text":"PACIFIC FOOD SAFETY CONFERENCE — SEATTLE, NOVEMBER 4–6\n\nRegistration Fees\n\n                    Early (by Sept. 30) | Regular (Oct. 1–Oct. 25) | On-site\nFull conference     $420 | $495 | $560\nOne day             $180 | $210 | $240\nStudent (full)      $150 | $150 | $180\n\n• Members of the Pacific Food Safety Association receive $50 off any full-conference registration.\n• Groups of five or more from the same organization receive 10% off. This discount cannot be combined with the member discount.\n• Cancellations made before October 15 receive a full refund minus a $40 processing fee."},{"doc_type":"이메일","title":"From: Teresa Molina, Quality Manager, Verde Valley Produce / To: registration@pacificfoodsafety.org / Date: October 8 / Subject: Registration question","text":"Hello,\n\nI would like to register for the full conference. I am a member of your association (member number PF-2817). Four of my colleagues would also like to attend the full conference, but they are not members.\n\nWould it be better for us to register as a group, or should I register separately with my member discount? Please let me know which option would cost our company less in total.\n\nAlso, one colleague may have to cancel because of a product launch. If he cancels on October 20, will we get any money back?\n\nBest regards,\nTeresa Molina"}],"questions":[{"q":"What is indicated about the conference?","choices":["It is held every two years.","It lasts three days.","It is free for association members.","It is open only to students."],"answer":1,"type":"사실 확인(NOT/TRUE)","explanation":"11월 4~6일에 열리므로 사흘간 진행된다. 회원은 50달러 할인일 뿐 무료가 아니다."},{"q":"What fee level applies to Ms. Molina's registration?","choices":["Early","Regular","On-site","Student"],"answer":1,"type":"연계 문제","explanation":"몰리나 씨는 10월 8일에 이메일을 보냈고, 정규 등록 기간은 10월 1일~25일이다. 조기 등록 마감(9월 30일)은 지났다."},{"q":"Why did Ms. Molina write the e-mail?","choices":["To request a student rate for her team","To become an association member","To cancel a registration","To ask which discount is cheaper"],"answer":3,"type":"주제·목적","explanation":"단체로 등록하는 것과 자신만 회원 할인을 받는 것 중 회사 전체로 어느 쪽이 더 싼지 알려 달라고 했다."},{"q":"If the five people register as a group, how much will they pay in total?","choices":["$2,227.50","$2,425.00","$2,475.00","$1,890.00"],"answer":0,"type":"연계 문제","explanation":"정규 기간 전체 등록비는 495달러이므로 5명은 2,475달러이고 단체 10% 할인을 받으면 2,227.50달러이다. 따로 등록하면 몰리나 씨만 50달러 할인되어 2,425달러이므로 단체 등록이 더 싸다."},{"q":"What is suggested about the colleague who may cancel?","choices":["He will receive a full refund.","He will receive a refund minus a fee.","He will not receive a refund.","He can transfer his registration to Ms. Molina."],"answer":2,"type":"연계 문제","explanation":"10월 15일 이전에 취소해야 환불받는데, 동료가 취소할 수 있는 날은 10월 20일이다. 웹페이지에는 그 이후 환불 규정이 없으므로 환불받지 못할 것으로 추론된다."}],"translation":"[웹페이지]\n태평양 식품안전 콘퍼런스 — 시애틀, 11월 4~6일\n\n등록비\n\n                    조기(9월 30일까지) | 정규(10월 1일~25일) | 현장\n전체 일정          420달러 | 495달러 | 560달러\n1일권              180달러 | 210달러 | 240달러\n학생(전체)         150달러 | 150달러 | 180달러\n\n• 태평양 식품안전협회 회원은 전체 일정 등록 시 50달러 할인됩니다.\n• 같은 기관에서 5명 이상 단체로 등록하면 10% 할인됩니다. 이 할인은 회원 할인과 중복되지 않습니다.\n• 10월 15일 이전 취소 시 처리 수수료 40달러를 뺀 전액을 환불합니다.\n\n[이메일]\n보낸 사람: 테레사 몰리나, 베르데 밸리 농산물 품질 관리자 / 받는 사람: registration@pacificfoodsafety.org / 날짜: 10월 8일 / 제목: 등록 문의\n\n안녕하세요,\n\n전체 일정으로 등록하고 싶습니다. 저는 협회 회원입니다(회원 번호 PF-2817). 동료 네 명도 전체 일정에 참석하고 싶어 하지만 회원은 아닙니다.\n\n단체로 등록하는 것이 나을까요, 아니면 제가 회원 할인을 받아 따로 등록하는 것이 나을까요? 회사 전체로 어느 쪽이 더 적게 드는지 알려 주세요.\n\n또한 동료 한 명은 제품 출시 때문에 취소해야 할 수도 있습니다. 10월 20일에 취소하면 돈을 돌려받을 수 있나요?\n\n감사합니다.\n테레사 몰리나","part":7},{"id":"p7-148","level":3,"kind":"double","passages":[{"doc_type":"공지","title":"Product Safety Notice — Hearthmate Electric Kettle","text":"PRODUCT SAFETY NOTICE\nHearthmate 1.7-Liter Electric Kettle, Model HK-170\n\nHearthmate Appliances has found that some HK-170 kettles may fail to turn off automatically after the water boils. This problem affects only kettles with serial numbers beginning with 23B, which were sold between March and June of this year.\n\nCustomers who own an affected kettle should stop using it immediately. To receive a free replacement, visit www.hearthmate.com/kettle and enter the serial number found on the bottom of the kettle. A replacement will be shipped within ten business days, along with a prepaid label for returning the old kettle.\n\nKettles with other serial numbers are not affected and may continue to be used."},{"doc_type":"이메일","title":"From: Ahmed Saleh / To: support@hearthmate.com / Date: August 2 / Subject: Kettle HK-170","text":"Hello,\n\nI bought an HK-170 kettle for our office kitchen in May. After reading your safety notice, I checked the serial number, which begins with 23B. I entered it on your Web site on July 15, but I still have not received a replacement.\n\nOur staff have been boiling water in the microwave since then, which is not very convenient. Could you tell me when the new kettle will arrive? My order number is HM-55107.\n\nThank you,\nAhmed Saleh\nOffice Coordinator, Tilden Architects"}],"questions":[{"q":"What problem does the notice describe?","choices":["Some kettles may leak water.","Some kettles were given incorrect serial numbers.","Some kettles were sold with the wrong cord.","Some kettles may not switch off by themselves."],"answer":3,"type":"주제·목적","explanation":"일부 HK-170 주전자가 물이 끓은 뒤 자동으로 꺼지지 않을 수 있다는 문제를 알리는 공지이다."},{"q":"According to the notice, where can the serial number be found?","choices":["On the box","On the receipt","On the bottom of the kettle","On the power cord"],"answer":2,"type":"세부 사항","explanation":"일련번호는 주전자 바닥에 있다고 했다."},{"q":"What is suggested about Mr. Saleh's kettle?","choices":["It is not affected by the problem.","It was bought outside the affected period.","It is one of the affected kettles.","It has already been returned."],"answer":2,"type":"연계 문제","explanation":"공지에서 23B로 시작하는 일련번호, 3~6월 판매 제품이 해당된다고 했다. 살레 씨는 5월에 샀고 번호가 23B로 시작하므로 문제 제품이다."},{"q":"Why is Mr. Saleh concerned?","choices":["His replacement is taking longer than promised.","He was charged for a replacement.","The Web site did not accept his serial number.","He lost the return label."],"answer":0,"type":"연계 문제","explanation":"공지는 영업일 10일 안에 교체품을 보낸다고 했지만, 7월 15일에 신청한 살레 씨는 8월 2일까지도 받지 못했다. 약속한 기간보다 늦어지고 있는 것이다."},{"q":"What has Mr. Saleh's office been doing since July 15?","choices":["Using a kettle borrowed from a neighbor","Buying bottled hot water","Heating water in a microwave","Using the old kettle carefully"],"answer":2,"type":"세부 사항","explanation":"그 이후 직원들이 전자레인지로 물을 끓이고 있다고 했다."}],"translation":"[공지]\n제품 안전 공지\n하스메이트 1.7리터 전기 주전자, 모델 HK-170\n\n하스메이트 가전은 일부 HK-170 주전자가 물이 끓은 뒤 자동으로 꺼지지 않을 수 있다는 사실을 발견했습니다. 이 문제는 올해 3월부터 6월 사이에 판매된, 일련번호가 23B로 시작하는 주전자에만 해당합니다.\n\n해당 주전자를 가진 고객은 즉시 사용을 중단해 주십시오. 무료 교체품을 받으시려면 www.hearthmate.com/kettle에 접속해 주전자 바닥에 있는 일련번호를 입력하십시오. 교체품은 영업일 기준 10일 안에 기존 주전자 반송용 선불 라벨과 함께 발송됩니다.\n\n다른 일련번호의 주전자는 해당되지 않으므로 계속 사용하셔도 됩니다.\n\n[이메일]\n보낸 사람: 아메드 살레 / 받는 사람: support@hearthmate.com / 날짜: 8월 2일 / 제목: HK-170 주전자\n\n안녕하세요,\n\n5월에 사무실 주방용으로 HK-170 주전자를 샀습니다. 안전 공지를 읽고 일련번호를 확인해 보니 23B로 시작했습니다. 7월 15일에 웹사이트에 번호를 입력했는데 아직 교체품을 받지 못했습니다.\n\n그 이후로 직원들이 전자레인지로 물을 끓이고 있어 불편합니다. 새 주전자가 언제 도착하는지 알려 주시겠습니까? 주문 번호는 HM-55107입니다.\n\n감사합니다.\n아메드 살레\n틸던 건축사무소 사무 담당","part":7},{"id":"p7-149","level":3,"kind":"triple","passages":[{"doc_type":"구인 광고","title":"Now Hiring — Customer Success Specialist, Lumen Payroll","text":"LUMEN PAYROLL — CUSTOMER SUCCESS SPECIALIST (Full-Time, Denver Office)\n\nLumen Payroll provides payroll software to more than 3,000 small businesses. We are looking for a specialist to help new clients set up and use our software.\n\nRequirements:\n• At least two years of experience in customer service or accounting\n• Excellent communication skills\n• Ability to travel to client sites about twice a month\n\nPreferred: Ability to speak Spanish\n\nTo apply, send a résumé and a short cover letter to careers@lumenpayroll.com by May 20. Interviews will be held the week of May 26."},{"doc_type":"이메일","title":"From: Carmen Ortiz / To: careers@lumenpayroll.com / Date: May 14 / Subject: Customer Success Specialist","text":"Dear Hiring Manager,\n\nI am writing to apply for the Customer Success Specialist position. For the past three years, I have worked at the help desk of Tallis Accounting Software, where I answer questions from business owners by phone and online chat. I grew up in Mexico City and am fluent in both English and Spanish.\n\nI should mention that I will be attending a training course in Chicago from May 26 to May 28. I hope that it will still be possible to arrange an interview that week.\n\nMy résumé is attached.\n\nSincerely,\nCarmen Ortiz"},{"doc_type":"일정표","title":"Lumen Payroll — Interview Schedule, Customer Success Specialist","text":"INTERVIEW SCHEDULE — CUSTOMER SUCCESS SPECIALIST\nInterviewers: Brian Sato (Client Services Director), Leah Kim (HR)\n\nMonday, May 26 — 10:00 A.M. — Paul Gentry — Room 4A\nMonday, May 26 — 2:00 P.M. — Dana Wells — Room 4A\nTuesday, May 27 — 11:00 A.M. — Rob Hughes — Room 4A\nThursday, May 29 — 9:30 A.M. — Carmen Ortiz — Video call\nFriday, May 30 — 1:00 P.M. — Simone Lyle — Room 2C\n\n*Ms. Lyle's interview will be conducted with the help of a Spanish-speaking client manager, Rafael Cruz."}],"questions":[{"q":"What is indicated about the position?","choices":["It is a part-time job.","It requires some travel.","It is located in Chicago.","It requires a degree in accounting."],"answer":1,"type":"사실 확인(NOT/TRUE)","explanation":"한 달에 두 번 정도 고객사를 방문할 수 있어야 한다고 했다. 정규직이며 근무지는 덴버이다."},{"q":"Why is Ms. Ortiz most likely a strong candidate?","choices":["She has worked at Lumen Payroll before as a team supervisor and trainer","She has managed a team of specialists.","She lives near the Denver office.","She has a preferred skill as well as the required experience."],"answer":3,"type":"연계 문제","explanation":"광고는 2년 이상 고객 서비스 경력을 요구하고 스페인어 가능자를 우대한다. 오르티스 씨는 3년간 헬프데스크에서 일했고 스페인어에 능통하다."},{"q":"What problem does Ms. Ortiz mention?","choices":["She cannot travel twice a month.","She does not have a cover letter.","She missed the application deadline.","She will be away during part of the interview week."],"answer":3,"type":"세부 사항","explanation":"5월 26~28일에 시카고에서 교육 과정에 참석한다고 했다. 면접 주간(5월 26일 주)의 일부이다."},{"q":"What is suggested about Ms. Ortiz's interview?","choices":["It was arranged after her training course.","It will be conducted by Mr. Cruz in the Denver office","It will take place in Room 4A.","It was canceled."],"answer":0,"type":"연계 문제","explanation":"오르티스 씨의 교육은 5월 28일에 끝나고, 면접은 5월 29일 화상 통화로 잡혔다. 교육이 끝난 다음 날로 일정이 조정된 것이다."},{"q":"Why most likely will Mr. Cruz join Ms. Lyle's interview?","choices":["To test her Spanish ability","To give her a tour of the office","To explain the company's payroll software","To replace Mr. Sato"],"answer":0,"type":"추론","explanation":"스페인어를 하는 고객 담당자가 면접에 함께한다고 했고, 스페인어가 우대 조건이므로 지원자의 스페인어 실력을 확인하기 위한 것으로 볼 수 있다."}],"translation":"[구인 광고]\n루멘 페이롤 — 고객 성공 전문가 (정규직, 덴버 사무소)\n\n루멘 페이롤은 3,000곳이 넘는 소기업에 급여 관리 소프트웨어를 제공합니다. 신규 고객이 소프트웨어를 설정하고 사용하도록 돕는 전문가를 찾습니다.\n\n자격 요건:\n• 고객 서비스 또는 회계 분야 2년 이상 경력\n• 뛰어난 의사소통 능력\n• 월 2회 정도 고객사 출장 가능\n\n우대: 스페인어 가능자\n\n지원하려면 5월 20일까지 이력서와 짧은 자기소개서를 careers@lumenpayroll.com으로 보내 주십시오. 면접은 5월 26일 주간에 진행됩니다.\n\n[이메일]\n보낸 사람: 카르멘 오르티스 / 받는 사람: careers@lumenpayroll.com / 날짜: 5월 14일 / 제목: 고객 성공 전문가\n\n채용 담당자님께,\n\n고객 성공 전문가 직책에 지원합니다. 저는 지난 3년간 탤리스 회계 소프트웨어의 헬프데스크에서 일하며 전화와 온라인 채팅으로 사업주들의 질문에 답해 왔습니다. 멕시코시티에서 자라 영어와 스페인어 모두 유창합니다.\n\n말씀드릴 것은 제가 5월 26일부터 28일까지 시카고에서 교육 과정에 참석한다는 점입니다. 그 주에 면접을 잡는 것이 여전히 가능하기를 바랍니다.\n\n이력서를 첨부합니다.\n\n카르멘 오르티스 드림\n\n[일정표]\n면접 일정 — 고객 성공 전문가\n면접관: 브라이언 사토(고객 서비스 이사), 리아 김(인사팀)\n\n5월 26일 월요일 — 오전 10:00 — 폴 젠트리 — 4A호\n5월 26일 월요일 — 오후 2:00 — 데이나 웰스 — 4A호\n5월 27일 화요일 — 오전 11:00 — 롭 휴즈 — 4A호\n5월 29일 목요일 — 오전 9:30 — 카르멘 오르티스 — 화상 통화\n5월 30일 금요일 — 오후 1:00 — 시몬 라일 — 2C호\n\n*라일 씨의 면접에는 스페인어를 하는 고객 담당자 라파엘 크루즈 씨가 함께합니다.","part":7},{"id":"p7-150","level":3,"kind":"triple","passages":[{"doc_type":"웹페이지","title":"www.greenleafteas.com/shipping","text":"GREENLEAF TEAS — SHIPPING OPTIONS\n\nStandard (5–7 business days): $6.00 — free on orders over $50\nExpress (2–3 business days): $12.00\nNext Day (order by 2 P.M.): $25.00\n\n• Orders are shipped from our warehouse in Portland, Oregon.\n• We do not ship on weekends or holidays.\n• Gift wrapping is available for $4.00 per item.\n• If any item arrives damaged, send us a photo within 7 days and we will send a replacement at no cost."},{"doc_type":"주문 확인서","title":"Greenleaf Teas — Order Confirmation #GT-30871","text":"ORDER CONFIRMATION #GT-30871\nOrder date: Thursday, December 11, 4:15 P.M.\nCustomer: Laura Bianchi, Bianchi Interiors\n\nJasmine Pearl tea (tin) × 2 — $36.00\nEarl Grey Reserve (tin) × 2 — $28.00\nGift wrapping × 4 — $16.00\nShipping (Next Day) — $25.00\nTotal: $105.00\n\nShip to: Bianchi Interiors, 210 Alder Street, Seattle, WA"},{"doc_type":"이메일","title":"From: Laura Bianchi / To: help@greenleafteas.com / Date: December 15 / Subject: Order #GT-30871","text":"Hello,\n\nI ordered four tins of tea as holiday gifts for clients. I chose next-day shipping because I wanted to hand them out at our office party on Friday, December 12. However, the package did not arrive until Monday, December 15, so I had to give the gifts later.\n\nIn addition, one of the Earl Grey tins was badly dented. I have attached a photo.\n\nI understand that delays happen, but I would like the shipping charge refunded since I paid extra for faster delivery.\n\nRegards,\nLaura Bianchi"}],"questions":[{"q":"What does the Web page indicate about Greenleaf Teas?","choices":["It ships orders on Saturdays.","It has stores in Seattle.","It offers free gift wrapping.","It replaces damaged items for free."],"answer":3,"type":"사실 확인(NOT/TRUE)","explanation":"상품이 파손되어 도착하면 7일 안에 사진을 보내면 무료로 교체품을 보낸다고 했다. 주말에는 배송하지 않고 선물 포장은 개당 4달러이다."},{"q":"Why most likely did Ms. Bianchi's package arrive on December 15?","choices":["It was sent to the wrong address and then redirected","She placed the order after the daily cutoff time.","The warehouse was closed for a holiday.","She chose the standard shipping option."],"answer":1,"type":"연계 문제","explanation":"익일 배송은 오후 2시까지 주문해야 하는데 비앙키 씨는 목요일 오후 4시 15분에 주문했다. 그래서 금요일에 발송되어 주말에는 배송하지 않으므로 월요일에 도착한 것으로 볼 수 있다."},{"q":"Who were the teas intended for?","choices":["Ms. Bianchi's family","New employees","Clients of Ms. Bianchi's company","Guests at a hotel"],"answer":2,"type":"세부 사항","explanation":"이메일에서 고객(clients)에게 줄 연말 선물로 차 네 통을 주문했다고 했다."},{"q":"What will Greenleaf Teas most likely send Ms. Bianchi?","choices":["A new tin of Earl Grey Reserve","A new tin of Jasmine Pearl tea","Four gift-wrapped tins","A discount coupon"],"answer":0,"type":"연계 문제","explanation":"얼그레이 통 하나가 심하게 찌그러졌다며 사진을 첨부했고, 웹페이지 규정상 7일 안에 사진을 보내면 무료 교체품을 보낸다. 12월 15일에 도착해 같은 날 보냈으므로 기한 안이다."},{"q":"In the e-mail, the word “hand” in paragraph 1 is closest in meaning to","choices":["give","help","touch","write"],"answer":0,"type":"동의어","explanation":"'hand them out'은 선물을 '나눠 주다'라는 뜻이므로 give가 가장 가깝다."}],"translation":"[웹페이지]\n그린리프 티 — 배송 옵션\n\n일반 배송(영업일 5~7일): 6달러 — 50달러 초과 주문 시 무료\n빠른 배송(영업일 2~3일): 12달러\n익일 배송(오후 2시까지 주문): 25달러\n\n• 주문 상품은 오리건주 포틀랜드 창고에서 발송됩니다.\n• 주말과 공휴일에는 발송하지 않습니다.\n• 선물 포장은 개당 4달러에 가능합니다.\n• 파손된 상품이 도착하면 7일 안에 사진을 보내 주십시오. 무료로 교체품을 보내 드립니다.\n\n[주문 확인서]\n주문 확인서 #GT-30871\n주문일: 12월 11일 목요일 오후 4시 15분\n고객: 로라 비앙키, 비앙키 인테리어\n\n재스민 펄 티(통) × 2 — 36달러\n얼그레이 리저브(통) × 2 — 28달러\n선물 포장 × 4 — 16달러\n배송(익일) — 25달러\n합계: 105달러\n\n배송지: 워싱턴주 시애틀 앨더 스트리트 210번지, 비앙키 인테리어\n\n[이메일]\n보낸 사람: 로라 비앙키 / 받는 사람: help@greenleafteas.com / 날짜: 12월 15일 / 제목: 주문 #GT-30871\n\n안녕하세요,\n\n고객들에게 줄 연말 선물로 차 네 통을 주문했습니다. 12월 12일 금요일 사무실 파티에서 나눠 주고 싶어서 익일 배송을 선택했습니다. 그런데 소포가 12월 15일 월요일에야 도착해서 선물을 나중에 줄 수밖에 없었습니다.\n\n게다가 얼그레이 통 하나가 심하게 찌그러져 있었습니다. 사진을 첨부합니다.\n\n배송이 늦어질 수 있다는 것은 이해하지만, 빠른 배송을 위해 추가 요금을 냈으니 배송비를 환불해 주셨으면 합니다.\n\n로라 비앙키","part":7},{"id":"p7-151","level":4,"kind":"single","passages":[{"doc_type":"기사","title":"Restaurant Week Returns with a Twist / By Marisol Duarte","text":"CALDERA BAY (February 18) — Caldera Bay Restaurant Week, which offers fixed-price menus at participating restaurants, will return from March 9 to 15. This year, however, organizers are making a significant change. [1]\n\nIn previous years, every restaurant offered a three-course dinner for $35. Some owners complained that the single price made it difficult for higher-end restaurants to take part without losing money, while smaller cafés felt pressured to offer more than they normally would. [2] This year, restaurants may choose one of three price levels: $25, $40, or $55.\n\n“We wanted the event to reflect the full range of dining in the city,” said Abdul Rahim, director of the Caldera Bay Hospitality Association. [3] As a result, 74 restaurants have signed up, up from 52 last year.\n\nFor the first time, lunch menus will also be offered, at $18 or $25. [4] A full list of participating restaurants and their menus is available at www.calderabayeats.com."}],"questions":[{"q":"What is the article mainly about?","choices":["The opening of a new restaurant","Changes to a citywide dining event","A dispute between two restaurant owners","A rise in food prices in Caldera Bay"],"answer":1,"type":"주제·목적","explanation":"칼데라 베이 레스토랑 위크가 올해 가격 체계를 바꾸고 점심 메뉴를 추가하는 등 변화를 준다는 기사이다."},{"q":"According to the article, what was a problem with the previous format?","choices":["Customers found the menus too limited for their taste","Restaurants had to stay open later.","One price did not suit all types of restaurants.","The event was held during a busy season."],"answer":2,"type":"세부 사항","explanation":"단일 가격 때문에 고급 식당은 손해 없이 참여하기 어렵고 작은 카페는 평소보다 더 많이 제공해야 하는 부담이 있었다고 했다."},{"q":"What is suggested about the change?","choices":["It has attracted more participants.","It was proposed by customers.","It will be used only this year.","It applies only to lunch menus."],"answer":0,"type":"추론","explanation":"그 결과(As a result) 참여 식당이 작년 52곳에서 74곳으로 늘었다고 했으므로 변화가 더 많은 참여를 끌어냈다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“These will be available on weekdays only, between 11:30 A.M. and 2:30 P.M.”","choices":["[1]","[2]","[3]","[4]"],"answer":3,"type":"문장 삽입","explanation":"'These'는 처음 제공되는 점심 메뉴를 가리키며, 제공 시간(11시 30분~2시 30분)도 점심에 맞는다. 따라서 점심 메뉴 문장 뒤인 [4]가 알맞다."}],"translation":"[기사]\n레스토랑 위크, 새로운 모습으로 돌아온다 / 마리솔 두아르테 기자\n\n칼데라 베이 (2월 18일) — 참여 식당에서 정해진 가격의 메뉴를 제공하는 칼데라 베이 레스토랑 위크가 3월 9일부터 15일까지 다시 열린다. 그러나 올해 주최 측은 중요한 변화를 준다.\n\n예년에는 모든 식당이 3코스 저녁을 35달러에 제공했다. 일부 업주들은 단일 가격 때문에 고급 식당은 손해를 보지 않고 참여하기 어렵고, 작은 카페는 평소보다 더 많이 내놓아야 한다는 부담을 느낀다고 불만을 제기했다. 올해는 식당이 25달러, 40달러, 55달러 세 가지 가격대 중 하나를 고를 수 있다.\n\n칼데라 베이 외식업협회의 압둘 라힘 회장은 \"행사가 이 도시의 다양한 외식 문화를 모두 보여 주기를 원했다\"고 말했다. 그 결과 참여 식당은 작년 52곳에서 74곳으로 늘었다.\n\n처음으로 점심 메뉴도 18달러 또는 25달러에 제공된다. (점심 메뉴는 평일 오전 11시 30분부터 오후 2시 30분까지만 제공된다.) 참여 식당과 메뉴의 전체 목록은 www.calderabayeats.com에서 볼 수 있다.","part":7},{"id":"p7-152","level":4,"kind":"single","passages":[{"doc_type":"온라인 채팅","title":"Online chat discussion — Felix Brandt, Yara Haddad, Owen Pike","text":"Felix Brandt [4:02 P.M.]: Quick update on the e-mail migration. The test group moved to the new system this morning, and so far there have been no major issues.\nYara Haddad [4:04 P.M.]: Good to hear. When does the rest of the company switch over?\nFelix Brandt [4:05 P.M.]: The plan is Saturday night, when traffic is lowest. Everyone should be able to log in by Monday at 7 A.M.\nOwen Pike [4:07 P.M.]: The accounting team closes the quarter on Monday. If anything goes wrong, that could be a real problem.\nFelix Brandt [4:08 P.M.]: Understood. We could move accounting a week later.\nOwen Pike [4:09 P.M.]: That would be a relief.\nYara Haddad [4:11 P.M.]: Will the old and new systems be able to exchange messages during that week?\nFelix Brandt [4:12 P.M.]: Yes, mail will be forwarded automatically between them. Shared calendars won't sync, though.\nYara Haddad [4:13 P.M.]: Then I'll let the accounting managers know so they can schedule meetings by e-mail that week."}],"questions":[{"q":"What are the writers mainly discussing?","choices":["The schedule for moving to a new e-mail system","The results of the quarterly financial report review","A complaint about slow Internet service","Training for new accounting staff"],"answer":0,"type":"주제·목적","explanation":"이메일 시스템 이전 진행 상황과 나머지 직원의 전환 일정, 회계팀 예외 처리를 논의하고 있다."},{"q":"Why is Mr. Pike concerned?","choices":["The test group reported several errors.","His team cannot attend a training session.","An important accounting task is scheduled for Monday.","The new system will cost more than expected."],"answer":2,"type":"세부 사항","explanation":"회계팀이 월요일에 분기 마감을 하는데 문제가 생기면 큰일이라고 했다."},{"q":"At 4:09 P.M., what does Mr. Pike mean when he writes, “That would be a relief”?","choices":["He approves of delaying his team's migration.","He wants the test group to be expanded to more staff","He is glad the project is finished.","He would like to take a week off."],"answer":0,"type":"의도 파악","explanation":"브란트 씨가 회계팀 전환을 일주일 뒤로 미룰 수 있다고 하자 '그러면 한시름 놓겠다'고 했으므로 그 제안에 찬성하는 것이다."},{"q":"What will Ms. Haddad most likely tell the accounting managers?","choices":["To log in early on Monday","To close the quarter a week later","To forward their e-mail manually","To avoid using shared calendars for scheduling for a week"],"answer":3,"type":"추론","explanation":"그 주에는 메일은 자동 전달되지만 공유 달력은 동기화되지 않는다고 하자, 하다드 씨는 회계 관리자들에게 그 주에는 이메일로 회의 일정을 잡도록 알리겠다고 했다."}],"translation":"[온라인 채팅]\n펠릭스 브란트 [오후 4:02]: 이메일 이전 진행 상황 짧게 알려 드려요. 테스트 그룹이 오늘 아침 새 시스템으로 옮겼고, 지금까지 큰 문제는 없어요.\n야라 하다드 [오후 4:04]: 다행이네요. 나머지 직원들은 언제 전환하나요?\n펠릭스 브란트 [오후 4:05]: 사용량이 가장 적은 토요일 밤에 할 계획이에요. 월요일 오전 7시까지는 모두 로그인할 수 있을 거예요.\n오언 파이크 [오후 4:07]: 회계팀은 월요일에 분기 마감을 해요. 뭔가 잘못되면 정말 문제가 될 수 있어요.\n펠릭스 브란트 [오후 4:08]: 알겠어요. 회계팀은 일주일 뒤에 옮길 수도 있어요.\n오언 파이크 [오후 4:09]: 그러면 한시름 놓겠네요.\n야라 하다드 [오후 4:11]: 그 주 동안 예전 시스템과 새 시스템 사이에 메일을 주고받을 수 있나요?\n펠릭스 브란트 [오후 4:12]: 네, 메일은 둘 사이에 자동으로 전달돼요. 하지만 공유 달력은 동기화되지 않아요.\n야라 하다드 [오후 4:13]: 그럼 그 주에는 회의 일정을 이메일로 잡도록 회계 관리자들에게 알려 둘게요.","part":7},{"id":"p7-153","level":4,"kind":"single","passages":[{"doc_type":"회람","title":"To: All Employees / From: Naomi Achterberg, Human Resources / Date: July 1 / Subject: Home-office equipment allowance","text":"As announced last month, employees who work from home at least two days a week are now eligible for a one-time home-office equipment allowance of up to $400. The allowance may be used for items such as desks, chairs, monitors, and keyboards. It may not be used for computers or phones, which continue to be provided by the IT department.\n\nTo receive the allowance, purchase the items yourself and submit the receipts through the expense system by September 30. Your manager must confirm your remote-work schedule before the request can be approved. Reimbursements will appear in the paycheck following approval.\n\nPlease note that items bought with the allowance become your personal property. However, employees who leave the company within one year of receiving the allowance will be asked to repay half of the amount."}],"questions":[{"q":"Who is eligible for the allowance?","choices":["All new employees","Employees who work from home every single day of the week","Managers in the IT department","Employees who work remotely two or more days a week"],"answer":3,"type":"세부 사항","explanation":"일주일에 최소 이틀 재택근무하는 직원이 대상이라고 했다."},{"q":"What can NOT be purchased with the allowance?","choices":["A chair","A monitor","A laptop computer","A keyboard"],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"컴퓨터와 전화기는 IT 부서가 계속 제공하므로 이 지원금으로 살 수 없다."},{"q":"What is required before a request can be approved?","choices":["A manager's confirmation","A quote from a supplier","A visit from the IT department","Proof of a home address"],"answer":0,"type":"세부 사항","explanation":"요청이 승인되기 전에 관리자가 재택근무 일정을 확인해야 한다고 했다."},{"q":"What is suggested about an employee who resigns six months after receiving the allowance?","choices":["They must return the purchased items.","They will have to pay back part of the money.","They will receive the remaining balance.","They can transfer the items to a coworker."],"answer":1,"type":"추론","explanation":"지원금을 받은 후 1년 이내에 퇴사하면 금액의 절반을 갚아야 한다. 구매 물품은 개인 소유이므로 반납할 필요는 없다."}],"translation":"[회람]\n받는 사람: 전 직원 / 보낸 사람: 나오미 악터버그, 인사부 / 날짜: 7월 1일 / 제목: 재택근무 장비 지원금\n\n지난달 발표한 대로, 일주일에 최소 이틀 재택근무를 하는 직원은 이제 최대 400달러의 1회성 재택 사무 장비 지원금을 받을 수 있습니다. 지원금은 책상, 의자, 모니터, 키보드 등의 물품에 쓸 수 있습니다. 컴퓨터와 전화기는 계속 IT 부서에서 제공하므로 지원금으로 살 수 없습니다.\n\n지원금을 받으려면 직접 물품을 구입한 뒤 9월 30일까지 경비 시스템으로 영수증을 제출하십시오. 요청이 승인되려면 먼저 관리자가 재택근무 일정을 확인해야 합니다. 환급액은 승인 후 다음 급여에 포함됩니다.\n\n지원금으로 산 물품은 개인 소유가 된다는 점을 알려 드립니다. 다만 지원금을 받은 지 1년 이내에 퇴사하는 직원은 금액의 절반을 반환해야 합니다.","part":7},{"id":"p7-154","level":4,"kind":"single","passages":[{"doc_type":"편지","title":"Bellmore Business Review / 400 Fulton Avenue, Bellmore","text":"March 3\n\nMs. Rachel Ingram\nIngram & Lowe Consulting\n27 Cedar Court, Bellmore\n\nDear Ms. Ingram,\n\nThank you for subscribing to the Bellmore Business Review for the past six years. [1] We are writing to inform you of changes to our subscription rates that will take effect on May 1.\n\nThe annual price of the print edition will rise from $89 to $99. [2] This is our first price increase in four years, and it reflects higher costs for paper and delivery. The digital-only subscription will remain $59.\n\nAs a long-time subscriber, you can renew now at the current rate for up to two years. [3] To do so, simply complete the enclosed form and return it by April 15, or call our subscriber office at 555-0190.\n\nIn addition, all print subscribers now receive full access to our online archive at no extra charge. [4] We believe this makes the print edition an even better value.\n\nSincerely,\nMartin Okafor\nSubscriber Services"}],"questions":[{"q":"What is the main purpose of the letter?","choices":["To thank Ms. Ingram for writing an article","To introduce a new magazine","To request payment of an overdue bill","To announce a price change"],"answer":3,"type":"주제·목적","explanation":"5월 1일부터 구독료가 바뀐다는 사실을 알리는 편지이다."},{"q":"What is indicated about the digital-only subscription?","choices":["Its price will not change.","It will be discontinued.","It includes the print edition.","It costs $99 per year."],"answer":0,"type":"사실 확인(NOT/TRUE)","explanation":"디지털 전용 구독은 59달러로 유지된다(will remain)고 했다."},{"q":"What is Ms. Ingram invited to do?","choices":["Switch to a digital subscription at a reduced price","Write a review of the online archive","Attend an event for long-time subscribers","Renew at the current price before the change"],"answer":3,"type":"세부 사항","explanation":"장기 구독자로서 지금 현재 요금으로 최대 2년까지 갱신할 수 있으니 4월 15일까지 양식을 보내거나 전화하라고 했다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“Previously, this service was available only to digital subscribers.”","choices":["[1]","[2]","[3]","[4]"],"answer":3,"type":"문장 삽입","explanation":"'this service'는 이제 인쇄본 구독자도 추가 요금 없이 이용할 수 있게 된 온라인 자료실을 가리킨다. 따라서 그 문장 바로 뒤인 [4]가 알맞다."}],"translation":"[편지]\n벨모어 비즈니스 리뷰 / 벨모어 풀턴 애비뉴 400번지\n\n3월 3일\n\n레이철 잉그럼 님\n잉그럼 앤 로 컨설팅\n벨모어 시더 코트 27번지\n\n잉그럼 님께,\n\n지난 6년 동안 벨모어 비즈니스 리뷰를 구독해 주셔서 감사합니다. 5월 1일부터 적용되는 구독료 변경 사항을 알려 드리고자 편지를 드립니다.\n\n인쇄본의 연간 구독료가 89달러에서 99달러로 오릅니다. 4년 만의 첫 인상이며, 종이와 배송 비용 상승을 반영한 것입니다. 디지털 전용 구독은 59달러로 유지됩니다.\n\n장기 구독자이신 고객님께서는 지금 현재 요금으로 최대 2년까지 갱신하실 수 있습니다. 동봉한 양식을 작성해 4월 15일까지 보내 주시거나 구독자 사무실(555-0190)로 전화해 주십시오.\n\n또한 이제 모든 인쇄본 구독자는 추가 요금 없이 온라인 자료실 전체를 이용할 수 있습니다. (이전에는 디지털 구독자만 이 서비스를 이용할 수 있었습니다.) 이로써 인쇄본이 더욱 좋은 가치를 제공하게 되리라 믿습니다.\n\n마틴 오카포\n구독자 서비스팀","part":7},{"id":"p7-155","level":4,"kind":"single","passages":[{"doc_type":"문자 메시지","title":"Text-message chain","text":"Gina Russo [6:40 A.M.]: I'm at the Elmhurst Hotel ballroom. The stage is set up, but the screen for the slides is much smaller than what we requested.\nTheo Lambert [6:42 A.M.]: Seriously? We confirmed the 5-meter screen twice.\nGina Russo [6:43 A.M.]: The hotel says the large one is being used in another ballroom today. Guests start arriving at 8:30.\nTheo Lambert [6:45 A.M.]: Can people at the back read the slides on the small one?\nGina Russo [6:46 A.M.]: Not the charts. The text might be OK.\nTheo Lambert [6:48 A.M.]: Ask whether they have two more screens of that size. We could put them along the side walls.\nGina Russo [6:55 A.M.]: They have two. A technician can connect them by 8.\nTheo Lambert [6:56 A.M.]: Let's do it. And make sure the bill reflects that we didn't get what we ordered."}],"questions":[{"q":"Where most likely is Ms. Russo?","choices":["At a printing company","At an event venue","At an electronics store","At an airport"],"answer":1,"type":"추론","explanation":"엘름허스트 호텔 연회장에 있다고 했고, 무대와 스크린, 손님 도착 시간 이야기를 하므로 행사장에 있다."},{"q":"At 6:42 A.M., why does Mr. Lambert write, “We confirmed the 5-meter screen twice”?","choices":["To express surprise that the request was not met","To ask Ms. Russo to measure the screen","To suggest canceling the event","To correct an error in an order"],"answer":0,"type":"의도 파악","explanation":"요청한 것보다 훨씬 작은 스크린이 설치되었다는 말에 5미터 스크린을 두 번이나 확인했다고 한 것은 요청이 지켜지지 않은 데 대한 놀라움과 불만을 표현한 것이다."},{"q":"What problem does Ms. Russo mention about the small screen?","choices":["It cannot be connected in time.","It does not display any text.","It is being used in another ballroom at the same time","Charts on it would be hard to see from the back."],"answer":3,"type":"세부 사항","explanation":"뒷자리에서 슬라이드를 읽을 수 있냐는 질문에 차트는 안 되고 글자는 괜찮을 것 같다고 했다."},{"q":"What does Mr. Lambert want Ms. Russo to do about the bill?","choices":["Pay it before the event","Request that it be adjusted","Send it to the technician","Divide it between two departments"],"answer":1,"type":"추론","explanation":"주문한 것을 받지 못했다는 점이 청구서에 반영되도록 하라고 했으므로 요금 조정을 요청하라는 뜻이다."}],"translation":"[문자 메시지]\n지나 루소 [오전 6:40]: 엘름허스트 호텔 연회장에 와 있어요. 무대는 설치됐는데 슬라이드용 스크린이 우리가 요청한 것보다 훨씬 작아요.\n테오 램버트 [오전 6:42]: 정말요? 5미터 스크린을 두 번이나 확인했잖아요.\n지나 루소 [오전 6:43]: 호텔 말로는 큰 스크린을 오늘 다른 연회장에서 쓰고 있대요. 손님들은 8시 30분부터 도착해요.\n테오 램버트 [오전 6:45]: 작은 스크린으로도 뒷자리 사람들이 슬라이드를 읽을 수 있어요?\n지나 루소 [오전 6:46]: 차트는 안 돼요. 글자는 괜찮을 수도 있고요.\n테오 램버트 [오전 6:48]: 같은 크기 스크린이 두 개 더 있는지 물어봐요. 양쪽 벽을 따라 설치하면 되겠어요.\n지나 루소 [오전 6:55]: 두 개 있대요. 기술자가 8시까지 연결해 줄 수 있대요.\n테오 램버트 [오전 6:56]: 그렇게 해요. 그리고 우리가 주문한 걸 받지 못했다는 점이 청구서에 꼭 반영되게 해 줘요.","part":7},{"id":"p7-156","level":4,"kind":"double","passages":[{"doc_type":"보도 자료","title":"FOR IMMEDIATE RELEASE — Solano Hotels","text":"FOR IMMEDIATE RELEASE\nContact: Wendy Arce, Communications Manager, warce@solanohotels.com\n\nSolano Hotels to Open First Property in Lisbon\n\nMADRID (April 7) — Solano Hotels announced today that it will open the Solano Lisbon Riverside, its first hotel outside Spain, on September 1. The 140-room hotel occupies a restored 19th-century warehouse on the bank of the Tagus River.\n\nUnlike the company's city-center properties, the Riverside will focus on longer stays. Half of its rooms will include small kitchens, and guests staying seven nights or more will receive weekly cleaning instead of daily cleaning at a reduced rate.\n\n“Many of our guests in Madrid and Barcelona are business travelers on assignments lasting several weeks,” said CEO Tomás Vidal. “Lisbon has a growing number of such visitors, and we want to serve them.”\n\nMr. Vidal will be available for interviews at the company's Madrid headquarters from April 14 to 18. After that, he will be traveling in Asia until early May."},{"doc_type":"이메일","title":"From: Ines Moreau, Hospitality Today / To: Wendy Arce / Date: April 9 / Subject: Interview request","text":"Dear Ms. Arce,\n\nI write for Hospitality Today, a magazine for hotel industry professionals. We are preparing a feature on hotels designed for extended stays, and I would very much like to include the Solano Lisbon Riverside.\n\nI will be in Madrid for a conference from April 16 to 17. Could Mr. Vidal meet with me on one of those days? If his schedule is full, I would also be happy to speak with the hotel's general manager.\n\nAdditionally, I would appreciate any photos of the building before and after its restoration.\n\nBest regards,\nInes Moreau"}],"questions":[{"q":"What is the press release mainly about?","choices":["The sale of a warehouse in Lisbon","The opening of a new hotel","A change in the company's leadership","A conference for business travelers"],"answer":1,"type":"주제·목적","explanation":"솔라노 호텔이 스페인 밖 첫 호텔인 솔라노 리스본 리버사이드를 9월 1일에 연다는 보도 자료이다."},{"q":"What is NOT mentioned as a feature of the Solano Lisbon Riverside?","choices":["It is in a renovated building.","Some rooms have kitchens.","It offers reduced-rate weekly cleaning for long stays.","It has a conference center."],"answer":3,"type":"사실 확인(NOT/TRUE)","explanation":"복원된 19세기 창고 건물, 객실 절반의 주방, 장기 투숙객 주간 청소는 언급되지만 회의장은 없다."},{"q":"Why is Ms. Moreau interested in the hotel?","choices":["She plans to stay there in September.","She used to work for Solano Hotels.","She is organizing a conference in Lisbon.","It fits the topic of an article she is writing."],"answer":3,"type":"세부 사항","explanation":"장기 투숙용 호텔에 관한 특집 기사를 준비 중이라 리버사이드를 포함하고 싶다고 했다."},{"q":"What is suggested about Ms. Moreau's request to meet Mr. Vidal?","choices":["It falls within the period when he is available for interviews.","It conflicts with a business trip he plans to take to Asia in April","It must take place in Lisbon.","It was already rejected."],"answer":0,"type":"연계 문제","explanation":"보도 자료에 비달 사장은 4월 14~18일 마드리드 본사에서 인터뷰가 가능하다고 했고, 모로 씨는 4월 16~17일 마드리드에 있으므로 가능한 기간에 해당한다."},{"q":"What does Ms. Moreau ask Ms. Arce to provide?","choices":["A list of room rates","Tickets to a conference","A copy of a speech by Mr. Vidal","Images of the building's restoration"],"answer":3,"type":"세부 사항","explanation":"건물 복원 전후 사진을 보내 주면 고맙겠다고 했다."}],"translation":"[보도 자료]\n즉시 배포용\n문의: 웬디 아르세, 홍보 매니저, warce@solanohotels.com\n\n솔라노 호텔, 리스본에 첫 호텔 개장\n\n마드리드 (4월 7일) — 솔라노 호텔은 오늘 스페인 밖의 첫 호텔인 솔라노 리스본 리버사이드를 9월 1일에 연다고 발표했다. 객실 140개의 이 호텔은 테주강 강변의 복원된 19세기 창고 건물에 자리한다.\n\n도심에 있는 다른 지점과 달리 리버사이드는 장기 투숙에 초점을 맞춘다. 객실의 절반에는 소형 주방이 있으며, 7박 이상 투숙객은 매일 청소 대신 할인된 요금으로 주 1회 청소를 받는다.\n\n토마스 비달 CEO는 \"마드리드와 바르셀로나의 손님 중 상당수가 몇 주씩 파견 근무를 하는 출장객\"이라며 \"리스본에도 그런 방문객이 늘고 있어 이들을 맞이하고 싶다\"고 말했다.\n\n비달 CEO는 4월 14일부터 18일까지 마드리드 본사에서 인터뷰가 가능하다. 그 이후에는 5월 초까지 아시아 출장 중이다.\n\n[이메일]\n보낸 사람: 이네스 모로, 호스피탈리티 투데이 / 받는 사람: 웬디 아르세 / 날짜: 4월 9일 / 제목: 인터뷰 요청\n\n아르세 님께,\n\n저는 호텔업계 종사자를 위한 잡지 호스피탈리티 투데이에 글을 쓰고 있습니다. 장기 투숙용 호텔에 관한 특집을 준비 중인데, 솔라노 리스본 리버사이드를 꼭 소개하고 싶습니다.\n\n저는 4월 16~17일 콘퍼런스 때문에 마드리드에 있을 예정입니다. 비달 사장님께서 그중 하루 저를 만나 주실 수 있을까요? 일정이 꽉 차 있다면 호텔 총지배인과 이야기해도 좋습니다.\n\n또한 건물 복원 전후 사진을 보내 주시면 감사하겠습니다.\n\n이네스 모로 드림","part":7},{"id":"p7-157","level":4,"kind":"double","passages":[{"doc_type":"공지","title":"Notice to Customers — Coastline Seafood Supply","text":"NOTICE TO CUSTOMERS — PRICE AND ORDERING CHANGES\n\nDue to rising fuel costs and a shorter fishing season, Coastline Seafood Supply will adjust prices on the following items, effective October 1:\n\nAtlantic salmon fillet (per kg): $21.50 → $23.80\nWild shrimp (per kg): $18.00 → $19.40\nCod fillet (per kg): $15.20 — no change\nFresh mussels (per kg): $6.90 — no change\n\nIn addition, the deadline for next-day delivery orders will move from 6 P.M. to 3 P.M. Orders received after 3 P.M. will be delivered in two days.\n\nCustomers who sign a six-month supply agreement before September 25 will keep current prices on all items until March 31."},{"doc_type":"이메일","title":"From: Hugo Lindqvist, Owner, The Driftwood Kitchen / To: orders@coastlineseafood.com / Date: September 22 / Subject: Agreement and weekend orders","text":"Hello,\n\nWe have been buying from Coastline for three years, and salmon and shrimp are the two most popular dishes on our menu. I would like to sign the six-month agreement you mentioned in your recent notice. Please send me the paperwork as soon as possible.\n\nI also have a question about the new ordering deadline. Our head chef usually finalizes Saturday's order after the Friday dinner rush begins, around 5 P.M. Would it be possible to make an exception for Friday orders, or should we plan to order on Thursday instead?\n\nThank you,\nHugo Lindqvist"}],"questions":[{"q":"According to the notice, why are some prices changing?","choices":["A supplier went out of business.","The company has opened a new warehouse.","Demand for seafood has fallen.","Fuel costs have increased."],"answer":3,"type":"세부 사항","explanation":"연료비 상승과 짧아진 조업 기간 때문에 가격을 조정한다고 했다."},{"q":"Which item's price will NOT change?","choices":["Salmon","Shrimp","Cod","None of the items"],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"대구 필레와 홍합은 '변동 없음'이고, 보기 중에는 대구(Cod)가 해당한다."},{"q":"Why does Mr. Lindqvist want to sign the agreement?","choices":["To receive faster delivery","To get a discount on mussels and other shellfish ordered every week","To try new menu items","To keep paying current prices on items whose prices are rising"],"answer":3,"type":"연계 문제","explanation":"린드크비스트 씨의 인기 메뉴는 연어와 새우인데, 공지에서 이 두 품목은 가격이 오른다. 9월 25일 전에 6개월 계약을 하면 3월 31일까지 현재 가격이 유지되므로 계약하려는 것이다."},{"q":"Will Mr. Lindqvist's agreement most likely be accepted?","choices":["Yes, because he is requesting it before the deadline","No, because he has not been a customer long enough","No, because the offer ended in September","Yes, because he orders only on Thursdays"],"answer":0,"type":"연계 문제","explanation":"계약은 9월 25일 전에 해야 하는데 이메일 날짜가 9월 22일이므로 기한 안에 요청한 것이다."},{"q":"Why is the head chef's Friday ordering habit a problem?","choices":["The restaurant is closed on Saturdays.","Orders placed at 5 P.M. will no longer arrive the next day.","Coastline does not deliver on Fridays.","The chef works only on weekends and cannot receive deliveries on weekdays"],"answer":1,"type":"연계 문제","explanation":"익일 배송 마감이 오후 3시로 앞당겨지므로 금요일 오후 5시쯤 하는 주문은 이틀 뒤에 배송되어 토요일에 받을 수 없다."}],"translation":"[공지]\n고객 안내 — 가격 및 주문 변경\n\n연료비 상승과 짧아진 조업 기간으로 인해 코스트라인 해산물 공급은 10월 1일부터 다음 품목의 가격을 조정합니다.\n\n대서양 연어 필레(kg당): 21.50달러 → 23.80달러\n자연산 새우(kg당): 18.00달러 → 19.40달러\n대구 필레(kg당): 15.20달러 — 변동 없음\n생홍합(kg당): 6.90달러 — 변동 없음\n\n또한 익일 배송 주문 마감 시각이 오후 6시에서 오후 3시로 바뀝니다. 오후 3시 이후에 받은 주문은 이틀 뒤에 배송됩니다.\n\n9월 25일 전에 6개월 공급 계약을 맺는 고객은 3월 31일까지 모든 품목을 현재 가격으로 구매할 수 있습니다.\n\n[이메일]\n보낸 사람: 휴고 린드크비스트, 드리프트우드 키친 사장 / 받는 사람: orders@coastlineseafood.com / 날짜: 9월 22일 / 제목: 계약 및 주말 주문\n\n안녕하세요,\n\n저희는 3년째 코스트라인과 거래하고 있으며, 연어와 새우 요리가 저희 메뉴에서 가장 인기 있는 두 가지입니다. 최근 공지에서 말씀하신 6개월 계약을 맺고 싶습니다. 서류를 최대한 빨리 보내 주세요.\n\n새 주문 마감 시각에 대해서도 질문이 있습니다. 저희 주방장은 보통 금요일 저녁 손님이 몰리기 시작하는 오후 5시쯤 토요일 주문을 확정합니다. 금요일 주문은 예외로 해 주실 수 있을까요, 아니면 목요일에 주문하도록 계획해야 할까요?\n\n감사합니다.\n휴고 린드크비스트","part":7},{"id":"p7-158","level":4,"kind":"double","passages":[{"doc_type":"계약서","title":"Catering Agreement — Excerpt / Saffron Table Catering and Norwick Biotech","text":"CATERING AGREEMENT — EXCERPT\nBetween Saffron Table Catering (“the Caterer”) and Norwick Biotech (“the Client”)\nEvent: Norwick Biotech Annual Partners' Dinner, Friday, November 14, Glasshouse Pavilion\n\n3. Guest Count. The Client shall confirm the final number of guests no later than ten days before the event. The Caterer will prepare food for the confirmed number. Increases of up to 10 percent may be requested up to three days before the event and will be charged at the per-person rate for the menu selected. Requests to reduce the guest count made fewer than ten days before the event will not reduce the amount owed.\n\n4. Price. The per-person rate is $85 for the standard menu and $98 for the premium menu, which adds a seafood course.\n\n5. Dietary Requests. Vegetarian and gluten-free meals are available at no additional cost if requested with the final guest count."},{"doc_type":"이메일","title":"From: Sung-min Cho, Norwick Biotech / To: Daria Volkova, Saffron Table Catering / Date: November 10 / Subject: Partners' Dinner","text":"Dear Ms. Volkova,\n\nAs confirmed on November 3, we are expecting 120 guests for the premium menu. Since then, several partners from our Singapore office have decided to attend, so I would like to add 11 guests.\n\nAlso, I have just learned that two of our original guests require gluten-free meals. I realize this information is late, and I would be grateful if you could accommodate them.\n\nFinally, one guest has canceled. I assume this will reduce our total slightly.\n\nBest regards,\nSung-min Cho\nEvent Coordinator"}],"questions":[{"q":"According to the agreement, when must the final guest count be confirmed?","choices":["At least three days before the event","One month before the event","On the day of the event","At least ten days before the event"],"answer":3,"type":"세부 사항","explanation":"계약서 3항에 행사 10일 전까지 최종 인원을 확정해야 한다고 했다."},{"q":"What is indicated about the premium menu?","choices":["It includes a seafood course.","It is available only for groups of 100 or more.","It costs $85 per person.","It does not include vegetarian options."],"answer":0,"type":"사실 확인(NOT/TRUE)","explanation":"프리미엄 메뉴는 해산물 코스가 추가되며 1인당 98달러라고 했다."},{"q":"How much will Norwick Biotech most likely be charged for each additional guest?","choices":["$85","$13","$98","$110"],"answer":2,"type":"연계 문제","explanation":"조 씨 측은 프리미엄 메뉴를 선택했고, 추가 인원은 선택한 메뉴의 1인 요금으로 청구된다. 계약서 4항에서 프리미엄 메뉴는 1인당 98달러이다. 11명은 120명의 10%(12명) 이내이고 행사 3일 전보다 일찍 요청했으므로 추가가 가능하다."},{"q":"What is true about the gluten-free meal request?","choices":["It was made at the correct time.","It was made later than the agreement specifies.","It will cost an extra $13 per meal.","It was requested by the Caterer."],"answer":1,"type":"연계 문제","explanation":"계약서 5항에 따르면 특별식은 최종 인원 확정 때 함께 요청해야 무료로 제공되는데, 조 씨는 확정(11월 3일) 이후인 11월 10일에 요청하며 늦었다고 인정했다."},{"q":"What is suggested about the canceled guest?","choices":["The cancellation will not lower the total amount owed.","Norwick Biotech will receive a refund for that guest's meal","The guest will be replaced by someone from Singapore.","The guest required a vegetarian meal."],"answer":0,"type":"연계 문제","explanation":"계약서상 행사 10일 전 이후의 인원 감소 요청은 금액을 줄이지 않는다. 11월 10일은 행사(11월 14일) 4일 전이므로 총액은 줄지 않는다. 조 씨의 짐작은 틀렸다."}],"translation":"[계약서]\n출장 요리 계약서 — 발췌\n사프런 테이블 케이터링(이하 '케이터링 업체')과 노윅 바이오테크(이하 '고객') 간\n행사: 노윅 바이오테크 연례 파트너 만찬, 11월 14일 금요일, 글라스하우스 파빌리온\n\n3. 참석 인원. 고객은 행사 10일 전까지 최종 참석 인원을 확정해야 한다. 케이터링 업체는 확정된 인원에 맞춰 음식을 준비한다. 행사 3일 전까지 최대 10%의 인원 증가를 요청할 수 있으며, 선택한 메뉴의 1인 요금으로 청구된다. 행사 10일 전 이후에 요청한 인원 감소는 지불액을 줄이지 않는다.\n\n4. 가격. 1인 요금은 표준 메뉴 85달러, 해산물 코스가 추가되는 프리미엄 메뉴 98달러이다.\n\n5. 식이 요청. 채식 및 글루텐 프리 식사는 최종 인원 확정 시 함께 요청하면 추가 비용 없이 제공된다.\n\n[이메일]\n보낸 사람: 조성민, 노윅 바이오테크 / 받는 사람: 다리아 볼코바, 사프런 테이블 케이터링 / 날짜: 11월 10일 / 제목: 파트너 만찬\n\n볼코바 님께,\n\n11월 3일에 확정한 대로 프리미엄 메뉴로 120명이 참석할 예정입니다. 그 후 싱가포르 지사의 파트너 몇 분이 참석하기로 해서 11명을 추가하고 싶습니다.\n\n또한 기존 참석자 중 두 명이 글루텐 프리 식사가 필요하다는 것을 방금 알았습니다. 늦게 알려 드리는 것은 알지만 맞춰 주시면 감사하겠습니다.\n\n끝으로 참석자 한 명이 취소했습니다. 이에 따라 총액이 조금 줄어들 것으로 생각합니다.\n\n감사합니다.\n조성민\n행사 담당자","part":7},{"id":"p7-159","level":4,"kind":"triple","passages":[{"doc_type":"안내문","title":"Midwest Packaging Expo — Exhibitor Booth Assignments, Hall B","text":"MIDWEST PACKAGING EXPO — HALL B BOOTH ASSIGNMENTS\n\nB-01 to B-10 (near main entrance): Machinery and automation\nB-11 to B-20 (center aisle): Sustainable and recycled materials\nB-21 to B-30 (near loading dock): Labels and printing\nB-31 to B-36 (near food court): Start-up companies (first-time exhibitors)\n\nNotes:\n• Exhibitors in B-01 to B-10 may bring equipment weighing up to 2,000 kg; heavier equipment must be displayed in Hall A.\n• Booths B-31 to B-36 are offered at 30% off the standard rate.\n• Exhibitor setup: Tuesday, 1 P.M.–8 P.M. Show days: Wednesday–Thursday."},{"doc_type":"이메일","title":"From: Expo Operations / To: Kofi Mensah, Greenfold Packaging / Date: May 2 / Subject: Booth confirmation","text":"Dear Mr. Mensah,\n\nThank you for registering Greenfold Packaging for this year's Midwest Packaging Expo. Since this is your first time exhibiting with us and your products are made from recycled cardboard, you were eligible for two sections. As you requested, we have assigned you booth B-14, which is in the section that matches your product category. Please note that you will be charged the standard rate for this booth.\n\nYour exhibitor badges will be available for pickup at the Hall B service desk during setup hours.\n\nExpo Operations"},{"doc_type":"문자 메시지","title":"Text-message chain — Kofi Mensah, Lena Ruiz","text":"Kofi Mensah [12:20 P.M.]: I'm at the hall. Our booth is in a great spot — lots of people will walk past.\nLena Ruiz [12:21 P.M.]: Great. I'm stuck in traffic with the display boxes, though. I won't get there until about 2:30.\nKofi Mensah [12:22 P.M.]: That's fine. We have until 8 to finish. I'll go get our badges and wait for you by the loading dock.\nLena Ruiz [12:23 P.M.]: Perfect. Can you also check if they'll lend us a hand truck?\nKofi Mensah [12:24 P.M.]: Will do."}],"questions":[{"q":"What is indicated about booths B-01 to B-10?","choices":["They are reserved for start-up companies.","They are located near the loading dock.","They have a weight limit for displayed equipment.","They are the least expensive booths."],"answer":2,"type":"사실 확인(NOT/TRUE)","explanation":"B-01~B-10 출품사는 2,000kg까지의 장비만 가져올 수 있고 그보다 무거우면 A홀에 전시해야 한다고 했다."},{"q":"Why did Mr. Mensah most likely choose booth B-14 instead of a cheaper one?","choices":["He wanted to be in the section for sustainable materials.","The start-up section was full.","He needed space for heavy machinery and large equipment on display","He wanted to be near the main entrance."],"answer":0,"type":"연계 문제","explanation":"이메일에서 그린폴드는 첫 출품(스타트업 구역 할인 대상)이자 재활용 소재 제품이라 두 구역 모두 가능했지만, 요청대로 제품 분류에 맞는 B-14를 배정했다고 했다. 안내문상 B-11~B-20은 친환경·재활용 소재 구역이다."},{"q":"On what day were the text messages most likely sent?","choices":["Monday","Tuesday","Wednesday","Thursday"],"answer":1,"type":"연계 문제","explanation":"멘사 씨가 8시까지 설치를 마치면 된다고 했고 배지를 받으러 간다고 했다. 안내문에 설치 시간은 화요일 오후 1시~8시이고, 배지는 설치 시간 중 받을 수 있다."},{"q":"At 12:22 P.M., what does Mr. Mensah mean when he writes, “That's fine”?","choices":["Ms. Ruiz's late arrival will not cause a problem.","The booth location is acceptable.","He does not need the display boxes.","The traffic is not very heavy."],"answer":0,"type":"의도 파악","explanation":"루이스 씨가 2시 30분쯤에야 도착한다고 하자 8시까지 마치면 되니 괜찮다고 했다. 늦게 와도 문제없다는 뜻이다."},{"q":"Where will Mr. Mensah go after picking up the badges?","choices":["To the food court","To the main entrance of the exhibition hall to meet Ms. Ruiz","To the area near the labels and printing booths","To Hall A"],"answer":2,"type":"연계 문제","explanation":"멘사 씨는 하역장(loading dock) 옆에서 기다리겠다고 했고, 안내문에서 하역장 근처는 B-21~B-30 라벨·인쇄 구역이다."}],"translation":"[안내문]\n중서부 포장 박람회 — B홀 부스 배정\n\nB-01~B-10 (정문 근처): 기계 및 자동화\nB-11~B-20 (중앙 통로): 친환경·재활용 소재\nB-21~B-30 (하역장 근처): 라벨 및 인쇄\nB-31~B-36 (푸드코트 근처): 스타트업 기업 (첫 출품사)\n\n참고:\n• B-01~B-10 출품사는 2,000kg 이하의 장비를 가져올 수 있으며, 더 무거운 장비는 A홀에 전시해야 합니다.\n• B-31~B-36 부스는 표준 요금에서 30% 할인됩니다.\n• 출품사 설치: 화요일 오후 1시~8시. 전시일: 수~목요일.\n\n[이메일]\n보낸 사람: 박람회 운영팀 / 받는 사람: 코피 멘사, 그린폴드 패키징 / 날짜: 5월 2일 / 제목: 부스 확정\n\n멘사 님께,\n\n올해 중서부 포장 박람회에 그린폴드 패키징을 등록해 주셔서 감사합니다. 처음 출품하시고 제품이 재활용 판지로 만들어졌기 때문에 두 구역 모두 배정 대상이었습니다. 요청하신 대로 제품 분류에 맞는 구역의 B-14 부스를 배정했습니다. 이 부스는 표준 요금이 청구된다는 점을 알려 드립니다.\n\n출품사 배지는 설치 시간 중 B홀 서비스 데스크에서 받으실 수 있습니다.\n\n박람회 운영팀\n\n[문자 메시지]\n코피 멘사 [오후 12:20]: 전시장에 와 있어요. 부스 자리가 아주 좋아요. 사람들이 많이 지나다닐 거예요.\n레나 루이스 [오후 12:21]: 잘됐네요. 그런데 저는 전시용 상자를 싣고 차가 막혀서 2시 30분쯤에야 도착할 것 같아요.\n코피 멘사 [오후 12:22]: 괜찮아요. 8시까지만 끝내면 돼요. 제가 배지를 받아서 하역장 옆에서 기다릴게요.\n레나 루이스 [오후 12:23]: 좋아요. 손수레를 빌려주는지도 확인해 줄래요?\n코피 멘사 [오후 12:24]: 그럴게요.","part":7},{"id":"p7-160","level":4,"kind":"triple","passages":[{"doc_type":"일정표","title":"Travel Itinerary — Priya Raman, Marlow Analytics","text":"TRAVEL ITINERARY — PRIYA RAMAN, MARLOW ANALYTICS\nPurpose: Client workshops in Toronto and Montreal\n\nMon., Jun. 9 — Flight AC 712, Chicago 8:05 A.M. → Toronto 10:50 A.M. Hotel: Bayview Suites, Toronto (2 nights)\nTue., Jun. 10 — Workshop at Hensley Insurance, 9 A.M.–4 P.M.\nWed., Jun. 11 — Train VIA 64, Toronto 9:30 A.M. → Montreal 2:41 P.M. Hotel: Hôtel Saint-Denis, Montreal (2 nights)\nThu., Jun. 12 — Workshop at Duval Retail Group, 9 A.M.–5 P.M.\nFri., Jun. 13 — Flight AC 409, Montreal 11:15 A.M. → Chicago 12:40 P.M."},{"doc_type":"이메일","title":"From: Priya Raman / To: Leo Fischer, Finance / Date: June 16 / Subject: Expense report — Canada trip","text":"Hi Leo,\n\nI've submitted my expense report for last week's trip. There are two items I should explain.\n\nFirst, the Hensley workshop ended early, and the client asked me to visit their Ottawa office on the way to Montreal. I changed my train ticket so that I could stop in Ottawa for the afternoon and continue to Montreal in the evening. There was a fee for the change.\n\nSecond, I couldn't get a receipt for one taxi ride because the driver's machine was broken. I've listed the fare without a receipt, as our policy allows for amounts under $30.\n\nThanks,\nPriya"},{"doc_type":"경비 보고서","title":"Expense Report — Priya Raman (excerpt)","text":"EXPENSE REPORT — PRIYA RAMAN (EXCERPT)\n\nJun. 9 — Taxi, Toronto airport to hotel — $54.00 — receipt attached\nJun. 10 — Hotel, Bayview Suites (2 nights) — $398.00 — receipt attached\nJun. 11 — Train ticket change fee — $35.00 — receipt attached\nJun. 11 — Taxi, Montreal station to hotel — $22.50 — no receipt\nJun. 12 — Dinner with Duval Retail Group managers — $186.40 — receipt attached\nJun. 13 — Hotel, Hôtel Saint-Denis (2 nights) — $452.00 — receipt attached\n\nApproved by: ________ (Finance)"}],"questions":[{"q":"What was the purpose of Ms. Raman's trip?","choices":["To attend a conference","To open a new office","To interview job candidates","To lead workshops for clients"],"answer":3,"type":"주제·목적","explanation":"일정표에 목적이 토론토와 몬트리올 고객 워크숍이라고 나와 있다."},{"q":"Where did Ms. Raman go on the afternoon of June 11?","choices":["Ottawa","Toronto","Montreal","Chicago"],"answer":0,"type":"연계 문제","explanation":"이메일에서 몬트리올로 가는 길에 오후 동안 오타와에 들르도록 기차표를 바꿨다고 했고, 일정표상 이동일은 6월 11일이다."},{"q":"According to the expense report, how much did the change to the travel plan cost?","choices":["$22.50","$35.00","$54.00","$186.40"],"answer":1,"type":"세부 사항","explanation":"6월 11일 기차표 변경 수수료가 35달러로 기재되어 있다."},{"q":"Which expense did Ms. Raman explain in the e-mail as lacking a receipt?","choices":["The taxi in Toronto","The Hôtel Saint-Denis stay","The dinner with Duval managers","The taxi in Montreal"],"answer":3,"type":"연계 문제","explanation":"이메일에서 기사의 단말기가 고장 나 택시 영수증을 받지 못했다고 했고, 경비 보고서에서 영수증이 없는 항목은 6월 11일 몬트리올역~호텔 택시(22.50달러)이다. 30달러 미만이라 규정상 허용된다."},{"q":"What is suggested about Ms. Raman's arrival in Montreal?","choices":["It was earlier than originally planned.","It was later than originally planned.","It was on June 12.","It was by plane."],"answer":1,"type":"연계 문제","explanation":"원래 일정은 오후 2시 41분 몬트리올 도착이었지만, 오타와에 오후 동안 들른 뒤 저녁에 몬트리올로 갔다고 했으므로 예정보다 늦게 도착했다."}],"translation":"[일정표]\n출장 일정 — 프리야 라만, 말로 애널리틱스\n목적: 토론토 및 몬트리올 고객 워크숍\n\n6월 9일(월) — AC 712편, 시카고 오전 8:05 → 토론토 오전 10:50. 숙소: 토론토 베이뷰 스위트(2박)\n6월 10일(화) — 헨슬리 보험 워크숍, 오전 9시~오후 4시\n6월 11일(수) — VIA 64 열차, 토론토 오전 9:30 → 몬트리올 오후 2:41. 숙소: 몬트리올 호텔 생드니(2박)\n6월 12일(목) — 뒤발 리테일 그룹 워크숍, 오전 9시~오후 5시\n6월 13일(금) — AC 409편, 몬트리올 오전 11:15 → 시카고 오후 12:40\n\n[이메일]\n보낸 사람: 프리야 라만 / 받는 사람: 레오 피셔, 재무팀 / 날짜: 6월 16일 / 제목: 경비 보고서 — 캐나다 출장\n\n안녕하세요, 레오.\n\n지난주 출장 경비 보고서를 제출했습니다. 설명드릴 항목이 두 가지 있습니다.\n\n첫째, 헨슬리 워크숍이 일찍 끝났고, 고객사가 몬트리올로 가는 길에 오타와 사무소를 방문해 달라고 요청했습니다. 그래서 오후 동안 오타와에 들렀다가 저녁에 몬트리올로 갈 수 있도록 기차표를 바꿨습니다. 변경 수수료가 있었습니다.\n\n둘째, 기사의 단말기가 고장 나서 택시 한 번은 영수증을 받지 못했습니다. 30달러 미만은 규정상 허용되므로 영수증 없이 요금을 기재했습니다.\n\n감사합니다.\n프리야\n\n[경비 보고서]\n경비 보고서 — 프리야 라만 (발췌)\n\n6월 9일 — 택시, 토론토 공항→호텔 — 54.00달러 — 영수증 첨부\n6월 10일 — 호텔, 베이뷰 스위트(2박) — 398.00달러 — 영수증 첨부\n6월 11일 — 기차표 변경 수수료 — 35.00달러 — 영수증 첨부\n6월 11일 — 택시, 몬트리올역→호텔 — 22.50달러 — 영수증 없음\n6월 12일 — 뒤발 리테일 그룹 관리자들과 저녁 식사 — 186.40달러 — 영수증 첨부\n6월 13일 — 호텔, 호텔 생드니(2박) — 452.00달러 — 영수증 첨부\n\n승인: ________ (재무팀)","part":7},{"id":"p7-161","level":5,"kind":"single","passages":[{"doc_type":"기사","title":"Smaller Offices, Bigger Budgets / By Lionel Ashby","text":"Since flexible work arrangements became widespread, companies have been steadily giving up office space. A survey of 400 mid-sized firms released last month by property consultancy Dunmore Partners found that the average firm now leases 22 percent less floor area than it did five years ago. [1]\n\nWhat the survey also revealed, however, is that spending per square meter has risen sharply. Firms are replacing rows of assigned desks with meeting rooms of varying sizes, soundproof booths for video calls, and shared kitchens designed to encourage informal conversation. [2] “The office is no longer where people go to do focused work they could do anywhere,” said Dunmore's research director, Helena Voss. “It's where they go to do what they can't do alone.”\n\nNot every change has been well received. In follow-up interviews, employees at several firms said that the move away from assigned desks made it harder to find colleagues and that the most popular rooms were often fully booked. [3] Some firms have responded by introducing “neighborhoods”—zones where members of the same team can expect to find one another, even without fixed seats.\n\nMs. Voss expects the trend toward smaller but more costly offices to continue. [4] Landlords, she added, have begun to take notice: newer buildings increasingly offer flexible floor plans that tenants can reconfigure without major construction."}],"questions":[{"q":"What is the article mainly about?","choices":["Why companies are moving to cheaper cities outside the capital","How companies are changing the way they use office space","A decline in demand for meeting rooms","The rising cost of commercial construction"],"answer":1,"type":"주제·목적","explanation":"기업들이 사무 공간은 줄이되 회의실·통화 부스·공용 주방 등에 더 많이 투자하는 방식으로 사무실 활용을 바꾸고 있다는 기사이다."},{"q":"What does Ms. Voss suggest about the purpose of offices today?","choices":["They are mainly for quiet individual work.","They are becoming unnecessary for most firms.","They are used primarily to impress clients.","They are mainly for activities that require working with others."],"answer":3,"type":"추론","explanation":"보스 씨는 사무실이 어디서나 할 수 있는 집중 업무가 아니라 혼자서는 할 수 없는 일을 하러 가는 곳이라고 했다. 즉 협업을 위한 공간이라는 뜻이다."},{"q":"According to the article, what complaint did some employees make?","choices":["Video-call booths were too noisy for private conversations","Kitchens were too small.","It was difficult to locate coworkers.","Their commute had become longer."],"answer":2,"type":"세부 사항","explanation":"고정 좌석이 없어지면서 동료를 찾기 어려워졌고 인기 있는 회의실은 자주 예약이 꽉 찬다고 했다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“Among firms with more than 200 employees, the reduction was even larger, at 31 percent.”","choices":["[1]","[2]","[3]","[4]"],"answer":0,"type":"문장 삽입","explanation":"'the reduction'은 평균 22% 줄어든 임차 면적을 가리키며, 직원 200명 이상 기업은 더 크게(31%) 줄었다는 보충 정보이다. 따라서 그 통계 바로 뒤인 [1]이 알맞다."}],"translation":"[기사]\n작아진 사무실, 커진 예산 / 라이어널 애시비 기자\n\n유연 근무가 널리 퍼진 이후 기업들은 꾸준히 사무 공간을 줄여 왔다. 부동산 컨설팅 업체 던모어 파트너스가 지난달 발표한 중견기업 400곳 조사에 따르면, 평균적인 기업은 현재 5년 전보다 22% 적은 면적을 임차하고 있다. (직원 200명 이상 기업에서는 감소 폭이 31%로 더 컸다.)\n\n그러나 조사에서는 제곱미터당 지출이 크게 늘었다는 사실도 드러났다. 기업들은 줄지어 놓인 지정 좌석을 다양한 크기의 회의실, 화상 통화용 방음 부스, 격식 없는 대화를 유도하도록 설계한 공용 주방으로 바꾸고 있다. 던모어의 연구 책임자 헬레나 보스는 \"사무실은 더 이상 어디서든 할 수 있는 집중 업무를 하러 가는 곳이 아니라, 혼자서는 할 수 없는 일을 하러 가는 곳\"이라고 말했다.\n\n모든 변화가 환영받은 것은 아니다. 후속 인터뷰에서 여러 기업 직원들은 지정 좌석이 사라지면서 동료를 찾기가 어려워졌고, 가장 인기 있는 방은 예약이 꽉 차 있는 경우가 많다고 말했다. 일부 기업은 고정 좌석이 없어도 같은 팀원끼리 서로를 찾을 수 있는 구역인 '네이버후드'를 도입해 대응했다.\n\n보스 씨는 작지만 비용이 더 드는 사무실로의 흐름이 계속될 것으로 예상한다. 그녀는 건물주들도 이를 주목하기 시작했다며, 신축 건물일수록 입주사가 큰 공사 없이 구조를 바꿀 수 있는 유연한 평면을 제공하는 경우가 늘고 있다고 덧붙였다.","part":7},{"id":"p7-162","level":5,"kind":"single","passages":[{"doc_type":"온라인 채팅","title":"Online chat discussion — Ruth Delacroix, Amir Haddad, Sean Whitlock, Mei Lin","text":"Ruth Delacroix [9:14 A.M.]: Talvik Polymers sent their renewal terms this morning. They want a 9 percent increase on resin starting in January.\nAmir Haddad [9:16 A.M.]: Nine? Last year they settled for four after we pushed back.\nRuth Delacroix [9:17 A.M.]: They're pointing to energy costs. To be fair, the other suppliers I've spoken to are raising prices too, just not by as much.\nSean Whitlock [9:19 A.M.]: How much are we talking about with the others?\nRuth Delacroix [9:20 A.M.]: Brenner Chemical quoted 5 percent, but their minimum order is twice what we usually buy.\nMei Lin [9:22 A.M.]: We could meet that if we combined orders for the Leeds and Glasgow plants.\nSean Whitlock [9:23 A.M.]: Glasgow's warehouse is already full through March.\nMei Lin [9:24 A.M.]: Leeds has room. We'd just need to schedule transfers.\nAmir Haddad [9:26 A.M.]: Before we change suppliers, let's see whether Talvik will move. Ruth, mention Brenner's quote when you call them—without the name.\nRuth Delacroix [9:27 A.M.]: Got it. I'll also ask whether they'd lock in the price for 18 months instead of 12."}],"questions":[{"q":"What are the writers mainly discussing?","choices":["Hiring a new supplier for packaging","A supplier's proposed price increase","Closing the Glasgow plant","Problems with the quality of resin"],"answer":1,"type":"주제·목적","explanation":"탈빅 폴리머스가 1월부터 수지 가격을 9% 올리겠다고 한 갱신 조건에 어떻게 대응할지 논의하고 있다."},{"q":"At 9:16 A.M., what does Mr. Haddad imply when he writes, “Last year they settled for four after we pushed back”?","choices":["The supplier may accept a smaller increase if challenged.","The company should accept the 9 percent increase without further talks","The supplier has never raised prices before.","He was not involved in last year's negotiation."],"answer":0,"type":"의도 파악","explanation":"작년에도 반발하자 4%로 합의했다는 말은 이번에도 협상하면 인상 폭을 줄일 수 있다는 뜻을 담고 있다. 실제로 그는 나중에 탈빅이 양보할지 먼저 보자고 한다."},{"q":"What is a drawback of Brenner Chemical's offer?","choices":["Its price increase is larger.","It requires larger orders than usual.","It cannot deliver to Leeds.","It is valid for only six months."],"answer":1,"type":"세부 사항","explanation":"브레너 케미컬은 5%를 제시했지만 최소 주문량이 평소 구매량의 두 배라고 했다."},{"q":"What will Ms. Delacroix most likely do?","choices":["Sign an 18-month contract with Brenner Chemical this week","Arrange transfers to the Leeds warehouse","Negotiate with Talvik Polymers using a competing offer","Ask Glasgow to reduce its orders"],"answer":2,"type":"추론","explanation":"하다드 씨가 탈빅에 전화할 때 이름은 밝히지 말고 브레너의 견적을 언급하라고 했고, 들라크루아 씨가 알겠다며 18개월 가격 고정도 묻겠다고 했다. 경쟁 견적을 활용해 탈빅과 협상할 것이다."}],"translation":"[온라인 채팅]\n루스 들라크루아 [오전 9:14]: 탈빅 폴리머스가 오늘 아침 갱신 조건을 보냈어요. 1월부터 수지 가격을 9% 올리겠대요.\n아미르 하다드 [오전 9:16]: 9%요? 작년에는 우리가 반발하니까 4%로 합의했잖아요.\n루스 들라크루아 [오전 9:17]: 에너지 비용을 이유로 들고 있어요. 공정하게 말하면 제가 이야기해 본 다른 공급업체들도 가격을 올리고 있어요. 그만큼은 아니지만요.\n숀 위틀록 [오전 9:19]: 다른 곳은 어느 정도인데요?\n루스 들라크루아 [오전 9:20]: 브레너 케미컬이 5%를 제시했는데, 최소 주문량이 우리가 보통 사는 양의 두 배예요.\n메이 린 [오전 9:22]: 리즈 공장과 글래스고 공장 주문을 합치면 맞출 수 있어요.\n숀 위틀록 [오전 9:23]: 글래스고 창고는 3월까지 이미 꽉 찼어요.\n메이 린 [오전 9:24]: 리즈는 공간이 있어요. 이송 일정만 잡으면 돼요.\n아미르 하다드 [오전 9:26]: 공급업체를 바꾸기 전에 탈빅이 양보할지 먼저 봅시다. 루스, 그쪽에 전화할 때 브레너의 견적을 언급해 줘요. 이름은 빼고요.\n루스 들라크루아 [오전 9:27]: 알겠어요. 가격을 12개월 대신 18개월 동안 고정해 줄 수 있는지도 물어볼게요.","part":7},{"id":"p7-163","level":5,"kind":"single","passages":[{"doc_type":"회람","title":"To: All Staff, Northern and Coastal Regions / From: Elias Brandvold, Chief Operating Officer / Date: August 28 / Subject: Regional consolidation","text":"As many of you know, the executive committee has spent the past several months reviewing how our regional operations are organized. I am writing to share the outcome of that review.\n\nEffective November 1, the Northern and Coastal regions will be combined into a single Northwest region, headquartered in our existing Trondale office. The two regions already share a distribution center and many of the same customers, and combining them will allow us to eliminate duplicated reporting and respond more consistently to clients that operate in both areas.\n\nI want to be clear about what this change does not involve. No positions are being eliminated as a result of the consolidation, and no one will be required to relocate. Staff currently based in the Coastal region's Harlow office will continue to work there, although some may report to new managers. Each affected employee will receive a letter from Human Resources by September 15 outlining any change to his or her reporting line.\n\nGreta Solheim, currently director of the Northern region, will lead the new Northwest region. Thomas Achebe, who has directed the Coastal region for six years, has accepted the role of head of national key accounts, a position created to strengthen relationships with our largest customers.\n\nQuestions may be directed to your manager or to Human Resources."}],"questions":[{"q":"What is the purpose of the memo?","choices":["To announce the closure of the Harlow office","To request feedback on a proposed review","To introduce a new distribution center","To explain a reorganization of two regions"],"answer":3,"type":"주제·목적","explanation":"11월 1일부터 북부와 해안 지역을 북서부 지역 하나로 통합한다는 검토 결과를 알리는 회람이다. 할로 사무소는 계속 운영된다."},{"q":"According to the memo, what is one reason for the change?","choices":["To reduce the number of employees","To open an office in Trondale","To move staff closer to customers","To avoid duplicated reporting"],"answer":3,"type":"세부 사항","explanation":"통합하면 중복 보고를 없애고 두 지역 모두에서 활동하는 고객에게 더 일관되게 대응할 수 있다고 했다. 인원 감축은 없다."},{"q":"What will employees in the Harlow office receive by September 15?","choices":["A relocation package","A revised employment contract","Information about any change in their supervisor","An invitation to a meeting in Trondale"],"answer":2,"type":"세부 사항","explanation":"영향을 받는 직원은 9월 15일까지 보고 체계 변경 사항을 담은 인사부 서신을 받는다고 했다. 일부는 새 관리자에게 보고하게 될 수 있다."},{"q":"What is suggested about Mr. Achebe?","choices":["He will leave the company in November.","He will move to the Trondale office.","He will take on a newly created role.","He will report to Ms. Solheim."],"answer":2,"type":"추론","explanation":"아체베 씨는 최대 고객과의 관계를 강화하기 위해 만든(a position created) 전국 주요 고객 책임자 자리를 맡기로 했다."}],"translation":"[회람]\n받는 사람: 북부·해안 지역 전 직원 / 보낸 사람: 엘리아스 브란볼, 최고운영책임자 / 날짜: 8월 28일 / 제목: 지역 통합\n\n많은 분이 아시다시피, 경영위원회는 지난 몇 달 동안 지역 조직 구성을 검토해 왔습니다. 그 결과를 알려 드리고자 합니다.\n\n11월 1일부로 북부 지역과 해안 지역이 하나의 북서부 지역으로 통합되며, 본부는 기존 트론데일 사무소에 둡니다. 두 지역은 이미 물류 센터와 많은 고객을 공유하고 있으며, 통합하면 중복된 보고를 없애고 두 지역 모두에서 활동하는 고객에게 더 일관되게 대응할 수 있습니다.\n\n이번 변화에 포함되지 않는 점도 분명히 말씀드립니다. 통합으로 인해 없어지는 직책은 없으며, 누구도 근무지를 옮길 필요가 없습니다. 현재 해안 지역 할로 사무소에서 근무하는 직원은 계속 그곳에서 일하며, 일부는 새 관리자에게 보고하게 될 수 있습니다. 영향을 받는 직원은 9월 15일까지 보고 체계 변경 내용을 담은 인사부 서신을 받게 됩니다.\n\n현재 북부 지역 책임자인 그레타 솔헤임이 새 북서부 지역을 이끕니다. 6년간 해안 지역을 이끌어 온 토머스 아체베는 최대 고객과의 관계를 강화하기 위해 신설된 전국 주요 고객 책임자 직을 맡기로 했습니다.\n\n문의 사항은 소속 관리자나 인사부로 해 주십시오.","part":7},{"id":"p7-164","level":5,"kind":"single","passages":[{"doc_type":"편지","title":"Pemberton & Royce LLP, Chartered Accountants / 18 Wexford Square, Halden","text":"January 12\n\nMs. Adaeze Nwosu\nChief Financial Officer\nCorran Outdoor Equipment Ltd.\n92 Millbank Road, Halden\n\nDear Ms. Nwosu,\n\nThank you for appointing Pemberton & Royce to audit Corran Outdoor Equipment's financial statements for the year ended December 31. As discussed at our planning meeting on January 8, our team will begin fieldwork at your offices on February 3 and expects to complete it within three weeks.\n\nTo keep to this timetable, we ask that the documents listed in the enclosed schedule be made available by January 27. Of particular importance are the year-end inventory count sheets from your two warehouses and the supporting contracts for the three new retail leases signed during the year. Because the Stanton warehouse count was carried out by an outside firm, we will also need a copy of that firm's report.\n\nWe understand that your accounting team will be short-staffed during the first week of February due to the launch of your new ordering system. If it would help, our team can begin with the work that requires the least input from your staff, such as testing fixed assets, and schedule interviews for the following week.\n\nPlease do not hesitate to contact me with any questions.\n\nYours sincerely,\nGraham Royce\nAudit Partner"}],"questions":[{"q":"What is the main purpose of the letter?","choices":["To propose a fee for audit services","To request a meeting to discuss a new ordering system","To report the findings of a completed audit","To outline arrangements for an upcoming audit"],"answer":3,"type":"주제·목적","explanation":"감사 현장 작업 시작일, 제출 서류와 기한, 일정 조정 방안 등 앞으로 진행할 감사 준비 사항을 안내하는 편지이다."},{"q":"What is indicated about the Stanton warehouse?","choices":["It was recently sold.","Its inventory was counted by another company.","It will be visited on February 3 by the audit team","It is leased to a retailer."],"answer":1,"type":"사실 확인(NOT/TRUE)","explanation":"스탠턴 창고의 재고 조사는 외부 업체가 했기 때문에 그 업체의 보고서 사본이 필요하다고 했다."},{"q":"Why does Mr. Royce offer to change the order of the audit work?","choices":["His own team has too few members.","Corran's staff will be busy with another project.","Some documents will arrive late.","The fieldwork will start earlier than planned."],"answer":1,"type":"세부 사항","explanation":"새 주문 시스템 도입 때문에 2월 첫 주에 회계팀 인력이 부족할 것을 알고, 직원의 도움이 덜 필요한 업무부터 시작하겠다고 제안했다."},{"q":"The word “short-staffed” in paragraph 3 is closest in meaning to","choices":["working shorter hours","poorly trained","recently hired","lacking enough employees"],"answer":3,"type":"동의어","explanation":"'short-staffed'는 일손이 부족하다는 뜻이므로 'lacking enough employees'가 가장 가깝다."}],"translation":"[편지]\n펨버턴 앤 로이스 회계법인 / 할든 웩스퍼드 스퀘어 18번지\n\n1월 12일\n\n아다에제 은오수 님\n최고재무책임자\n코런 아웃도어 장비 주식회사\n할든 밀뱅크 로드 92번지\n\n은오수 님께,\n\n12월 31일로 끝나는 회계연도의 코런 아웃도어 장비 재무제표 감사를 펨버턴 앤 로이스에 맡겨 주셔서 감사합니다. 1월 8일 계획 회의에서 논의한 대로, 저희 팀은 2월 3일 귀사 사무실에서 현장 작업을 시작해 3주 안에 마칠 예정입니다.\n\n이 일정을 지키기 위해 동봉한 목록의 서류를 1월 27일까지 준비해 주시기 바랍니다. 특히 중요한 것은 두 창고의 연말 재고 조사표와, 올해 체결한 신규 소매점 임대차 계약 세 건의 계약서입니다. 스탠턴 창고의 재고 조사는 외부 업체가 수행했으므로 그 업체의 보고서 사본도 필요합니다.\n\n새 주문 시스템 도입으로 2월 첫 주에 귀사 회계팀 인력이 부족하다는 점을 알고 있습니다. 도움이 된다면 저희 팀은 고정자산 검증처럼 귀사 직원의 협조가 가장 덜 필요한 작업부터 시작하고, 면담은 그다음 주로 잡을 수 있습니다.\n\n궁금한 점이 있으면 언제든 연락 주십시오.\n\n그레이엄 로이스\n감사 파트너","part":7},{"id":"p7-165","level":5,"kind":"single","passages":[{"doc_type":"웹페이지","title":"www.vantrellgroup.com/suppliers/onboarding","text":"BECOMING A VANTRELL SUPPLIER\n\nVantrell Group sources components from more than 1,200 suppliers in 30 countries. Before any purchase order can be issued, new suppliers must complete our onboarding process, which typically takes four to six weeks. [1]\n\nStep 1 — Registration. Submit company details, banking information, and tax documents through the Supplier Portal. Incomplete registrations are automatically closed after 30 days.\n\nStep 2 — Compliance review. Our team verifies that your company meets the standards set out in the Vantrell Supplier Code of Conduct, including those relating to working conditions and environmental reporting. [2] Suppliers that already hold a current certificate from an approved independent auditor may skip the on-site assessment.\n\nStep 3 — Quality qualification. Sample parts are tested at our laboratory in Eindhoven. [3] Suppliers of safety-critical components must also pass a process audit at their production site.\n\nStep 4 — Approval. Once approved, suppliers receive a vendor number and access to forecasting data. [4] Approval is reviewed every two years, or sooner if performance falls below agreed targets."}],"questions":[{"q":"What is the purpose of the Web page?","choices":["To advertise job openings at Vantrell Group's Eindhoven office","To explain how companies can start supplying Vantrell Group","To announce changes to Vantrell's Code of Conduct","To list Vantrell's approved auditors"],"answer":1,"type":"주제·목적","explanation":"신규 공급업체가 발주를 받기 전에 거쳐야 하는 등록·준법 검토·품질 인증·승인 절차를 설명하는 페이지이다."},{"q":"What is true about suppliers with a valid certificate from an approved auditor?","choices":["They can avoid one part of the compliance review.","They do not need to register on the Supplier Portal.","They are approved automatically.","They do not need to send sample parts."],"answer":0,"type":"사실 확인(NOT/TRUE)","explanation":"승인된 독립 감사 기관의 유효한 인증서가 있으면 준법 검토 중 현장 평가를 생략할 수 있다고 했다. 다른 단계는 그대로 거쳐야 한다."},{"q":"What is suggested about approved suppliers?","choices":["Their status may be reviewed early if they perform poorly.","They must reapply every year.","They are required to open an office in Eindhoven.","They receive payment within 30 days."],"answer":0,"type":"추론","explanation":"승인은 2년마다 재검토되며, 실적이 합의 목표에 못 미치면 더 일찍 검토된다고 했다."},{"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“Results are usually available within ten business days of receipt.”","choices":["[1]","[2]","[3]","[4]"],"answer":2,"type":"문장 삽입","explanation":"'Results'와 'receipt'는 아인트호벤 연구소에서 견본 부품을 시험한다는 내용과 연결된다. 견본을 받은 뒤 영업일 10일 안에 결과가 나온다는 뜻이므로 [3]이 알맞다."}],"translation":"[웹페이지]\n반트렐 공급업체가 되려면\n\n반트렐 그룹은 30개국 1,200곳이 넘는 공급업체로부터 부품을 조달합니다. 신규 공급업체는 발주서를 받기 전에 반드시 등록 절차를 마쳐야 하며, 이 절차는 보통 4~6주가 걸립니다.\n\n1단계 — 등록. 공급업체 포털에서 회사 정보, 은행 정보, 세무 서류를 제출합니다. 완료되지 않은 등록은 30일 후 자동으로 종료됩니다.\n\n2단계 — 준법 검토. 저희 팀이 귀사가 근로 조건과 환경 보고 관련 기준을 포함한 반트렐 공급업체 행동 강령의 기준을 충족하는지 확인합니다. 승인된 독립 감사 기관의 유효한 인증서를 이미 보유한 공급업체는 현장 평가를 생략할 수 있습니다.\n\n3단계 — 품질 인증. 견본 부품을 아인트호벤의 저희 연구소에서 시험합니다. (결과는 보통 견본 접수 후 영업일 10일 안에 나옵니다.) 안전에 중요한 부품의 공급업체는 생산 현장 공정 감사도 통과해야 합니다.\n\n4단계 — 승인. 승인되면 공급업체 번호와 수요 예측 자료 접근 권한을 받습니다. 승인은 2년마다 재검토되며, 실적이 합의된 목표에 못 미치면 더 일찍 검토됩니다.","part":7},{"id":"p7-166","level":5,"kind":"double","passages":[{"doc_type":"규정","title":"Halloran Engineering — Travel Policy (Section 4: Air Travel)","text":"HALLORAN ENGINEERING — TRAVEL POLICY\nSection 4: Air Travel\n\n4.1 Employees must book flights through the company's travel portal at least 14 days before departure. Bookings made fewer than 14 days in advance require written approval from a department director.\n\n4.2 Economy class is required for all flights under six hours. Premium economy may be booked for flights of six hours or more. Business class is permitted only for flights exceeding ten hours, or where a medical condition has been documented with Human Resources.\n\n4.3 Employees may extend a business trip for personal reasons, provided that the additional days do not increase the airfare paid by the company. Any difference in fare must be paid by the employee.\n\n4.4 Exceptions to this section may be granted by the Chief Financial Officer."},{"doc_type":"이메일","title":"From: Ingrid Solberg / To: Patrick Mwangi, Director of Structural Design / Date: March 3 / Subject: Trip to Singapore","text":"Dear Patrick,\n\nAs you know, Ridgeway Properties has asked us to present our design for the Marina tower in person. The meeting is on March 12, so I will need your approval to book the flight, as it is now too late to book without it.\n\nThe flight from Copenhagen to Singapore takes about twelve and a half hours. I would like to arrive two days early so that I can visit the site with the local contractor.\n\nI would also like to stay in Singapore for three days after the meeting to visit a friend. I have checked the portal, and returning on March 16 rather than March 13 would actually lower the fare by about €140, so this should not be a problem.\n\nThank you,\nIngrid"}],"questions":[{"q":"Why must Ms. Solberg get approval from Mr. Mwangi?","choices":["She wants to fly business class instead of economy class on this trip","She is booking her flight less than two weeks before departure.","She is extending her trip for personal reasons.","She wants to use a different travel portal."],"answer":1,"type":"연계 문제","explanation":"규정 4.1에 따르면 출발 14일 전 이후의 예약은 부서장의 서면 승인이 필요하다. 3월 3일에 3월 10일경 출발을 예약하므로 승인이 필요하다."},{"q":"What class of travel is Ms. Solberg allowed to book?","choices":["Economy class only","Premium economy but not business class","Business class","First class"],"answer":2,"type":"연계 문제","explanation":"규정 4.2에서 비행시간이 10시간을 넘으면 비즈니스석이 허용된다. 코펜하겐~싱가포르는 약 12시간 30분이다."},{"q":"What is the purpose of Ms. Solberg's trip?","choices":["To meet a client and present a design","To attend a training course","To interview a local contractor for a job","To inspect a completed building"],"answer":0,"type":"주제·목적","explanation":"리지웨이 프로퍼티스가 마리나 타워 설계를 직접 발표해 달라고 요청해서 가는 출장이다."},{"q":"What is suggested about Ms. Solberg's plan to stay longer?","choices":["It requires approval from the Chief Financial Officer.","She will have to pay part of the airfare.","It is consistent with the travel policy.","It will increase the company's costs."],"answer":2,"type":"연계 문제","explanation":"규정 4.3은 추가 일정이 회사 부담 항공료를 늘리지 않으면 개인 사유로 연장할 수 있다고 한다. 3월 16일 귀국이 오히려 약 140유로 싸므로 규정에 부합한다."},{"q":"In the policy, the word “documented” in section 4.2 is closest in meaning to","choices":["recorded officially","treated medically","written by hand","shared publicly"],"answer":0,"type":"동의어","explanation":"'a medical condition has been documented with Human Resources'는 건강 상태가 인사부에 공식적으로 기록·증빙되었다는 뜻이므로 'recorded officially'가 가장 가깝다."}],"translation":"[규정]\n핼러런 엔지니어링 — 출장 규정\n제4절: 항공 이용\n\n4.1 직원은 출발 최소 14일 전에 회사 출장 포털에서 항공편을 예약해야 한다. 출발 14일 이내에 예약하려면 부서장의 서면 승인이 필요하다.\n\n4.2 비행시간 6시간 미만의 모든 항공편은 일반석을 이용해야 한다. 6시간 이상은 프리미엄 일반석을 예약할 수 있다. 비즈니스석은 10시간을 초과하는 항공편이거나 인사부에 건강 상태가 증빙된 경우에만 허용된다.\n\n4.3 직원은 추가 일정이 회사가 부담하는 항공료를 늘리지 않는 한 개인 사유로 출장을 연장할 수 있다. 요금 차액은 직원이 부담해야 한다.\n\n4.4 이 절에 대한 예외는 최고재무책임자가 승인할 수 있다.\n\n[이메일]\n보낸 사람: 잉그리드 솔베르그 / 받는 사람: 패트릭 음왕기, 구조설계 부서장 / 날짜: 3월 3일 / 제목: 싱가포르 출장\n\n패트릭께,\n\n아시다시피 리지웨이 프로퍼티스가 마리나 타워 설계를 직접 발표해 달라고 요청했습니다. 회의가 3월 12일이라 이제는 승인 없이 예약하기에 너무 늦었으므로, 항공편 예약에 승인이 필요합니다.\n\n코펜하겐에서 싱가포르까지는 약 12시간 30분이 걸립니다. 현지 시공사와 현장을 둘러볼 수 있도록 이틀 일찍 도착하고 싶습니다.\n\n또한 회의 후 친구를 만나기 위해 싱가포르에 사흘 더 머물고 싶습니다. 포털에서 확인해 보니 3월 13일 대신 3월 16일에 돌아오면 항공료가 오히려 약 140유로 낮아지므로 문제가 없을 것 같습니다.\n\n감사합니다.\n잉그리드","part":7},{"id":"p7-167","level":5,"kind":"double","passages":[{"doc_type":"비교표","title":"Bid Comparison — Roof Replacement, Ellison Distribution Center (prepared by Facilities Planning)","text":"BID COMPARISON — ROOF REPLACEMENT, ELLISON DISTRIBUTION CENTER\nPrepared by Facilities Planning\n\nContractor | Total price | Duration | Warranty | Notes\nAltura Roofing | $1,184,000 | 9 weeks | 20 years | Can work only at night if loading docks must stay open by day\nBrightcap Builders | $1,092,000 | 12 weeks | 15 years | Requires two full-day closures of the north loading docks\nKestrel Commercial | $1,236,000 | 7 weeks | 25 years | Price includes solar-ready reinforcement of roof structure\nOrland & Sons | $998,000 | 14 weeks | 10 years | Has not previously completed a roof of this size\n\nBudget approved by the board: $1,200,000\nDeadline for completion: before the October peak shipping season (work may begin July 7)"},{"doc_type":"이메일","title":"From: Valeria Quintero, Director of Operations / To: Facilities Planning / Date: June 2 / Subject: Re: Roof bids","text":"Thank you for the comparison. A few thoughts.\n\nGiven the size of the project, I'm not comfortable with a contractor that has no experience at this scale, regardless of price. I'm also unwilling to close any loading docks during the day in July or August; our largest customer's back-to-school orders peak then.\n\nI realize the option with the longest warranty and the solar-ready structure is attractive, and we may well install panels in a few years. But I can't recommend going over the amount the board approved without first going back to them, and there isn't enough time for that before July 7.\n\nPlease set up a call with the remaining contractor this week so we can discuss how night work would affect the timeline.\n\nValeria"}],"questions":[{"q":"Which contractor offers the shortest construction period?","choices":["Altura Roofing","Brightcap Builders","Kestrel Commercial","Orland & Sons"],"answer":2,"type":"세부 사항","explanation":"비교표에서 케스트럴 커머셜의 공사 기간이 7주로 가장 짧다."},{"q":"Why does Ms. Quintero reject Orland & Sons?","choices":["Its price is too high.","Its warranty is too long.","It requires daytime closures.","It lacks experience with projects of this size."],"answer":3,"type":"연계 문제","explanation":"퀸테로 씨는 가격과 상관없이 이 규모의 경험이 없는 업체는 불안하다고 했고, 비교표에서 올랜드 앤 선스는 이런 크기의 지붕 공사를 해 본 적이 없다고 되어 있다."},{"q":"Why is Brightcap Builders most likely not selected?","choices":["It would require closing loading docks during the day.","It cannot finish before October because of the summer schedule","It exceeds the approved budget.","It offers no warranty."],"answer":0,"type":"연계 문제","explanation":"브라이트캡은 북쪽 하역장을 이틀 종일 폐쇄해야 하는데, 퀸테로 씨는 7~8월 낮 동안 하역장을 닫는 것을 원하지 않는다."},{"q":"What is suggested about Kestrel Commercial's bid?","choices":["It does not include a warranty.","It exceeds the amount approved by the board.","It requires night work.","It was submitted after the deadline."],"answer":1,"type":"연계 문제","explanation":"케스트럴의 입찰가는 1,236,000달러로 이사회 승인 예산 1,200,000달러를 넘는다. 퀸테로 씨는 이사회에 다시 묻지 않고는 승인 금액을 넘길 수 없다고 했다."},{"q":"Which contractor will Facilities Planning most likely contact?","choices":["Altura Roofing","Brightcap Builders","Kestrel Commercial","Orland & Sons"],"answer":0,"type":"연계 문제","explanation":"남은 업체와 야간 작업이 일정에 미칠 영향을 논의하자고 했다. 다른 세 곳이 제외되었고, 낮에 하역장을 열어 두려면 야간에만 작업할 수 있다고 한 업체는 알투라 루핑이다."}],"translation":"[비교표]\n입찰 비교 — 엘리슨 물류센터 지붕 교체\n작성: 시설기획팀\n\n업체 | 총액 | 공사 기간 | 보증 | 비고\n알투라 루핑 | 1,184,000달러 | 9주 | 20년 | 낮에 하역장을 열어 두어야 하면 야간에만 작업 가능\n브라이트캡 빌더스 | 1,092,000달러 | 12주 | 15년 | 북쪽 하역장 이틀 종일 폐쇄 필요\n케스트럴 커머셜 | 1,236,000달러 | 7주 | 25년 | 태양광 설치 대비 지붕 구조 보강 포함\n올랜드 앤 선스 | 998,000달러 | 14주 | 10년 | 이 규모의 지붕 공사 경험 없음\n\n이사회 승인 예산: 1,200,000달러\n완공 기한: 10월 성수기 배송 시즌 전 (7월 7일부터 착공 가능)\n\n[이메일]\n보낸 사람: 발레리아 퀸테로, 운영 이사 / 받는 사람: 시설기획팀 / 날짜: 6월 2일 / 제목: Re: 지붕 입찰\n\n비교표 고맙습니다. 몇 가지 의견입니다.\n\n프로젝트 규모를 고려하면 가격과 상관없이 이 정도 규모의 경험이 없는 업체는 마음이 놓이지 않습니다. 또한 7~8월에는 낮 동안 하역장을 하나라도 닫을 생각이 없습니다. 최대 고객의 신학기 주문이 그때 정점을 찍기 때문입니다.\n\n보증 기간이 가장 길고 태양광 대비 구조를 갖춘 안이 매력적이라는 건 압니다. 몇 년 안에 패널을 설치할 가능성도 충분하고요. 하지만 이사회에 다시 묻지 않고 승인 금액을 넘기는 것은 권할 수 없고, 7월 7일 전에 그럴 시간도 없습니다.\n\n야간 작업이 일정에 어떤 영향을 주는지 논의할 수 있도록 이번 주에 남은 업체와 통화 일정을 잡아 주세요.\n\n발레리아","part":7},{"id":"p7-168","level":5,"kind":"double","passages":[{"doc_type":"기사","title":"Start-Up Bets on Reusable Shipping Boxes / By Corinne Abara","text":"HAVERFIELD (October 6) — Loopcrate, a two-year-old company based in Haverfield, believes online retailers are ready to give up cardboard. The company rents durable plastic shipping boxes to retailers; customers return the empty boxes by dropping them at any of Loopcrate's 300 collection points, mostly located in pharmacies and convenience stores.\n\nThe company announced last week that it had raised $8 million from investors, which it will use to expand into three neighboring cities next spring. Loopcrate currently works with 45 retailers, most of them clothing brands.\n\nChief executive Marcus Thiele said that each box can be used about 50 times before it is recycled. “For retailers that ship lightweight goods, the cost per delivery is already close to that of cardboard,” he said.\n\nNot everyone is convinced. Analyst Joan Petrakis of Corvane Research noted that only about 60 percent of Loopcrate boxes are currently returned, which she said limits the environmental and financial benefits."},{"doc_type":"이메일","title":"From: Marcus Thiele / To: Corinne Abara / Date: October 7 / Subject: Yesterday's article","text":"Dear Ms. Abara,\n\nThank you for your article about Loopcrate. Overall, I think it gave readers a fair picture of what we do, and we have already received inquiries from several retailers as a result.\n\nI would, however, like to point out one figure that needs correcting. The 60 percent return rate mentioned by Ms. Petrakis applied to our first six months of operation, before we added collection points in pharmacies. Our return rate over the past year has been 87 percent, and I would be happy to share the data that supports this.\n\nI would also note that, of the three cities we are entering next spring, two already host collection points through our partnership with the Medira pharmacy chain.\n\nWould it be possible to publish a correction?\n\nBest regards,\nMarcus Thiele\nChief Executive Officer, Loopcrate"}],"questions":[{"q":"What does Loopcrate provide?","choices":["Recycled cardboard packaging for online retailers","Software for tracking packages","Delivery services for pharmacies","Reusable containers for shipping goods"],"answer":3,"type":"세부 사항","explanation":"룹크레이트는 온라인 소매업체에 내구성 있는 플라스틱 배송 상자를 대여하며, 고객이 빈 상자를 반납하는 방식이다."},{"q":"According to the article, how will Loopcrate use the money it raised?","choices":["To develop a new type of box","To expand to other cities","To open pharmacies","To buy a recycling plant"],"answer":1,"type":"세부 사항","explanation":"투자자들에게 받은 800만 달러로 내년 봄 인접한 세 도시로 확장할 것이라고 했다."},{"q":"Why did Mr. Thiele write to Ms. Abara?","choices":["To complain about the tone of her article","To ask her to interview Ms. Petrakis","To invite her to visit a collection point","To request that a statistic be corrected"],"answer":3,"type":"주제·목적","explanation":"기사 전반은 공정했다고 하면서도 회수율 60%라는 수치가 초기 6개월 기준이라 정정이 필요하다며 정정 보도를 요청했다."},{"q":"What is suggested about the return rate cited by Ms. Petrakis?","choices":["It was calculated by Loopcrate's investors.","It reflects a period when Loopcrate had fewer convenient return locations.","It includes boxes returned by retailers.","It was published in a previous article by Ms. Abara."],"answer":1,"type":"연계 문제","explanation":"기사에서 페트라키스 씨는 회수율이 약 60%라고 했는데, 티엘레 씨는 그것이 약국 수거 지점을 추가하기 전인 첫 6개월의 수치라고 했다. 즉 반납 장소가 적던 시기의 수치이다."},{"q":"What can be inferred about the Medira pharmacy chain?","choices":["It has invested $8 million in Loopcrate to fund its expansion into three new cities","It operates in some of the cities where Loopcrate plans to expand.","It is Loopcrate's largest retail customer.","It sells clothing online."],"answer":1,"type":"추론","explanation":"내년 봄 진출할 세 도시 중 두 곳에 메디라 약국 체인과의 제휴로 이미 수거 지점이 있다고 했으므로, 메디라가 그 도시들에서 영업하고 있다고 추론할 수 있다."}],"translation":"[기사]\n재사용 배송 상자에 거는 스타트업 / 코린 아바라 기자\n\n헤이버필드 (10월 6일) — 헤이버필드에 본사를 둔 설립 2년 차 기업 룹크레이트는 온라인 소매업체들이 골판지를 포기할 준비가 되어 있다고 믿는다. 이 회사는 소매업체에 내구성 있는 플라스틱 배송 상자를 대여하며, 고객은 대부분 약국과 편의점에 있는 룹크레이트의 수거 지점 300곳 중 아무 곳에나 빈 상자를 반납하면 된다.\n\n회사는 지난주 투자자들로부터 800만 달러를 유치했다고 발표했으며, 이 자금으로 내년 봄 인접한 세 도시로 사업을 확장할 예정이다. 룹크레이트는 현재 45개 소매업체와 거래하며, 대부분 의류 브랜드이다.\n\n마커스 티엘레 대표는 상자 하나를 재활용하기 전까지 약 50번 쓸 수 있다며 \"가벼운 상품을 배송하는 소매업체라면 배송 1건당 비용이 이미 골판지와 거의 비슷하다\"고 말했다.\n\n모두가 납득한 것은 아니다. 코베인 리서치의 분석가 조앤 페트라키스는 현재 룹크레이트 상자의 약 60%만 반납되고 있으며, 이 때문에 환경적·재정적 이점이 제한된다고 지적했다.\n\n[이메일]\n보낸 사람: 마커스 티엘레 / 받는 사람: 코린 아바라 / 날짜: 10월 7일 / 제목: 어제 기사\n\n아바라 기자님께,\n\n룹크레이트에 관한 기사 감사합니다. 전반적으로 저희가 하는 일을 독자들에게 공정하게 전해 주셨다고 생각하며, 덕분에 벌써 여러 소매업체로부터 문의를 받았습니다.\n\n다만 정정이 필요한 수치 하나를 말씀드리고 싶습니다. 페트라키스 씨가 언급한 60% 회수율은 약국에 수거 지점을 추가하기 전, 사업 첫 6개월에 해당하는 수치입니다. 지난 1년간 저희 회수율은 87%였으며, 이를 뒷받침하는 자료를 기꺼이 공유하겠습니다.\n\n또한 내년 봄 진출하는 세 도시 중 두 곳에는 메디라 약국 체인과의 제휴로 이미 수거 지점이 있다는 점도 말씀드립니다.\n\n정정 보도를 내 주실 수 있을까요?\n\n마커스 티엘레\n룹크레이트 대표","part":7},{"id":"p7-169","level":5,"kind":"triple","passages":[{"doc_type":"웹페이지","title":"www.nordicfintechweek.com/sponsors","text":"NORDIC FINTECH WEEK — SPONSORSHIP PACKAGES (Oslo, September 22–24)\n\nPlatinum — €40,000 (2 available): Keynote speaking slot on the opening day; 36 m² exhibition space; logo on all printed and digital materials; 10 full passes\nGold — €22,000 (6 available): Panel speaking slot; 18 m² exhibition space; logo on digital materials; 6 full passes\nSilver — €12,000 (10 available): 9 m² exhibition space; logo on the event Web site; 3 full passes\nNetworking Reception Host — €15,000 (1 available): Branding at the evening reception on September 23; opportunity to give a five-minute welcome address; 4 full passes\n\nSponsors who commit before May 31 receive a 10% discount. Packages may be combined."},{"doc_type":"이메일","title":"From: Henrik Aalto, Marketing Director, Ledgerline / To: sponsors@nordicfintechweek.com / Date: May 20 / Subject: Sponsorship inquiry","text":"Hello,\n\nLedgerline is launching a new payments platform for small businesses this autumn, and we are considering sponsoring Nordic Fintech Week.\n\nOur chief executive would very much like to address the full audience on the opening day, but we would prefer not to take a large exhibition space, since our product is entirely software and we plan to demonstrate it on tablets. We would also like an opportunity to meet potential partners informally.\n\nCould you tell me whether a speaking slot of the kind we want is still available? We would need to receive approval from our finance team before committing, which normally takes about two weeks.\n\nBest regards,\nHenrik Aalto"},{"doc_type":"이메일","title":"From: Sofie Lund, Sponsorship Manager / To: Henrik Aalto / Date: May 21 / Subject: RE: Sponsorship inquiry","text":"Dear Mr. Aalto,\n\nThank you for your interest. I'm afraid both packages that include an opening-day keynote were committed earlier this month. However, the Networking Reception package is still available and would give your chief executive a chance to address attendees at our most popular social event, where many partnerships are formed.\n\nAs for your timing, I understand that internal approvals take time. If you can send us a signed letter of intent by the end of this month, I can apply the early-commitment discount even if your final contract is signed in June.\n\nI'd be glad to arrange a call this week.\n\nSofie Lund"}],"questions":[{"q":"What is indicated about the sponsorship packages?","choices":["More than one can be purchased by the same company.","They must be purchased separately.","They all include exhibition space.","They are available only to Nordic companies."],"answer":0,"type":"사실 확인(NOT/TRUE)","explanation":"웹페이지 마지막에 패키지를 함께 구매할 수 있다(Packages may be combined)고 했다. 네트워킹 리셉션 패키지에는 전시 공간이 없다."},{"q":"Which package was Mr. Aalto originally most interested in?","choices":["Platinum","Gold","Silver","Networking Reception Host"],"answer":0,"type":"연계 문제","explanation":"알토 씨는 대표가 개막일에 전체 청중 앞에서 연설하기를 원한다고 했고, 개막일 기조연설 기회가 포함된 것은 플래티넘 패키지이다."},{"q":"Why is the Networking Reception package likely a good fit for Ledgerline?","choices":["It includes the largest exhibition space for displaying products to visitors and partners","It offers a speaking opportunity and an informal setting for meeting partners.","It is the least expensive package.","It includes ten full passes."],"answer":1,"type":"연계 문제","explanation":"알토 씨는 큰 전시 공간은 필요 없고 잠재 파트너를 비공식적으로 만날 기회를 원했다. 리셉션 패키지는 5분 환영사 기회가 있고 전시 공간이 없으며, 룬드 씨 말대로 많은 파트너십이 맺어지는 사교 행사이다."},{"q":"What problem does Mr. Aalto mention?","choices":["His company's product is not ready.","His company needs time for internal approval.","His chief executive cannot attend in September.","His company cannot afford a Gold package."],"answer":1,"type":"세부 사항","explanation":"약정 전에 재무팀 승인이 필요하며 보통 2주 정도 걸린다고 했다."},{"q":"If Ledgerline sends a letter of intent by May 31, how much will the Networking Reception package most likely cost?","choices":["€12,000","€13,500","€15,000","€36,000"],"answer":1,"type":"연계 문제","explanation":"리셉션 패키지는 15,000유로이고, 룬드 씨는 5월 말까지 의향서를 보내면 조기 약정 10% 할인을 적용해 주겠다고 했다. 15,000유로의 90%는 13,500유로이다."}],"translation":"[웹페이지]\n노르딕 핀테크 위크 — 후원 패키지 (오슬로, 9월 22~24일)\n\n플래티넘 — 40,000유로 (2개): 개막일 기조연설 기회, 36m² 전시 공간, 모든 인쇄·디지털 자료에 로고, 전체 일정 출입증 10장\n골드 — 22,000유로 (6개): 패널 토론 연설 기회, 18m² 전시 공간, 디지털 자료에 로고, 전체 일정 출입증 6장\n실버 — 12,000유로 (10개): 9m² 전시 공간, 행사 웹사이트에 로고, 전체 일정 출입증 3장\n네트워킹 리셉션 호스트 — 15,000유로 (1개): 9월 23일 저녁 리셉션 브랜딩, 5분 환영사 기회, 전체 일정 출입증 4장\n\n5월 31일 전에 약정하는 후원사는 10% 할인을 받습니다. 패키지는 함께 구매할 수 있습니다.\n\n[이메일 1]\n보낸 사람: 헨리크 알토, 레저라인 마케팅 이사 / 받는 사람: sponsors@nordicfintechweek.com / 날짜: 5월 20일 / 제목: 후원 문의\n\n안녕하세요,\n\n레저라인은 올가을 소기업용 새 결제 플랫폼을 출시하며, 노르딕 핀테크 위크 후원을 검토하고 있습니다.\n\n저희 대표께서 개막일에 전체 청중 앞에서 연설하기를 매우 원하십니다. 다만 제품이 전부 소프트웨어이고 태블릿으로 시연할 계획이라 넓은 전시 공간은 필요하지 않습니다. 잠재 파트너를 비공식적으로 만날 기회도 있으면 좋겠습니다.\n\n저희가 원하는 연설 기회가 아직 남아 있는지 알려 주시겠습니까? 약정 전에 재무팀 승인을 받아야 하는데, 보통 2주 정도 걸립니다.\n\n헨리크 알토 드림\n\n[이메일 2]\n보낸 사람: 소피 룬드, 후원 담당 매니저 / 받는 사람: 헨리크 알토 / 날짜: 5월 21일 / 제목: RE: 후원 문의\n\n알토 님께,\n\n관심 가져 주셔서 감사합니다. 아쉽게도 개막일 기조연설이 포함된 두 패키지는 이달 초에 모두 약정되었습니다. 하지만 네트워킹 리셉션 패키지는 아직 남아 있으며, 많은 파트너십이 맺어지는 저희의 가장 인기 있는 사교 행사에서 대표님이 참석자들에게 연설하실 기회가 됩니다.\n\n일정 문제는 내부 승인에 시간이 걸린다는 점을 이해합니다. 이달 말까지 서명한 의향서를 보내 주시면 최종 계약이 6월에 체결되더라도 조기 약정 할인을 적용해 드릴 수 있습니다.\n\n이번 주에 통화 일정을 잡으면 좋겠습니다.\n\n소피 룬드","part":7},{"id":"p7-170","level":5,"kind":"triple","passages":[{"doc_type":"제품 사양표","title":"Aerivo Industrial Dehumidifiers — Model Comparison","text":"AERIVO INDUSTRIAL DEHUMIDIFIERS — MODEL COMPARISON\n\nModel | Moisture removal (liters/day) | Recommended area | Operating range | Price\nDX-120 | 120 | up to 600 m² | 5°C to 35°C | $3,400\nDX-200 | 200 | up to 1,000 m² | 5°C to 35°C | $5,100\nDX-200C | 200 | up to 1,000 m² | -5°C to 35°C | $6,250\nDX-350 | 350 | up to 1,800 m² | 1°C to 38°C | $8,900\n\n• All models include a two-year parts warranty. Extended five-year coverage is available for 12% of the unit price.\n• Model DX-200C is designed for unheated warehouses and cold-storage areas."},{"doc_type":"견적서","title":"Quotation #Q-4471 — Aerivo Climate Systems / Customer: Brannock Paper Mills","text":"QUOTATION #Q-4471\nAerivo Climate Systems\nCustomer: Brannock Paper Mills — Finished Goods Warehouse (unheated, 900 m²)\nDate: November 4 / Valid for 30 days\n\n2 × DX-200 @ $5,100 — $10,200\nExtended warranty (5 years) × 2 — $1,224\nInstallation — $1,150\nTotal: $12,574\n\nPrepared by: Lucas Ferro, Sales Engineer"},{"doc_type":"이메일","title":"From: Danielle Ostrowski, Plant Engineer, Brannock Paper Mills / To: Lucas Ferro / Date: November 6 / Subject: Quotation #Q-4471","text":"Dear Mr. Ferro,\n\nThank you for the quotation. Before we proceed, I'd like to raise two points.\n\nFirst, as noted on the quotation, the finished goods warehouse is unheated. Between December and February, temperatures inside regularly drop to around -3°C. I'm concerned that the units you've quoted won't operate in those conditions.\n\nSecond, I wonder whether two units are necessary. If one unit can cover the whole area, we would prefer to buy one unit and spend the savings on the extended warranty.\n\nPlease send a revised quotation reflecting these points.\n\nBest regards,\nDanielle Ostrowski"}],"questions":[{"q":"What is true about all Aerivo models?","choices":["They operate below freezing.","They come with a two-year parts warranty.","They are suitable for areas up to 1,800 m².","They cost less than $6,000."],"answer":1,"type":"사실 확인(NOT/TRUE)","explanation":"모든 모델에 2년 부품 보증이 포함된다고 했다. 영하에서 작동하는 것은 DX-200C뿐이다."},{"q":"Why is Ms. Ostrowski concerned about the quoted model?","choices":["It cannot operate at the warehouse's winter temperatures.","It removes too little moisture.","It is too large for the warehouse.","It does not include installation."],"answer":0,"type":"연계 문제","explanation":"견적 모델 DX-200의 작동 범위는 5°C~35°C인데, 창고는 겨울에 -3°C 안팎까지 내려간다고 했다."},{"q":"Which model will most likely appear on the revised quotation?","choices":["DX-120","DX-200","DX-200C","DX-350"],"answer":2,"type":"연계 문제","explanation":"영하 5°C까지 작동하고 1,000m²까지 감당하는 DX-200C가 난방하지 않는 900m² 창고에 맞는다. 사양표에도 비난방 창고용으로 설계되었다고 했다."},{"q":"What does Ms. Ostrowski suggest about the number of units?","choices":["She wants to add a third unit.","She will decide after the winter.","She wants one unit for each floor of the warehouse building","She thinks one unit may be enough for the area."],"answer":3,"type":"세부 사항","explanation":"한 대로 전체 면적을 감당할 수 있다면 한 대만 사고 절감액을 연장 보증에 쓰고 싶다고 했다."},{"q":"If Brannock buys one unit of the appropriate model with the extended warranty, what will the warranty cost?","choices":["$612","$750","$1,224","$1,068"],"answer":1,"type":"연계 문제","explanation":"연장 보증은 단가의 12%이다. 적합한 모델 DX-200C는 6,250달러이므로 12%는 750달러이다. 612달러는 DX-200 기준 금액이다."}],"translation":"[제품 사양표]\n에어리보 산업용 제습기 — 모델 비교\n\n모델 | 제습량(리터/일) | 권장 면적 | 작동 온도 | 가격\nDX-120 | 120 | 600m²까지 | 5°C~35°C | 3,400달러\nDX-200 | 200 | 1,000m²까지 | 5°C~35°C | 5,100달러\nDX-200C | 200 | 1,000m²까지 | -5°C~35°C | 6,250달러\nDX-350 | 350 | 1,800m²까지 | 1°C~38°C | 8,900달러\n\n• 모든 모델에 2년 부품 보증이 포함됩니다. 5년 연장 보증은 단가의 12%로 이용할 수 있습니다.\n• DX-200C 모델은 난방하지 않는 창고와 냉장 보관 구역용으로 설계되었습니다.\n\n[견적서]\n견적서 #Q-4471\n에어리보 클라이밋 시스템즈\n고객: 브래녹 제지 — 완제품 창고 (비난방, 900m²)\n날짜: 11월 4일 / 30일간 유효\n\nDX-200 2대 @ 5,100달러 — 10,200달러\n연장 보증(5년) × 2 — 1,224달러\n설치 — 1,150달러\n합계: 12,574달러\n\n작성: 루카스 페로, 영업 엔지니어\n\n[이메일]\n보낸 사람: 대니엘 오스트로스키, 브래녹 제지 설비 엔지니어 / 받는 사람: 루카스 페로 / 날짜: 11월 6일 / 제목: 견적서 #Q-4471\n\n페로 님께,\n\n견적서 감사합니다. 진행하기 전에 두 가지를 말씀드리고 싶습니다.\n\n첫째, 견적서에도 적혀 있듯이 완제품 창고는 난방을 하지 않습니다. 12월부터 2월까지는 내부 온도가 자주 영하 3도 안팎까지 떨어집니다. 견적하신 제품이 그런 조건에서 작동하지 않을까 걱정됩니다.\n\n둘째, 두 대가 꼭 필요한지 궁금합니다. 한 대로 전체 면적을 감당할 수 있다면 한 대만 사고, 절약한 돈을 연장 보증에 쓰고 싶습니다.\n\n이 점들을 반영한 수정 견적서를 보내 주십시오.\n\n대니엘 오스트로스키 드림","part":7}];
